window.DEEP_STORIES["telephone"] = {"slug":"telephone","title":"The Telephone","emoji":"☎️","tagline":"How humans learned to send their voices across the world","intro":"Imagine needing to tell your friend in another city something important. Today you would just call. But for almost all of human history, a message could only travel as fast as a runner, a horse, a ship, or a puff of smoke. In this Deep Dive we follow one of the greatest journeys in invention history: from signal fires on hilltops and clacking telegraph keys, through the fierce race between Alexander Graham Bell, Elisha Gray and Antonio Meucci, to busy switchboards full of operators, spinning rotary dials, giant cables lying on the bottom of the ocean, and finally phones you can carry in your pocket. Across 20 parts you will learn how a telephone turns your voice into electricity and back again, meet the people who built it (and argued about who deserves credit), discover how it changed homes, jobs and emergencies, and peek at what calling might look like in the future. Pick up the receiver — let's begin!","outline":[{"n":1,"title":"Smoke, Drums and Fire on the Hills","when":"Ancient times – 1700s"},{"n":2,"title":"Towers with Arms and Sparks in a Jar","when":"1790s – 1830s"},{"n":3,"title":"Lightning Messages: The Electric Telegraph","when":"1830s – 1860s"},{"n":4,"title":"A Wire Across the Ocean","when":"1850 – 1866"},{"n":5,"title":"Dreamers of the Talking Wire","when":"1850s – 1875"},{"n":6,"title":"Alexander Graham Bell, Teacher of Sound","when":"1847 – 1875"},{"n":7,"title":"The Same Day at the Patent Office","when":"February – March 1876"},{"n":8,"title":"Showing the World","when":"1876 – 1878"},{"n":9,"title":"How a Telephone Turns Your Voice into Electricity","when":"The science (1876 – 1880s inventions)"},{"n":10,"title":"Patent Wars: Who Really Invented It?","when":"1877 – 1888, and later"},{"n":11,"title":"Hello, Central! Switchboards and Operators","when":"1878 – 1920s"},{"n":12,"title":"Spinning Dials and Automatic Switches","when":"1889 – 1960s"},{"n":13,"title":"Coast to Coast and Across the Sea by Radio","when":"1885 – 1940s"},{"n":14,"title":"Voices Under the Ocean and Light in a Glass Thread","when":"1947 – today"},{"n":15,"title":"How the Phone Changed Everyday Life","when":"1880s – 1990s"},{"n":16,"title":"Problems, Fights and Hard Questions","when":"1880s – today"},{"n":17,"title":"Phones That Leave the House","when":"1946 – 1983"},{"n":18,"title":"Pocket Phones for Everyone","when":"1990s – 2000s"},{"n":19,"title":"The Future of Talking at a Distance","when":"2000s – the future"},{"n":20,"title":"From Signal Fire to Satellite: Putting It All Together","when":"Ancient times – today"}],"people":[["Aeschylus (about 525–456 BCE)","Greek playwright whose play Agamemnon describes a chain of signal fires"],["Claude Chappe (1763–1805)","French engineer who, with his brothers, built the optical semaphore telegraph"],["Alessandro Volta (1745–1827)","Italian physicist who invented the first battery in 1800"],["Hans Christian Ørsted (1777–1851)","Danish physicist who discovered that electric current affects a magnet (1820)"],["Michael Faraday (1791–1867)","English scientist who discovered electromagnetic induction"],["Joseph Henry (1797–1878)","American scientist who built powerful electromagnets and early telegraph experiments"],["William Fothergill Cooke (1806–1879) and Charles Wheatstone (1802–1875)","British co-inventors of a needle telegraph patented in 1837"],["Samuel Morse (1791–1872)","American painter and inventor who developed the US electric telegraph and, with Vail, Morse code"],["Alfred Vail (1807–1859)","Morse's partner who did much of the mechanical work and helped create the code"],["Cyrus Field (1819–1892)","American businessman who drove the transatlantic telegraph cable project"],["William Thomson, Lord Kelvin (1824–1907)","Scottish-Irish physicist who solved cable signalling problems and later praised Bell's telephone"],["Charles Bourseul (1829–1912)","French telegraph worker who described the idea of electrical speech in 1854"],["Johann Philipp Reis (1834–1874)","German teacher who built a 'Telephon' in 1861 that sent tones and some speech"],["Antonio Meucci (1808–1889)","Italian-American inventor who developed a voice-carrying 'telettrofono' and filed a caveat in 1871"],["Elisha Gray (1835–1901)","American inventor and Western Electric co-founder who filed a telephone caveat the same day as Bell's patent"],["Alexander Graham Bell (1847–1922)","Scottish-born teacher of the deaf and inventor who received the key 1876 telephone patent"],["Alexander Melville Bell (1819–1905)","Bell's father, speech expert who created Visible Speech"],["Mabel Hubbard Bell (1857–1923)","Bell's wife, deaf from childhood scarlet fever, important supporter of his work"],["Gardiner Greene Hubbard (1822–1897)","lawyer, Mabel's father, Bell's financial backer and first president of the Bell Telephone Company"],["Thomas A. Watson (1854–1934)","Bell's assistant who built the devices and heard the first famous call"],["Dom Pedro II (1825–1891)","Emperor of Brazil who praised Bell's telephone at the 1876 Centennial Exhibition"],["Thomas Edison (1847–1931)","American inventor who improved the telephone with a carbon transmitter"],["Emile Berliner (1851–1929)","German-American inventor who developed an early microphone (and later the gramophone)"],["David Edward Hughes (1831–1900)","inventor who demonstrated a carbon microphone in 1878"],["Daniel Drawbaugh (1827–1911)","Pennsylvania mechanic who claimed an earlier telephone; lost at the Supreme Court in 1888"],["George W. Coy (1836–1915)","built the first commercial telephone switchboard in New Haven, 1878"],["Emma Nutt (1860–1915)","the first woman telephone operator, hired in Boston in 1878"],["Almon Strowger (1839–1902)","Kansas City undertaker who invented the automatic telephone switch"],["Theodore Vail (1845–1920)","business leader who built the Bell System and AT&T"],["Michael Pupin (1858–1935)","Serbian-American physicist who patented loading coils for long-distance lines"],["Lee de Forest (1873–1961)","American inventor of the Audion vacuum tube, later developed into amplifiers"],["Charles Kao (1933–2018)","engineer who showed glass fibers could carry signals far; Nobel Prize 2009"],["Claude Shannon (1916–2001)","Bell Labs mathematician who founded information theory in 1948"],["Robert Weitbrecht (1920–1983)","deaf physicist who made TTY phone communication possible for deaf people"],["Hedy Lamarr (1914–2000)","actress and inventor who co-patented a frequency-hopping idea with composer George Antheil in 1942"],["Douglas H. Ring and W. Rae Young","Bell Labs engineers who proposed the cellular network idea in 1947"],["Martin Cooper (born 1928)","Motorola engineer who made the first public handheld cellular call in 1973"],["Joel Engel (born 1936)","Bell Labs engineer who received Cooper's famous first call"],["Neil Papworth (born 1969)","engineer who sent the first SMS text message in 1992"]],"glossary":[["signal","any sign (light, sound, electricity, radio) used to carry a message"],["telegraph","a system that sends coded messages (like Morse code) over a distance, usually by electric wire"],["Morse code","a code of short and long signals (dots and dashes) for each letter and number"],["electromagnet","a coil of wire that becomes a magnet when electricity flows through it"],["diaphragm","a thin, flexible disk in a phone that vibrates with sound"],["transmitter","the part of a phone you speak into; it turns sound into a changing electric signal"],["receiver","the part of a phone you listen to; it turns the electric signal back into sound"],["analog","a signal that changes smoothly, like a copy of the shape of a sound wave"],["digital","a signal made of numbers (ones and zeros)"],["patent","a government document giving an inventor the right to control their invention for a set time"],["caveat","an old US patent office notice saying an inventor is working on an idea and plans to patent it"],["exchange","a central place where telephone lines meet and are connected to each other"],["switchboard","a panel where operators connected calls by plugging cords into jacks"],["operator","a person who connected calls by hand on a switchboard"],["party line","one telephone line shared by several homes"],["rotary dial","a spinning dial that sends a number as a series of quick clicks (pulses)"],["undersea cable","a cable laid on the ocean floor to carry telegraph, telephone or internet signals"],["fiber optics","sending signals as flashes of light through very thin strands of glass"],["amplifier / repeater","a device that makes a weak signal stronger so it can travel farther"],["cell","the small area covered by one mobile phone tower; many cells together make a cellular network"]],"parts":[{"n":1,"title":"Smoke, Drums and Fire on the Hills","when":"Ancient times – 1700s","summary":"Long ago, nobody could just pick up a phone. To send news far away, people lit fires on hilltops, beat drums that copied the sound of words, sent runners racing along mountain roads, and even let birds carry tiny letters home. Every one of these tricks was clever, but each one was slow, easy to stop, or able to say only a few simple things.","sections":[{"heading":"A World That Moved at the Speed of Feet","paragraphs":["Try a little experiment in your head. Your cousin lives 500 kilometres (about 300 miles) away, and you have big news: a new baby brother has just been born. Today the news would reach your cousin in less time than it takes to sneeze. Now take away every phone, computer, radio and wire. What is left? You could walk there, which might take about two weeks. You could ride a good horse and swap it for fresh ones along the way, which might take three or four days. You could hand a letter to a ship's captain and hope the winds were kind. That was it. For almost all of human history, news could travel no faster than the fastest thing that could carry it.","This is the giant problem at the very start of our story. A message is a kind of invisible cargo. It has no weight, but before electricity it still had to ride on something real: a person's memory, a scrap of papyrus, a knot in a string, a bird's leg. If the carrier was slow, the news was slow. If the carrier got lost, sick, captured or eaten by a wolf, the news simply vanished.","That mattered enormously. Kings needed to know when an enemy army crossed the border. Merchants needed to know whether a ship full of spices had arrived or sunk. Families needed to know whether a traveller was alive. Often, by the time the news arrived, it was already too late to do anything about it. Battles were sometimes fought after a peace treaty had already been signed, simply because nobody had told the soldiers.","So people all over the world, in completely different places and times, came up with tricks to make messages move faster than a walking human. Some used light, which travels incredibly fast. Some used sound, which is quick over short distances. Some used relay teams, so no single runner or horse ever got tired. Some even borrowed the amazing homing sense of birds. None of these tricks is a telephone, but all of them were attempts to solve the same puzzle the telephone would finally crack: how do you get a message across a great distance, quickly, without carrying it there yourself?"]},{"heading":"Fires on the Mountaintops","paragraphs":["Light is the fastest thing in the universe. It covers about 300,000 kilometres every second, which means a flash on one hilltop reaches your eyes on another hilltop practically instantly. Ancient people did not know that number, but they certainly knew that a big fire on a high place could be seen from very far away, especially at night. That simple fact gave us the oldest long-distance signal of all: the signal fire, or beacon.","One of the most famous beacon chains in history comes not from a history book but from a play. In 458 BCE, in the city of Athens, the playwright Aeschylus presented a set of three tragedies called the Oresteia, which won first prize at a great theatre festival. The first play, Agamemnon, opens with a tired watchman lying on the roof of a palace in the Greek city of Argos. For a whole year he has stared into the dark, waiting for one particular fire. When it finally blazes on the horizon, it means that the Greek army has captured the city of Troy, far across the sea.","Later in the play, Queen Clytemnestra explains how the news got there so fast. She describes a chain of bonfires leaping from mountaintop to mountaintop: from Mount Ida near Troy, across the sea to the island of Lemnos, on to the huge peak of Mount Athos, and onward over many more hills until the last fire is lit within sight of Argos. Each team of watchers saw the fire before them and lit their own, passing the flame along like a relay baton made of light.","It is an exciting scene, but remember: Agamemnon is a play, a work of imagination about a legendary war. It is not a news report, and nobody knows whether such a chain was ever really built for the Trojan War, or whether the Trojan War even happened the way the old stories say. What the play does tell us is something real about Aeschylus's own time: Greek audiences in the 400s BCE clearly understood the idea of passing a fire signal from hill to hill. The idea had to be familiar for the story to make sense.","There was one big weakness with a single fire. It could only say one thing. Fire lit means yes; no fire means no. A computer scientist today would call that one 'bit' of information, the smallest possible piece of a message. A fire could shout 'Troy has fallen!' but it could not add 'and the king is coming home on Tuesday with ten ships.'","Clever Greeks tried to fix this. In the 300s BCE, a writer on warfare named Aeneas Tacticus described a 'water telegraph'. Two teams on two hills each had an identical pot of water with a floating rod inside, and the rod was marked with a list of prepared messages, such as 'cavalry has arrived' or 'send grain'. At a first torch signal, both teams opened a tap at the bottom of their pots. When the right message reached the top of the pot, the sender raised a torch again, and both closed their taps. Because the water had drained for the same length of time, the floating rods sank to the same mark, and the receiver could read which message was meant. About two centuries later, the historian Polybius described this method and grumbled that it still fell far short of what an army really needed, because you could only send messages someone had written on the rod in advance. Polybius described a better scheme too: arranging the letters of the alphabet in a grid and using different numbers of torches to point to each letter, so that any word could be spelled out, slowly, one letter at a time.","Centuries later, the Byzantine Empire, whose capital was Constantinople (today's Istanbul), built a real and well-recorded beacon line. In the 800s CE, during wars with Arab armies, a chain of fire stations stretched about 720 kilometres (450 miles) from a mountain pass called the Cilician Gates, in what is now southern Turkey, all the way to the lighthouse of the emperor's Great Palace. Reports credit a scholar called Leo the Mathematician with a clever upgrade. At each end of the line stood an identical water clock. Each of the twelve hours had its own pre-agreed meaning, perhaps 'invasion' at one hour and 'battle' at another. The hour at which the first fire was lit told the emperor what had happened. Modern experiments suggest a signal could race down the whole line in about an hour, when a horse rider would have needed many days."]},{"heading":"Smoke by Day, Flame by Night on the Great Wall","paragraphs":["Now travel east to China, to one of the most famous structures on Earth. The Great Wall is not really a single wall. It is a whole collection of walls, forts and towers built and rebuilt over roughly 2,000 years by different Chinese dynasties to guard the northern frontier. Many of the walls you see in photographs today were built or rebuilt under the Ming dynasty, which ruled from 1368 to 1644.","Along and near the walls stood beacon towers, sometimes placed on hilltops a few kilometres apart so that each one could see its neighbours. Guards in these towers watched the empty grasslands and mountains to the north. If raiders appeared, the guards sent a warning: thick columns of smoke during the day, which could be seen against the sky, and blazing fires at night, which could be seen against the darkness. Flags and drums sometimes helped too.","Chinese commanders also found a way to make their signals say a little more than 'danger'. Accounts of Ming-era rules describe how the number of smoke columns or fires, sometimes along with gunshots or firecracker bangs, gave a rough idea of how many enemies were coming. One fire might warn of a small band, while several fires at once warned of a huge army in the thousands. The exact rules changed between periods and places, but the basic idea was a code: an agreed list of signals with agreed meanings. Every long-distance system in this story, right up to Morse code and the telephone network, depends on that same idea.","How fast was it? Historians describe Great Wall signals travelling hundreds of kilometres in a matter of hours, passing inland toward garrisons and even the capital. That was far quicker than any galloping messenger. But think about the weak spots. Heavy rain could stop a fire. Thick fog could hide smoke. A sleepy or careless guard could break the whole chain. And the signal could still only say a few simple things, like 'raiders, many' or 'raiders, few'. If the commander wanted to know which valley they were in, what weapons they carried, or where they were heading, he still had to wait for a rider."]},{"heading":"Beacon Hill: England Watches for the Armada","paragraphs":["Let us jump to the summer of 1588 and to the green hills of southern England. King Philip II of Spain had gathered an enormous fleet, the Armada, of roughly 130 ships. His plan was to sail up the English Channel, link up with a Spanish army waiting in the Netherlands, and invade England to overthrow Queen Elizabeth I.","The English knew something was coming, but not exactly when. So for months they had kept beacons ready along the coast and inland. A beacon in Tudor England was often an iron basket or a tall pile of wood, tar and brush on a high spot, guarded by local men who took turns watching. Their instructions were simple: if you see the enemy fleet, or if you see the next beacon burning, light yours.","On 19 July 1588, by the calendar England used at the time (29 July by the calendar we use today), lookouts spotted the Armada off the Lizard, the southernmost tip of Cornwall. The fires began. The warning raced eastward and inland, from hill to hill, across Devon and Dorset and along the high chalk ridges of Sussex, toward London. Local histories name some of the hills in the chain, such as Ditchling Beacon and Firle Beacon in Sussex. Nobody today knows exactly how many beacons were actually lit or precisely how long the message took, but the system was designed to beat any horse by a huge margin.","Each fire did more than send news. It was also an alarm clock for a whole region. When the local beacon flared, militia men knew to grab their weapons and gather at agreed meeting points, and coastal towns knew to prepare their defences. The Armada itself was battered by English ships and later wrecked by terrible storms as it sailed home around Scotland and Ireland, and the invasion never happened.","You can still see traces of this system today. Many hills across England are called Beacon Hill, a clue that a signal fire once stood there. In 1988, for the 400th anniversary, people lit 461 beacons and bonfires across England and Wales, starting at Kynance Cove in Cornwall. The chain of flames reached Berwick-upon-Tweed in the far north of England in about 18 minutes."]},{"heading":"Drums That Speak","paragraphs":["Fire and smoke speak to the eyes. Now let us listen with our ears, in West Africa, where people developed something much cleverer than a simple alarm: drums that could imitate speech itself.","To understand how, you need to know a secret about many West African languages, such as Yoruba in what is now Nigeria and Twi, spoken by the Akan people of what is now Ghana. They are tonal languages. In a tonal language, the pitch of your voice, whether a syllable is said high, middle or low, changes the meaning of a word. In English, if you say 'cat' in a high voice or a low voice, it is still a cat. In Yoruba, two words with exactly the same consonants and vowels can mean completely different things depending on their tones. Yoruba uses three main tones: high, mid and low.","That means the 'tune' of a sentence carries a lot of its meaning. And a drum can play a tune. The most famous talking drums, such as the Yoruba dùndún, are shaped like an hourglass, wide at both ends and narrow in the middle. A drumhead made of skin covers each end, and the two heads are connected by many leather cords running down the sides. The drummer tucks the drum under one arm and hits it with a curved stick. By squeezing the cords with the arm, the drummer tightens the drumheads and the note goes higher. Relaxing the arm loosens them and the note goes lower. A skilled player can even slide the pitch during a single beat, so the drum seems to swoop and wobble like a voice.","The drum cannot make vowels or consonants, but it can copy the pitch, rhythm and loudness of speech. For listeners who grew up with the language, that pattern can be enough to recognise words and phrases. Among the Asante, part of the Akan people, a pair of large drums called atumpan was used for important messages and for 'speaking' at royal ceremonies, reciting proverbs and the praises of rulers.","There was still a problem: lots of different words share the same tone pattern. Drummers solved this with extra words. An English missionary named John F. Carrington, who lived for many years in what is now the Democratic Republic of the Congo and learned to drum himself, explained this in his 1949 book The Talking Drums of Africa. Drummers did not just beat a short word. They wrapped it in a longer, fixed phrase that could only fit one meaning, a bit like saying 'the moon that looks down at the earth' instead of just 'moon'. The extra beats made the message longer, but much harder to misunderstand. In some communities, each person had their own 'drum name', so a drummer could call a particular person by beating their name, followed by the sender's name and then the message.","How far could a drum talk? Under good conditions, a big drum could be heard several kilometres away, often reported as around 6 to 8 kilometres (4 to 5 miles), especially in the still air of evening. Drummers in the next village could then pass the message on, so news could travel much farther than one drum could reach. Talking drums are still played today, at festivals, in ceremonies and in popular music, and they are one of the best examples in history of people turning the patterns of human speech into another kind of signal. That idea, turning speech into a signal that can travel, sits at the very heart of the telephone."]},{"heading":"Runners and Riders","paragraphs":["Signals like fire and drums are fast, but they can only carry simple or carefully coded messages. If a ruler wanted to send a detailed order, a long letter or a report full of numbers, someone had to carry it. The great empires of the ancient world discovered that the trick was not to find one superhuman messenger. The trick was teamwork: a relay.","In ancient Persia, the Achaemenid Empire of rulers like Cyrus the Great and Darius the Great stretched from what is now Turkey to the borders of India. To hold this huge empire together, the Persians used the Royal Road, running about 2,700 kilometres (1,700 miles) from the city of Sardis, in western Turkey, to Susa, one of the royal capitals in what is now Iran. Along it stood relay stations about a day's ride apart, with fresh horses, food and riders. The Greek historian Herodotus, writing around 440 BCE, counted 111 stations along this road. A royal message was handed from rider to rider, so it never had to wait for a tired horse. Estimates suggest it could cross the whole road in about nine days, while an ordinary traveller on foot would need roughly 90.","Herodotus was so impressed that he wrote a line praising these riders, saying that nothing stopped them from finishing their stage, not snow, nor rain, nor heat, nor darkness. More than 2,300 years later, a version of his words was carved on the front of a large post office building in New York City, where it is often thought of as an unofficial motto of American mail carriers.","On the other side of the world, the Inca Empire built an even more amazing network in the steep Andes mountains of South America. Its roads, called the Qhapaq Ñan, stretched about 40,000 kilometres (25,000 miles) through lands that are now parts of Peru, Ecuador, Bolivia, Chile, Argentina and Colombia, climbing over passes, across deserts and over rope bridges hung above deep gorges. The Inca had no horses and no wheeled carts. So they used human legs, organised brilliantly.","The messengers were called chasqui (also spelled chaski). Small huts stood beside the road at short intervals; most Spanish chroniclers described them as about half a league apart, roughly 2.5 kilometres, though others gave different figures. Runners waited at each hut. When a chasqui approached, he blew a trumpet made from a conch shell, called a pututu, so the next runner could get ready. As they ran side by side for a few steps, the first runner repeated the spoken message until the second had it right, or handed over a quipu. A quipu (or khipu) was a bundle of coloured strings with knots in particular positions. It mainly recorded numbers, like how much a village owed in taxes or how many soldiers to send, and trained record-keepers, rather than the runners themselves, were the experts at reading them.","Because each runner only sprinted a short stage and then rested, the message never slowed down. Sources often say the chasqui system could carry a message around 240 kilometres (150 miles) in a day, and some estimates go even higher. One Spanish chronicler, Martín de Murúa, wrote that runners brought fish from the sea to the ruler in Cusco, high in the mountains, while it was still fresh. That is a report written by a chronicler after the Spanish conquest, so treat it with care, but it shows how impressive the system seemed to people who saw it.","And what about the most famous messenger story of all? You may have heard that after the Battle of Marathon in 490 BCE, when the Athenians defeated a Persian army, a runner called Pheidippides dashed about 40 kilometres to Athens, cried out the news of victory, and collapsed dead. It is a wonderful story, and it inspired the marathon race at the first modern Olympic Games in 1896. But it is a legend. Herodotus, who wrote within living memory of the battle, tells a different story: that before the battle, Pheidippides, a professional runner, was sent from Athens to Sparta to ask for help, covering about 240 kilometres in roughly two days. The tale of the run from Marathon to Athens and the dramatic death only appears in writers who lived around 500 years or more after the battle, and it became truly famous through a poem by Robert Browning in 1879. So: the Sparta run comes from our oldest source, while the deadly dash to Athens is best thought of as a legend."]},{"heading":"Messages on Wings","paragraphs":["There was one more messenger in the ancient world that could beat any runner or horse over long distances, and it did not need roads at all: the pigeon.","Homing pigeons have an astonishing ability. If you take one far from its home loft and release it, it will usually fly straight back home, often across hundreds of kilometres of unfamiliar land. Scientists still study exactly how they do it; pigeons seem to use the position of the Sun, Earth's magnetic field and landmarks, and possibly smells and very low sounds as well. People noticed this talent thousands of years ago, and some evidence suggests messages were being carried by pigeons in ancient Egypt more than 3,000 years ago.","The method is simple, but it has a catch. You tie a tiny, light message to the bird's leg and let it go, and it flies home. That means pigeons only carry messages in one direction: toward their home loft. To send news from a distant city back to your capital, you first had to carry pigeons from the capital to that city, in cages on horseback or by ship, and keep them there until needed.","Even so, pigeon post was used for an extremely long time. Roman writers mention pigeons carrying messages during a siege at Mutina, in northern Italy, in 43 BCE. In the Middle East, pigeon post became highly organised; by the 1100s CE, rulers had set up regular pigeon services linking Baghdad with cities in Syria, with lofts and keepers along the routes. A good homing pigeon can average roughly 80 to 95 kilometres per hour (50 to 60 miles per hour) over long flights, far faster than a horse can keep up for hours on end.","Pigeons had their own weak spots, though: they could be shot down or caught by hawks, they could get lost in storms, they would only fly home, and they could carry only a very small load."]},{"heading":"Why None of It Was Enough","paragraphs":["Let us line up everything we have seen and give each system an honest report card.","Beacon fires and smoke signals were incredibly fast, because they used light. But they were blind in fog, rain and snow; smoke was useless at night and small fires were hard to see by day. They needed teams of watchers sitting on cold hilltops for weeks or months, waiting for something that might never happen. Worst of all, they could say very little: usually a yes-or-no warning, or a handful of codes agreed in advance. If something happened that nobody had planned a signal for, the beacons were silent.","Talking drums could send real phrases, but only to listeners who knew the language and the drum's special phrases, and only as far as the sound carried, often a few kilometres. Wind, rain and the noise of everyday life could drown them out.","Relay runners and riders could carry long, detailed messages and even objects, but they were limited by the speed of legs, hooves and roads. The best relay systems in history could move a message a few hundred kilometres in a day. That is amazing for a human team, but it meant news from a far corner of an empire could still be weeks old by the time it arrived. Rivers flooded, bridges collapsed, messengers fell ill or were captured.","Pigeons were quick, but they only flew one way, carried tiny loads and did not always arrive.","So by the 1700s, after thousands of years, humanity was stuck. Messages over long distances were either fast but simple, or detailed but slow. Nobody had found a way to send a detailed message quickly over a long distance, in any weather, by day or night. And absolutely nobody could send the sound of their actual voice farther than they could shout.","But the world was changing. The 1700s were the age of the Enlightenment, when scientists and inventors were measuring, testing and questioning everything. Telescopes were getting better, making it possible to see small details on a far-off hill. In France, a revolution was about to tear the old kingdom apart and leave the new government desperate for fast news from its armies at the borders. And in a small town in the French countryside, a young man and his brothers were wondering: what if, instead of one fire meaning one thing, you built towers with big moving arms that could spell out whole sentences? What if a message could fly faster than any runner, not by fire, but by shape? In the 1790s, Claude Chappe was about to find out."]}],"deepDive":"Historians of communication often describe all the systems in this part with two measurements that engineers still use today: speed (how quickly a signal crosses a distance) and capacity (how much information it can carry). Ancient methods were forced to trade one for the other. A beacon signal moved at the speed of light between stations, but the real delay came from people: a watcher had to notice the fire and then light their own, which takes minutes. Even so, a well-run chain could cross hundreds of kilometres in about an hour, as modern tests of the Byzantine line suggest. Its capacity, however, was tiny. A single fire carries one bit of information (yes or no). The Byzantine water-clock trick raised this to one of twelve messages, about 3.6 bits, by adding time as a second dimension. Aeneas Tacticus's water telegraph did something similar, using the time between torch signals to select one message from a prepared list. Polybius's alphabet grid was a conceptual leap, because it could in principle spell anything, but it was painfully slow. Relay couriers had the opposite profile: huge capacity (a whole letter, a quipu full of numbers, even goods) but low speed, a few hundred kilometres per day at most. Historians also debate how reliable some famous numbers are. Figures for chasqui speed come mainly from Spanish chroniclers writing after the conquest and from modern estimates, and they range from about 240 to over 300 kilometres per day, partly because sources disagree on how far apart the relay huts were. Herodotus's count of 111 stations on the Royal Road is respected but cannot be checked directly. Literary sources need special care: Aeschylus's beacon chain tells us what fifth-century Athenians found believable, not what happened at Troy, and the Marathon-to-Athens death run grew from much later writers such as Plutarch and Lucian before Robert Browning's 1879 poem fixed it in popular memory. Talking drums raise a different question that linguists find fascinating: they show that a language's tones alone can carry enough information to be understood, if extra 'redundant' phrases are added to remove ambiguity. Engineers would recognise this as an early example of error correction, the same principle that helps modern phones repair scrambled data.","funFact":"When England lit 461 beacons in 1988 to mark the 400th anniversary of the Spanish Armada, the chain of fires ran from Cornwall to Berwick-upon-Tweed in about 18 minutes.","check":{"q":"How did a Yoruba talking drum copy the sound of speech?","a":"The drummer squeezed the cords to change the pitch, copying the tones and rhythm of the tonal language","wrong":["It played a recording of a person's voice","It made vowel and consonant sounds exactly like a mouth","Each beat stood for one letter of the alphabet"]},"sources":[{"title":"Chasqui","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chasqui"},{"title":"Talking drum","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Talking_drum"},{"title":"Angarium (Chapar Khaneh)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Angarium"},{"title":"Pheidippides","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pheidippides"},{"title":"Byzantine beacon system","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Byzantine_beacon_system"},{"title":"Hydraulic telegraph","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hydraulic_telegraph"},{"title":"Homing pigeon","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Homing_pigeon"},{"title":"Britain fetes Armada defeat ... minus a myth","publisher":"The Christian Science Monitor","url":"https://www.csmonitor.com/1988/0808/oarma.html"}],"photos":[{"src":"img/deep/telephone/01-1.jpg","alt":"Guaman Poma's drawing (about 1615) of an Inca chasqui messenger blowing a conch-shell trumpet.","file":"A chaski, 1615.jpg","url":"https://commons.wikimedia.org/wiki/File:A_chaski,_1615.jpg","author":"Felipe Huaman Puma de Ayala","license":"Public domain"},{"src":"img/deep/telephone/01-2.jpg","alt":"An hourglass-shaped West African talking drum, with leather cords that tighten the drumhead to change its pitch.","file":"Talking drum made by me.jpg","url":"https://commons.wikimedia.org/wiki/File:Talking_drum_made_by_me.jpg","author":"Danotech","license":"CC BY-SA 4.0"},{"src":"img/deep/telephone/01-3.jpg","alt":"The worn rammed-earth remains of a Great Wall beacon tower standing on a hill in northern China.","file":"Great Wall Beacon Tower - panoramio.jpg","url":"https://commons.wikimedia.org/wiki/File:Great_Wall_Beacon_Tower_-_panoramio.jpg","author":"danmairen","license":"CC BY-SA 3.0"}],"words":4376},{"n":2,"title":"Towers with Arms and Sparks in a Jar","when":"1790s – 1830s","summary":"In France, Claude Chappe and his brothers built tall towers with giant moving wooden arms that spelled out messages from hilltop to hilltop, faster than any horse. At the same time, scientists were discovering amazing things about electricity: how to store it in a battery, how it can wiggle a compass needle, and how it can turn a coil of wire into a magnet. Soon people began to wonder whether electricity could carry messages instead.","sections":[{"heading":"The Boys from Brûlon","paragraphs":["At the end of the last part, we left humanity stuck: messages could be fast but simple, like a beacon fire, or detailed but slow, like a relay runner. Our story now moves to a small town in the west of France called Brûlon, and to a family of five brothers who decided to break that rule.","Claude Chappe was born in Brûlon on 25 December 1763, Christmas Day. His family was comfortably well off, and young Claude was raised for a career in the Catholic Church, a common path for younger sons of respectable families in those days. He also grew up hearing about an exciting uncle, the astronomer Jean-Baptiste Chappe d'Auteroche, who had travelled as far as Siberia and Mexico to observe the planet Venus passing across the face of the Sun. Claude loved science, especially physics, and he experimented whenever he could.","Then, in 1789, the French Revolution exploded. The old system of kings, nobles and church privileges was overturned, and Claude lost the church income he had been expecting. Suddenly he and several of his brothers had a great deal of free time and not much money. They put their brains together on a single problem: how to send messages long distances, fast.","Their first ideas were surprisingly modern. One early plan used two clocks whose hands moved in perfect step, one at each end. When the hand on the sender's clock pointed at a certain number, the sender made a loud noise or a visible signal; the receiver looked at where his own clock's hand was pointing at that moment and wrote down that number. Each number stood for a word in a codebook. Notice the trick: just like the Byzantine water clocks in Part 1, it used time to choose between many messages.","On 2 March 1791, the brothers held a public test between Brûlon and the village of Parcé, about 16 kilometres (10 miles) away. They used synchronised pendulum clocks and a large panel that could be flipped to show black or white. Local officials watched as a message chosen on the spot was sent from one town and correctly written down in the other, by a brother who had no idea what was coming. It worked. Now the Chappes needed something bigger, clearer and faster, and they needed the government to pay for it."]},{"heading":"A Telegraph for a Nation at War","paragraphs":["Luckily for the Chappes, one brother, Ignace, was elected to the new Legislative Assembly in Paris. He helped Claude present the idea to the lawmakers in 1792. The timing was perfect, though in a frightening way. Revolutionary France was going to war with Austria, Prussia, Britain and others. French armies were fighting on several borders at once, and news from the front could take days to reach Paris by horse. The government badly needed a faster way to send orders and get reports.","There were setbacks. The brothers built trial equipment in Paris, and twice crowds smashed it. In those nervous revolutionary days, people suspected that strange signalling machines might be used to send secret messages to the king's supporters. Inventing can be dangerous when nobody understands what you are building.","Claude also needed a name for his invention. He first called it the 'tachygraphe', from Greek words meaning 'fast writer'. A government official named André François Miot de Mélito suggested another name, built from Greek words meaning 'far writer': télégraphe. That is the word we still use today, and you will meet it again and again in this Deep Dive, because every telegraph, and in a sense every telephone, owes its name to Chappe's towers.","In 1793 the revolutionary government, the National Convention, approved a line of towers from Paris to Lille, a fortress city near the northern border where French armies were fighting. Claude was given an official title as a telegraph engineer, and the brothers raced to build it. The line was about 230 kilometres (140 miles) long and used a chain of around fifteen stations, each built on a high spot where it could see its neighbours. It began working in 1794.","Its big moment came that summer. In August 1794, French troops recaptured the towns of Le Quesnoy and then Condé-sur-l'Escaut from the Austrians. The news flew down the line of towers and reached the Convention in Paris in well under an hour, when a rider on horseback would have needed roughly a day. Lawmakers were thrilled. Imagine the excitement: for the first time in history, a detailed message, with names of places and real news, had crossed more than 200 kilometres in less time than it takes to eat lunch."]},{"heading":"How to Talk with Wooden Arms","paragraphs":["So how did a Chappe tower actually work? Picture a small stone building on top of a hill, often with a little room for the operators to live and work in. Rising from its roof is a tall wooden mast. At the top of the mast is a long horizontal beam called the regulator, about 4.6 metres (15 feet) long. At each end of the regulator is a shorter arm called an indicator, about 2 metres long. All three pieces are painted black so they stand out against the sky, and they are made like slatted shutters so the wind blows through them instead of snapping them.","Down inside the room, an operator works a set of handles, ropes and pulleys that turn the regulator and the two indicators into different angles. The regulator can be horizontal or vertical. Each indicator can point in one of seven clear positions. If you multiply the choices together, 2 times 7 times 7, you get 98 different shapes the machine can make. A few of these were saved for special 'housekeeping' signals, such as 'error' or 'start of message', leaving 92 for the message itself.","Ninety-two shapes is a lot more than a beacon fire's single 'yes' or 'no', but it is still not enough to spell every word quickly. So the system used a codebook. Later versions of the code had 92 pages, each with 92 numbered words or phrases, for a total of 8,464 entries. To send a word, the operator first sent a shape meaning the page number, then a second shape meaning the line on that page. Two signals could stand for a whole word or even a common phrase, which saved huge amounts of time.","Each station had a telescope pointing at the next tower in each direction. One operator watched the incoming tower through the telescope and called out each new shape, and the operator at the handles copied it so that the next station down the line could see it. Then everyone waited for the next tower along to copy the signal too, before sending the following one. In good weather, a short message could ripple the whole way from Paris to Lille in about nine minutes, and an experienced team could send two or three signals a minute.","Here is a clever security detail: most of the operators in the towers did not know what the messages said. They only copied shapes. The codebooks were kept by officials at the main stations at each end of the line. That made the system harder to spy on, because capturing one tower would not reveal the secrets. As we will see, it did not make it impossible to cheat."]},{"heading":"An Empire of Towers","paragraphs":["After Lille, the towers spread. New lines stretched from Paris toward Strasbourg in the east, Brest on the Atlantic coast, and on toward Lyon, Marseille, Bordeaux and the borders. A message that took a galloping courier about four days to carry from Strasbourg to Paris could, in good weather, arrive by telegraph in a couple of hours.","Napoleon Bonaparte, who seized power in 1799 and later crowned himself emperor, understood the value of fast news better than almost anyone. He used the telegraph to coordinate his armies and to keep control of his huge empire. As French power grew, lines reached into conquered or allied lands, as far as Amsterdam, Mainz in Germany and Venice in Italy. Abraham Chappe, one of the brothers, even designed a portable telegraph that could travel with an army on campaign.","Other countries quickly built their own systems. In Sweden, an inventor named Abraham Niclas Edelcrantz tested an optical telegraph near Stockholm in 1794. His design used a frame of hinged shutters that could each be opened or closed, a little like a pattern of on-off switches. Sweden's network grew to about 50 stations, and some parts kept working until 1881. In Britain, the Royal Navy adopted a shutter telegraph designed by Lord George Murray in 1795, linking the Admiralty in London to the port of Deal on the Kent coast, so orders could reach the fleet quickly. Later a semaphore line with movable arms linked London and the great naval base at Portsmouth from 1822 to 1847; in clear weather, a signal could pass along it in a few minutes. Spain and Russia built lines as well; the Russian line between Moscow and Warsaw, opened in 1833, had about 220 stations.","France's own network kept growing for decades. By 1844 it had more than 530 towers linking 29 cities across more than 5,000 kilometres (over 3,000 miles), and at its largest it had around 550 stations. It was the first nationwide telecommunications network in history, built more than half a century before the telephone.","But it also brought a brand-new kind of crime. Between 1834 and 1836, two brothers from Bordeaux, François and Louis-Joseph Blanc, bribed telegraph operators to slip hidden signals into official messages, sending news of stock market prices from Paris to Bordeaux faster than the regular mail. That let them make money by trading before other investors knew what had happened. When they were caught, the court found them not guilty of the main charge because no law yet forbade misusing the telegraph like this. France soon passed laws to fix that gap. A few years later, the novelist Alexandre Dumas made a telegraph trick part of the plot of his famous book The Count of Monte Cristo, in which the Count bribes an operator to send a false message.","For all its success, the optical telegraph had serious limits. It was useless in fog, heavy rain or snow, and it could not work in the dark, so night shut it down completely. A long line needed dozens of towers, each with operators who had to be paid, housed and fed. The towers had to be in sight of each other, which meant building on hills and sometimes in awkward, lonely spots. It was also expensive and slow to extend, and it was used mostly by the government, not ordinary people. Even at its best, a long message still took many minutes or even hours to work through all those page-and-line signals.","Claude Chappe did not live to see most of this. He died in Paris in January 1805, aged 41, after a period of poor health and bitter quarrels with rivals who claimed he had copied their ideas. His brothers kept the network running for many years. It was finally replaced in the late 1840s and 1850s by something even faster, a system that did not care about fog or darkness at all. To understand where that came from, we need to leave the hilltops and step into the laboratories of Europe."]},{"heading":"Frogs' Legs and a Pile of Discs","paragraphs":["In the 1700s, electricity was a mysterious and exciting show. Scientists could make it by rubbing glass or amber, which creates static electricity, the same thing that crackles when you pull off a wool jumper. In the 1740s, experimenters in Germany and in the Dutch city of Leiden discovered they could store a charge in a glass jar lined with metal foil. This 'Leyden jar' could hold enough electricity to give a painful jolt, and entertainers used chains of them to shock lines of people holding hands. In 1752 Benjamin Franklin famously argued that lightning itself was a giant electric spark.","But there was a problem for anyone who wanted to use electricity for something useful. A Leyden jar released all its electricity in one quick spark, and then it was empty. It was like a water balloon: one splash and done. To do real work, you would need electricity that kept flowing steadily, like water from a tap. That is what we call an electric current.","The first step toward steady current began with frogs. In the 1780s, an Italian doctor named Luigi Galvani, working in Bologna, noticed that the legs of dead frogs twitched when touched by two different metals. Galvani believed the electricity came from inside the animal, and he called it 'animal electricity'. Another Italian scientist, Alessandro Volta, a physics professor at the University of Pavia, was not convinced. Volta suspected that the electricity came from the two different metals touching through something wet, and that the frog's leg was simply acting as a sensitive detector.","To prove his point, Volta built something with no frog at all. He stacked up small discs in a repeating pattern: a disc of zinc, a disc of copper or silver, and a piece of cardboard or cloth soaked in salty water, then zinc, copper, wet cardboard again, over and over, in a tall column. When he connected the top and bottom of the pile with a wire, a steady electric current flowed. Each zinc and copper pair produced only a small push, well under one volt in today's units, but stacking many pairs added their pushes together, so a tall pile gave a much stronger current.","Volta described his invention in a letter dated 20 March 1800 to Sir Joseph Banks, the president of the Royal Society in London, and it was published later that year. It became known as the voltaic pile, and it was the first electric battery. The news spread fast. Within weeks, two English scientists, William Nicholson and Anthony Carlisle, used a pile to split water into hydrogen and oxygen gases. A few years later, Humphry Davy in London used enormous batteries to discover new chemical elements such as sodium and potassium. Volta was invited to Paris in 1801 to demonstrate the pile, and Napoleon himself came to see it and later honoured him. Today the unit of electrical push, the volt, is named after him.","For our story, the battery mattered because it was the first reliable source of steady electric current. With a battery, you could push electricity through a wire for minutes or hours, instead of in a single spark. That opened the door to everything that followed, from telegraphs to telephones to the phone in your pocket, which still runs on a battery whose basic idea goes back to Volta's stack of discs."]},{"heading":"The Needle That Twitched","paragraphs":["For centuries, people had known about two invisible forces. One was magnetism, which makes compass needles point north and lets a magnet pick up iron nails. The other was electricity, which makes sparks and shocks. Many scientists suspected they were related, but nobody could show a clear connection.","In Copenhagen, Denmark, a physics professor named Hans Christian Ørsted had been hunting for the link for years. In 1820, he set up a wire connected to a battery and placed a magnetic compass near it. When the current flowed through the wire, the compass needle swung sideways, away from north. When the current stopped, the needle swung back. When he reversed the direction of the current, the needle swung the other way.","That simple twitch was one of the most important moments in the history of science. It proved that an electric current creates a magnetic force around it. In July 1820, Ørsted sent a short report about his experiments to scientists across Europe, and they rushed to repeat them. In Paris, André-Marie Ampère worked out within weeks how currents in wires push and pull on each other, creating a whole new science that came to be called electrodynamics. In Germany, Johann Schweigger wrapped a wire around a compass in many loops, which made the needle much more sensitive to even a tiny current. His device, an early galvanometer, could detect electricity that was far too weak to feel or see.","Now think like an inventor. If a current in a wire can make a needle move, and you can switch the current on and off with your hand, then you can make a needle move from far away. A needle that swings left or right could be a signal. Ampère himself suggested in 1820 that needles and wires might be used to send messages. An English mathematician named Peter Barlow tested the idea in 1825 and found the signal grew too weak after only about 60 metres (200 feet) of wire, so he declared it impractical. He turned out to be wrong, but solving that problem would take better batteries, better wires and better magnets."]},{"heading":"Magnets You Can Switch On","paragraphs":["In 1825 an English inventor named William Sturgeon took Ørsted's discovery one step further. He wrapped wire loosely around a horseshoe-shaped piece of iron coated in varnish. When he sent a current through the wire, the iron became a magnet strong enough to lift several kilograms. When he switched off the current, the iron let go. He had built the first electromagnet: a magnet you could turn on and off with a switch.","Across the Atlantic, in Albany, New York, a young teacher named Joseph Henry, born in 1797, set out to make electromagnets far stronger. Sturgeon's wire was bare, so the loops could not touch each other without short-circuiting. Henry insulated his wire by wrapping it in silk thread, and that let him wind hundreds of tightly packed turns around the iron. The more turns, the stronger the magnet. By 1831 Henry had built an electromagnet that could lift about 750 pounds (340 kilograms) of iron, and he also built an even more powerful one for Yale College.","Henry also learned how to match his batteries and coils to the job. He found that a magnet at the end of a long wire worked best with a battery made of many cells joined end to end, which gave a stronger electrical push, and a coil with many turns of thin wire. In 1831, working at the Albany Academy where he taught, he strung a long wire around a room and used it to make a small electromagnet at the far end tap a bell. Accounts differ about how long the wire was, from a few hundred metres up to about a mile, but the point was clear: you could ring a bell at a distance by closing a circuit. Henry published his findings and did not patent them, and his ideas helped later telegraph builders. He went on to become the first secretary of the Smithsonian Institution in 1846, and the unit of a property called inductance, the henry, is named after him.","Meanwhile in London, Michael Faraday was asking the opposite question. Faraday had grown up poor, the son of a blacksmith, and left school early to work as a bookbinder's apprentice. He read the science books he was binding, went to lectures by the famous chemist Humphry Davy, and in 1813 managed to get a job as Davy's assistant at the Royal Institution. In 1821 he showed that a wire carrying current could be made to spin around a magnet, the basic idea behind every electric motor.","If electricity could make magnetism, Faraday wondered, could magnetism make electricity? For years his experiments failed. Then, in August 1831, in his basement laboratory at the Royal Institution, he wound two separate coils of insulated copper wire on opposite sides of an iron ring about 17 centimetres (7 inches) across. One coil was connected to a battery. The other was connected to a galvanometer, the needle detector. On 29 August 1831, he connected the battery. The needle on the other coil flicked, just for a moment, then went still. When he disconnected the battery, it flicked again, the other way. Over the next weeks he showed that pushing a magnet into a coil of wire, or pulling it out, also made a current flow.","Faraday had discovered electromagnetic induction: a changing magnetic field creates an electric current in a nearby wire. Joseph Henry had noticed similar effects in Albany at around the same time, but Faraday published first, so he usually gets the credit for the discovery. Faraday's iron ring, which is still kept at the Royal Institution, is often called the first transformer. Induction would one day power generators, transformers and electric grids, and, much later in our story, it would also play a starring role in the first telephones. Keep it in mind."]},{"heading":"Lightning in a Wire","paragraphs":["By the early 1830s, all the pieces were on the table. Volta's battery could push a steady current. Ørsted and Schweigger had shown that a current could move a needle, even a very weak current. Sturgeon and Henry had built electromagnets that could switch on and off, strong enough to pull a lever or ring a bell. Faraday had shown how electricity and magnetism could create each other.","And there was one more amazing fact. Electrical signals in a wire travel extraordinarily fast, close to the speed of light in the best cases and still enormously fast in ordinary wires. Compare that with Chappe's towers, where each operator needed time to see and copy every shape, or a relay rider, who could manage perhaps a few hundred kilometres in a day. Electricity did not care about fog. It did not stop for darkness. It did not need a hilltop with a clear view, only a wire. The big question became obvious: could electricity carry messages?","Inventors had actually been trying for a while, with mixed results. As early as 1774, Georges-Louis Le Sage in Geneva built a static-electricity telegraph with a separate wire for each letter, but it only worked between rooms of his house. In 1809 Samuel Thomas von Sömmerring in Germany built a telegraph that used Volta's new battery. Each letter had its own wire ending in a tube of acidic water, and when current flowed, bubbles rose beside the chosen letter. It needed around 35 wires and worked over a few kilometres, but it was far too clumsy to be practical. In 1816 an Englishman named Francis Ronalds built a working static-electricity telegraph in his garden in Hammersmith, London, using about 13 kilometres (8 miles) of wire. When he offered it to the Admiralty, which was happy with its optical shutter telegraph, he was told that such a device was 'wholly unnecessary'.","After Ørsted's discovery, the experiments got better. In 1832 Pavel Schilling, a diplomat working in St Petersburg for the Russian government, demonstrated a needle telegraph between two rooms of his apartment. In 1833 the great German mathematician Carl Friedrich Gauss and the physicist Wilhelm Weber strung a wire about 1,200 metres long over the rooftops of the town of Göttingen to connect their observatory and their physics laboratory, and sent messages using a code of left and right swings of a needle. These were brilliant experiments, but none of them yet became a public business.","That was about to change. Railways were spreading fast across Britain and soon America, and railway companies desperately needed a way to tell the next station that a train was coming. Businesses wanted prices and news faster. Governments wanted to talk to distant cities. The ingredients were ready: batteries, wires, needles and electromagnets. All that was missing was someone to turn a laboratory trick into a practical system that ordinary people could pay to use. In the late 1830s, inventors in Britain and America were racing to make electricity write messages along a wire, and the age of the electric telegraph was about to begin."]}],"deepDive":"The Chappe telegraph is a favourite example for historians of technology because it already had many features of modern networks. Its 98 arm positions, minus six control signals, gave 92 usable symbols, and the two-step codebook (page, then line) gave 92 times 92, or 8,464, possible words and phrases. Information scientists would say each symbol carried about 6.5 bits, and a skilled crew sending two or three symbols a minute achieved roughly 15 to 20 bits per minute along a whole line, hundreds of millions of times slower than a modern home internet connection, yet revolutionary in 1794. The real bottleneck was human: each station had to observe, copy and confirm every symbol, so speed depended on the number of stations and the weather. The system also showed problems that never went away. The Blanc brothers' fraud in the 1830s is one of the earliest documented cases of insider trading using a telecommunications network, and France's response, making unauthorised use of the telegraph a crime, is an early example of communications law. The scientific side of this period raises questions of credit that historians still discuss. Ørsted's 1820 discovery is sometimes told as a lucky accident during a lecture, but he had been searching for a link between electricity and magnetism for years, and historians debate how planned the moment was. Joseph Henry and Michael Faraday both observed electromagnetic induction around 1830 to 1831; Faraday published first and systematically, so priority is usually given to him, while Henry is credited with discovering self-induction, published in 1832. Henry's long-wire bell experiment is reported with different wire lengths, from about 300 metres to about 1.6 kilometres, so it is best described as 'a long wire'. Finally, the many pre-1837 electric telegraphs, from Le Sage and Sömmerring to Ronalds, Schilling, and Gauss and Weber, show that the electric telegraph had no single inventor. What changed after the mid-1830s was not the basic idea but practical engineering, business backing and the sudden demand created by railways.","funFact":"The word 'telegraph', meaning 'far writer', was first used for Claude Chappe's wooden-armed towers, decades before any electric telegraph existed.","check":{"q":"Why was Volta's pile so important for sending messages by electricity?","a":"It was the first battery, giving a steady electric current instead of a single spark","wrong":["It could send light signals between hilltops","It stored messages written in Morse code","It made compass needles point north"]},"sources":[{"title":"Chappe telegraph","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chappe_telegraph"},{"title":"Optical telegraph","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Optical_telegraph"},{"title":"Claude Chappe","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Claude_Chappe"},{"title":"Voltaic pile","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Voltaic_pile"},{"title":"Hans Christian Ørsted","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hans_Christian_%C3%98rsted"},{"title":"Michael Faraday's ring-coil apparatus","publisher":"The Royal Institution","url":"https://www.rigb.org/node/143"},{"title":"Joseph Henry","publisher":"Edison Tech Center","url":"https://edisontechcenter.org/JosephHenry.html"},{"title":"Electrical telegraph","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Electrical_telegraph"}],"photos":[{"src":"img/deep/telephone/02-1.jpg","alt":"A restored Chappe optical telegraph tower near Saverne, France, with its signal arms on a mast on top.","file":"Tour du telegraphe Chappe Saverne 02.JPG","url":"https://commons.wikimedia.org/wiki/File:Tour_du_telegraphe_Chappe_Saverne_02.JPG","author":"Hans-Peter Scholz Ulenspiegel","license":"CC BY-SA 2.0 de"},{"src":"img/deep/telephone/02-2.jpg","alt":"A modern museum reproduction of Volta's 1800 pile: a column of metal discs, the first electric battery.","file":"Reproduction of first electric Voltaic Pile cr56n2016 47429b20d dl full size.jpg","url":"https://commons.wikimedia.org/wiki/File:Reproduction_of_first_electric_Voltaic_Pile_cr56n2016_47429b20d_dl_full_size.jpg","author":"Staff photographer","license":"Public domain"},{"src":"img/deep/telephone/02-3.jpg","alt":"Michael Faraday's iron ring wrapped in wire coils, which he used to discover electromagnetic induction in 1831.","file":"Faraday ring transformer.jpg","url":"https://commons.wikimedia.org/wiki/File:Faraday_ring_transformer.jpg","author":"Unknown author","license":"Public domain"}],"words":4291},{"n":3,"title":"Lightning Messages: The Electric Telegraph","when":"1830s – 1860s","summary":"In the 1830s and 1840s, inventors in Britain and America finally made electricity carry messages along a wire. Little needles twitched, keys clicked, and the news that once took days by horse now arrived in a blink. Soon wires followed the railways across whole countries.","sections":[{"heading":"A Race on Two Sides of the Ocean","paragraphs":["By the 1830s, scientists knew three exciting things. A battery could push a steady electric current through a wire. That current could make a compass needle swing. And a coil of wire wrapped around iron became a magnet whenever electricity flowed through it. Put those clues together and a thrilling question appears: if you switch a current on and off at one end of a long wire, could someone at the other end see or hear it, and read a message?","Many people tried to answer that question at almost the same time. In Russia, the diplomat Pavel Schilling built a needle telegraph in the early 1830s. In the German town of Göttingen, the famous mathematician Carl Friedrich Gauss and the physicist Wilhelm Weber strung a wire about a kilometre long over the rooftops in 1833 so they could signal between the observatory and the physics laboratory. None of these became a big public system, but they proved the idea could work.","The two names that history remembers most are from Britain and the United States. In London, a businessman named William Fothergill Cooke teamed up with a scientist named Charles Wheatstone. In New York, a painter named Samuel Morse worked with a young mechanic named Alfred Vail and several helpers. Each team built a different kind of telegraph, and each one changed its country. So when people ask who invented the electric telegraph, the honest answer is: quite a few people, building on each other's discoveries, racing in different places at the same time.","The word telegraph comes from Greek words meaning far writing. The Chappe brothers had already used it for their tower-and-arm system in France. Now the far writing was going to be done by electricity, and electricity moves along a wire so fast that, for a message travelling between two cities, the delay is far too small for any person to notice."]},{"heading":"Five Needles, a Railway and a Famous Arrest","paragraphs":["William Cooke was not a scientist at first. He had been an officer in the army in India and was studying medicine in Germany when, in 1836, he saw a professor at Heidelberg demonstrate an electric needle telegraph based on Schilling's work. He hurried back to England full of plans. He soon realised he needed help with the science, so in 1837 he went to see Charles Wheatstone, a professor at King's College London who was already experimenting with sending electric signals through long wires. Wheatstone was a clever, shy man who also invented a small musical instrument called the concertina and an early 3D viewer called the stereoscope.","Their two personalities did not always get along, and later they argued bitterly over who deserved more credit. But together they received a British patent in 1837 for a needle telegraph. Picture a wooden board shaped like a diamond, with the letters of the alphabet painted on it in a grid. Across the middle of the board stand five magnetic needles, each one able to swing left or right. When the operator at the far end pressed certain buttons, electric current flowed through two of the wires, and two needles tilted toward each other. Wherever their imaginary lines crossed, that was the letter being sent.","This design had a clever advantage: the person reading it did not need to learn any code. They just looked at which letter the needles were pointing to. But it also had a problem. Five needles could only point to 20 different letters, so C, J, Q, U, X and Z were left out. Senders had to spell creatively, using other letters that sounded similar. And the system needed five or six separate wires, which was expensive to build and maintain.","Over time, Cooke and Wheatstone made simpler versions with two needles and then just one needle. With fewer needles, the operator could no longer simply read a letter off the board. Instead, each letter became a pattern of left and right swings that operators had to memorise. The single-needle telegraph, which needed far less wire, turned out to be so reliable that some were still in use on British railways in the 1930s, almost a hundred years after the first patent.","Railways and telegraphs grew up together like twins. Railways needed a fast way to know where trains were, so that two trains would not end up on the same track heading toward each other. Telegraphs needed long, straight, guarded strips of land along which to run their wires. A railway line was perfect.","In 1838 Cooke and Wheatstone's telegraph was installed along the Great Western Railway in England, between Paddington station in London and West Drayton, about 21 kilometres (13 miles) away. It is often described as the first commercial electric telegraph in the world. Soon the line was extended to Slough, near Windsor Castle. Ordinary people could pay to send messages along it, and some came just to marvel at the machine.","The telegraph became truly famous in Britain because of a crime. On 1 January 1845, a woman was found poisoned in a house near Slough. A man in an unusual long brown coat, dressed like a Quaker, had been seen leaving and boarding a train to London. The train was much faster than any horse, so in the past he would simply have disappeared into the busy city. But this time the station staff at Slough sent a description of him by telegraph to Paddington. Because the needle telegraph had no letter Q, the message had to spell Quaker as KWAKER. When the train arrived, a police officer was waiting. He followed the man, John Tawell, who was arrested the next day and later convicted.","Newspapers everywhere reported the story. For the first time, ordinary people understood that a message could outrun a train. According to a popular story, the telegraph wires near Slough were nicknamed the cords that hanged John Tawell. After that, people began to think of the telegraph not as a strange scientific toy but as something that could change real life."]},{"heading":"The Painter Who Wanted Faster News","paragraphs":["Across the Atlantic, the American story begins with an artist. Samuel Finley Breese Morse was born in 1791 in Charlestown, Massachusetts. He studied painting in London and became a well-known portrait painter in the United States. He painted presidents and famous visitors, and in 1826 he helped found the National Academy of Design in New York. Science interested him too, but painting was his career.","His biographers tell a sad story from 1825. Morse was in Washington, D.C., painting a portrait of the Marquis de Lafayette, when a letter came from his father saying that his young wife, Lucretia, was very ill. By the time the slow news reached him and he travelled home to Connecticut, she had already died and been buried. Many writers think this painful experience of news arriving too late stayed with him for the rest of his life.","In 1832, Morse was sailing home from Europe on a ship called the Sully. At dinner, the passengers talked about electricity and electromagnets, and a scientist named Charles Thomas Jackson described experiments he had seen in Europe. Morse became excited by the idea that electricity could carry signals along a wire, and he began filling his sketchbook with plans. He later claimed the whole idea as his own, though Jackson disagreed, and the two men quarrelled about it for years.","Morse was a good artist but not an expert in electricity. Back in New York, where he taught painting at the university now called New York University, he got important help. Leonard Gale, a chemistry professor there, showed him how to use more powerful batteries and many turns of wire so his electromagnet would work at the end of a long line. Gale also pointed Morse to the work of the American scientist Joseph Henry, who had built some of the strongest electromagnets in the world. Henry had already shown how a weak current could switch on a second, stronger circuit. This idea, called a relay, meant a signal could be refreshed along the way, so it could travel much farther without fading away.","In 1837 a young man named Alfred Vail watched one of Morse's demonstrations. Vail was skilled with machines, and his family owned the Speedwell Ironworks in Morristown, New Jersey. He joined the project, put in money, and rebuilt Morse's clumsy prototype into a much better machine. In January 1838 the team demonstrated their telegraph at Speedwell over about 3 kilometres (2 miles) of wire coiled around a room. Morse received a US patent in 1840, but he still needed money to build a real line between two cities."]},{"heading":"Dots, Dashes and a Single Wire","paragraphs":["The most important idea in the American telegraph was simplicity. Instead of several wires and needles pointing at letters, Morse and Vail used just one wire, plus the ground itself to complete the circuit. At the sending end was a key, a springy metal lever. Press it down and you close the circuit, so current flows. Let it go and the circuit opens, so the current stops. That is all: on and off, on and off.","At the receiving end, the current flowed through an electromagnet. Each time current arrived, the electromagnet pulled a small iron bar called an armature toward it. In the first machines, called registers, the armature pressed a pointed stylus into a moving strip of paper tape, leaving short and long marks. Later, operators used a simpler device called a sounder, which made a sharp click when the armature was pulled down and another click when a spring snapped it back up. Experienced operators learned to hear the rhythm of the clicks and write down the message by ear, so the paper tape was no longer needed.","To turn on-and-off pulses into words, the team needed a code. Each letter got its own pattern of short signals, called dots, and long signals, called dashes. Alfred Vail is believed to have done much of the work of matching letters to patterns. According to a well-known account, he visited a newspaper print shop in Morristown and counted how many pieces of metal type the printers kept for each letter. Printers keep lots of E's and T's because those letters are used most often, and only a few Q's and Z's. So in the code, E became a single dot and T a single dash, while rare letters got longer patterns. This made messages quicker to send.","The code they made, now called American Morse code, had some extra-long dashes and odd spaces inside certain letters. In 1848 a German engineer named Friedrich Gerke simplified it, and in 1865 an international meeting of telegraph countries in Paris agreed on a standard version, International Morse code. That is the version most people learn today, where SOS is three dots, three dashes, three dots. A skilled operator could send and receive dozens of words a minute, tapping out letters so fast that onlookers could not follow."]},{"heading":"Inside the Circuit: Battery, Key, Wire, Click","paragraphs":["Let's follow a single dot from start to finish, as if we were tiny enough to ride along with the electricity. Our journey starts at a battery in the sending office. In the 1840s this was a row of glass jars filled with acid and metal plates, a descendant of Volta's pile. The battery is always ready to push current, but only if there is a complete loop, called a circuit, for the current to flow around.","The operator presses the key. Two metal contacts touch, and the circuit is complete. Current rushes out along the wire on its poles, travels the whole distance to the receiving office, flows round and round the coil of the electromagnet there, and then goes down into a metal plate buried in the damp earth. The earth itself carries the current back, completing the loop. Using the ground instead of a second return wire was a trick worked out by the German scientist Carl August von Steinheil in 1838, and it cut the cost of building lines nearly in half.","While current flows, the iron core of the far electromagnet becomes a magnet and yanks the armature down: click. The operator releases the key after a short moment, the circuit breaks, the magnetism vanishes, and a spring pulls the armature back up: clack. A short gap between click and clack is a dot. A longer gap is a dash. Silence of different lengths separates letters and words. Everything in the message is just timing.","Over long distances, the current grew weaker because the wire resisted it and some leaked away through damp poles. That is where Joseph Henry's relay idea mattered. At a relay station, the weak incoming current was strong enough only to move a very light switch, but that switch connected a fresh local battery to the next stretch of line. The message was copied, click for click, into a strong new signal and sent onward. By chaining relays, messages could cross hundreds and then thousands of kilometres."]},{"heading":"What Hath God Wrought","paragraphs":["Building a telegraph line between cities cost far more than Morse could afford. For years he begged Congress for help, and many members laughed at the idea. Finally, on March 3, 1843, the very last day of that session of Congress, a bill was signed giving him 30,000 dollars to build an experimental line from Washington, D.C., to Baltimore, Maryland.","The builders first tried to bury the wire underground inside lead pipes, using a special plough designed by a young man named Ezra Cornell, who later helped found Western Union and Cornell University. But the buried wires leaked electricity and failed, and much of the money was spent. So the team changed plans and hung the wire on wooden poles alongside the Baltimore and Ohio Railroad, with glass and other materials used to keep the current from leaking into the poles. By May 1844 the wire stretched about 60 kilometres (nearly 40 miles) between the two cities.","Even before the official opening, the line proved its worth. On May 1, 1844, the Whig Party met in Baltimore and chose Henry Clay as its candidate for president. Vail, working at a station along the line, sent the news to Morse in Washington, where it arrived about an hour before the train carrying the same news. A few weeks later, people crowded around the telegraph to follow live updates from the Democratic convention in Baltimore.","The famous official demonstration came on May 24, 1844. Morse sat at his instrument in the Capitol building in Washington. Annie Ellsworth, the young daughter of the Commissioner of Patents, a friend of Morse, had been allowed to choose the message. She picked a phrase from the Bible, from the Book of Numbers: What hath God wrought. In plain modern English it means something like: look at what God has done. Morse tapped out the dots and dashes, and in Baltimore Alfred Vail received them and sent the same words straight back. The original paper tape, with Morse's handwritten note about it, is kept today at the Library of Congress.","It was not the first electric telegraph message ever sent, since Britain already had working lines. But it was the first long-distance public demonstration of Morse's system in the United States, and it convinced Americans that the telegraph worked."]},{"heading":"Wires Across a Continent","paragraphs":["After 1844, telegraph lines spread across the United States astonishingly fast. Private companies strung wire between towns, often along railways, roads and rivers. By the early 1850s there were tens of thousands of kilometres of telegraph wire in the country, run by dozens of competing companies. It was messy: some lines were badly built, and messages often had to be handed from one company to another.","Railways became some of the telegraph's best customers. In 1851, a superintendent of the Erie Railroad named Charles Minot began using telegraph messages to direct trains, telling them where to wait and when to go. This let a railway run more trains safely on a single track. Newspapers also changed. Instead of waiting days for news from distant cities, editors could print stories that had happened the day before. In 1846, several New York newspapers began sharing the cost of sending news by telegraph, an early step toward the news organisation later called the Associated Press.","A message sent by telegraph and delivered on paper was called a telegram. You walked into a telegraph office, wrote your message on a form, and paid by the word. Because every word cost money, people learned to write in a very short, clipped style, such as ARRIVING TUESDAY NOON STOP SEND CARRIAGE. A messenger, often a teenage boy, then ran or cycled the telegram from the receiving office to the person's door. Telegraph operating became a respected skilled job. A woman named Sarah Bagley is often named as the first American woman telegraph operator, in Lowell, Massachusetts, in 1846. A young Thomas Edison, who later improved the telephone, worked as a travelling telegraph operator as a teenager.","In 1856 several companies combined to form the Western Union Telegraph Company, led by Hiram Sibley, and it soon became one of the largest companies in America. When Congress passed the Pacific Telegraph Act in 1860, offering support for a line from the Missouri River to California, Western Union took on the job. Crews began in two directions. Edward Creighton led a team building westward from Nebraska and put up his first pole on July 4, 1861, while another crew built eastward from California. They faced deserts, mountains, freezing weather and the problem of finding wooden poles where few trees grew.","The two lines met in Salt Lake City, and the first transcontinental telegraph was completed on October 24, 1861. Among the first messages was one from California to President Abraham Lincoln, sent by Stephen Field, the Chief Justice of California, promising that California would stay loyal to the Union as the Civil War began. Just two days later, the famous Pony Express, whose young riders had galloped mail across the West in about ten days, announced that it was closing. A rider could never compete with a message that crossed the continent in minutes. During the Civil War, Lincoln spent hours in the War Department's telegraph office reading reports from his generals, making him one of the first leaders to follow a war almost as it happened."]},{"heading":"Amazing, But Not Yet a Voice","paragraphs":["The electric telegraph was one of the biggest changes in human history. For the first time, information could travel far faster than any person, animal or vehicle. Prices in one city could be known in another the same hour. Families could hear about a birth or a death in a day instead of weeks. Governments, armies, railways and businesses all started to depend on it.","But it had limits. Ordinary people could not use a telegraph themselves. You needed a trained operator who knew the code and could tap it out quickly and accurately. You had to go to a telegraph office, which might be miles away, and pay by the word. Messages were short and often stiff, like little notes in a hurry. And no matter how fast the operator tapped, the telegraph could only carry clicks. You could not hear your mother laugh, your friend's excitement or the worried tone in someone's voice.","There were arguments, too. Morse fought long court battles to defend his patent against rival telegraph makers. In 1853 the US Supreme Court, in a case called O'Reilly v. Morse, agreed that Morse's own system was his invention, but ruled that he could not claim to own every possible use of electromagnetism for sending signals at a distance. In Britain, Cooke and Wheatstone quarrelled so badly over credit that a special panel had to give its opinion, which praised both men. Arguments over who invented what would come back even louder with the telephone.","Each wire could also carry only one message at a time, so busy lines became crowded. Inventors began wondering whether a single wire could carry several messages at once, perhaps using different musical tones. That puzzle, as we will see later, would lead some of them straight toward the telephone.","There was one more giant problem. Wires could be hung on poles across fields, forests, deserts and mountains. But what about the sea? Between Britain and France lay the stormy English Channel, and between Europe and America lay the vast, deep Atlantic Ocean. Ships still took about ten days to carry news across it. To truly connect the world, someone would have to lay a wire along the bottom of the ocean."]}],"deepDive":"Historians increasingly describe the electric telegraph as a case of simultaneous invention rather than the work of one genius. Schilling in Russia, Gauss and Weber in Göttingen, Steinheil in Munich, Cooke and Wheatstone in London and Morse and Vail in the United States all built working systems within roughly a decade, because the same scientific ingredients had become available to all of them: Volta's battery (1800), Ørsted's discovery that current deflects a magnetic needle (1820), and the powerful multi-turn electromagnets developed by Joseph Henry and others around 1830. What separated the systems was engineering and economics. The Cooke and Wheatstone five-needle design could be read by an untrained clerk but needed five or six wires; Morse's design needed only one wire plus an earth return, at the price of requiring trained operators who knew the code. In the long run, the cheaper single wire won almost everywhere, and even British railways moved toward single-needle and Morse equipment. Morse code itself is an early example of efficient coding: by giving the most frequent letters (E, T) the shortest signals, it reduced average transmission time, an idea that information theorists such as Claude Shannon later made mathematically precise. Credit within the American team is still discussed. Morse held the patents and the fame, but many historians believe Alfred Vail contributed much of the mechanical design and the dot-dash alphabet, and Joseph Henry's research on electromagnets and relays made long lines possible; Henry later felt Morse did not acknowledge this fairly. The economic effects were enormous. The telegraph separated communication from transportation for the first time, allowing prices for goods such as cotton and grain to converge between distant markets, letting railways schedule trains safely on single tracks, and supporting the rise of large national companies such as Western Union, which by the late 1860s dominated American telegraphy. Its weakness was that it needed skilled intermediaries, which kept it a service people visited rather than a device they owned.","funFact":"Because Cooke and Wheatstone's needle telegraph had no letter Q, the 1845 message that led to the capture of the murderer John Tawell had to describe him as dressed like a 'KWAKER'.","check":{"q":"What were the words of Morse's famous 1844 telegraph message from Washington to Baltimore?","a":"What hath God wrought","wrong":["Come here, I want to see you","Hello from Washington","The British are coming"]},"sources":[{"title":"Cooke and Wheatstone telegraph","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cooke_and_Wheatstone_telegraph"},{"title":"Morse's Telegraph in the Capitol","publisher":"United States Senate","url":"https://www.senate.gov/artandhistory/senate-stories/morses-telegraph-in-the-capitol.htm"},{"title":"Samuel Morse","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Samuel_Morse"},{"title":"Morse code","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Morse_code"},{"title":"First transcontinental telegraph","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/First_transcontinental_telegraph"},{"title":"William Fothergill Cooke","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Fothergill_Cooke"},{"title":"Pony Express","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pony_Express"}],"photos":[{"src":"img/deep/telephone/03-1.jpg","alt":"Cooke and Wheatstone's 1837 five-needle telegraph at the Science Museum, London; the needles pointed to letters on the diamond board.","file":"Wheatstone-Cooke five-needle telegraph (1837), Science Museum, London (141904071).jpg","url":"https://commons.wikimedia.org/wiki/File:Wheatstone-Cooke_five-needle_telegraph_(1837),_Science_Museum,_London_(141904071).jpg","author":"chailey","license":"CC BY 2.0"},{"src":"img/deep/telephone/03-2.jpg","alt":"An early Morse telegraph register in a museum, which marked dots and dashes onto a long paper tape.","file":"Morse Telegraph 1837 cropped.jpg","url":"https://commons.wikimedia.org/wiki/File:Morse_Telegraph_1837_cropped.jpg","author":"Zubro","license":"CC BY-SA 3.0"},{"src":"img/deep/telephone/03-3.jpg","alt":"Pony Express rider Frank E. Webner on horseback, around 1861, the year the telegraph line put the Pony Express out of business.","file":"\"Frank E. Webner, pony express rider,\" ca. 1861 - NARA - 513351.jpg","url":"https://commons.wikimedia.org/wiki/File:%22Frank_E._Webner,_pony_express_rider,%22_ca._1861_-_NARA_-_513351.jpg","author":"Unknown authorUnknown author or not provided","license":"Public domain"}],"words":3743},{"n":4,"title":"A Wire Across the Ocean","when":"1850 – 1866","summary":"Telegraph wires could cross land, but the ocean was a huge, dark, salty problem. Brave businessmen, scientists and sailors tried again and again to lay a cable on the sea floor between Europe and America. After broken cables, a giant ship and one short-lived success, the Atlantic was finally crossed in 1866.","sections":[{"heading":"Why the Sea Is a Terrible Place for a Wire","paragraphs":["Imagine trying to lay a garden hose from Ireland to Canada, along the bottom of an ocean that is in places more than 4 kilometres (about 2.5 miles) deep, without ever seeing where it lands. Then imagine that the hose has to carry tiny electric signals the whole way without leaking a drop. That was roughly the challenge facing the people who wanted to wire the world together in the 1850s.","On land, telegraph wire could be bare metal hung on poles, because dry air does not carry electricity well. Seawater is different. Salt water conducts electricity, so a bare copper wire dropped into the sea would simply leak its current into the water, like a pipe full of holes. To work underwater, a wire needs a coating, called insulation, that keeps the electricity inside. That coating must stay waterproof under enormous pressure, never crack in the cold, and last for years without rotting.","There were other problems too. A cable has to be strong enough not to snap while it is lowered from a rolling ship, yet flexible enough to coil up in the ship's hold. It has to survive anchors, rocks, currents and storms. And nobody in the 1850s really understood what would happen to an electric signal after it had travelled thousands of kilometres through a wire wrapped in insulation and surrounded by seawater. As we will see, the answer surprised almost everyone."]},{"heading":"Gutta-Percha: The Sap That Wired the World","paragraphs":["The solution to the insulation problem came from the rainforests of Southeast Asia. Trees of the genus Palaquium, especially Palaquium gutta, which grow in places such as the Malay Peninsula, Sumatra and Borneo, ooze a milky sap when their bark is cut. When the sap dries, it becomes a tough, rubbery material. Its name, gutta-percha, comes from Malay words for the sap of the tree.","Local people had used it for a long time to make handles and other objects. In 1843 a Scottish surgeon named William Montgomerie, who worked in Singapore, brought it to the attention of scientists in Britain and was awarded a gold medal by the Royal Society of Arts. Gutta-percha had a wonderful property: dip it in hot water and it becomes soft enough to mould like clay, but let it cool and it hardens again. That meant it could be pressed around a copper wire in a smooth, seamless coat. Even better, it did not rot in seawater, and in the cold, dark depths of the ocean it lasted for years.","Scientists, including Michael Faraday and Charles Wheatstone, quickly realised that gutta-percha was an excellent insulator, which means it blocks electricity from escaping. Wheatstone suggested using it for a cable across the English Channel as early as 1845, and engineers tested gutta-percha-coated wire under rivers and in harbours in the late 1840s.","For about ninety years, almost every undersea telegraph cable in the world was insulated with gutta-percha. The demand was so huge that collectors cut down vast numbers of trees, often felling a whole tree to collect its sap, and supplies began to run short. It was an early example of how a new technology can harm a faraway environment. Gutta-percha was also used to make golf balls, called gutties, and it is still used today by dentists to fill teeth during root canal treatment. Only around 1940 did a plastic called polyethylene replace it as the main material for insulating cables."]},{"heading":"First Tries Across the English Channel","paragraphs":["The first big test was the English Channel, the narrow sea between England and France, only about 40 kilometres (25 miles) wide at its narrowest point. Two brothers, John Watkins Brett and Jacob Brett, formed a company to lay a cable between Dover and the French coast near Calais. In August 1850 a small steam tug called the Goliath set out, paying out a copper wire covered only in a layer of gutta-percha, with lead weights clamped to it every so often to make it sink.","It worked, at least for a little while. A few messages crossed the Channel, but then the line went silent. The thin, unprotected cable had been damaged, probably on the rocks near the French coast. A popular story says that a French fisherman hauled up the cable in his net, cut off a piece and took it home, believing he had found a strange new seaweed with gold in its middle. It is a fun tale, but it is just that: a story that historians cannot confirm.","Whatever the cause, the lesson was clear. A cable needed armour. In September 1851, the Channel was crossed again, this time with a much heavier cable. Its copper wires were insulated with gutta-percha, wrapped in tarred hemp, and then wound with a strong outer layer of iron wires, like a steel rope. It was laid from an old hulk called the Blazer, towed by tugs. This cable worked and kept working. Within months, people could send messages between London and Paris, and traders in each city could learn the other's stock and money prices in minutes rather than days.","After that, undersea cables multiplied. By 1853 cables linked Great Britain with Ireland, Belgium and the Netherlands, and others crossed straits in Denmark and the Mediterranean. Each success made a far bigger dream seem possible: a cable across the Atlantic Ocean itself, connecting Europe and North America. That would be more than fifty times longer than the Channel cable, lying in water that in places is about 4 kilometres deep instead of a few dozen metres."]},{"heading":"Cyrus Field Will Not Give Up","paragraphs":["The man who made the Atlantic cable happen was not a scientist or an engineer. Cyrus West Field was born in 1819 in Stockbridge, Massachusetts. At 15 he went to New York City to work as an errand boy in a big store. Later he went into the paper business and did so well that by the age of 34 he was rich enough to partly retire, with a fortune of about 250,000 dollars and a fine house in New York's Gramercy Park.","In January 1854, a British-born engineer named Frederic Newton Gisborne came to Field with a problem. Gisborne had been trying to build a telegraph line across the island of Newfoundland, the part of North America closest to Europe, so that news from ships could be flashed to New York faster. His company had run out of money. Field listened, then looked at a globe in his study, and a much bigger idea struck him. Why stop at Newfoundland? Why not keep going, right across the ocean to Ireland?","Field knew little about electricity, so he asked the experts. He wrote to Samuel Morse, who believed an ocean cable could work. He also wrote to Lieutenant Matthew Fontaine Maury of the US Navy, who studied ocean depths and currents. Ships measuring the depth of the North Atlantic with long weighted lines had found a broad, fairly level stretch of sea floor between Ireland and Newfoundland. Maury called it the Telegraph Plateau and said it seemed almost made for a cable, being deep enough to be safe from icebergs and anchors but not covered in sharp mountains.","Field threw himself into the project with astonishing energy. He first finished the land line across Newfoundland and a cable to the mainland, which alone cost more than a million dollars. Then, in 1856, he helped found the Atlantic Telegraph Company in Britain, raising money from investors on both sides of the ocean. The British and American governments both promised to lend warships and to pay for using the cable. Over the next twelve years Field crossed the Atlantic by ship dozens of times, persuading, arguing and raising money again after each disaster.","The first disaster came quickly. In August 1857, two warships, the British HMS Agamemnon and the American USS Niagara, set out from Valentia Island on the west coast of Ireland. No single ship could carry the whole cable, so each took about half. The Niagara began paying out cable from Ireland, planning to splice it to the Agamemnon's half in the middle of the ocean. But a few days out, the cable snapped and sank into water more than 3 kilometres deep. About 300 miles (480 kilometres) of expensive cable were lost on the sea floor, and the ships had to sail home."]},{"heading":"1858: A Message from the Queen","paragraphs":["In 1858 the team tried a new plan. The two ships would sail to the middle of the Atlantic together, join their two halves of cable there, and then steam away from each other, one toward Ireland and one toward Newfoundland, each paying out cable behind it. That way, if something went wrong, it would happen far from land but at least the job would be shared.","The first try in June 1858 ran into one of the worst storms the sailors had ever seen. The Agamemnon, top-heavy with more than a thousand tonnes of coiled cable, rolled so violently that crew members feared she would capsize. Coal broke loose in the hold, and some sailors were injured. When the ships finally met and began laying, the cable broke several times. Again they gave up and returned to Ireland.","Field refused to quit. In July 1858 the ships sailed once more. This time, after the mid-ocean splice, everything held. On August 4, 1858, the Niagara reached Trinity Bay in Newfoundland, and the next day the Agamemnon reached Valentia Island in Ireland. For the first time in history, a single wire linked Europe and North America.","There was a lot of testing and adjusting before the cable was officially opened. On August 16, 1858, Queen Victoria sent a greeting to President James Buchanan. Her message was 98 words long, yet sending it took about 16 hours. That works out to around one word every ten minutes. The signals were so weak and blurred that operators had to repeat letters over and over before they could be sure. Buchanan replied, calling the cable a triumph that would help keep peace between nations.","Still, people went wild with joy. In New York there were parades, church bells and a huge fireworks display, so enthusiastic that the roof of City Hall caught fire. The jewellery company Tiffany bought leftover cable, cut it into short pieces and sold them as souvenirs. Newspapers called it the greatest achievement of the age.","Then the signals grew weaker and weaker. Less than three weeks after the Queen's message, in early September 1858, the cable fell silent for good. Some people even suspected the whole thing had been a hoax. It had not been: hundreds of messages had crossed, including one cancelling the departure of two British army regiments from Canada, which saved a great deal of money. But the first Atlantic cable had failed, and investors had lost a fortune. What had gone wrong?"]},{"heading":"Professor Thomson and the Smeared Signals","paragraphs":["Part of the answer lay in a quarrel between two very different experts. One was Wildman Whitehouse, a doctor turned electrician who was the company's chief electrician. The other was William Thomson, a brilliant young physicist who had been born in Belfast in 1824 and became a professor at the University of Glasgow when he was only 22. Thomson would later be made Lord Kelvin, and the Kelvin temperature scale used by scientists today is named after him.","Scientists had already noticed something strange about long underwater cables. When you send a sharp, clean pulse of electricity into one end, it does not come out of the other end sharp and clean. It comes out late, weak and smeared, like a crisp drumbeat turned into a long, soft rumble. Michael Faraday had worked out why. A cable is a copper wire, wrapped in insulation, lying in salty water that also conducts electricity. That arrangement acts a bit like a long, thin storage tank for electric charge. Each pulse has to fill up the tank along the whole length of the cable before much current reaches the far end, and then it takes time to drain away again.","A good way to picture it is a very long, stretchy garden hose. Turn the tap on for one second and you do not get a neat one-second squirt at the far end. Instead, the hose swells, then water dribbles out slowly for a while. If you turn the tap on and off quickly, the separate squirts blur together into one long trickle. On a telegraph cable, that blurring meant dots and dashes ran into each other, so operators had to send very slowly, leaving long gaps.","In 1854 and 1855, Thomson worked out the mathematics of this effect. He showed that the delay grows with the square of the cable's length. Double the length and the signals become about four times slower. For a cable thousands of kilometres long, this was a huge problem. But Thomson's maths also showed how to fight it: use a thicker core of very pure copper, which carries current more easily, and a thicker layer of insulation. And instead of blasting the cable with powerful currents, use gentle currents and a super-sensitive detector at the far end.","Whitehouse disagreed. He believed bigger voltages were the answer, and he used huge induction coils that pushed up to about 2,000 volts into the 1858 cable. Many experts think these powerful jolts helped damage the cable's gutta-percha insulation, which already had weak spots from being stored in the sun and handled roughly. Whitehouse was dismissed. Afterwards, a special committee spent about two years studying what had happened and how to build a better cable, and many of Thomson's ideas were adopted."]},{"heading":"A Mirror on a Silk Thread","paragraphs":["Thomson's most famous gadget for the cable was the mirror galvanometer, which he patented in 1858. A galvanometer is a device that detects electric current. Ordinary ones used a needle that swung when current flowed, but on a long ocean cable the current arriving at the far end was so feeble that a normal needle would hardly twitch.","Thomson's clever solution was to make the moving part almost weightless. He glued tiny magnets to the back of a small, light, round mirror and hung it on a single fine thread inside a coil of wire. When even a very weak current flowed through the coil, the magnets twisted slightly and the mirror tilted. A lamp shone a beam of light onto the mirror, which reflected it onto a scale on the wall, several feet away. Because the light beam acted like a very long, weightless pointer, a tiny tilt of the mirror made the spot of light jump a large distance along the scale.","Operators sat in a darkened room watching the bright spot dance left and right. A swing one way meant a dot, a swing the other way meant a dash. With this delicate instrument, a cable could be worked with gentle currents that did not harm its insulation. Later, in 1867, Thomson invented the siphon recorder, which used a tiny ink tube to draw the signals as a wavy line on moving paper tape, so the message could be checked afterwards.","Thomson's ideas also shaped the new cable itself. The cable planned for the next attempt had a much heavier copper core and much thicker gutta-percha insulation than the 1858 one. It was protected by iron wires each wrapped in tarred hemp, which made it strong but also much heavier. In fact, it was so heavy and bulky that no ordinary ship could carry all of it. Luckily, there was one ship in the world big enough."]},{"heading":"The Great Eastern Saves the Day","paragraphs":["The SS Great Eastern was the giant of its age. Designed by the famous engineer Isambard Kingdom Brunel and launched on the River Thames in London in 1858, it was about 211 metres (692 feet) long, longer than two football fields, and was built to carry about 4,000 passengers all the way to Australia without stopping for coal. It had both huge paddle wheels and a propeller. But as a passenger ship it was a disappointment. It was expensive to run, and it never filled up. For years it seemed like a giant white elephant.","For cable laying, though, it was perfect. Its enormous holds could carry the entire Atlantic cable, thousands of kilometres of it, in giant water-filled tanks that kept the gutta-percha cool. That meant no risky splice in mid-ocean. Its huge size also made it steadier in rough seas than smaller ships, and it carried enough coal for the whole trip.","In July 1865 the Great Eastern set out from Ireland, paying out the new cable over its stern. Field and Thomson were both on board. Engineers on deck constantly tested the cable as it went down, and several times they had to haul faulty sections back up to repair them. Then, on August 2, 1865, after more than 1,000 nautical miles (about 2,000 kilometres) had been laid, the cable snapped and slid into water more than 3 kilometres deep. The crew lowered grappling hooks on long ropes and actually caught the cable several times, but each time the rope broke before the cable reached the surface. Once again, the ship returned home defeated.","Field and his partners raised new money and formed a new company. On July 13, 1866, the Great Eastern left Valentia Island again with a fresh, improved cable. This time the voyage went smoothly. On July 27, 1866, the giant ship arrived at the little fishing village of Heart's Content in Newfoundland, and the cable was brought ashore. Europe and North America were connected again, and this time the connection lasted.","Then the Great Eastern did something even more amazing. It sailed back out to where the 1865 cable had been lost. Over many days, the crew dragged grappling hooks along the ocean floor, more than 3 kilometres below. It was like trying to pick up a piece of string from the bottom of a deep lake while standing on a moving boat in the dark. At the start of September they finally lifted the old cable to the surface, tested it, and found the signal from Ireland still came through. They spliced on new cable and landed it at Heart's Content on September 7, 1866. Now there were two working Atlantic cables. The ship's first officer, Robert Halpin, who helped find the lost cable, later became her captain and laid more cables around the world."]},{"heading":"News in Minutes Instead of Days","paragraphs":["The 1866 cable changed the speed of the world. The 1858 cable had managed only about one-tenth of a word per minute. The new cable could carry around eight words per minute, and later improvements made it faster still. A piece of news that had needed about ten days to cross the Atlantic by steamship could now cross in minutes.","At first, sending a cable message, often called a cablegram, was extremely expensive. In the early days a message of twenty words reportedly cost about 20 British pounds, more than many workers earned in months. So most users were governments, newspapers, banks and big merchants. Traders in London and New York could now know each other's prices almost the same day, and newspapers could print European news while it was still fresh. Governments could discuss problems quickly instead of waiting weeks for letters, which sometimes helped calm disagreements before they grew.","The heroes were rewarded. William Thomson was knighted in 1866, becoming Sir William, partly for his cable work. In 1867 the United States Congress gave Cyrus Field a gold medal. Field later lost much of his fortune through bad investments, but his headstone in Stockbridge says the world owes the Atlantic telegraph to his courage, energy and perseverance.","Over the next few decades, more and more cables were laid. Cables soon reached India, Australia, South America and Asia, and by the end of the century a web of undersea wires linked most of the world's major countries. A message could travel from London to Bombay or from New York to Cape Town in hours. Historians sometimes call this network the Victorian internet, because for the first time the whole planet could share news almost at once.","Yet every one of these cables still did the same simple thing as Morse's first line: it carried clicks. Short pulses and long pulses, dots and dashes, letter by letter. Nobody could talk through them. And that raised a new and even more daring question. If electricity could carry clicks under a whole ocean, could it be made to carry something much more complicated and beautiful: the sound of a human voice?"]}],"deepDive":"The physics behind the 1858 failure and the 1866 success is one of the founding stories of electrical engineering. A submarine cable is a conductor separated from the conducting seawater by a thin layer of insulation, so it behaves as a long distributed capacitor in series with the resistance of the copper core. Faraday and Latimer Clark observed the resulting signal retardation in the early 1850s, and in 1854–55 William Thomson modelled it with the same diffusion equation used for heat flow. His result, often called the 'law of squares' or 'KR law', says the time a pulse takes to build up at the far end is proportional to the cable's total resistance multiplied by its total capacitance, and since both grow with length, the delay scales with the square of the length. Whitehouse, a medical man with practical experience but little theory, doubted the law, argued that results from short test lengths would scale up, and favoured high-voltage induction coils. The 1858 cable had a thin core of uneven-quality copper and insulation that had been damaged during storage and laying; most historians conclude that its faults were made worse by Whitehouse's high voltages, though the cable was probably doomed anyway. After the failure, a joint committee of the British Board of Trade and the Atlantic Telegraph Company (1859–1861) produced a landmark report on cable design, testing and materials, helping turn telegraph engineering into a science based on measurement. Standard units of resistance and other electrical quantities, eventually including the ohm, grew partly out of this need to specify cable properties precisely. The 1866 cable reflected Thomson's prescriptions: a core of high-conductivity copper about three times heavier per mile than in 1858, thicker gutta-percha, and sensitive low-voltage detection. Later, Oliver Heaviside extended Thomson's analysis by including inductance, work that would matter greatly for telephone lines. Economically, cable rates fell over time from the very high 1866 tariff, and by 1900 British companies owned most of the world's cable network, a fact historians link to British commercial and imperial power.","funFact":"When the 1858 Atlantic cable was celebrated in New York, the fireworks display was so enthusiastic that it set the roof of City Hall on fire.","check":{"q":"Which giant steamship laid the successful 1866 Atlantic telegraph cable?","a":"The Great Eastern","wrong":["The Titanic","The Mayflower","HMS Victory"]},"sources":[{"title":"Transatlantic telegraph cable","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Transatlantic_telegraph_cable"},{"title":"Submarine communications cable","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Submarine_communications_cable"},{"title":"Cyrus West Field","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cyrus_West_Field"},{"title":"SS Great Eastern","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/SS_Great_Eastern"},{"title":"Gutta-percha","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gutta-percha"},{"title":"Mirror galvanometer","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mirror_galvanometer"},{"title":"William Thomson, 1st Baron Kelvin","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Thomson,_1st_Baron_Kelvin"}],"photos":[{"src":"img/deep/telephone/04-1.jpg","alt":"Robert Dudley's 1866 painting of the cable-laying machinery on the deck of the giant steamship Great Eastern.","file":"Deck of the Great Eastern, the Cable Trough, etc., 1866 MET DP820957.jpg","url":"https://commons.wikimedia.org/wiki/File:Deck_of_the_Great_Eastern,_the_Cable_Trough,_etc.,_1866_MET_DP820957.jpg","author":"Robert Charles Dudley","license":"CC0"},{"src":"img/deep/telephone/04-2.jpg","alt":"A short piece of the first transatlantic telegraph cable of 1858, showing its twisted outer wires, in the Bennington Museum.","file":"First trans-Atlantic cable, c. 1858 - Bennington Museum - Bennington, VT - DSC08635.JPG","url":"https://commons.wikimedia.org/wiki/File:First_trans-Atlantic_cable,_c._1858_-_Bennington_Museum_-_Bennington,_VT_-_DSC08635.JPG","author":"Daderot","license":"Public domain"},{"src":"img/deep/telephone/04-3.jpg","alt":"William Thomson's 1858 mirror galvanometer, which detected the tiny signals arriving through the Atlantic cable.","file":"Thomsons mirror galvanometer, 1858. (9663806048).jpg","url":"https://commons.wikimedia.org/wiki/File:Thomsons_mirror_galvanometer,_1858._(9663806048).jpg","author":"Science Museum London / Science and Society Picture Library","license":"CC BY-SA 2.0"}],"words":3744},{"n":5,"title":"Dreamers of the Talking Wire","when":"1850s – 1875","summary":"Long before anyone made a real phone call, a few dreamers believed a wire could carry a human voice. A French telegraph worker wrote about it, a German teacher built a wooden ear that sent music, and an Italian inventor in New York tinkered for years in his house. Meanwhile, inventors raced to make one wire carry many messages at once, using musical notes.","sections":[{"heading":"A Wild Idea in a Paris Magazine","paragraphs":["By the 1850s the electric telegraph was clicking away across Europe and America. Messages that once took days now took minutes. But every one of those messages had to be squeezed into a code of short and long pulses, tapped out by a trained operator and decoded by another trained operator at the far end. Nobody could simply pick up a wire and talk. To most people, the idea of sending an actual voice along a wire sounded like a fairy tale.","One young man thought differently. His name was Charles Bourseul. He was born in Brussels, Belgium, on 28 April 1829, grew up in the town of Douai in northern France, and went to work for the French telegraph service. He spent his days around batteries, wires and electromagnets, and he knew how they behaved. He also knew something about sound: that every voice is really a pattern of vibrations in the air.","In 1854, when Bourseul was only about 25, a short article describing his idea appeared in L'Illustration, a popular illustrated magazine in Paris. A French postal history document dates the article to 26 August 1854. In it, Bourseul imagined a person speaking close to a thin, flexible metal disc. The disc would shake back and forth with every vibration of the voice. Each time it shook, it would open and close an electric circuit connected to a battery. At the far end of the wire, a second disc, pulled by an electromagnet, would shake in exactly the same rhythm and, he hoped, recreate the sound.","Bourseul was confident. He predicted that, sooner or later, speech would be carried by electricity. Some readers thought it was a charming daydream. A French writer later remarked that before 1854 hardly anyone had dared to believe that speech could be sent electrically at all.","There was one big problem: Bourseul never built a working version. His idea used what engineers call a \"make-and-break\" circuit, where the current is switched fully on and fully off. That works well for telegraph clicks, but, as we will see, it turns out to be a poor way to copy the smooth, rich shape of a human voice. Still, Bourseul had done something important. He had written down, clearly and publicly, the basic plan that every telephone would follow: turn sound vibrations into electrical changes, send them along a wire, and turn them back into vibrations at the other end.","Bourseul kept working for the telegraph service for many years and made improvements to telegraph equipment. He lived until 23 November 1912, long enough to see telephones spread all over the world. Today a statue of him stands in the French town of Saint-Céré, where he died. He is a good reminder that inventions often begin as ideas on paper, years before anyone can make them work."]},{"heading":"The Schoolteacher Who Carved an Ear","paragraphs":["Our next dreamer did not just write about a talking wire. He built one. Johann Philipp Reis was born on 7 January 1834 in Gelnhausen, a small town in the German region of Hesse. His life started hard. His mother died when he was a baby, and his father, a baker, died before Philipp turned ten. His grandmother raised him.","Reis was a bright, curious boy. He went to a school called Garnier's Institute in the town of Friedrichsdorf, near Frankfurt, where he learned French and English, and later studied Latin and Italian in Frankfurt. His uncle wanted him to become a merchant, so in 1850 the teenage Reis was sent to work for a paint dealer. He did not enjoy it. In his spare time he taught himself mathematics and physics and joined Frankfurt's Physical Society, a club where scientists and science lovers met to hear lectures and see experiments.","After doing military service, Reis finally got the job he wanted. In 1858 Garnier's Institute invited him back as a teacher, and he married and settled in Friedrichsdorf in 1859. Now he had a classroom, students and a little workshop. He began thinking about how the human ear works.","Here is the clever part. Your ear has an eardrum, a thin skin stretched across a tube. When sound waves hit it, the eardrum vibrates. Tiny bones behind it pass those vibrations inward. Reis asked: what if I copied the ear, but made it control an electric current? According to the German Historical Museum in Berlin, his first transmitter was a carved wooden model of a human ear. For the eardrum he stretched a thin membrane made from pig intestine. On that membrane he attached a small platinum strip, and a platinum point touched it, a little like the ear's tiny bones. The platinum pieces were part of a circuit with a battery. When someone spoke or sang into the wooden ear, the membrane shook, and the platinum contact jiggled, changing the current flowing through the wire.","At the receiving end, Reis used a thin iron rod surrounded by a coil of wire. (Some versions famously used a knitting needle.) The rod sat on a wooden sounding box, like the body of a violin, to make the faint sound louder. When the changing current flowed through the coil, the iron rod changed very slightly in length and gave out tiny clicks and hums, which the box amplified. This effect, that iron can make sounds when magnetized and demagnetized quickly, had been noticed by the American scientist Charles Grafton Page in the 1830s. Reis built on it.","He named his device the \"Telephon\", from two Greek words meaning \"far\" and \"sound\". That is where our word telephone comes from, though Reis was not the very first person to use the word for a sound-sending gadget. By 1860 he had a prototype that could send sounds about 100 metres."]},{"heading":"The Horse, the Cucumber Salad and a Philosophical Toy","paragraphs":["On 26 October 1861, Reis stood before the Physical Society of Frankfurt and gave a lecture with a very grown-up title: \"On Telephony by Galvanic Current.\" (Galvanic simply meant electricity from a battery.) He was 27 years old. He showed his Telephon sending a folk tune and some spoken words. Music came through much better than speech. Tunes are mostly about pitch, how fast something vibrates, and the Telephon was good at copying pitch. Speech is much more complicated.","Imagine being in Reis's experiments. One person stands in a room speaking into the transmitter. Another sits in a different room, ear pressed to the receiver box, trying to make out the words. To prove the listener was not just guessing a memorized sentence, the speakers used deliberately odd sentences that no one could predict. The most famous is \"Das Pferd frisst keinen Gurkensalat,\" which means \"The horse does not eat cucumber salad.\" Another reported test sentence was \"Die Sonne ist von Kupfer\" (\"The sun is made of copper\"). Accounts disagree on exactly when and by whom the cucumber salad sentence was spoken, and some call it a story that grew in the retelling, but it has become one of the most famous sentences in German science history. Even today German speakers sometimes use it as a joke about bad phone lines.","According to later accounts, one witness, a fellow teacher at Garnier's Institute named Peter, described how a listener in another room repeated sentences he had made up on the spot, and how amazed everyone was. Reis improved his design between 1861 and 1863, switching to a box-shaped transmitter that was easier to make. He sold copies to physics collections and science teachers. Instruments built to his design traveled to London, Dublin and even Tiflis (today Tbilisi, in Georgia). One made in London in 1863 by the instrument maker William Ladd survives today at the University of Aberdeen in Scotland. In 1862 an inspector of the Prussian telegraph service, Wilhelm von Legat, studied the Telephon and published a report on it.","So why didn't Reis become famous as the inventor of the telephone? The main reason is the way his transmitter worked. Like Bourseul's idea, it was mostly a make-and-break device. When the membrane vibrated, the platinum contact tended to open and close the circuit, turning the current on and off. On and off is fine for showing how fast something vibrates, which is why melodies came through. But a voice is not just pitch. The difference between the vowel \"ah\" and the vowel \"ee\" lies in the detailed shape of the sound wave: how strong each little part of the vibration is. A switch that is either fully on or fully off throws most of that shape away. What is needed instead is a current that rises and falls smoothly, copying the wave. Engineers later called this an undulating current. Reis's device sometimes passed a word or two, especially when the contact was adjusted so that it never fully broke, but it was never reliable for clear speech.","Reis also struggled to be taken seriously. A leading physics journal turned down his papers, and he is reported to have blamed this on being \"only a poor schoolmaster\". Some scientists treated the Telephon as a \"philosophical toy\", a clever gadget for lectures rather than a useful machine. Reis had tuberculosis, a serious lung disease, and his health got worse. He died on 14 January 1874, aged just 40, two years before Bell's famous patent.","Later, his device became part of the patent battles over the telephone. In one American court case a judge decided that Reis's make-and-break design could not have become a speaking telephone simply by being improved. Yet in 1947, engineers at the British company Standard Telephones and Cables tested a Reis instrument from 1863 and reported that, when carefully adjusted, it could pass speech of good quality but at very low volume. Those results were kept quiet for decades. Historians still debate how close Reis came. Germany remembers him proudly: a prize for achievements in communication technology carries his name, and a monument was raised over his grave in 1878."]},{"heading":"A Theatre Wizard from Florence","paragraphs":["While Reis was growing up in Germany, a very different inventor was already on his second continent. Antonio Meucci was born on 13 April 1808 in Florence, Italy. As a teenager he studied at Florence's Academy of Fine Arts, learning drawing and mechanics. He went on to work backstage at the Teatro della Pergola, one of the city's famous theatres. Theatre technicians in those days were a bit like special-effects wizards: they built moving scenery, trapdoors and machinery. In 1834 Meucci married Esterre Mochi, a costume designer. According to accounts of his life, he also rigged up a speaking tube, a simple pipe that carried voices, so people on the stage could talk to the crew working the machinery.","In 1835 Antonio and Esterre sailed across the Atlantic to Havana, Cuba, where they both worked at the grand new Teatro Tacón, then one of the largest theatres in the Americas. Meucci stayed in Havana for about 15 years. Besides his theatre work, he experimented with electricity, which was then a fashionable and mysterious subject. Some people at the time believed electric shocks could cure illnesses, and Meucci experimented with this kind of treatment.","That is where one of the most famous stories about Meucci comes from. According to his own later account, around 1849 he was giving an electric treatment to a patient in another room, connected to him by a wire. When the patient cried out, Meucci said he heard the sound faintly through the apparatus near his own ear. He became convinced that electricity could carry the human voice and named his idea a \"telegrafo parlante\", a talking telegraph. We only know this story from Meucci's own descriptions years later, so historians treat it carefully. Still, it shows that by mid-century he was already chasing the same dream as Bourseul and Reis.","In 1850 the Meuccis left Cuba and moved to New York, settling in Clifton on Staten Island, then a quiet area of farms and villages across the harbour from Manhattan."]},{"heading":"Candles, Garibaldi and the Telettrofono","paragraphs":["On Staten Island, Meucci needed to earn a living. He started a factory making tallow candles. One of the people who stayed in his house in the early 1850s was a remarkable guest: Giuseppe Garibaldi, the soldier and patriot who later became a hero of Italy's unification. Garibaldi was living in exile at the time, and he is said to have worked in Meucci's candle factory. Today the house is the Garibaldi-Meucci Museum on Tompkins Avenue, run since 1956 by the Order Sons and Daughters of Italy in America, with exhibits about both men.","In 1854 a sad change came. Esterre developed severe rheumatoid arthritis, a disease that makes joints painful and stiff, and she could no longer move around easily. Meucci, who worked in a laboratory in another part of the house, wanted to be able to talk to her from his workshop. According to his supporters, around 1856 he built an electrical voice link between her bedroom and his lab. Museum guides say he was using a talking device in the house at a time when Alexander Graham Bell was still a small child in Scotland. These claims rest mostly on Meucci's own notes and later testimony, and historians do not all agree on how well these early devices worked.","Meucci kept tinkering through the 1850s and 1860s. His supporters say he built more than 30 different versions of his device. He gave it a new name: the \"telettrofono\". In one account, in August 1870 he managed to send spoken words about a mile (1.6 kilometres) along a copper wire wrapped in cotton for insulation. He also wrote letters to Italian newspapers in 1865 describing his experiments.","Sadly, his inventive mind was not matched by good fortune. The candle business failed, and Meucci lost much of his money through bad deals and people he trusted. He never became comfortable in English, which made dealing with lawyers, businessmen and the patent office much harder. He was, in many ways, a brilliant inventor stuck on the outside of the system that could have made him rich."]},{"heading":"A Ferry Explosion and a Ten-Dollar Notice","paragraphs":["In the summer of 1871, disaster struck. On 30 July, the boiler of the Staten Island ferry Westfield exploded at its dock in Manhattan, killing dozens of passengers and injuring many more. Meucci was among the injured. He was badly burned and needed months to recover. During this time the family was so short of money that, by his own account, his wife sold his drawings and models to a second-hand dealer.","Meucci still wanted to protect his idea. In December 1871 he and a few Italian friends signed an agreement to form a small company to develop the telettrofono. On 28 December 1871 he filed a caveat with the United States Patent Office. A caveat, as our glossary explains, was an old type of notice. It was not a patent. It was more like raising your hand and saying, \"I am working on this invention and plan to patent it soon.\" If someone else applied for a patent on the same thing while the caveat was active, the patent office was supposed to let the caveat holder know. Meucci's caveat, number 3335, was titled \"Sound Telegraph\".","A caveat lasted one year, and keeping it alive cost a fee each year. The US House of Representatives' 2002 resolution about Meucci mentions a fee of 10 dollars. Meucci renewed it for a few years, but after 1874 he did not, and the caveat lapsed. He later said he was simply too poor. Critics point out that he did manage to pay for several other full patents on different inventions in the 1870s, so the full reason is debated. Historians also argue about how much the short caveat text actually described an electrical telephone, since it did not explain clearly how the voice would be turned into electricity.","In 1872, Meucci and a friend went to Edward B. Grant, a vice president of the American District Telegraph Company in New York, hoping to test his invention on the company's wires. According to Meucci, his papers and model were left with the company and later said to be lost. Meucci always believed he had been treated unfairly. As later parts of this Deep Dive will show, his story became part of a long legal fight after 1876.","It is important to be fair here. Meucci was a real inventor who worked on voice transmission for many years, and he deserves to be remembered. But he did not receive a patent for a telephone, and the evidence about exactly what his devices could do is still argued about. Like Reis and Bourseul, he is one of the many people whose work came before the telephone that finally succeeded."]},{"heading":"Many Messages on One Wire","paragraphs":["While the dreamers were trying to send voices, the big telegraph companies had a different, very practical worry: their wires were too busy. In the 1870s the largest American telegraph company, Western Union, ran wires on poles across the country. A normal telegraph wire could carry only one message at a time. If a company wanted to send more messages, it had to string more wire, which meant more poles, more workers, and much more money. Whoever found a way to send several messages along a single wire at the same time could become very rich.","Inventors attacked this problem in different ways. Thomas Edison, then a young telegraph inventor, built a \"quadruplex\" system in 1874 that could send four messages on one wire, two in each direction, by cleverly using both the direction and the strength of the current. But a group of inventors tried something that sounds more like music class: they used musical notes.","Here is the idea. Every vibrating object has a natural pitch. If you pluck a short, stiff steel strip, called a reed, it hums at one particular note. If you have a second reed tuned to exactly the same note, it will start to hum in sympathy when it \"hears\" that note, while reeds tuned to other notes stay quiet. This is called resonance. You can sometimes see it at home: sing a loud note near a piano with the sustain pedal down, and the matching strings will quietly hum back.","In a harmonic telegraph, the sending station has several reeds, each tuned to a different note, and each switched on by its own telegraph key. When an operator presses key number one, reed number one vibrates, sending a buzzing current at its pitch along the wire. Another operator can press key number two at the same moment, sending a different pitch. All the pitches travel together along one wire, mixed like several instruments playing at once. At the receiving station, a matching set of tuned reeds sits over electromagnets. Each receiving reed only responds to its own note, so it picks out its own message and ignores the others. In theory, one wire could carry many Morse code conversations at the same time.","In practice it was very hard. Reeds drifted out of tune, signals blurred together, and long wires weakened the tones. But the harmonic telegraph turned out to be a doorway. To make it work, inventors had to think deeply about how sound vibrations could be copied into an electric current and back again, and that is exactly the problem of the telephone. Two of the inventors racing to build a harmonic telegraph would become the main rivals in the telephone story: Elisha Gray and Alexander Graham Bell."]},{"heading":"Elisha Gray, the Farm Boy Who Built Western Electric","paragraphs":["Elisha Gray was born on 2 August 1835 in Barnesville, Ohio, into a Quaker family, and grew up on a farm. He was fascinated by electricity and spent several years at Oberlin College in Ohio, where he experimented with electrical devices and built laboratory equipment, though he did not graduate. In 1865 he invented a self-adjusting telegraph relay, a device that helped weak telegraph signals keep working, and patented it in 1867. It was the first of more than 70 patents he would receive.","In 1869 Gray and a partner, Enos M. Barton, founded a company called Gray and Barton in Cleveland to make telegraph equipment, mostly for Western Union. The business soon moved to Chicago. In 1872 Western Union bought a third of the company, and it was renamed the Western Electric Manufacturing Company. Western Electric grew into one of the most important electrical manufacturers in America. In a twist of history, a few years later it would become the company that built telephones for Bell's own company.","So by the mid-1870s Gray was not a struggling outsider like Meucci or Reis. He was an experienced, respected inventor with money, workshops and connections to the biggest telegraph company in the country. In 1874 he stepped back from running the business so he could do his own research. He became fascinated with sending musical tones by electricity. On 29 December 1874 he demonstrated his \"musical telegraph\" at a Presbyterian church in Highland Park, near Chicago, sending tunes electrically. Because his device could produce notes electrically, some people today call him an early ancestor of the electronic music synthesizer.","Gray's main goal was the harmonic telegraph: many messages on one wire, using musical notes. He filed patent applications for his ideas in early 1875. His financial backer, a Philadelphia dentist named Samuel S. White, wanted him to focus on the telegraph, where the money seemed to be, rather than on the idea of transmitting speech. Gray did think about speech, though, and his ideas were heading toward a telephone.","Gray was not alone in this race. In Boston, another inventor had been funded to build a harmonic telegraph too. He was not a telegraph professional at all. He was a young Scottish teacher of deaf students, a man who knew more about how voices and ears worked than almost anyone, and who could not stop thinking about how sound might travel along a wire. His name was Alexander Graham Bell."]}],"deepDive":"Why did Bourseul's idea and Reis's Telephon fall short, while the telephone of 1876 succeeded? The key is the difference between an interrupted current and an undulating (smoothly varying) current. A sound wave is a pressure that rises and falls continuously. Its pitch depends on how many times per second it repeats (its frequency, measured in hertz), while its tone colour, or timbre, depends on the exact shape of the wave, which can be described as a mix of many frequencies at different strengths, called harmonics or overtones. Vowels are distinguished mainly by their overtones, so to make words understandable a telephone must preserve the wave's shape, not just its repetition rate. A make-and-break contact produces a current that is either on or off. That square, pulsing current keeps the timing of the vibration, so a melody's pitch survives, but most of the detailed shape is replaced by sharp on-off steps. This is why Reis's audiences heard tunes clearly but speech only fitfully. Supporters of Reis have argued that when the platinum contact was set very lightly, it did not fully break the circuit but varied its pressure and therefore its electrical resistance, producing a partly undulating current. This is essentially the principle of the later loose-contact and carbon microphones. That is why the 1947 tests found that an 1863 instrument could pass intelligible but very faint speech. Courts in the 1880s, focused on what Reis had actually described and intended, generally held that his method was the interrupted-current method and not the one Bell patented. The harmonic telegraph is an early example of what engineers now call frequency-division multiplexing: sending several signals at once on one channel by giving each its own frequency band. The same principle later allowed thousands of telephone calls to share long-distance cables, and radio stations to share the air. Historians studying this period also stress how much funding and networks mattered. Gray had Western Union connections and a wealthy backer; Bell had Boston investors; Reis was a poorly paid teacher; Meucci was an impoverished immigrant who struggled with English. Who got credit was shaped not only by ideas but by money, language, lawyers and timing.","funFact":"Johann Philipp Reis's most famous test sentence, \"Das Pferd frisst keinen Gurkensalat\", means \"The horse does not eat cucumber salad\", and it was chosen to be so silly that the listener could not possibly guess it in advance.","check":{"q":"What did inventors hope a harmonic telegraph would do?","a":"Send several telegraph messages along one wire at the same time, each using a different musical note","wrong":["Play music in theatres without an orchestra","Send telegraph messages without any wire at all","Translate Morse code automatically into spoken words"]},"sources":[{"title":"Oktober 1861: Die Erfindung des Telefons","publisher":"Deutsches Historisches Museum (LeMO)","url":"https://www.dhm.de/lemo/rueckblick/oktober-1861-die-erfindung-des-telefons.html"},{"title":"Philipp Reis's telephone in Aberdeen","publisher":"arXiv (University of Aberdeen authors)","url":"https://arxiv.org/abs/1811.01357"},{"title":"Johann Philipp Reis","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Johann_Philipp_Reis"},{"title":"Charles Bourseul","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charles_Bourseul"},{"title":"Antonio Meucci","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Antonio_Meucci"},{"title":"Stories From Main Street: Staten Island Museum Differs On Telephone's Inventor","publisher":"CBS New York","url":"https://www.cbsnews.com/newyork/news/telephone-inventor-staten-island/"},{"title":"Elisha Gray","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Elisha_Gray"}],"photos":[{"src":"img/deep/telephone/05-1.jpg","alt":"A replica of Philipp Reis's 1860s telephone receiver: a wire coil around a needle, mounted on a wooden sounding box.","file":"Philipp Reis Telephone Replica 02.png","url":"https://commons.wikimedia.org/wiki/File:Philipp_Reis_Telephone_Replica_02.png","author":"Travok32","license":"CC BY 3.0"},{"src":"img/deep/telephone/05-2.jpg","alt":"A photograph of Antonio Meucci (1808-1889), the Italian-American inventor who worked on an early telephone.","file":"Antonio Meucci.jpg","url":"https://commons.wikimedia.org/wiki/File:Antonio_Meucci.jpg","author":"Unknown author","license":"Public domain"},{"src":"img/deep/telephone/05-3.jpg","alt":"An engraved portrait of Elisha Gray, the American inventor who raced Alexander Graham Bell to patent the telephone.","file":"Elisha Gray portrait.jpg","url":"https://commons.wikimedia.org/wiki/File:Elisha_Gray_portrait.jpg","author":"Unknown author","license":"Public domain"}],"words":4004},{"n":6,"title":"Alexander Graham Bell, Teacher of Sound","when":"1847 – 1875","summary":"Alexander Graham Bell grew up in Scotland in a family that studied how people speak. He became a teacher of deaf students in Boston, and at night he tinkered with wires, magnets and tuned steel reeds. Then, on a hot June day in 1875, a stuck reed made a twang that changed everything.","sections":[{"heading":"A Family Obsessed with Voices","paragraphs":["Alexander Bell was born on 3 March 1847 in Edinburgh, Scotland, in a family home on South Charlotte Street. Yes, at first he was just Alexander Bell. He was named after his grandfather, and his family called him \"Aleck\". When he was 10, he asked for a middle name like his two brothers had, and on his 11th birthday he adopted \"Graham\", after Alexander Graham, a Canadian who knew his father.","If any family was going to produce an inventor of the telephone, it was probably this one, because the Bells were experts in the human voice. Aleck's grandfather, also named Alexander Bell, taught elocution, the art of speaking clearly and expressively, and helped people who stammered. His father, Alexander Melville Bell, was a famous teacher of speech and a phonetician, a scientist who studies the sounds of language. He wrote books on speaking that were used in schools for decades. Words, mouths, tongues and voices were discussed at the Bell dinner table the way some families talk about football.","Aleck's mother, Eliza Grace Symonds Bell, was a talented painter of miniature portraits and a gifted pianist. She was also hard of hearing, and her hearing got worse as Aleck grew older, until she was deaf. She used an ear trumpet, a horn-shaped tube held to the ear to collect sound. Aleck found his own way to talk with her: instead of shouting, he spoke in a low, clear voice very close to her forehead, so that she could feel the vibrations of his voice through her head. He also learned to use finger spelling with her. Many historians believe that growing up with a deaf mother helped make Aleck deeply curious about how sound travels and how people hear.","He was a lively, inventive boy. When he was about 12, he was playing at a neighbour's flour mill and saw how hard it was to remove the husks from wheat grains. He came up with a simple machine, using rotating paddles and a nail brush, that did the job. It was used at the mill for years. Aleck also loved music, played the piano by ear and was a brilliant mimic who could imitate voices and sounds."]},{"heading":"Visible Speech and a Talking Dog","paragraphs":["In the 1860s Aleck's father worked on his greatest project. He wanted a way to write down any sound any human could make, in any language or accent. Ordinary letters are not good at this. Think of how differently the letters \"ough\" sound in \"though\", \"through\" and \"cough\". Melville Bell's answer was a system he called Visible Speech, published in 1867 in a book called \"Visible Speech: The Science of Universal Alphabetics\".","Visible Speech did not use normal letters at all. Each symbol was a little picture of what your mouth does. Curved shapes showed the position of the tongue, other marks showed whether the lips were open or rounded, and a line showed whether the voice box was buzzing. If you learned to read these symbols, you could pronounce a word you had never heard, in a language you did not know, just by following the instructions for your mouth.","Aleck and his brothers helped demonstrate the system. Their father would send the boys out of the room. A volunteer from the audience would then make some strange sound, perhaps a phrase in a foreign language, a sneeze, or a regional accent, and Melville Bell would write it down in Visible Speech. When the boys came back in, they would read the symbols and reproduce the sound so exactly that audiences were amazed. It was a bit like a magic trick, but it was really science.","Melville Bell soon realized Visible Speech could help deaf people. Someone who cannot hear cannot copy speech by listening, but they could learn from symbols showing what to do with their lips, tongue and throat. This became one of the main tools Aleck used later as a teacher. (Over time, other teaching methods replaced Visible Speech, because it was complicated to learn.)","The Bell boys also had fun experimenting with speech themselves. After seeing a speaking machine built by the scientist Charles Wheatstone, Aleck and his older brother Melville (called \"Melly\") built their own talking head, with movable lips and tongue and a throat made from tin. When they blew air through it with a bellows, it could produce a sound like \"Ma-ma\", and Aleck later remembered that neighbours came out to look for the crying baby. Aleck also trained the family's Skye terrier, Trouve, to growl steadily while he moved the dog's mouth and throat with his hands. According to Bell's own memory, the result sounded a bit like \"How are you, Grandmamma?\" It was a silly experiment, but notice what he was doing: studying how shapes of the mouth turn a plain buzz into words."]},{"heading":"A Young Teacher and a Lucky Mistake","paragraphs":["Aleck went to the Royal High School in Edinburgh but was not a star pupil and left at 15. He then spent a year in London with his grandfather, who treated him like a young adult and encouraged his love of learning. At just 16 he became a pupil-teacher of elocution and music at Weston House Academy in Elgin, in the north of Scotland, teaching boys not much younger than himself while studying Latin and Greek. Later he studied at the University of Edinburgh and at University College London, though he did not finish a degree, and he taught at schools in Bath and London, including teaching deaf children.","He also kept experimenting. As a teenager he began studying how vowel sounds are made, using tuning forks held in front of his mouth to listen to the different pitches that make up each vowel. When he wrote about this to a speech expert, Alexander Ellis, he learned that the great German scientist Hermann von Helmholtz had already done similar work. Helmholtz had used electromagnets to make tuning forks vibrate and combine into vowel-like sounds.","Here comes one of the most famous mistakes in invention history. Bell could not read German well. Looking at Helmholtz's book, he got the wrong idea that Helmholtz had sent vowel sounds along a wire by electricity. Helmholtz had done no such thing. But Bell later said that this misunderstanding gave him confidence: if a famous scientist could send vowels electrically, then surely speech could travel along a wire too. Sometimes believing something is possible is what keeps an inventor going.","There was also great sadness in these years. Tuberculosis, a lung infection that was a leading cause of death in the 1800s, struck the family. Aleck's younger brother Edward died of it in 1867, and his older brother Melly in May 1870. Aleck himself was thin and unwell, and his parents feared he would be next. Melville Bell made a big decision: the family would leave Britain for a healthier life in Canada."]},{"heading":"A New Home Above the Grand River","paragraphs":["In the summer of 1870, Aleck, his parents and Melly's widow crossed the Atlantic. According to the City of Brantford, they arrived in August 1870 and settled on a small farm on a hill called Tutelo Heights, just outside Brantford, Ontario. The house, now known as the Bell Homestead, still stands and is a museum and a National Historic Site of Canada.","Aleck was 23 and in poor health when he arrived. The fresh country air, rest and walks did him good. He liked to sit on a slope above the Grand River, a spot he called his \"dreaming place\", and think. He turned a carriage house into a workshop. He also became interested in the language of the Mohawk people living nearby on the Six Nations reserve. He learned some Mohawk and wrote down its sounds using Visible Speech, and he was honoured by the community for this work.","In his Brantford workshop Bell was already mixing music and electricity. He adapted a melodeon, a small reed organ pumped with the feet, so that it could send musical notes along a wire by electricity. It was a small experiment, but it shows where his mind was heading: toward tones, reeds and electric currents, the same ingredients that would soon fill his Boston workroom.","After about eight months, Aleck was healthy again, and an opportunity arrived from the United States. A school for deaf children in Boston wanted someone to teach Visible Speech to its teachers. They had first asked his father, who suggested Aleck go instead. In April 1871 Aleck moved to Boston. For the next several years he lived and worked in the United States but returned to Brantford in the summers. That back-and-forth matters, because some of his most important telephone thinking happened on those visits home."]},{"heading":"Teacher of the Deaf in Boston","paragraphs":["Boston in the 1870s was a booming city of universities, factories, publishers and inventors. Bell began at the Boston School for Deaf Mutes (the word \"mute\" is no longer used this way, and today the school is called the Horace Mann School for the Deaf). Its principal, Sarah Fuller, was a pioneer in teaching deaf children to speak. Bell trained her teachers to use Visible Speech, and then repeated his training at schools in Hartford, Connecticut, and Northampton, Massachusetts. His results impressed people, and his reputation grew fast.","What did a lesson look like? Imagine a classroom with a large chart of Visible Speech symbols on the wall. Bell would point to a symbol and show a child where to place the lips and tongue, letting the child feel the vibration of his throat with their fingertips and then feel their own. Step by step, a deaf child who had never heard a word could learn to produce sounds and syllables. It was slow, patient work, and it trained Bell to think about speech in extraordinary detail: exactly how each sound is shaped, and exactly what kind of vibration it makes. That knowledge would turn out to be his secret weapon as an inventor.","In October 1872 he opened his own small school in Boston, which he called a School of Vocal Physiology, to train teachers of deaf students. Vocal physiology means the science of how the body makes the voice. Around 1872–73 he also became a professor of vocal physiology at Boston University's School of Oratory (sources differ on the exact year), while still only in his mid-twenties. He was a tall, dark-haired man with a beard, who often worked late into the night and slept late into the morning.","Teaching was also how Bell met the two families who would change his life. One of his private pupils was a deaf boy named Georgie Sanders. Georgie's father, Thomas Sanders, was a wealthy leather merchant. Bell lived for a time at the home of Georgie's grandmother in Salem, Massachusetts, teaching the boy, and he was allowed to use the basement for his experiments.","Another student, starting in 1873, was a 15-year-old girl named Mabel Hubbard. Mabel had been born on 25 November 1857 in Cambridge, Massachusetts. When she was about five, she caught scarlet fever, a dangerous illness in those days, and it left her completely deaf. Her family refused to send her away to an institution. Instead they helped her learn to speak and to lip-read, and she became extremely good at both, even in several languages. Mabel's father, Gardiner Greene Hubbard, was a Boston lawyer and businessman who helped found the Clarke School for the Deaf in Northampton, the first school in the United States to teach deaf children mainly through speech and lip-reading.","Bell's teaching came from his family's belief that deaf children should be helped to speak and lip-read. In later parts of this Deep Dive we will look at how many Deaf people disagreed with his views, especially about sign language. But in the 1870s he was a dedicated, hard-working teacher, and his students were very important to him. Over time, his feelings for Mabel grew into love. Mabel was more than ten years younger, and her parents at first thought she was too young. In November 1875 the two became engaged, and they married on 11 July 1877."]},{"heading":"Backers, a Real Ear and the Mechanic from Salem","paragraphs":["Even while teaching full time, Bell spent his evenings on inventions. Like Elisha Gray, he was working on a harmonic telegraph, the multi-message telegraph that used tuned reeds, which you met in Part 5. He even liked to show a party trick: singing a note into a piano and listening to the matching string answer, the same resonance his telegraph depended on.","Inventing costs money, and Bell had little. Two men stepped in. One was Thomas Sanders, Georgie's father. The other was Gardiner Greene Hubbard, Mabel's father. Hubbard had a special interest in the telegraph. He believed Western Union had too much power and had campaigned for the government to run a cheaper postal telegraph service. A system that let one wire carry many messages could shake up the whole telegraph business. In early 1875 the three men made an agreement: Sanders and Hubbard would pay for experiments, and they would share in any patents Bell received.","Bell's mind kept wandering, though, from telegraphs toward speech. In 1874, with the help of a Boston ear doctor, Clarence Blake, he experimented with an amazing and slightly spooky instrument: a real human ear taken from a person who had died, used for medical science. Bell attached a stalk of straw to the tiny bones of the ear. When he spoke into it, the eardrum vibrated, the bones moved, and the straw traced wavy lines on a piece of smoked glass, drawing a picture of his voice. Bell was struck by something. The eardrum was thin and delicate, yet it could move the much heavier bones. Maybe a thin iron disc vibrated by the voice could move enough to change an electric current.","That summer, in July 1874, Bell was back at his parents' home near Brantford. Sitting in his dreaming place above the Grand River, he worked out the principle of a speaking telephone in his head: a sound wave could be copied into an electric current whose strength rose and fell exactly like the air pressure of the voice, and an electromagnet at the other end could turn that current back into sound. Parks Canada's plaque at the Bell Homestead says that the basic idea of the telephone was conceived there in July 1874. Bell would later say the telephone was conceived in Brantford and born in Boston. Knowing the idea and building it, however, were very different things.","Bell was a brilliant thinker about sound, but he was not skilled at building electrical equipment. Fortunately, there was a place in Boston full of people who were. Charles Williams Jr. ran an electrical workshop at 109 Court Street, where inventors went to have their gadgets built. There Bell met a young man named Thomas Augustus Watson. Watson was born on 18 January 1854 in Salem, Massachusetts. He left school as a teenager, tried several jobs, and at 18 joined Williams's shop, where he learned to make telegraph instruments and fire-alarm equipment. Within two years he was one of the most skilled workers there. In 1874 he was assigned to build parts for Bell, and the two quickly became a team. Watson was practical, patient and good with his hands, and Bell was full of ideas. They worked in a room at the top of the building.","In March 1875 Bell visited Washington, D.C., to meet Joseph Henry, the famous American scientist who had built powerful electromagnets decades earlier and was now head of the Smithsonian Institution. Bell explained his ideas, including his hope of sending speech, and admitted he did not know enough about electricity to do it. According to Bell, Henry told him he had the germ of a great invention, and answered his worry with two words: \"Get it!\" Bell went back to Boston determined."]},{"heading":"The Twang of 2 June 1875","paragraphs":["Hubbard and Sanders wanted results on the harmonic telegraph, the invention they believed would make money. So through the spring of 1875, Bell and Watson worked on it. Their setup had several transmitters in one room and receivers in another, each with a thin steel reed held over an electromagnet. Normally, each transmitter reed vibrated and rapidly opened and closed a contact, sending a pulsing, on-off current down the wire.","2 June 1875 was a hot day in Boston. Watson was in one room tending the transmitters and Bell was in another room with the receivers. One of Watson's reeds was not vibrating properly. It seemed stuck, and its contact had been screwed down too tightly, so it was not opening and closing the circuit as it should. Watson plucked the reed with his finger to free it.","In the other room, Bell heard something through his receiver: not a plain buzz, but a twang, a sound with the richness of a plucked string, overtones and all. He rushed into Watson's room shouting to ask what he had just done and told him not to change anything.","Why was this so important? Because the contact was stuck closed, the reed was not switching the current on and off. Instead, the vibrating steel reed was moving back and forth near the electromagnet, and a moving magnetized piece of iron near a coil makes a small electric current, the effect Michael Faraday discovered in 1831. That current did not jump between on and off. It rose and fell smoothly, following every detail of the reed's vibration, including its overtones. This was exactly the undulating current Bell had been dreaming about. It proved that a vibrating piece of metal could create a current with the full shape of a sound, and that the current could make another piece of metal vibrate with the same shape far away. Voices are just more complicated vibrations. If a reed could do it, a thin disc moved by the voice should be able to do it too.","Bell described the discovery in letters, and years later he and Watson both told the story many times, with small differences in the details, which is normal for memories. That same evening, Bell sketched a design, and Watson built it, apparently by the next day: a frame shaped like a gallows holding a stretched membrane with a piece of metal attached, over an electromagnet. When Bell spoke or sang into it, Watson, listening at the other end, heard voice-like sounds, but he could not make out clear words. It was progress, but it was not yet a telephone you could talk on.","Over the following months, the two men kept testing. The problem was power. In the gallows design, all the electrical energy came from the speaker's voice moving a bit of metal near a magnet, and a voice does not carry much energy. The current that reached the far end was extremely weak. Bell and Watson tried different membranes, different magnets and different coils. Listening at the receiving end meant pressing an ear tight against the instrument and straining to catch anything at all. They were close, and they knew it, but turning a faint mumble into clear words would take more invention."]},{"heading":"Racing Toward the Patent Office","paragraphs":["For the rest of 1875 Bell was pulled in many directions. Hubbard pushed him to finish the harmonic telegraph and worried that the speech idea was a distraction. Bell was also teaching, falling in love with Mabel, and, during the summer of 1875 at his parents' home in Brantford, writing out the detailed description of his method that he hoped to patent. He believed his key discovery was not one particular gadget but the principle itself: transmitting sound by an electric current that varies in strength exactly as the air vibrates.","A patent, as our glossary explains, is a government document that gives an inventor the right to control an invention for a set time. In those days, getting a patent in one country first could sometimes cause problems getting one in another. Bell wanted protection in Britain too, and he arranged for a Canadian friend of his family, the politician and newspaper publisher George Brown, to take his description to Britain, so he delayed filing in the United States. But the weeks went by and nothing came of it.","Meanwhile, just as you read in Part 5, Elisha Gray in Chicago was thinking along similar lines. Inventors with similar knowledge, reading the same science and chasing the same telegraph prize, often reach similar ideas at almost the same time. So the question was no longer just who could build a talking machine, but whose ideas would be officially recorded first.","By early 1876 Hubbard had lost patience. Bell was about to hurry his idea toward the patent office in Washington, D.C. He did not know it yet, but on the very same day his application arrived, a lawyer for Elisha Gray would also deliver to that same patent office a description of Gray's own idea for sending speech along a wire."]}],"deepDive":"Bell's breakthrough of 2 June 1875 is best understood as the difference between modulating a current by interruption and generating or modulating it continuously. In the harmonic telegraph, a reed driven by its electromagnet opened and closed a contact, producing a pulsed current at the reed's frequency. When the contact screw was set too tightly, the circuit stayed closed, and the plucked reed acted instead as a tiny generator: a magnetized steel reed moving near a coil changes the magnetic flux through the coil, and by Faraday's law of induction this induces a voltage proportional to the rate of change of that flux. The resulting current is analog: its waveform follows the mechanical vibration, overtones included. Bell's existing interest in Helmholtz's analysis of vowels as combinations of harmonics told him why this mattered: if the full waveform could survive, so could the overtones that distinguish speech sounds. The magneto design that grew from this was reversible, the same kind of instrument could act as transmitter or receiver, but its output was tiny, because all the energy came from the voice itself. That is why the gallows prototype produced only faint, unclear sounds, and why later transmitters used a battery whose current was varied by the voice (first a liquid variable-resistance transmitter, then carbon). Historians debate several points about this period. One is how much Bell understood electricity versus how much Watson's craft and Williams's workshop supplied, since Bell himself told Joseph Henry he lacked electrical knowledge. Another is how independent the paths of Bell and Gray were; both were trying to multiplex telegraph lines using tuned reeds, and both moved toward speech within months of each other. A third concerns dates and memories: many famous details, like Henry's \"Get it!\", come from Bell's own later accounts and testimony in patent cases, where people had reasons to stress particular dates. Notebooks, letters and witness testimony are therefore read carefully, and small disagreements between Bell's and Watson's descriptions of the June experiment are treated as ordinary differences in memory rather than evidence of invention.","funFact":"As a teenager, Bell trained his family's Skye terrier to growl while he shaped its mouth with his hands, and he later remembered that the dog could be made to say something like \"How are you, Grandmamma?\"","check":{"q":"What happened on 2 June 1875 that gave Bell his key clue?","a":"Watson plucked a stuck reed and Bell heard its twang, with overtones, through the wire in another room","wrong":["Bell spoke the first full sentence over a telephone to Watson","Bell received his telephone patent from the patent office","Bell demonstrated the telephone to Queen Victoria"]},"sources":[{"title":"Alexander Graham Bell","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alexander_Graham_Bell"},{"title":"Bell Homestead National Historic Site of Canada","publisher":"Parks Canada","url":"https://pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=1772"},{"title":"Bell Homestead: History","publisher":"City of Brantford","url":"https://www.brantford.ca/things-to-do/arts-and-culture/museums-and-galleries/bell-homestead/history/"},{"title":"Visible Speech","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Visible_Speech"},{"title":"Mabel Gardiner Hubbard","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mabel_Gardiner_Hubbard"},{"title":"Gardiner Greene Hubbard","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gardiner_Greene_Hubbard"},{"title":"Thomas A. Watson","publisher":"Braintree Electric Light Department","url":"https://beld.com/thomas-a-watson"},{"title":"Thomas A. Watson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_A._Watson"}],"photos":[{"src":"img/deep/telephone/06-1.jpg","alt":"The Bell Homestead in Brantford, Ontario, the Bell family's first home in Canada, now a museum.","file":"Alexander Graham Bell in Brantford, Ontario, Canada -the Bell Homestead, the Bell Family's first home in Canada, now preserved as a museum to A.G. Bell.JPG","url":"https://commons.wikimedia.org/wiki/File:Alexander_Graham_Bell_in_Brantford,_Ontario,_Canada_-the_Bell_Homestead,_the_Bell_Family%27s_first_home_in_Canada,_now_preserved_as_a_museum_to_A.G._Bell.JPG","author":"Harry Zilber","license":"CC BY-SA 3.0"},{"src":"img/deep/telephone/06-2.jpg","alt":"Melville Bell's Visible Speech chart: drawings of mouth, tongue and lips, each with its sound symbol.","file":"Melville Bell's Drawing of Organic Formation of the Principal Elements of Speech.jpg","url":"https://commons.wikimedia.org/wiki/File:Melville_Bell%27s_Drawing_of_Organic_Formation_of_the_Principal_Elements_of_Speech.jpg","author":"Bell, Alexander Melville","license":"Public domain"},{"src":"img/deep/telephone/06-3.jpg","alt":"Thomas A. Watson, Bell's assistant, in later life, holding a model of Bell's first telephone.","file":"Thomas A. Watson cph.3b07402.jpg","url":"https://commons.wikimedia.org/wiki/File:Thomas_A._Watson_cph.3b07402.jpg","author":"Unknown author","license":"Public domain"}],"words":3819},{"n":7,"title":"The Same Day at the Patent Office","when":"February – March 1876","summary":"On one winter Monday in 1876, two inventors sent papers about a talking machine to the same government office in Washington. Alexander Graham Bell got the patent, and a few weeks later he spoke the first clear sentence ever heard over a telephone wire. People are still arguing about what happened in between!","sections":[{"heading":"Two Envelopes on Valentine's Day","paragraphs":["Picture Washington, D.C., on the morning of Monday, February 14, 1876. It is Valentine's Day, but nobody at the United States Patent Office is thinking about cards or chocolates. The Patent Office sits inside a huge stone building with tall columns, and its halls are lined with glass cases full of little models of inventions: ploughs, sewing machines, water wheels and clever gadgets of every kind. Clerks scratch away with steel pens. Lawyers in dark coats come and go, carrying envelopes stuffed with drawings and long, careful descriptions.","Two of those envelopes, delivered that day, would become some of the most argued-about pieces of paper in the history of invention.","One came from Alexander Graham Bell, the 28-year-old Boston teacher of deaf students whom we met in Part 6. It was a full application for a patent, titled “Improvement in Telegraphy.” It described Bell's ideas for sending several telegraph messages at once using musical tones, but tucked inside it was something much bigger: a method for sending “vocal or other sounds” along a wire by making the electric current rise and fall in the same pattern as the sound itself. In other words, it described a way to send a human voice.","The other envelope came from Elisha Gray, the experienced Chicago inventor and co-founder of the company that became Western Electric, whom we met in Part 5. Gray was not asking for a patent yet. He was filing a caveat, a kind of official notice that said, in effect, “I am working on this invention and I plan to patent it soon.” His caveat had a long title: “Instruments for Transmitting and Receiving Vocal Sounds Telegraphically.” It included a drawing of a person speaking into a cone-shaped mouthpiece above a small container of liquid. That design is called a liquid transmitter, and we will see exactly how it works later in this chapter.","So on the very same day, two inventors who barely knew each other told the same government office that they had found a way to make electricity talk. It sounds almost like a made-up story. But it really happened, and the papers still exist in archives today.","Bell's application had actually been ready for weeks. So why had it not been filed sooner?","The reason was money and a bit of international planning. Bell had made a deal with George Brown, a Canadian newspaper owner and politician from Toronto, who agreed to help pay for a British patent. Patent rules in Britain at that time could refuse a patent for an invention that had already been made public somewhere else. So Bell's side wanted Brown to file in Britain first, before the American patent was published. Brown sailed to England carrying a copy of Bell's description, but he was slow to act, and some accounts say he worried that British experts would think the idea was silly.","Meanwhile, Bell's main backer in Boston, Gardiner Greene Hubbard, was growing impatient. Hubbard was a lawyer and businessman, and he was also the father of Mabel Hubbard, the young woman Bell hoped to marry. Hubbard understood patents well, and he knew that other inventors, especially Elisha Gray, were working on very similar musical telegraph ideas. Every week of waiting was a week in which someone else might get there first.","In the end, Hubbard decided not to wait for Brown. Bell's patent lawyers in Washington, Anthony Pollok and Marcellus Bailey, had the application ready, and it was delivered by hand to the Patent Office on February 14. Bell himself was in Boston at the time. Some accounts say Hubbard sent the application in without asking Bell first, which would show how nervous his backers were about the race.","It is worth pausing on how much depended on this one decision. If Hubbard had waited even a few more days, Gray's caveat would have been sitting in the office alone, and the story of the telephone might have been told very differently."]},{"heading":"Patents and Caveats: The Rules of the Race","paragraphs":["To understand why people still argue about February 14, 1876, you need to know what a patent and a caveat actually were.","A patent is a government document that gives an inventor the right to control their invention for a set time. In the United States in 1876, a patent lasted 17 years. During that time, nobody else was allowed to make, use or sell the invention without the patent owner's permission. In return, the inventor had to explain the invention clearly in writing, with drawings, so that after the patent ran out, anyone could use the idea. A patent is a kind of deal: the inventor shares the secret, and the government protects it for a while.","Getting a patent was not automatic. A government worker called an examiner read each application and checked whether the idea was new and whether anyone else had claimed something similar. If two people seemed to claim the same invention, the examiner could declare an interference, which was like calling a time-out so the Patent Office could figure out who had really invented it first.","A caveat was something smaller. It was an old type of US patent office notice, now no longer used, that an inventor could file when an invention was not quite finished. It cost only a small fee, about 10 dollars, and lasted for one year. The caveat was kept secret. Its main power was this: if someone else applied for a patent on something that clashed with the caveat during that year, the Patent Office was supposed to warn the person who filed the caveat, and give them about three months to send in a full application of their own.","There was one more very important rule. In 1876, the United States gave patents to the first person to invent something, not simply to the first person whose papers reached the office. (The US only switched to a mostly “first to file” system in the 2010s.) That means the hour of arrival was not supposed to decide everything by itself. But it still mattered a great deal, because it affected whether Gray's caveat could block Bell's application or force a contest between them. That is why the order of the two envelopes became such a big deal."]},{"heading":"Who Got There First?","paragraphs":["Here is where the story gets tangled. Nobody wrote down the exact minute each envelope came through the door, so historians have had to piece the day together from office records and from what people said years later, often in court.","What seems clear is that Gray signed his caveat and had it notarized (officially stamped by a witness) in Washington that Monday morning, and his patent lawyer, William D. Baldwin, took it to the Patent Office. Bell's lawyer, Marcellus Bailey, delivered Bell's application by hand, probably shortly before noon.","But arriving at the building was not the same as being officially recorded. The office kept a “cash blotter,” a daily list of fees paid. Bell's fee was written down early in the day; one account says his application was the fifth entry. Gray's caveat, according to many accounts, sat in a basket of incoming papers and was not entered until later that afternoon, far down the list. So on paper, Bell's application looked like it came first, even if Gray's lawyer may have walked through the door earlier.","Gray himself changed his mind about this over the years. At first he wrote that he had been “an hour or two behind” Bell. Later, after years of lawsuits had dug up more evidence, he became convinced that his caveat had actually arrived first. To this day, the honest answer is that which one arrived first is still debated.","What happened next is better documented. On February 19, five days after the filings, the patent examiner, Zenas Fisk Wilber, read both documents. He noticed that one idea in Bell's application, using a changing resistance to make the current copy a sound wave, also appeared in Gray's caveat. Following the rules, Wilber suspended Bell's application for three months so that Gray would have time to file a full application if he wanted to.","Bell's lawyers protested. They argued that Bell's application had been received first, so the caveat should not count against it. The Patent Office agreed, and the suspension was lifted. Bell then travelled from Boston to Washington in late February and met Wilber in person. What exactly the two men talked about in that meeting would later become the most controversial part of the whole story, as we will see.","Gray, meanwhile, did not rush to file a full application. He seems to have believed, like many telegraph experts, that the real money was in sending many telegraph messages at once, not in a talking toy. That decision would cost him dearly."]},{"heading":"Patent Number 174,465","paragraphs":["On March 7, 1876, the United States Patent Office issued Patent No. 174,465 to Alexander Graham Bell of Salem, Massachusetts. (Bell often stayed with the Sanders family in Salem, which is why that town is printed on the patent.) Its official title was still “Improvement in Telegraphy.” Nothing on the front page shouted the word “telephone.”","The patent was only a few pages long, with a couple of sheets of drawings. Much of it describes ways to send several musical tones down one wire. But near the end come the claims, the numbered sentences that say exactly what the inventor owns. Claim 4 describes making “undulations,” which means smooth waves, in a continuous electric current by gradually increasing and decreasing the resistance of the circuit. Resistance is how hard it is for electricity to flow through something. Change the resistance smoothly, and the current changes smoothly too.","Claim 5 is the famous one. It claims the method of, and apparatus for, transmitting vocal or other sounds telegraphically by causing “electrical undulations, similar in form to the vibrations of the air” that go with the sound. In everyday words: make the electric current wiggle in exactly the same shape as the sound wave, send it down the wire, and turn it back into sound at the other end. That is the basic idea of every telephone that worked on wires for the next hundred years.","There was something strange about this patent, though. When it was granted, Bell had not yet made a device that sent clear spoken words. He had heard the twang of a reed in June 1875, and he and Watson had heard faint voice-like sounds with their “gallows” instrument that summer. But no one had yet heard a full, understandable sentence. The patent described a principle and some instruments that should work, rather than a finished, tested product. Patent law allowed this, as long as the description was clear enough.","Because Claim 5 was written so broadly, it covered almost any way of sending speech by an electric current that copied the sound wave. That made it fantastically valuable. Over the next years Bell's company would use it to defend its business in hundreds of court cases, which you will read about in Part 10. Patent 174,465 is often called one of the most valuable patents ever issued."]},{"heading":"How a Liquid Transmitter Works","paragraphs":["Before we get to the big moment, let's look at the strange device that made it possible. It is called a liquid transmitter, or sometimes a water transmitter.","Imagine a small metal cup filled with water that has a little acid mixed in. Acid makes water carry electricity much better than pure water would. A wire from a battery is connected to the cup. Above the cup hangs a stretched sheet of thin material called a diaphragm, a bit like the skin of a drum. A thin metal needle or wire is fixed to the middle of the diaphragm and dips just slightly into the liquid. A second wire runs from that needle out to the line and on to the receiver in the other room.","Now speak into a mouthpiece aimed at the diaphragm. Your voice is made of quick pushes and pulls in the air. Each push nudges the diaphragm down, so the needle sinks a tiny bit deeper into the acid water. Each pull lets the diaphragm rise, and the needle comes up a little. When the needle is deeper, the electricity has a wider, shorter path through the liquid, so the resistance drops and more current flows. When it rises, the resistance goes up and less current flows.","The result is wonderful: the current in the wire now rises and falls in the same pattern as your voice. Bell's own patent described the idea this way: the more deeply a wire is dipped in the liquid, the less resistance the liquid offers to the current.","At the far end, that wobbling current flows through an electromagnet, a coil of wire that becomes a magnet when electricity flows through it. The stronger the current, the harder the magnet pulls on a thin piece of iron or a reed nearby. As the current wobbles, the iron shakes back and forth, pushing the air and recreating the sound. You will learn much more about receivers in Part 9.","The liquid transmitter had big problems. The acid could spill, the needle had to be adjusted very carefully, and the sound was weak. It was a great tool for proving an idea in a laboratory, but not something you would want in your living room. That is why neither Bell nor anyone else used it in telephones that were sold to the public."]},{"heading":"Mr. Watson, Come Here","paragraphs":["Now we arrive at the most famous moment in telephone history.","It is Friday, March 10, 1876, three days after the patent was granted. Bell and his assistant, Thomas Watson, are working in Bell's rented rooms in Boston. Most accounts place them at 5 Exeter Place, where Bell lived and kept a small workshop. The transmitter, a liquid transmitter much like the one we just described, is in one room. The receiver is in another room, with the door closed between them. A wire runs from one to the other.","Watson waits in the receiving room with his ear pressed to the instrument. Bell leans over the transmitter in the other room and speaks into the mouthpiece.","That evening, Bell wrote about the experiment in his laboratory notebook. His entry describes how the receiving instrument was set up in one room and the transmitting instrument in another, and then says that he shouted into the mouthpiece: “Mr. Watson — come here — I want to see you.” Bell wrote that, to his delight, Watson came, and declared that he had heard and understood what Bell said.","Notice the exact words. Many books and films say Bell called “Mr. Watson, come here, I need you,” but that is not what his notebook records. The written wording, in Bell's own hand, is “Mr. Watson — come here — I want to see you.” Watson, writing his memories many years later, remembered it slightly differently, which is normal for human memory. That is why historians trust the notebook, written that same day, more than stories told decades afterwards.","Bell's notebook goes on. He asked Watson to repeat the words, and Watson did. Then they swapped places. Bell listened at the receiver while Watson read passages from a book into the transmitter. Bell wrote that he could definitely hear speech sounds coming from the receiver, though they were loud but muffled and not always clear. He could make out some words, but not every one.","There is also a well-known story, told by Watson in his autobiography published in 1926, that Bell called for him because he had spilled some of the battery acid on his clothes. It makes a fun scene, but it does not appear in Bell's notebook entry for that day, so it is best to treat it as a later memory rather than a certain fact. Whatever the reason for calling, the important thing is that the message got through.","Bell was thrilled. In a letter to his father written around this time, he said he felt he had at last found the solution to a great problem, and he imagined a day when wires would run into houses like water or gas pipes, so that friends could talk to each other without leaving home. The notebook from that day is now kept in the Library of Congress in Washington, D.C., as part of the Alexander Graham Bell Family Papers, and you can see scans of the pages online."]},{"heading":"A Fair Look at the Big Argument","paragraphs":["Now for the hard question that has followed Bell for 150 years. The transmitter that worked on March 10 used a needle dipped in acid water to change resistance. That is very similar to the drawing in Elisha Gray's caveat. And just two days earlier, on March 8, Bell's notebook had included a sketch of a liquid transmitter that looks a lot like Gray's drawing. Did Bell see Gray's papers?","Here are the pieces of evidence, laid out as fairly as possible.","First, the patent examiner. Ten years later, in 1886, Zenas Wilber signed a sworn statement saying that during Bell's visit in February 1876 he had shown Bell Gray's caveat drawing, and that Bell had given him money. Bell strongly denied this under oath. Wilber's story was not as solid as it sounds: in 1885 he had signed an earlier statement that said the opposite, and he was described as a heavy drinker who owed money to Bell's lawyer, Marcellus Bailey. His 1886 statement was also prepared with the help of lawyers for a rival company that was being sued by Bell's company. So both his statements are hard to trust.","Second, the margin note. In Bell's patent application there is a short passage about variable resistance in liquid that appears to have been added in the margin. Bell's supporters say this was his own idea, written before the filing. Some writers on Gray's side argue that it was added later. In 1879, Bell himself testified that Wilber had discussed Gray's caveat with him “in a general way” during the visit.","Third, Bell's earlier work. Bell's supporters point out that he had already been experimenting with variable resistance ideas, and that in the summer of 1875 he had heard sounds through his instruments. They argue that he understood the principle on his own, and that testing a liquid transmitter after the patent was granted was simply a sensible experiment.","Historians still disagree. In 2000, A. Edward Evenson argued in a book that Gray's idea may have leaked to Bell's lawyers, perhaps without Bell even knowing. In 2008, the journalist Seth Shulman argued in his book The Telephone Gambit that Bell did borrow from Gray's caveat. Other historians, including Bell's major biographer Robert V. Bruce, defended Bell and doubted Wilber's honesty. The courts of the time, after years of lawsuits, always ruled in Bell's favour. The Patent Office decided that although Gray may have been first to describe the variable-resistance idea, he had lost his claim by not acting on it until after others had shown it worked.","So what should you believe? The fairest answer is this: it has never been proven that Bell copied Gray, and it has never been completely disproven either. What we can say for sure is that both men were brilliant, both were working on the same problem at the same time, and both were building on the ideas of earlier people like Reis and Meucci. Inventions rarely spring from just one head."]},{"heading":"A Patent, a Device, and a Big Question","paragraphs":["By the middle of March 1876, Bell had two things almost nobody else in the world had: a United States patent covering the transmission of speech by electricity, and a working machine that had carried a whole sentence from one room to another.","But a machine that whispers through a closed door is not yet a world-changing invention. The sound was faint. The transmitter used a cup of acid. The wire was only a few metres long. To most people in 1876, the idea of talking through a wire sounded either like magic or like a parlour trick, a fun gadget to show guests at a party.","Bell and Watson quickly set to work making better instruments. Within months they had built new transmitters that used magnets and coils instead of acid, so they did not need any liquid at all. These magneto instruments were weaker but much simpler, and they could work as both a mouthpiece and an earpiece.","And Elisha Gray? He went on to have a long and successful career. He kept inventing, and in 1888 he patented the telautograph, a machine that could send handwriting over wires, an early ancestor of the fax machine. He died in 1901. He never stopped believing that he had been treated unfairly in the telephone story.","Bell, meanwhile, now faced a brand-new challenge, one that had nothing to do with wires or magnets. He held a patent and a working device. But he still needed to convince the world, from scientists and emperors to businessmen and ordinary families, that a talking wire was much more than a toy."]}],"deepDive":"The events of February and March 1876 sit at the centre of one of the longest-running disputes in the history of technology, and it is worth understanding why the evidence is so slippery. Under the US law of the time, patents were awarded on a first-to-invent basis, so the order in which papers reached the Patent Office was not in itself decisive. What mattered procedurally was whether Gray's caveat would trigger an interference against Bell's application. Patent examiner Zenas Fisk Wilber initially suspended Bell's application on February 19 for three months because Bell's claim about variable resistance overlapped Gray's caveat; Bell's attorneys argued that their application had been received first, and the suspension was withdrawn. Patent 174,465 issued on March 7. The disputed points are: when each document was actually received (office records show Bell's fee recorded earlier, while some accounts say Gray's caveat sat uncatalogued in an in-basket); whether a short passage on liquid variable resistance in Bell's application was added after his lawyers learned of Gray's caveat; and what passed between Bell and Wilber during Bell's late-February visit. Wilber gave contradictory sworn statements in 1885 and 1886, and the later one, alleging he showed Bell the caveat and received money, was drafted with lawyers for the Pan-Electric Telephone Company, a rival being sued by Bell. Bell denied the accusations under oath. Bell's notebook sketch of March 8 and the March 10 liquid transmitter strongly resemble Gray's caveat drawing, which is the core of the case made by writers such as A. Edward Evenson (2000) and Seth Shulman (2008). Bell's defenders, including biographer Robert V. Bruce, note Bell's earlier variable-resistance thinking and argue the March experiment was a proof of principle for a claim already made. Importantly, the liquid transmitter was a technological dead end: Bell's public demonstrations used magneto instruments, and practical telephones adopted carbon transmitters, which also work by variable resistance. Courts consistently upheld Bell's patent. Most historians today treat the question of copying as unresolved, while agreeing that several inventors were converging on electrical speech at the same moment.","funFact":"Bell's famous telephone patent, No. 174,465, never uses the word “telephone” in its title; it is officially called “Improvement in Telegraphy.”","check":{"q":"What did Bell say into the transmitter on March 10, 1876, according to his own notebook?","a":"Mr. Watson — come here — I want to see you","wrong":["Mr. Watson, come here, I need you","Hello, can you hear me?","What hath God wrought"]},"sources":[{"title":"Elisha Gray and Alexander Bell telephone controversy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Elisha_Gray_and_Alexander_Bell_telephone_controversy"},{"title":"Elisha Gray","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Elisha_Gray"},{"title":"US174465A - Improvement in telegraphy","publisher":"Google Patents","url":"https://patents.google.com/patent/US174465A/en"},{"title":"Alexander Graham Bell Receives First Patent","publisher":"Mass Moments (Mass Humanities)","url":"https://massmoments.org/moment-details/alexander-graham-bell-receives-first-patent.html"},{"title":"Invention of the telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Invention_of_the_telephone"},{"title":"Patent caveat","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Patent_caveat"},{"title":"Thomas A. Watson","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_A._Watson"}],"photos":[{"src":"img/deep/telephone/07-1.jpg","alt":"Sheet 1 of Bell's patent No. 174,465, granted March 7, 1876, with wave drawings and his signature.","file":"Drawing for an Improvement in Telegraphy - NARA - 595437 (page 1).jpg","url":"https://commons.wikimedia.org/wiki/File:Drawing_for_an_Improvement_in_Telegraphy_-_NARA_-_595437_(page_1).jpg","author":"Bell, Alexander Graham, 1847-1922 (NARA record: 10583213)","license":"Public domain"},{"src":"img/deep/telephone/07-2.jpg","alt":"Bell's notebook for March 10, 1876, with a sketch of his transmitter and the words \"Mr. Watson - Come here.\"","file":"AGBell Notebook.jpg","url":"https://commons.wikimedia.org/wiki/File:AGBell_Notebook.jpg","author":"Alexander Graham Bell","license":"Public domain"},{"src":"img/deep/telephone/07-3.jpg","alt":"A modern comparison: Elisha Gray's 1876 caveat drawing placed over a similar sketch in Bell's March 9 notebook.","file":"Bell-gray-smoking-gun.png","url":"https://commons.wikimedia.org/wiki/File:Bell-gray-smoking-gun.png","author":"Elisha Gray and Alexander Graham Bell","license":"Public domain"}],"words":3855},{"n":8,"title":"Showing the World","when":"1876 – 1878","summary":"Bell had a talking machine, but almost nobody believed in it yet. So he showed it off: to an emperor at a giant fair, to crowds in lecture halls, and even to Queen Victoria in her palace. Soon people were renting telephones in pairs and stringing wires between their homes and shops.","sections":[{"heading":"A Giant Fair for a Birthday","paragraphs":["In 1876 the United States turned 100 years old. To celebrate the centennial, the hundredth anniversary of the Declaration of Independence, the city of Philadelphia held an enormous fair called the Centennial Exhibition. It was the first official world's fair ever held in the United States.","Imagine walking through the gates in Fairmount Park, beside the Schuylkill River. The fair ran from May 10 to November 10, 1876, and covered a huge area with more than 200 buildings inside a fence nearly 5 kilometres (3 miles) long. The Main Exhibition Building alone was about 573 metres (1,880 feet) long, one of the biggest buildings in the world at the time. Around 10 million visitors came, at a time when the whole country had only about 46 million people. Dozens of nations sent displays.","The star of the fair was a gigantic steam engine called the Corliss Centennial Engine. It stood about 14 metres (45 feet) tall, could produce about 1,400 horsepower, and powered rows and rows of machines in Machinery Hall through long spinning belts and shafts. On opening day, President Ulysses S. Grant and the Emperor of Brazil, Dom Pedro II, started it together. Visitors could also see typewriters, new kinds of sewing machines, the right arm and torch of the future Statue of Liberty, and all kinds of telegraph equipment.","Somewhere in this sea of machines, among the displays about science and education, was a small exhibit by a Boston teacher named Alexander Graham Bell. It did not look like much: a few odd instruments, some wire, and a box or two. Most visitors walked straight past it.","Bell almost did not go at all. He was busy with his teaching in Boston, and his students had exams coming up. A well-known family story says that Mabel Hubbard, the young woman he hoped to marry, more or less tricked him onto the train to Philadelphia, and that he was annoyed with her until he realised she was right. Like many family stories, it may have grown a little in the retelling, but it is clear that Bell's backers, including Mabel's father Gardiner Greene Hubbard, wanted him at the fair. They knew that a single good demonstration in front of the right people could be worth more than months of work alone in a laboratory."]},{"heading":"The Emperor Picks Up the Receiver","paragraphs":["Every big fair had judges who walked from exhibit to exhibit to decide which inventions deserved awards. On Sunday, June 25, 1876, a hot summer day, the judges for electrical inventions reached Bell's table. They had been working for hours and were tired, and some accounts say they were ready to call it a day.","Among them were two very unusual judges. One was Sir William Thomson, the brilliant Scottish-Irish physicist who had helped make the transatlantic telegraph cable work, as you read in Part 4. He would later become Lord Kelvin. The other was Dom Pedro II, the Emperor of Brazil, who was touring the United States and was fascinated by science and education. According to many accounts, the emperor had already met Bell earlier that year in Boston, because he was interested in Bell's work teaching deaf students.","Standing nearby was another visitor with a special interest: Elisha Gray, whose caveat had reached the Patent Office on the same day as Bell's application. Gray was exhibiting his own telegraph inventions at the fair.","Bell's instruments had to be adjusted carefully, and it took some fiddling to get them working. The transmitter and receiver were placed some distance apart so the judges could be sure the sound was really coming through the wire. Bell went to the transmitter and spoke. Thomson listened at the receiver, and so did the emperor.","Thomson later reported that he heard Bell say “To be or not to be,” the famous line from Shakespeare's play Hamlet, and even the words that follow in the play, “there's the rub.” The sound was faint, but the words were there. Dom Pedro is said to have exclaimed something like “My God, it talks!” That quotation is repeated in many books, but nobody wrote it down at the moment, so we should treat it as a lively story rather than a certain fact.","What is certain is that the judges were deeply impressed. Bell's telephone received one of the exhibition's awards, and Thomson became one of its strongest early supporters. When he returned to Britain, he described the telephone at the meeting of the British Association for the Advancement of Science in Glasgow in September 1876, which was one of the first times it was presented to a British scientific audience. When a world-famous scientist like Thomson said the talking wire was real, other scientists started paying attention."]},{"heading":"Voices Along the Fence Posts in Ontario","paragraphs":["Talking from one end of a hall to another was one thing. But could a voice travel between towns? That summer, Bell set out to find out, and he did it in Canada.","Bell's parents lived on a farm at Tutela Heights, just outside the town of Brantford, Ontario. The family had moved there from Britain in 1870, as you read in Part 6. In the summer of 1876, Bell visited and began testing his telephone over longer wires. In one test, wire was strung along the tops of fences from Mount Pleasant Road to his father's house, with a receiver set up on the porch. Many years later, Bell remembered simply that it “worked.”","The most famous test came on August 10, 1876. Bell arranged to use a real telegraph line belonging to the Dominion Telegraph Company. The transmitter, with its batteries, was in Brantford. The receiver was in the town of Paris, Ontario, about 13 kilometres (8 miles) away, in the company's telegraph office, which was inside a shoe store owned by a man named Robert White. Bell himself is usually described as listening at the Paris end.","Picture the scene in the little shop in Paris: shelves of boots, a telegraph desk, and a small group of curious people crowding around a strange instrument. Then, out of the receiver, came voices from Brantford: people speaking, reading aloud and singing songs. By most accounts, some of the voices belonged to Bell's own relatives, including his father and his uncle.","This was a one-way call. People in Paris could hear Brantford, but they could not answer back through the telephone, because of how the equipment and batteries were set up. Even so, it is often called the world's first long-distance telephone call. Today a plaque in Paris remembers the event.","Two months later, in October 1876, Bell and Watson managed a true two-way conversation over a telegraph wire between Boston and Cambridge, Massachusetts, a few kilometres apart. They talked back and forth for hours and wrote down what they heard to check it. Now the telephone was not just sending sounds. It was letting two people have a conversation."]},{"heading":"Professor Bell Takes the Stage","paragraphs":["In the 1870s there was no television, no radio and no internet. If people wanted to learn about the latest science, they often bought a ticket to a public lecture. Famous speakers travelled from town to town, and crowds packed into halls to watch experiments on stage. Bell, who was a skilled speaker and teacher, realised this was the perfect way to show off the telephone, and to earn some money, which he badly needed.","The most famous of these lectures took place on the evening of February 12, 1877, at Lyceum Hall in Salem, Massachusetts. More than 500 people paid to see Professor Bell. On the stage was a telephone connected by a telegraph wire to Boston, roughly 25 kilometres (16 miles) away, where Thomas Watson was waiting at the other end.","Bell explained how sound and electricity worked, and then the show began. Voices came out of the telephone from Boston. Watson, who was not a trained singer but had a strong, loud voice, sang songs down the line so that the audience could hear. The early telephones were so faint that Watson had to shout and sing as loudly as he could, and the people in the hall leaned forward in silence to catch the sounds.","That night also made newspaper history. A local man named Henry Batchelder, who wrote reports for the Boston Globe, used the telephone to dictate his story about the lecture to a Globe reporter in Boston. The next day the newspaper printed it, and it is often described as the first news report ever sent by telephone.","Bell and Watson gave more lectures in other New England cities and in New York during 1877. Each demonstration followed a similar plan: Bell on stage explaining, Watson far away singing, talking, or playing an instrument such as a cornet or an organ, and the audience amazed that sounds could arrive from a distant city. Some people even suspected a trick, wondering if a singer was hidden backstage.","These shows did more than entertain. Every newspaper report about them was free advertising. Business owners in the audience began to imagine how useful it would be to talk to a warehouse, a factory or a home without sending a messenger boy running through the streets."]},{"heading":"A Queen on the Line","paragraphs":["Bell also took the telephone across the Atlantic. He had received a British patent on December 9, 1876, and in the summer of 1877 he travelled to Britain, where he stayed for more than a year, giving demonstrations and trying to start a telephone business there.","His most famous British audience was Queen Victoria herself. On the evening of January 14, 1878, Bell was invited to Osborne House, the Queen's seaside home on the Isle of Wight, off England's south coast. In a grand room called the Council Room, he set up his instruments, helped by two assistants, Colonel W. H. Reynolds and Charlton Wollaston. The Queen was joined by her daughter Princess Beatrice and her son the Duke of Connaught.","The demonstration ran from about half past nine at night until around midnight. Wires connected Osborne House to several places. At nearby Osborne Cottage, the home of Sir Thomas Biddulph, one of the Queen's officials, Sir Thomas and Lady Biddulph spoke with the Queen, and the American journalist Kate Field, a friend and supporter of Bell, sang songs into the telephone. At Cowes, an army officer, Major Webber of the Royal Engineers, was on the line, and in Southampton, William Preece, a senior engineer of the British Post Office, which ran the country's telegraphs, took part. Most amazing of all, a line was connected to London, nearly 130 kilometres (80 miles) away, where a Mr Wilmot played an organ and the listeners at Osborne could hear the music.","Not everything worked perfectly, and the sound was often faint. The early phones used in the demonstration had a single opening that served as both mouthpiece and earpiece, so people had to keep moving it from their mouth to their ear and back again.","Queen Victoria wrote about the evening in her journal. She described the sound as rather faint and noted that you had to hold the tube close to your ear. One of the actual telephones used at Osborne Cottage that night survives today in the collection of the Science Museum Group in Britain. The demonstration was reported in The Times newspaper, and having a queen try your invention was the kind of publicity no advertisement could buy."]},{"heading":"A Company and a Wedding in the Same Week","paragraphs":["Back in the United States, July 1877 turned out to be one of the most important months of Bell's life.","On July 9, 1877, Gardiner Greene Hubbard organised the Bell Telephone Company in Boston. It was built around one thing: Bell's patent, No. 174,465. The company was divided into 5,000 shares, which are pieces of ownership. Bell received 1,497 shares. Thomas Sanders, the Salem leather merchant who had paid for much of Bell's research, also received 1,497 and became the company's treasurer. Hubbard and his family held about 1,500, and Hubbard acted as the company's leader. Thomas Watson, who was only 23 years old, received 499 shares and was put in charge of making the telephones. Not bad for a young mechanic who had started out building other people's gadgets in a Boston workshop.","Two days later, on July 11, 1877, Alexander Graham Bell married Mabel Hubbard at her parents' home in Cambridge, Massachusetts. Mabel was 19. She had been deaf since a serious illness, scarlet fever, when she was about five years old, and she had become an excellent lip-reader. She was clever, practical and confident, and she would become one of Bell's most important partners in everything he did.","Bell's wedding present to his bride was remarkable. He gave her all but 10 of his 1,497 shares in the new telephone company. At that moment nobody knew whether the shares would ever be worth much. Within a few years they made the family wealthy.","Soon after the wedding, the couple set off for Britain on a long honeymoon that was also a working trip, which is how Bell came to be demonstrating telephones to Queen Victoria in January 1878. Their first daughter, Elsie May Bell, was born in London in May 1878."]},{"heading":"The $100,000 Offer and the Memo That Never Was","paragraphs":["You may have heard a famous story about the telegraph giant Western Union. It goes like this: Bell's side offered to sell the telephone patent to Western Union for $100,000, and the company's experts wrote a scornful memo saying the telephone was a useless toy with too many problems to ever be taken seriously. It is a great story about how even experts can be wrong. But the memo part almost certainly is not true.","Let's sort out what really happened and what did not.","The offer itself may well be real. Thomas Watson, writing many years later, remembered that in the autumn of 1876 Hubbard offered to sell the rights to Bell's patents to William Orton, the president of Western Union, for $100,000, and that the offer was turned down. Watson's memory is the main source for this, so historians treat it with some caution, but it fits with what else we know. Another documented episode involves Chauncey Depew, a well-known New York lawyer. Hubbard offered him a one-sixth share in the telephone for $10,000. Depew asked Orton for advice, Orton told him the telephone had no future, and Depew stayed out. Depew later joked about how much money he had missed.","The memo is a different matter. Researchers who have searched for it have found no trace of it in newspapers from 1876 to 1900, or in any documents from the period. The earliest known printed version appeared in 1968 in an engineering journal, where the writer said he had put it together from two similar versions he had come across. As early as 1976, an article in the engineering magazine IEEE Spectrum called it suspect. So it is best to think of the famous memo as a modern joke or legend, not a real historical document.","What Western Union actually did is even more interesting. It did not think the telephone was worthless for long. In 1877, once the telephone started to catch on, Western Union bought up rival telephone patents, including ones from Elisha Gray and Amos Dolbear, hired Thomas Edison to design a better transmitter, and set up its own telephone business to compete with Bell. That set the stage for a huge legal battle, which you will read about in Part 10."]},{"heading":"Renting Telephones in Pairs","paragraphs":["So how did you actually get a telephone in 1877? You could not walk into a shop and buy one. And you could not call just anyone, because there was no network yet. There were no telephone exchanges, no operators and no phone numbers.","Instead, Hubbard made a smart business decision: telephones would be rented, never sold. The company kept ownership of every instrument. Customers paid a yearly fee to use them, and the company would repair them for free. This gave the company steady income and control over how its telephones were used.","In May 1877, Hubbard put out a printed circular, a kind of advertising leaflet, that is often called the first telephone advertisement. It offered pairs of telephones for connecting two places “not more than twenty miles apart.” Renting two telephones to connect a home with another building cost $20 a year. For business use it cost $40 a year, paid every six months in advance. Each extra telephone on the same line was $10 more, and a louder call signal cost $5. If you did not already have a wire, the company could arrange to build a line for about $100 to $150 per mile. Orders were to be sent to Thomas A. Watson at 109 Court Street in Boston.","Notice the word pairs. Each early telephone line was a private line connecting exactly two places, such as a banker's home and his bank, a factory office and its warehouse, or a doctor's house and a pharmacy. If you wanted to talk to three places, you needed three separate lines, each with its own pair of telephones. One of the first private lines in the Boston area is often said to have connected the workshop of Charles Williams Jr., where Bell's telephones were made, to Williams's home.","What did one of these rented telephones look like? Many were simple wooden boxes or handheld wooden tubes, with a round opening at one end. Inside was a permanent magnet, a coil of wire and a thin iron diaphragm. These instruments did not need a battery at all. When you spoke into one, your voice shook the iron diaphragm near the magnet, and that movement created a tiny electric current in the coil all by itself. At the other end, the same kind of instrument turned the current back into sound. The same opening was used for talking and listening, so a conversation meant a lot of moving the telephone up to your mouth, then over to your ear, then back again.","Because the current came only from the speaker's voice, these telephones were quiet, and they worked best over short distances. There was also no proper ringing bell on the earliest models. To get the attention of the person at the other end, you might tap on the diaphragm or shout into the instrument and hope someone was close enough to hear. That is why the company offered a separate, louder call signal for an extra fee. It would take several more years of inventing, including new transmitters and proper ringers, before telephones became loud, clear and easy to use. Even so, people were willing to put up with the awkwardness, because being able to speak to someone in another building, instantly, felt almost like magic.","Even with these limits, the numbers grew quickly. By July 31, 1877, only weeks after the company was formed, 778 telephones had been rented out. By the end of 1877, more than 5,000 Bell telephones were in use. By the end of July 1878, the number was over 12,000, and by early 1879 it was about 22,000. By around 1880, there were tens of thousands of telephones in the United States, roughly 50,000 by common estimates, and the number was still climbing fast.","But wires running only between two places could not last. As more and more people got telephones, the tangle of private lines would have become impossible. In January 1878, the first commercial telephone exchange opened in New Haven, Connecticut, letting subscribers be connected to one another. That story belongs to Part 11.","First, though, there is a mystery we have been tiptoeing around since Part 6. What is really happening inside a telephone? How does a human voice, made of nothing but moving air, actually turn into electricity, rush down a wire, and turn back into a voice at the other end?"]}],"deepDive":"The years 1876 to 1878 show that inventing a device and launching a technology are different achievements. The Centennial demonstration of June 25, 1876, mattered less for its technical quality, which was poor (Thomson heard fragments of Hamlet only after much adjustment, and another judge heard little), than for its witnesses. William Thomson's endorsement carried enormous scientific weight, and his report to the British Association in Glasgow in September 1876 introduced the telephone to British science. The Ontario trials of August 1876 established that speech could survive real telegraph lines over about 13 km, though the Brantford–Paris link was one-way; the October 1876 Boston–Cambridge test showed two-way conversation. The 1877 lecture tour, beginning with the Salem lecture of February 12, combined fundraising with publicity; Boston Globe coverage, including the first news dispatch transmitted by telephone, spread the idea widely. The business model was equally important. Hubbard's decision to lease rather than sell instruments, borrowed from his earlier legal work for a shoe-machinery company that leased its machines, gave the Bell interests continuous revenue and control of equipment, a policy that shaped the Bell System for about a century. The May 1877 circular priced pairs of instruments at $20 a year for social use and $40 for business use. Growth was rapid: 778 instruments leased by July 31, 1877; 5,491 by year end; about 22,000 by March 1879. The often-repeated Western Union 'toy' memo deserves scepticism. No version has been found in newspapers from 1876 to 1900 or in documents through 1950; the earliest known printing is from 1968, in an engineering journal. The $100,000 offer rests mainly on Thomas Watson's later recollection. What is documented is that Western Union, after initially declining, moved quickly into the telephone business in 1877 by acquiring patents from Gray and Dolbear and commissioning Edison's transmitter work, a decision that led directly to the patent litigation settled in 1879.","funFact":"One of the actual telephones used at Osborne Cottage on the night of Bell's demonstration for Queen Victoria in January 1878 survives today in the collection of Britain's Science Museum Group.","check":{"q":"In 1877, how did customers usually get Bell telephones?","a":"They rented them in pairs to connect two places directly","wrong":["They bought them in shops and connected them to an exchange","The government gave them away for free","They borrowed them from Western Union telegraph offices"]},"sources":[{"title":"Centennial Exposition","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Centennial_Exposition"},{"title":"The Centennial Telephone","publisher":"Antique Telephone History","url":"https://www.antiquetelephonehistory.com/centennial.html"},{"title":"150 Years of Long-Distance Calling","publisher":"Canada's History","url":"https://www.canadashistory.ca/explore/science-technology/150-years-of-long-distance-calling"},{"title":"Stories of Long-Distance Human Voice Transmission","publisher":"The Henry Ford","url":"https://www.thehenryford.org/collections/explore/articles/stories-of-long-distance-human-voice-transmission"},{"title":"Early Bell telephone and terminal panel, 1877-8","publisher":"Science Museum Group","url":"https://collection.sciencemuseumgroup.org.uk/objects/co33399/early-bell-telephone-and-terminal-panel-1877-8"},{"title":"Bell Telephone Company","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bell_Telephone_Company"},{"title":"Popular Science Monthly, December 1906: Notes on the Development of Telephone Service II","publisher":"Wikisource","url":"https://en.wikisource.org/wiki/Popular_Science_Monthly/Volume_69/December_1906/Notes_on_the_Development_of_Telephone_Service_II"},{"title":"True Stuff: Alexander Graham Bell vs. Western Union","publisher":"Wondermark","url":"https://wondermark.com/?p=10896"}],"photos":[{"src":"img/deep/telephone/08-1.jpg","alt":"A bird's-eye engraving of the 1876 Centennial Exhibition grounds in Philadelphia, from Harper's Weekly.","file":"The Centennial-balloon view of the grounds - (Centennial Exhibition at Philadelphia, 1876) LOC 96686300.jpg","url":"https://commons.wikimedia.org/wiki/File:The_Centennial-balloon_view_of_the_grounds_-_(Centennial_Exhibition_at_Philadelphia,_1876)_LOC_96686300.jpg","author":"Harper & Brothers; Davis, Theodore R.; R. Newell & Son","license":"Public domain"},{"src":"img/deep/telephone/08-2.jpg","alt":"Bell's 1876 Centennial telephone: the iron-box receiver (left) and a transmitter (right).","file":"Bell Centennial telephone receiver & transmitter 1876.png","url":"https://commons.wikimedia.org/wiki/File:Bell_Centennial_telephone_receiver_%26_transmitter_1876.png","author":"Elmer Ellsworth Burns","license":"Public domain"},{"src":"img/deep/telephone/08-3.jpg","alt":"Osborne House on the Isle of Wight, where Bell showed the telephone to Queen Victoria in 1878.","file":"Osborne House, Isle of Wight (geograph 5806605).jpg","url":"https://commons.wikimedia.org/wiki/File:Osborne_House,_Isle_of_Wight_(geograph_5806605).jpg","author":"Derek Voller","license":"CC BY-SA 2.0"}],"words":3613},{"n":9,"title":"How a Telephone Turns Your Voice into Electricity","when":"The science (1876 – 1880s inventions)","summary":"When you talk, you make the air wiggle. A telephone catches those wiggles with a thin, shaky disk and turns them into a wiggling electric current, then a magnet at the other end shakes another disk to make your voice again. Inventors like Thomas Edison made phones much louder by squeezing tiny grains of carbon, and Edison even helped make 'Hello!' the word we say when we pick up.","sections":[{"heading":"Sound Is a Shove in the Air","paragraphs":["Put your fingers gently on the front of your throat and hum. Feel that buzzing? That is your vocal cords, two small folds of tissue in your voice box, snapping open and shut hundreds of times every second. Each time they flap, they give the air coming up from your lungs a tiny shove. That shove pushes on the air in front of your mouth, which pushes on the air in front of it, and so on, like a long line of people bumping shoulders in a crowded hallway.","This travelling pattern of squeezes and stretches is what scientists call a sound wave. Where the air molecules are pushed close together, the pressure is a little higher. Where they spread apart, the pressure is a little lower. The air itself does not fly across the room from your mouth to your friend's ear. Instead, each little bit of air jiggles back and forth and passes the push along, the way a wave travels across a stadium while every fan stays in their seat.","How fast does the wave move? In air at room temperature, sound travels about 343 metres (about 1,125 feet) every second. NASA's guide for students gives a slightly lower figure, about 1,100 feet per second, for the colder standard air used in aircraft calculations, because sound moves a little faster when air is warmer. Either way, that is quick enough that a friend across a classroom hears you almost instantly, but slow enough that you see a lightning flash before you hear the thunder.","When the wave reaches your friend, it bumps into their eardrum, a thin, tight piece of skin deep inside the ear. The eardrum is pushed in when the pressure rises and pulled out when it drops, so it copies the shape of the sound wave exactly. Three tiny bones behind it pass the motion on, and nerves turn it into signals the brain understands as words, music or the barking of a dog.","Two features of the wave matter most. The first is how many times per second it vibrates, called its frequency and measured in hertz. A low voice might vibrate around 100 times a second, a high whistle several thousand. A healthy young ear can hear from about 20 hertz up to about 20,000 hertz. The second feature is how big the pushes are, called the amplitude. Big pushes sound loud; small pushes sound quiet.","Here is the important part. A spoken word is not one neat, single vibration. The sound of 'ahh' and the sound of 'eee' have different mixtures of frequencies stacked on top of each other, and consonants like 's' and 't' are quick hisses and pops. That is why speech is so tricky to send. A telegraph only had to say 'on' or 'off'. A telephone had to copy a messy, constantly changing wave, with all its wiggles in the right places, and rebuild it somewhere else."]},{"heading":"Copying the Shape of a Voice","paragraphs":["Alexander Graham Bell's great insight, the one he chased after the twanging reed of June 1875, was that you did not need to turn speech into a code at all. You could make an electric current that rose and fell in exactly the same pattern as the air pressure of the voice. Bell called this an 'undulating' current, meaning a current that moves up and down in waves. If the current copied the wave faithfully, the far end only had to turn it back into motion.","The part of a telephone that does the copying is called the transmitter, the piece you speak into. At its heart sits a diaphragm, a thin, flexible disk, usually of metal. When the sound wave from your mouth reaches it, the diaphragm is pushed in and out just as your eardrum would be. In a sense, the transmitter is an electric ear. Its job is to make the current flowing through it change every time the diaphragm moves.","Bell tried two main ways of doing this. In the first, used for the famous 'Mr. Watson' call on March 10, 1876, a needle attached to the diaphragm dipped into a small cup of water mixed with acid. As the diaphragm moved, the needle went a little deeper or a little shallower. Electricity passes through the acid water more easily when there is less water to cross, so the current rose and fell with the voice. It worked, but sloshing acid was hardly practical for a phone in someone's kitchen.","The second method, which Bell used in his public demonstrations and in the first telephones sold to customers, needed no battery at all. A thin iron diaphragm sat just in front of a magnet wrapped in a coil of wire. When your voice moved the iron disk, it disturbed the magnet's invisible field, and that changing magnetism pushed a tiny current through the coil. This is the same principle of induction that Michael Faraday had discovered back in 1831. Your voice itself was making the electricity.","Either way, the result was what engineers call an analog signal. Analog means that the signal is a smooth copy, an 'analogy', of something else. If you could draw a graph of the air pressure in front of your mouth and another graph of the current in the wire, the two curves would have the same shape. A rise in pressure became a rise in current; a quick wiggle in the sound became a quick wiggle in the electricity. Nothing was turned into numbers. The current simply mirrored the wave, like a shadow follows the hand that makes it.","Once the signal is electric, distance stops being about the speed of sound. Electrical signals in a wire move at a large fraction of the speed of light, hundreds of thousands of kilometres every second. Shout across a valley and your voice takes several seconds to reach the far side and echo back. Send it down a wire and, for a listener a town away, the delay is far too small for any human to notice. The voice is still yours, but it is riding on electricity instead of air."]},{"heading":"The Earpiece: A Magnet That Talks","paragraphs":["At the other end of the line, the listener needs the opposite of a microphone: a device that turns a changing current back into moving air. This is the receiver, the earpiece. If the transmitter is an electric ear, the receiver is an electric mouth.","A classic receiver has three main parts. There is a permanent magnet, the ordinary kind that always attracts iron. Around one end of it, or around an iron core near it, is a coil of fine insulated wire. And in front of the magnet, almost but not quite touching it, sits another thin iron diaphragm. The permanent magnet holds the diaphragm under a gentle, steady pull, bending it very slightly toward the magnet.","Now send the voice current through the coil. A coil carrying current becomes an electromagnet, and its strength depends on how much current is flowing. When the current from the line rises, the coil adds to the permanent magnet's pull and the diaphragm is tugged a little closer. When the current falls, the pull weakens and the springy diaphragm moves back out. Because the current is a copy of the speaker's sound wave, the diaphragm now moves in the same pattern as the speaker's diaphragm did. It pushes and pulls on the air beside your ear, and the sound wave is born again.","Why bother with the permanent magnet? Without it, an iron diaphragm would be attracted whether the current flowed one way or the other, so it would vibrate twice as often as it should and the voice would come out garbled. The steady magnet gives the diaphragm a resting position to swing either side of, so a rise in current pulls it in and a dip lets it out. That simple trick keeps the copy honest.","Bell's electromagnetic receiver was such a good design that its basic idea lasted for a very long time. The very first telephones Bell's company rented out were simple wooden or hard-rubber tubes containing a magnet, a coil and a diaphragm. People sometimes call the 1877 to 1878 handheld version the 'butterstamp' telephone because its turned wooden handle looked like a tool for pressing patterns into butter. The same instrument served as both transmitter and receiver: you talked into it, then quickly moved it to your ear to listen. Some users had two, one for the mouth and one for the ear.","Look inside an old landline handset from the twentieth century and you will still find a magnet, a coil and a diaphragm in the earpiece. Even the little speakers in modern earbuds work on a related idea, using a coil and a magnet to move a thin membrane. When you listen to music, you are using a great-great-grandchild of the receiver Bell and Thomas Watson were building in a Boston workshop.","Later telephone designers added a thoughtful touch. When you speak into a landline handset, a little of your own voice is deliberately fed back into your own earpiece. Engineers call this 'sidetone'. Without it, the phone feels strangely dead, as if you were talking into a pillow, and people tend to raise their voices until they are shouting. With just the right amount, you hear yourself naturally and speak at a comfortable volume. It is a small example of how the science of the telephone is also the science of how humans listen."]},{"heading":"The Problem of the Whispering Wire","paragraphs":["Bell's magnet telephone had one big weakness, and anyone who used it noticed straight away: it was quiet. Very quiet. Early users often had to press the instrument hard against one ear, cover the other ear with a hand, and ask the speaker to talk loudly and slowly. Over a short line it was a marvel. Over a long one, the voice faded to a whisper buried in crackles.","The reason comes straight from the physics. In Bell's magnet transmitter, all the electrical energy on the line came from the speaker's voice. A voice carries surprisingly little energy. The gentle pushes of air that move a diaphragm can only create a feeble current in a coil, and that feeble current then has to travel through kilometres of wire, which resists it and wastes some of it as heat. By the time it arrived, there was not much left to shake the listener's diaphragm.","Think of it like this. Imagine trying to ring a big church bell at the far end of a long rope by blowing on your end of the rope. However cleverly you blow, there simply is not enough push. What you really want is a strong motor at your end of the rope, and a way for your breath to control that motor. Then your gentle effort decides when and how the bell moves, while the motor supplies the muscle.","That is exactly the trick the next generation of transmitters used. Instead of the voice making the current, a battery made a strong, steady current, and the voice merely controlled how much of that current got through. The voice became like a hand on a tap, opening and closing it, while the battery was the water pressure in the pipes. A small movement of the hand could make a big change in the flow.","This difference sounds small, but it changed everything about how far a call could go. With a magnet transmitter, a louder phone meant shouting harder, and there is a limit to how loudly anyone can shout. With a battery-powered transmitter, engineers could choose a stronger battery or a better circuit, and every word would arrive with more strength behind it. The question was no longer 'How hard can a person talk?' but 'How sensitive can we make the tap?'","Several inventors had already noticed a useful fact about electrical contacts. When two pieces of a conducting material just barely touch, the electrical resistance between them, how hard it is for current to pass, depends strongly on how firmly they are pressed together. Press harder and more tiny points touch, so current flows more easily. Press more lightly and the current is choked down. In Germany, Johann Philipp Reis had used loose contacts in his Telephon back in 1861. Now, in the late 1870s, inventors on both sides of the Atlantic turned to one particular material that was very good at this: carbon."]},{"heading":"Three Inventors and a Pinch of Soot","paragraphs":["Imagine a long wooden laboratory building in Menlo Park, New Jersey, in 1877, crammed with jars, wires and batteries, with lamps burning late into the night. This was the workshop of Thomas Alva Edison, already famous for his telegraph inventions. Western Union, the giant telegraph company, was paying him to improve on Bell's telephone, and Edison set his team testing material after material to find the best one for a pressure-sensitive contact.","Edison, who was himself hard of hearing, tried many substances. The winner turned out to be carbon in very fine form, including lampblack, the dark soot collected from smoky oil lamps, pressed into a small, firm button. Placed behind the diaphragm, the carbon button was squeezed a tiny bit harder whenever the voice pushed the diaphragm in, and relaxed whenever it moved out. Its resistance rose and fell with the voice, so the strong current from a battery rose and fell too. The result was a voice much louder and clearer than Bell's magnet transmitter could manage. Edison's carbon transmitter took shape between 1877 and 1878, and his patents covered several versions of it.","Edison was not alone. In the United States, a young German immigrant named Emile Berliner was working on the same problem in his spare time. Born in Hanover in 1851, Berliner had come to the United States in 1870 and studied physics in evening classes at Cooper Union in New York while doing odd jobs. In 1877 he worked out a loose-contact transmitter in which a metal diaphragm pressed against a contact point, so that changes in pressure changed the current. He also patented an induction coil for telephones, which we will meet again soon. The Bell company was impressed enough to acquire his patent, and Berliner went to work for it, leaving in 1883 to research on his own. He later became even more famous for the flat-disc gramophone record.","Across the ocean in London, the inventor and former music professor David Edward Hughes was exploring loose contacts with almost childlike simplicity. In one experiment he laid an ordinary iron nail across two other nails connected to a battery and a telephone receiver. The wobbly contact was so sensitive that tiny sounds near it, even faint scratches, were picked up and heard in the receiver. He refined the idea using small pencils of carbon held loosely between carbon blocks. His paper on it was read to the Royal Society in London on May 8, 1878.","Hughes gave the device the name we still use: the microphone, borrowing a word that Charles Wheatstone had used decades earlier for a sound-amplifying gadget. Even more remarkably, Hughes chose not to patent it. He believed the discovery should be free for everyone to develop. Many historians give Hughes much credit for working out how loose-contact carbon microphones really behave.","So who invented the carbon microphone? As so often in this story, the fair answer is that several people reached similar ideas at almost the same time. Edison and Berliner fought a long legal battle over American patent rights, and in 1901 a United States appeals court ruled Berliner's patent invalid and sided with Edison, stating that the use of carbon in a transmitter was Edison's invention. Hughes, who had stayed out of the patent race, kept his scientific reputation and later received the Royal Society's Royal Medal. Each man added something real."]},{"heading":"A Hundred Years of Carbon Grains","paragraphs":["The carbon idea kept improving. Around 1878–79 Francis Blake, working with the Bell company, developed a transmitter in which a platinum contact pressed against a hard carbon button, and the 'Blake transmitter' became the standard Bell mouthpiece for many years. Around the same time, the English inventor Henry Hunnings patented a transmitter filled with loose carbon granules, tiny grains a bit like coarse black sand, instead of one solid button. Lots of grains meant lots of contact points, and lots of contact points made the transmitter more sensitive.","In 1892, a Bell engineer named Anthony C. White patented the 'solid-back' transmitter. It held the carbon granules in a small, sealed chamber between a fixed carbon disk at the back and a carbon disk attached to the diaphragm at the front. This design was tough, loud and reliable, and versions of it were used for decades. Its descendants were the carbon transmitters screwed into the mouthpieces of telephones well into the late twentieth century.","To understand why the grains worked so well, imagine a jar of marbles. Push on the lid and the marbles squash together, touching each other at more places and with more force. Carbon granules behave the same way, but electrically. When a sound wave presses the diaphragm in, the grains are squeezed, they touch more firmly, the resistance drops and more current flows. When the pressure eases, the grains loosen, the resistance rises and less current flows. Squeezed harder means more current; squeezed less means less current. The current dances to the rhythm of your voice.","There was one more clever helper: the induction coil. A telephone line is long and resists current, so engineers added a small transformer, two coils of wire wound around an iron core, to each telephone set. The transmitter's changing current flowed through the first coil, and the second coil, with many more turns of wire, produced a matching signal at a higher voltage that travelled more efficiently along the line. Berliner and Edison both worked on this idea, and it became a standard part of the telephone.","Put together, carbon granules, a battery and an induction coil turned the telephone from a whispering novelty into a practical tool. The carbon transmitter actually gave out more electrical energy than the voice put in, because the battery supplied the extra. In other words, it acted as an amplifier, something that makes a weak signal stronger. Early telephone engineers even built carbon-based amplifiers to boost signals on long lines before vacuum tubes came along.","The carbon microphone also had faults. It produced a faint hissing noise, it did not reproduce the highest and lowest sounds very faithfully, and the grains could pack together over time, especially if the phone sat unused. Old telephone users sometimes tapped the handset to loosen them. But for ordinary speech those faults did not matter much. The design was cheap, simple, sturdy and loud. Carbon-granule microphones remained standard in telephones from the 1880s until roughly the 1980s, when electronic microphones finally replaced them. For about a hundred years, almost every phone call in the world travelled through a pinch of carbon."]},{"heading":"Hello, Hulloa or Ahoy?","paragraphs":["Once a voice could leap down a wire, people faced a surprisingly tricky question: what do you say first? Before the telephone, greetings usually happened face to face, where you could see who you were talking to and often said something linked to the time of day, like 'good morning'. On a phone line you could not see anyone, and you needed to grab the other person's attention before saying anything important.","Alexander Graham Bell had a favourite answer: 'Ahoy!' It was a sailor's call used to hail another ship across the water, and it fitted his picture of a voice calling out across a distance. Bell reportedly kept using it, but it never caught on with the public.","Thomas Edison suggested something different. In a letter dated August 15, 1877, to T. B. A. David, the president of a telegraph company in Pittsburgh, Edison proposed shouting 'Hello!' into the instrument. He argued that the word could be heard 10 to 20 feet (about 3 to 6 metres) away, so it could even do the job of a bell, telling someone across the room that a call was coming. 'Hello' and similar words like 'hullo' and 'halloo' already existed as ways of calling out to someone or showing surprise, but Edison's suggestion helped make it the telephone word.","Hello spread with the telephone itself. Telephone companies and operators used it, and by the late 1880s operators at telephone exchanges were being nicknamed 'hello girls'. Within a generation, picking up a phone and saying 'Hello?' felt so natural that people began to forget it had ever been a choice. You may hear a story that 'hello' was named after a woman connected to Bell. That is a myth with no evidence behind it; the word was around long before.","So the next time you answer a call, you are taking part in a small piece of history: a little contest between two great inventors, which Edison won. Bell's 'Ahoy!' lives on mostly in pirate films and on boats.","But notice something about this chapter. Edison was improving the telephone while working for Western Union, Bell's biggest rival. Berliner's patent was bought by the Bell company. Hughes gave his discovery away. Every improvement made the telephone more valuable, and the more valuable it became, the more people wanted a share of it. Better phones were about to lead to bigger fights: over patents, over money, and over the most explosive question of all, who had really invented the telephone in the first place."]}],"deepDive":"Engineers describe a telephone as a pair of transducers, devices that change energy from one form to another: the transmitter turns acoustic energy into electrical energy and the receiver does the reverse. Bell's first commercial instruments used the same electromagnetic transducer at both ends. Because induction produces a voltage proportional to how fast the magnetic field changes, the energy available was tiny, and every kilometre of line, with its resistance and capacitance, drained and blurred the signal further. The carbon transmitter changed the energy budget completely. It is not a generator but a variable resistor in a battery circuit, so the power delivered to the line comes from the battery, while the voice only modulates it. That makes it an amplifying transducer, with a power gain greater than one, decades before vacuum-tube amplifiers. The physics of why loose carbon contacts work so well is more subtle than 'squeezing increases contact area'. Hughes argued in 1878 that the effect came from the many microscopic points where carbon pieces touch rather than from compressing the carbon itself; modern explanations add that the number and size of these tiny contact spots, and thin surface films on them, change with pressure. Carbon was attractive because it conducts electricity, does not rust or easily weld together under sparking, and stays fairly stable over time. Its drawbacks were noise, non-linear response (louder sounds were not reproduced in exact proportion), a limited frequency range and 'packing' of granules. For speech these were acceptable, since intelligibility depends mainly on frequencies roughly between a few hundred and a few thousand hertz, the band later standardised for telephone networks. Credit for the carbon microphone remains genuinely shared: Edison won the decisive American patent rulings, ending with a 1901 appeals court decision against Berliner's patent; Hughes published openly in Britain and never patented; Berliner, Blake, Hunnings and White all contributed practical improvements. The story is a good example of how a key component is often the result of many overlapping efforts rather than a single flash of genius.","funFact":"In an August 1877 letter, Thomas Edison recommended answering the telephone with 'Hello!' because, he said, it could be heard 10 to 20 feet away, while Alexander Graham Bell preferred to say 'Ahoy!'","check":{"q":"In a carbon transmitter, what happens when sound pushes the diaphragm in and squeezes the carbon grains?","a":"The grains touch more firmly, their resistance drops and more current flows","wrong":["The grains catch fire and make a spark that carries the voice","The grains become magnetic and pull on the wire","The current stops completely until the diaphragm moves back"]},"sources":[{"title":"Carbon microphone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Carbon_microphone"},{"title":"David Edward Hughes","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/David_Edward_Hughes"},{"title":"Emile Berliner","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Emile_Berliner"},{"title":"How the Telephone Works","publisher":"Antique Telephone History","url":"https://antiquetelephonehistory.com/telworks.php"},{"title":"Speed of Sound","publisher":"NASA Glenn Research Center","url":"https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/speed-of-sound-interactive/"},{"title":"Hello","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hello"},{"title":"Timeline of the telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Timeline_of_the_telephone"},{"title":"Francis Blake (inventor)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Francis_Blake_(inventor)"}],"photos":[{"src":"img/deep/telephone/09-1.jpg","alt":"Thomas Edison's 1878 patent model of a carbon telephone transmitter, at the National Museum of American History.","file":"Carbon-resistance telephone transmitter, 1878.jpg","url":"https://commons.wikimedia.org/wiki/File:Carbon-resistance_telephone_transmitter,_1878.jpg","author":"Daderot","license":"Public domain"},{"src":"img/deep/telephone/09-2.jpg","alt":"An old engraving of the \"butterstamp\" hand telephone, shown cut open (top) and whole (bottom).","file":"Butterstamp telephone receiver.jpg","url":"https://commons.wikimedia.org/wiki/File:Butterstamp_telephone_receiver.jpg","author":"Unknown author","license":"Public domain"},{"src":"img/deep/telephone/09-3.jpg","alt":"A 1916 cross-section of a telephone carbon microphone, labelling the diaphragm and carbon granules.","file":"Carbon button microphone 1916.png","url":"https://commons.wikimedia.org/wiki/File:Carbon_button_microphone_1916.png","author":"Unknown author","license":"Public domain"}],"words":3914},{"n":10,"title":"Patent Wars: Who Really Invented It?","when":"1877 – 1888, and later","summary":"Once people saw how useful the telephone was, everyone wanted a piece of it. Bell's company went to court hundreds of times against rivals, including a huge telegraph company and a Pennsylvania tinkerer who said he got there first. The courts sided with Bell, but people still argue about how much credit others, like Antonio Meucci, deserve.","sections":[{"heading":"A Telegraph Giant Changes Its Mind","paragraphs":["In 1876, the most powerful communications company in the United States was Western Union. It owned telegraph lines stretching across the country, offices in thousands of towns, and close ties to inventors such as Elisha Gray and Thomas Edison. When Bell's backers offered to sell it the telephone patent, Western Union said no. (You may have seen a famous memo in which Western Union supposedly mocked the telephone as a useless toy. As Part 8 explained, that memo is almost certainly a fake. What is true is that the company turned down the chance to buy Bell's patent.)","Within about a year, Western Union's leaders realised they had made a mistake. Telephones were spreading. Businesses wanted them to talk between offices and warehouses, and doctors and shopkeepers wanted them too. If people could simply talk down a wire, they might stop sending telegrams. So Western Union decided not to buy the telephone, but to build its own.","In late 1877, Western Union and its subsidiary, the Gold and Stock Telegraph Company, set up the American Speaking Telephone Company. It had powerful weapons. It controlled telephone patents from Elisha Gray, whose caveat had been filed on the same day as Bell's patent application, and from other inventors. Most important of all, it had Edison's new carbon transmitter, which, as we saw in Part 9, made voices much louder and clearer than Bell's magnet transmitter. Western Union also had money, workers, poles and wires already strung through cities. In many places, its telephones simply sounded better than Bell's.","Imagine being one of the small team running the young Bell Telephone Company in Boston at this moment. You own the key patent, but you have little money, a handful of employees and a product that many customers now say is quieter than the competition. Your rival is one of the largest corporations in the country. It looked like a fight between a rowboat and a battleship.","Bell's side responded in two ways. First, it improved its own phones. The company acquired Emile Berliner's transmitter patent and adopted Francis Blake's carbon transmitter, so it no longer had to fear Edison's sound quality. Second, it hired a determined young manager named Theodore Vail, who became general manager in 1878. Vail would later shape the whole Bell System. One of his first jobs was to make sure the company's agents across the country stood firm and did not sell out to Western Union.","Then Bell's company took the boldest step of all: it went to court. In September 1878, it sued a man named Peter A. Dowd, who was an agent for Western Union's telephone business. Suing a single agent might seem small, but everyone understood the real target. If the court agreed that Dowd's telephones broke Bell's patent, then the whole Western Union telephone business was breaking it too."]},{"heading":"The Deal of November 1879","paragraphs":["The Dowd case became a giant contest of evidence. Lawyers for both sides gathered testimony about who had experimented with what, and when. Western Union's lawyers looked for any earlier inventor whose work might cancel Bell's patent. Bell's lawyers argued that Bell was the first to describe and claim the essential method: sending speech by a current that varied in the same way as the sound itself.","As the evidence piled up, Western Union's own legal team grew worried. The company's lead lawyer, George Gifford, reportedly came to believe that Bell's patent would hold up in court. At the same time, Western Union faced other troubles, including pressure from the financier Jay Gould, who was trying to gain control of the telegraph business. Fighting an expensive, possibly losing battle over telephones began to look like a bad idea.","On November 10, 1879, the two sides settled. Under the agreement, Western Union left the telephone business. It handed over its telephone network and its telephone patents, including those based on the work of Gray and Edison, to the Bell company. In return, Western Union was to receive a share of Bell's telephone rental income for years to come, usually described as about 20 percent, and the Bell company agreed to stay out of the telegraph business. Each giant, in effect, kept to its own territory.","For the Bell company, it was a stunning victory. Overnight it gained tens of thousands of telephones in cities across the country, Edison's and Gray's patents, and freedom from its most dangerous rival. Its share price soared. In early 1880, the company reorganised as the American Bell Telephone Company, and in 1881 it bought a controlling interest in Western Electric, the manufacturing company Elisha Gray had helped found, so it could build its own equipment.","The telephone fight was not only American. In Britain, Edison developed an unusual loud receiver that used a moistened chalk cylinder, and an Edison telephone company competed with a Bell company in London. Rather than fight on for years, the two British companies merged in 1880 to form the United Telephone Company. Again and again in these early years, rivals discovered that combining their patents was cheaper than battling over them.","There is a twist worth noticing. The settlement was a business deal, not a court verdict. No judge had ruled on whether Gray or anyone else had invented the telephone first. Western Union recognised Bell's patent as part of the agreement, but the deeper question of credit had not been answered. That left the door open for many more challengers."]},{"heading":"Six Hundred Courtroom Battles","paragraphs":["Bell's 1876 patent, number 174,465, and his second telephone patent of January 1877 were extremely valuable. Together they gave the Bell company control over the basic telephone in the United States until they ran out in the early 1890s. Anyone who wanted to make or rent telephones without paying Bell had only one real option: prove that the patents were invalid. And so, all through the 1880s, challengers lined up.","It helps to remember what a patent actually gives. In the United States at that time, a patent lasted 17 years. During that time, nobody else could make, use or sell the invention without the patent owner's permission. In exchange, the inventor had to describe the invention publicly, so that everyone could learn from it and freely use it once the patent ran out. For Bell's company, the patent was like a fence around a field: as long as the fence stood, the company could decide who was allowed in and how much they paid.","Bell's company fought an astonishing number of legal battles over its patents: around 600 in all. One careful count lists 587 court challenges, five of which reached the United States Supreme Court. Aside from a couple of minor contract disputes, the company never lost a case that ran all the way to a final judgment. Historians sometimes call this period the 'telephone patent wars'.","The challengers came in all shapes. Some were respectable scientists. Amos Dolbear, a physics professor at Tufts College near Boston, had built telephones of his own, including a receiver that worked using static electricity rather than an electromagnet. His backers argued that Bell's patent should not cover such different designs. Some were companies with grand names, like the Molecular Telephone Company. Others were small local businesses hoping that one lucky ruling would let them set up exchanges without paying Bell.","Why did Bell keep winning? The key was the way his patent was written. Besides describing particular devices, it claimed the method of sending speech and other sounds by an electric current that changes in the same pattern as the sound waves. Courts decided that this method was Bell's invention. So even if a rival used a different transmitter, a different receiver or a different material, it still used Bell's method if it carried a voice by a changing current. That made it very hard to build any working telephone without bumping into Bell's patent.","These cases were not just paperwork. Bell himself had to give long sworn statements, called depositions, answering detailed questions about his notebooks, experiments and letters. Lawyers combed through everything he had ever written. He found the process exhausting and sometimes deeply upsetting, because rival lawyers were not only disputing his work but suggesting he was dishonest. Still, his detailed records, kept carefully over years, proved to be among his strongest defences."]},{"heading":"The Tinkerer from Eberly's Mill","paragraphs":["Of all the challengers, the most colourful was Daniel Drawbaugh. Born on July 14, 1827, at Eberly's Mill in Cumberland County, Pennsylvania, not far from Harrisburg, Drawbaugh was a bearded country mechanic who could make almost anything in his little workshop near Yellow Breeches Creek. Over his long life he patented machines for shaping barrel staves, pneumatic tools, folding boxes and a coin-sorting device. Neighbours knew him as a gifted, endlessly busy tinkerer.","Drawbaugh claimed that he had built a working telephone years before Bell, as early as about 1867, using, among other things, a teacup as part of his transmitter. He said he had been too poor to apply for a patent at the time and only sought one around 1880, after Bell's telephone had become famous. A company called the People's Telephone Company backed his claim, hoping that if Drawbaugh were recognised as the first inventor, Bell's patent would collapse and People's could run telephones freely.","The case became a spectacle. Drawbaugh's side gathered many neighbours and acquaintances who swore that, years earlier, they had heard sounds or speech through the gadgets in his workshop. Bell's side pointed out that Drawbaugh had no dated drawings, no published descriptions and no patent applications from those years, and that memories of events a decade old could easily be mistaken. Drawbaugh's own testimony did not help him: when asked how he had arrived at his invention, he answered that he did not remember how he came to it. For a man claiming one of the great inventions of the century, that sounded unconvincing to many observers.","Imagine the scene in the lower courts and finally in Washington, D.C.: stacks of printed testimony thousands of pages long, models of strange early instruments, rows of lawyers in dark suits. People's Telephone was represented by an eloquent lawyer named Lysander Hill, who argued so persuasively that some observers thought he might actually win.","Drawbaugh's case was grouped with several others, including those of Dolbear and the Molecular Telephone Company, into what became known as the Telephone Cases. The Supreme Court heard arguments in early 1887 and announced its decision on March 19, 1888. Two justices took no part, so seven judges decided. The vote was 4 to 3 in favour of Bell. Chief Justice Morrison Waite wrote for the majority that Bell's patent was valid and that he was the first inventor of the method of transmitting speech by electricity.","The three dissenting justices, led by Justice Joseph Bradley, came to the opposite view about Drawbaugh. They believed the evidence showed that Drawbaugh had made a working telephone before Bell, which would have made Bell's patent invalid. So the most famous legal decision about who invented the telephone was won by a single vote. The written decision was so long that it fills most of a whole volume of the official reports of the Supreme Court.","Drawbaugh never received the credit he wanted, but he kept inventing for the rest of his life. He died on November 2, 1911, reportedly while working in his laboratory. Today a Pennsylvania historical marker near his old workshop remembers him."]},{"heading":"The Government Steps In, and Meucci's Last Chance","paragraphs":["Meanwhile, another battle had begun, this time with the United States government itself as the challenger. In 1885 and 1886, a scandal broke over a rival firm called the Pan-Electric Telephone Company. It turned out that several powerful politicians held shares in it, including the US Attorney General, Augustus Garland, the government's top lawyer. When the government began moving to attack Bell's patent, critics accused officials of trying to help a company they had money in. The scandal was embarrassing, but the legal case went ahead.","On January 13, 1887, the United States government filed a lawsuit asking the courts to cancel Bell's patent on the grounds of fraud and misrepresentation. One part of the case concerned Bell's patent application of 1876 and the patent office's handling of Elisha Gray's caveat. A former patent examiner, Zenas Wilber, gave sworn statements on the matter that contradicted each other, which made his evidence hard to trust. As Part 7 explained, whether Bell saw anything improper from Gray's papers is still debated by historians and has never been proven.","The government's case also drew on the story of Antonio Meucci. As we saw in Part 5, Meucci was an Italian inventor living on Staten Island, New York, who had worked for years on a voice-carrying device he called the telettrofono. He had set up a speaking link between rooms of his home, partly so he could talk with his wife, Ester, who was disabled by severe arthritis. He filed a patent caveat on December 28, 1871, but by his own account he could not afford the $10 fee to keep it going after 1874.","Meucci's life had been hard. He had lost money in business, his house had been sold at auction in 1861, and he had been badly injured in a steamboat boiler explosion. He also said that working models he had given to a telegraph company laboratory had been lost. When a company called the Globe Telephone Company tried to use his claims to challenge Bell, the Bell company sued it. In 1887, a federal judge, William J. Wallace, ruled against Globe, deciding that what Meucci had described was a mechanical device, more like a tin-can 'string telephone' than an electric telephone. Meucci's supporters, then and now, have called that ruling unfair.","The government's lawsuit, however, was still alive. In 1888 the Supreme Court decided that the government did have the right to bring such a case, and sent it back for trial. But the case moved slowly. Antonio Meucci died in October 1889, still poor, never having seen his claims fully tested. Bell's original telephone patent expired in 1893 and his second in 1894. With the patents gone, there was little left to fight over, and the government finally dropped the case in 1897. No court ever gave a final ruling in that case on Meucci's claim to be the true inventor.","For many Italian Americans especially, Meucci became a symbol of the poor, struggling immigrant inventor who never got his chance. His home on Staten Island, where his friend the Italian hero Giuseppe Garibaldi had also lived for a time, is today the Garibaldi-Meucci Museum."]},{"heading":"A Resolution in 2002","paragraphs":["More than a century later, Meucci's story returned to Washington. On June 11, 2002, the United States House of Representatives passed House Resolution 269, introduced by Representative Vito Fossella of New York, whose district included Staten Island.","The resolution told Meucci's story: his work in Staten Island, his 1871 caveat, his poverty, the lost models and the government's 1887 lawsuit, which ended without a final decision after his death. It included the striking statement that if Meucci had been able to pay the $10 fee to keep his caveat alive after 1874, no patent could have been issued to Bell. It ended by declaring that the life and achievements of Antonio Meucci should be recognised and that his work in the invention of the telephone should be acknowledged.","It is important to understand what this resolution did and did not do. A House resolution like this one is an expression of opinion, sometimes called a 'sense of the House' resolution. It is not a law, it was never passed by the Senate, and it did not change any patent, court ruling or official record. It did not declare Meucci 'the' inventor of the telephone, although many newspapers at the time reported it that way.","Resolutions of this kind are quite common. Congress regularly passes non-binding statements honouring scientists, athletes, soldiers, anniversaries and communities. They can matter a great deal to the people being honoured, because they put a story into the official record and draw public attention to it. But they are not trials, and nobody cross-examines the evidence the way a court would.","The resolution also caused friction in Canada, where Bell is a national hero: he worked on the telephone at his family's home in Brantford, Ontario, and later lived in Nova Scotia. About ten days after the US vote, Canada's House of Commons passed its own motion stating that Alexander Graham Bell was the inventor of the telephone. Some historians were sharply critical of the US resolution too. Robert Bruce, a respected biographer of Bell, argued that Meucci's claim did not stand up and that Meucci had not understood the basic principles of the electric telephone. Meucci's supporters reply that the evidence was never properly judged because he was too poor to defend it."]},{"heading":"So Who Really Invented the Telephone?","paragraphs":["After all these lawsuits, resolutions and arguments, what is the fairest answer? It helps to separate a few different questions that often get mixed together.","Who first imagined sending speech by electricity? Charles Bourseul described the idea in France in 1854, and others dreamed of it too. Who built early devices that carried musical tones and some speech? Johann Philipp Reis in Germany, in 1861. Who worked for years on a voice-carrying device in America before Bell? Antonio Meucci, and possibly Daniel Drawbaugh, though both claims depend on evidence that was disputed in court. Who arrived at a closely similar design at almost exactly the same moment? Elisha Gray, who filed his caveat on the very day Bell's application arrived.","Who received the key patent, made it work reliably, demonstrated it to the world and turned it into a successful business? Alexander Graham Bell, with Thomas Watson building the instruments and Gardiner Hubbard and others providing money and organisation. And who made it loud and practical enough to cover real distances? Edison, Berliner, Hughes, Blake and many engineers whose names are rarely remembered.","Historians today generally agree that Bell holds the key patent and deserves major credit, but that he did not work in a vacuum. Many people were circling the same idea at the same time, because the scientific pieces, electromagnets, batteries, telegraph wires and the study of sound, were all available. When that happens, inventions often appear in several places at once. The patent system rewards whoever wins the legal race, which is not always the same as being the only person with the idea.","This pattern, sometimes called simultaneous or multiple invention, is surprisingly common in the history of science. Isaac Newton and Gottfried Leibniz both developed calculus in the late 1600s. Charles Darwin and Alfred Russel Wallace reached the idea of evolution by natural selection independently in the 1850s. In the telephone's own story, Edison, Berliner and Hughes all arrived at carbon transmitters within months of each other. When an idea is 'in the air', the person remembered is often the one who files first, builds the best working version, or wins in court, and the others become footnotes, even though their work was real.","The patent wars also had big consequences for ordinary people. Because Bell's company controlled the basic telephone until 1893 and 1894, it could set prices and decide where to build. When the patents expired, thousands of independent telephone companies sprang up, especially in small towns and farming areas the Bell company had ignored. Competition brought prices down and spread telephones far more widely.","And that spreading created a brand-new problem. In the very first years, telephones were rented in pairs and wired directly to each other: one line from your shop to your house, for example. That works for two phones. But imagine a town with a hundred phones, each wanting to call any of the others. You would need thousands of separate wires zigzagging over every street. If everyone was going to get a telephone, someone needed a smarter way to connect them, and the answer would be a busy room full of plugs, cords and voices calling out 'Number, please.'"]}],"deepDive":"Legal historians often treat the Telephone Cases, 126 U.S. 1 (1888), as a landmark in how broad a patent claim can be. Bell's fifth claim covered 'the method of, and apparatus for, transmitting vocal or other sounds telegraphically' by causing electrical undulations similar in form to the vibrations of the voice. The majority led by Chief Justice Morrison Waite read this as a valid claim to a method, not merely to a specific machine, so later designs using carbon transmitters or different receivers still infringed. Critics then and now have argued this was extraordinarily wide protection for a patent whose own described liquid transmitter was not even its main embodiment. Decades earlier, in O'Reilly v. Morse, the Court had struck down Samuel Morse's broadest claim to all uses of electromagnetism for printing at a distance, so the telephone ruling is often compared with it. The 4 to 3 split is also notable: Justices Horace Gray and Lucius Lamar did not take part, and Justice Joseph Bradley's dissent, joined by Stephen Field and John Marshall Harlan, accepted Drawbaugh's evidence of priority. With two more participating justices the result could, in principle, have been different. Debates about Gray and the patent office centre on the timing of filings on February 14, 1876, on marginal notes about variable resistance in Bell's application, and on the conflicting affidavits of examiner Zenas Wilber; historians such as Robert Bruce defend Bell, while writers such as Seth Shulman and A. Edward Evenson have argued that Bell benefited improperly. None of this has been settled by new decisive evidence. Meucci's case rests partly on notebooks and witness statements; supporters, including researcher Basilio Catania, argue he understood electrical speech, while the 1887 Globe decision concluded his caveat described a mechanical device. The 2002 House Resolution 269 is non-binding, and Canada's House of Commons answered with a motion naming Bell the inventor. The economics also matter: the settlement of November 10, 1879 removed Western Union from telephony, and Bell's patent monopoly until 1893 to 1894 shaped the American telephone industry for a century.","funFact":"The US Supreme Court's 1888 decision in the Telephone Cases, which upheld Bell's patent by just one vote, was so long that it takes up most of a whole volume of the official Supreme Court reports.","check":{"q":"How did the US Supreme Court vote in the 1888 Telephone Cases?","a":"4 to 3 in favour of Bell","wrong":["9 to 0 in favour of Meucci","5 to 4 in favour of Drawbaugh","7 to 2 in favour of Western Union"]},"sources":[{"title":"The Telephone Cases","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/The_Telephone_Cases"},{"title":"Daniel Drawbaugh","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Daniel_Drawbaugh"},{"title":"Antonio Meucci","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Antonio_Meucci"},{"title":"H. Res. 269 (107th Congress), Engrossed in House","publisher":"US Government Publishing Office (govinfo)","url":"https://www.govinfo.gov/content/pkg/BILLS-107hres269eh/html/BILLS-107hres269eh.htm"},{"title":"Bell Telephone Company","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bell_Telephone_Company"},{"title":"Bell, Gray and the invention of the telephone","publisher":"Ericsson History","url":"https://www.ericsson.com/en/about-us/history/communication/early-developments/bell-gray-and-the-invention-of-the-telephone"},{"title":"Invention of the telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Invention_of_the_telephone"}],"photos":[{"src":"img/deep/telephone/10-1.jpg","alt":"Sheet 2 of Bell's patent No. 174,465; Fig. 7 shows two cones joined by a wire to carry voice.","file":"Alexander Graham Bell's Telephone Patent Drawing and Oath - NARA - 302052 (page 2).jpg","url":"https://commons.wikimedia.org/wiki/File:Alexander_Graham_Bell%27s_Telephone_Patent_Drawing_and_Oath_-_NARA_-_302052_(page_2).jpg","author":"Alexander Graham Bell","license":"Public domain"},{"src":"img/deep/telephone/10-2.jpg","alt":"A wood engraving of Antonio Meucci, the Italian inventor who lived on Staten Island.","file":"Antonio Meucci, inventore del Telefono.jpg","url":"https://commons.wikimedia.org/wiki/File:Antonio_Meucci,_inventore_del_Telefono.jpg","author":"Francesco Giovanni Cantagalli","license":"Public domain"},{"src":"img/deep/telephone/10-3.jpg","alt":"Chief Justice Morrison Waite, photographed by Mathew Brady in the 1870s.","file":"Chief Justice Morrison Waite closeup.jpg","url":"https://commons.wikimedia.org/wiki/File:Chief_Justice_Morrison_Waite_closeup.jpg","author":"Mathew Benjamin Brady","license":"Public domain"}],"words":3678},{"n":11,"title":"Hello, Central! Switchboards and Operators","when":"1878 – 1920s","summary":"Once lots of people had telephones, someone had to connect them. In 1878 a town in Connecticut built the first public switchboard, where a person called an operator plugged cords into holes to join two callers together. Soon thousands of operators, most of them young women, were saying \"Number, please?\" all day long.","sections":[{"heading":"The Problem of Too Many Wires","paragraphs":["At the end of the last part, we left the telephone with a very practical problem. In 1877 and early 1878, if you wanted a telephone, you rented a pair of them. One went in your shop and the other went in your house, or one went in a factory office and the other in the warehouse down the street. Then you paid someone, usually a telegraph contractor, to string a wire between the two. Your telephone could talk to exactly one other telephone, and nothing else in the world.","That was useful, but think about what happens when you want to talk to more people. Suppose a small town has just five families with telephones, and every family wants to be able to call every other family. Family A needs wires to B, C, D and E. Family B already has a wire to A, but still needs wires to C, D and E. If you count them all up, five homes need ten separate wires. That does not sound too bad.","Now try it with 100 homes. Every home needs a wire to 99 others. Count each wire only once and you get 4,950 wires. With 1,000 homes you would need almost half a million wires, and every house would need a wall covered in 999 different telephones or a giant pile of switches. Mathematicians have a neat formula for this: with n homes you need n times (n minus 1), divided by 2, wires. The number grows much faster than the number of homes. Long before a city filled up with telephones, the sky would be black with wire.","The solution was beautifully simple. Instead of running wires from every home to every other home, run one wire from each home to a single central room. In that room, a person can join any two wires together whenever someone wants to talk. With 100 homes you need just 100 wires, one from each house to the middle. With 1,000 homes you need 1,000. That central room is called an exchange, because it is where conversations are exchanged and connected. The panel inside it, where the wires end and can be joined, is called a switchboard. And the person who does the joining is called an operator.","This idea was not completely new. Telegraph companies and district messenger services already had central offices where lines came together, and burglar-alarm companies ran wires from shops to a central alarm office. Several people in Europe and America had the same thought about telephones at almost the same moment in 1877. A Hungarian engineer named Tivadar Puskas, who was working with Thomas Edison, proposed the idea of a telephone exchange that year. An experimental exchange based on such ideas was tried in Boston in 1877, and in Germany a state-run exchange opened on November 12, 1877, in Friedrichsberg, near Berlin. But the honour of opening the first commercial telephone exchange, one that ordinary paying customers could join, belongs to a small town in Connecticut and a man with a very short name: George Coy."]},{"heading":"Teapot Lids and Carriage Bolts in New Haven","paragraphs":["George W. Coy was a veteran of the American Civil War who managed a telegraph office in New Haven, Connecticut. On April 27, 1877, he went to hear Alexander Graham Bell give one of his popular lectures about the telephone at the Skiff Opera House in New Haven. Bell showed off his talking wire, and Coy left the hall with a business idea buzzing in his head. If a telegraph office could send messages for a whole town, why not a central office that could connect telephones for a whole town?","Coy moved fast. On November 3, 1877, he received permission, called a franchise, from the Bell Telephone Company to run telephone service in New Haven and Middlesex counties. In return, the Bell company would own 35 percent of his new business. With two partners, the businessman Herrick P. Frost and Walter Lewis, who was superintendent of the New Haven Clock Company, he set up the District Telephone Company of New Haven on January 15, 1878.","Then came the most famous part: the switchboard itself. There were no switchboard factories in 1878, because there had never been a telephone switchboard to make. So Coy built one himself out of whatever he could find. According to the University of Connecticut Libraries, which look after the company's historic records, he used carriage bolts (the round-headed bolts used to build horse carriages), handles taken from teapot lids, lengths of wire and other spare parts. It was the kind of clever, homemade gadget that any young inventor with a junk drawer would be proud of. All the furniture in the office, including the switchboard, was reportedly worth less than about forty dollars.","Coy's board was tiny compared with what came later. It had just eight lines for its 21 customers and reportedly could connect only two conversations at the same time, and each call needed several separate connections to be made by hand. But it worked, and that was what mattered. On January 28, 1878, the District Telephone Company of New Haven opened for business in a rented storefront in the Boardman Building, at the corner of Chapel and State Streets. It had 21 subscribers, which means 21 customers who paid for the service. Each one paid $1.50 a month.","Imagine standing in that little office on a winter day in 1878. A wire from a doctor's house, a wire from a drugstore, a wire from the police office and more all run along poles and in through the wall to Coy's board. A bell rings. Coy, or one of his helpers, answers and asks who the caller wants. Then he joins the right wires with his teapot-lid handles, and two people across town suddenly hear each other's voices. For the first time, a telephone could reach not just one other telephone, but a whole community.","The idea caught on almost instantly. Within less than a month the company had 50 subscribers. On February 21, 1878, it printed what is generally called the world's first telephone directory. It was a single sheet of paper, a one-page flyer, listing 50 people and businesses in New Haven, including doctors, dentists, stores, a meat market, the police and the post office, and the three founders themselves. There were no phone numbers on it. You did not need them. You simply told the operator the name of the person you wanted. Only two copies of that first directory are known to survive today, and one of them is kept at the University of Connecticut.","Coy's little company grew up quickly. By 1880 it had the rights to serve all of Connecticut and western Massachusetts, and in 1882 it was renamed the Southern New England Telephone Company, a business that went on to operate for more than a hundred years. The Boardman Building itself was later named a National Historic Landmark, but sadly it was knocked down in 1973 to make space for a parking garage. Other towns were close behind New Haven. In 1878 an exchange in Lowell, Massachusetts, opened with about 50 subscribers, and exchanges using Bell's patents opened in London and Manchester in 1879. Within a few years, nearly every sizeable city in North America and Europe had one."]},{"heading":"Inside the Switchboard: Lamps, Cords and Jacks","paragraphs":["So how did a switchboard actually work? Let's walk up to one from the early 1900s, when the design had settled down. It looks a bit like a huge wooden desk with a tall back. On the upright back panel are rows and rows of small round holes. Each hole is called a jack, and each jack is the end of one customer's telephone line. If an exchange has 500 customers, there are 500 jacks. Next to or above each jack is a tiny signal that tells the operator when that customer wants to make a call.","On the earliest boards that signal was a drop. A drop was a little metal flap held up by a catch. When a customer at home turned the crank on the side of their telephone, the crank spun a small electric generator called a magneto and sent a pulse of current down the line. At the exchange, that current energised a small electromagnet behind the drop, which released the catch, and the flap fell open with a clack. The operator would glance up, see which flap had fallen, and know exactly which line was calling. Later switchboards replaced drops with small electric lamps that lit up instead. A lit lamp was quicker to notice and did not need to be pushed back up by hand.","On the flat desk in front of the operator were pairs of cords. Each cord was a flexible, cloth-covered cable with a metal plug at its end, and the cords came in pairs: one for the caller and one for the person being called. Behind the desk, each cord ran down over a pulley with a small weight, so that when the operator let go of a plug the cord slid neatly back into its hole in the desk instead of tangling into a mess. In front of each cord pair sat a few small switches, called keys, which let the operator talk to the caller, listen to the line and ring the other telephone.","Here is how a call went. A lamp lights up above jack number 47. The operator picks up the back cord of a free pair and plugs it into jack 47. She flips the talk key and says the famous words: \"Number, please?\" The caller answers, \"Give me 112.\" The operator reaches across the board, takes the front cord of the same pair, and plugs it into jack 112. Then she pulls a key to send a ringing current down line 112, and a bell jangles in someone's kitchen. When that person picks up, the two cords form a complete electrical path from one home, through the switchboard, to the other home, and the two people can talk.","When the call was over and both people hung up, small supervision lamps on the desk lit up to tell the operator that the line was free. She pulled out both plugs, the weights drew the cords back down, and the pair was ready for the next call. A busy operator might repeat this whole routine hundreds of times in a single shift. The plugs themselves were cleverly designed. Each had three separate metal parts called the tip, the ring and the sleeve. The tip and ring carried the voice and the ringing current, and the sleeve could signal whether a line was already busy. Modern headphone plugs still use the same tip, ring and sleeve names.","Where did the electricity come from? On the earliest systems, every telephone had its own batteries at home to power the microphone, plus the hand-cranked magneto for ringing. Customers had to replace their batteries, which was messy and unreliable. Engineers soon came up with a smarter plan called common battery. Big batteries in the exchange sent power down every line at about 48 volts, so the telephones at home needed no batteries at all. The first battery-operated switchboard of this kind was installed by the New England Telephone and Telegraph Company in Lexington, Massachusetts, in 1894. That same idea is why old landline phones kept working during power cuts: the power came from the exchange, not from the wall socket.","As cities grew, switchboards grew too, until they became enormous. A large city exchange might have long rows of boards with dozens of operators sitting side by side. Because a single operator can only reach so far, engineers invented the multiple switchboard, in which every customer's jack appeared again and again along the row, so that any operator could reach any line within arm's length. Some systems divided the work, with one team of operators answering calls and another team completing them. Calls between different exchanges travelled on special connecting lines called trunks, and needed operators at both ends to cooperate. Long-distance calls could take a very long time: in 1918, an average long-distance connection took about 15 minutes to set up."]},{"heading":"Rude Boys and the Arrival of Emma Nutt","paragraphs":["Who should sit at these new switchboards? In 1878 the obvious answer seemed to be teenage boys. Boys had already worked for years as telegraph messengers and telegraph operators, they were cheap to hire, and companies assumed they would be good with the new machines. So the first telephone exchanges in Boston and elsewhere hired boys to answer the calls.","It did not go well. Telegraph work was done in code, without hearing the customer's voice, but telephone work meant talking to real people all day long, and many of the boys were not ready for that. Accounts from the time describe operators who were impatient, cheeky and sometimes downright rude. Some swore at customers, some played pranks such as connecting people to the wrong number on purpose, and some wrestled or shouted across the room when they should have been working. A grumpy businessman who wanted to reach his bank quickly did not enjoy being teased by a fourteen-year-old.","The managers of a Boston company called the Edwin Holmes Telephone Despatch Company decided to try something different. On September 1, 1878, they hired a young woman named Emma Nutt. She was about eighteen years old, came originally from Perry, Maine, and had been working at a telegraph office. Many accounts say Alexander Graham Bell himself was involved in hiring her. Emma Nutt is remembered as the world's first woman telephone operator. Just a few hours after she started, her sister Stella Nutt was hired too, so Stella became the second woman operator in history and the Nutt sisters became the first sister operators.","Emma was very good at the job. Customers praised her calm, soothing voice and polite manner, and she was said to be able to remember every number in the company's directory, which by then was no small list. Her pay, according to the usual accounts, was 10 dollars a month for a 54-hour working week. That was a long week, but office work for young women was still rare at the time, and telephone work was seen as a respectable job. Emma stayed with telephones for more than thirty years, retiring sometime between about 1911 and 1915. Stella, on the other hand, left after a few years.","The experiment worked so well that companies across North America and Europe copied it. Within a few years, the image of the telephone operator was almost always a young woman wearing a headset. People started greeting the exchange with \"Hello, Central!\", because the operator sat in the central office, and in the United States operators were often nicknamed \"hello girls\". There was another, less admirable reason companies liked to hire women: they could pay them much less. Historians note that women operators were often paid between a half and a quarter of what a man would earn. Even so, telephone operating soon became one of the biggest sources of jobs for women in many countries, opening the door to paid work outside the home for hundreds of thousands of them."]},{"heading":"Number, Please! Life at the Board","paragraphs":["What was it like to be an operator in, say, 1910? First, you would have to be hired, and many telephone companies were very picky. Rules varied from company to company, but operators were often expected to be young and unmarried, to have clear speech and good manners, and to be quick with their hands. Some companies checked that new operators were tall enough, or had arms long enough, to reach the highest and farthest jacks on the board without standing up. New operators went to training classes to learn exactly how to handle each type of call.","At the board, the rules were strict. Operators were usually taught to use only a set of approved phrases, such as \"Number, please?\" and \"I will ring them again.\" Chatting with customers, arguing with them or giving opinions was forbidden. A supervisor walked slowly up and down behind the row of operators, watching how fast each one answered, and could plug in to listen to their calls. In many offices operators needed permission to leave their seats, even for a short break. The company wanted every call answered within a few seconds, and the best operators could handle a light every few seconds during the busiest hours of the morning.","They also stood up for themselves. As the job grew, operators formed unions to push for better pay and working conditions. In New England, an operator named Julia O'Connor led a strike of telephone operators in 1919 that won negotiations with the company after five days, showing that the women at the switchboards were a force to be reckoned with. Another operator, Harriot Daley, started as the first operator at the United States Capitol in 1898, when the switchboard there had just 51 telephones. By 1937 she was chief operator, in charge of 37 operators handling about 1,200 telephone extensions. The job had grown from a single board to a whole department."]},{"heading":"The Hello Girls Go to War","paragraphs":["When the United States joined the First World War in 1917, its army in France faced a serious communication problem. The commander of the American Expeditionary Forces, General John J. Pershing, needed to coordinate huge numbers of soldiers spread across the country, and the telephone was by now the fastest way to pass orders. But the French telephone system worked in French, the American army worked in English, and the soldiers trying to run the switchboards were slow and inexperienced. In November 1917 Pershing asked for women telephone operators to be sent to France, and he specified that they should speak French and English equally well.","The response was huge. More than 7,000 women applied. The Army Signal Corps, the part of the army responsible for communication, chose about 450 of them for training, and about 223 eventually went overseas, according to the usual counts. They were the first American women to serve in the army as something other than nurses. They wore uniforms, followed army rules and swore an oath of service. People soon called them the \"Hello Girls\", the old nickname for telephone operators.","The first group, Telephone Unit No. 1, was made up of 33 operators led by Chief Operator Grace Banker. Banker was a college graduate from Barnard College in New York who had worked for AT&T teaching people how to use switchboards. Her unit sailed from New Jersey on March 6, 1918. In France they worked at Paris, at General Pershing's headquarters in the town of Chaumont, and at about 75 other places, and some served in British cities as well.","Their work made an enormous difference. By July 1918, after the women operators arrived, the American army's daily number of telephone calls in France had roughly tripled, because calls were now connected quickly and correctly. During the great battles of St. Mihiel and the Meuse-Argonne in the autumn of 1918, Grace Banker and a team of operators ran switchboards at First Army headquarters, close enough to the fighting to hear the guns. They worked long shifts, sometimes through the night, connecting commanders to units at the front, often translating between French and American officers as they did. For her service, Grace Banker received the Distinguished Service Medal in 1919, one of the army's high honours.","Sadly, when the Hello Girls came home, the army decided they had been civilian contract workers rather than real soldiers. That meant they were not given veterans' benefits or official recognition, even though they had worn uniforms and taken an oath. Some of them, especially a former operator named Merle Egan Anderson, spent decades campaigning for the truth to be recognised. Finally, in November 1977, President Jimmy Carter signed a law that recognised them as veterans. By then, most of the Hello Girls had already died. Their story is a reminder that operators were not just friendly voices; in a crisis, they were an essential part of how a country communicated."]},{"heading":"Party Lines and the First Pay Phone","paragraphs":["Not everyone could afford a private telephone line all to themselves. Running a separate wire to every farmhouse along a country road was expensive, so telephone companies offered a cheaper choice: the party line. A party line was one telephone line shared by several homes. Party lines began with the very first switchboards in 1878, and for much of the twentieth century they were common, especially in the countryside. In 1943, for example, nearly three-quarters of homes with telephones in the state of Pennsylvania were on party lines.","How did each house know when a call was for them? On many party lines, every home's bell rang for every call, but each house had its own ring pattern, a kind of code. One family's ring might be two long rings, another family's two short rings, and another's one long and two short. A phone number might look like 93R22, meaning subscriber number 93, ring two long and two short. When the bell jingled, everyone in every house on the line counted the rings to see whose call it was. Later, engineers found clever ways to ring only the right house on lines with two, four or even eight parties, by sending the ringing current down different wires or at different frequencies.","Party lines had one obvious problem: there was no privacy at all. When your phone rang with someone else's pattern, nothing stopped you from quietly lifting your receiver and listening. Eavesdropping on the party line was a famous small-town pastime, and gossip travelled fast. There were practical problems too. If a neighbour was chatting for an hour, nobody else on the line could make a call. Some companies asked customers to keep calls to five minutes, and many places passed laws requiring people to hang up and free the line if someone else needed it for an emergency. Party lines slowly disappeared as private lines became cheaper, and by the late 1980s most were gone.","The other great way to share a telephone was to put one in a public place and let anyone pay to use it. In 1889 the Southern New England Telephone Company, the same company that grew from George Coy's exchange, installed a coin-operated public telephone in the Hartford Bank in Hartford, Connecticut. The coin mechanism was the work of an inventor named William Gray. A story often told about him says he came up with the idea after struggling to find a telephone to call a doctor when his wife was ill, but that tale is hard to check. What is certain is that his early machine was a post-pay telephone: you made your call first, and at the end, when the operator asked, you dropped your coins into the slot.","How could the operator know you had really paid? Gray's design, patented in 1891, rang a bell inside the telephone each time a coin went in, and the operator listened for the right number of dings. It was simple, but it worked. That same year Gray founded the Telephone Pay Station Company, and coin telephones began to spread to railway stations, hotels, drugstores and street corners. By the mid-1990s there were more than two million payphones in the United States alone. For a century, the pay phone was the way to call home if you were away, and it all started with a bell that went ding for every coin.","By the early 1900s, then, the telephone network had become a vast web of wires, all meeting at central exchanges where operators connected every single call by hand. It worked, but it needed enormous numbers of people, and it meant that a stranger connected every call you made. Not everyone was happy about that. In Kansas City, Missouri, an undertaker who ran a funeral business was growing more and more angry. According to a popular story, he believed his customers' calls were being sent to a rival, and he decided the answer was to get rid of human operators altogether. His name was Almon Strowger, and his invention would change telephones for the next hundred years."]}],"deepDive":"Why did the exchange matter so much? Network engineers point to a simple bit of arithmetic. Connecting n telephones directly to each other needs n(n-1)/2 links, so the cost explodes as the network grows: 10 phones need 45 links, 100 need 4,950, and 10,000 need almost 50 million. A star-shaped network with an exchange in the middle needs only n links. That change, from a mesh to a star, is what made a telephone in every home economically possible, and the same star-and-hub shape still underlies telephone and internet networks today. The value of the network also rises as more people join, which helps explain why New Haven grew from 21 to 50 subscribers in under a month. Manual switching, though, created its own scaling problem. Each operator could only handle a limited number of calls an hour, so the number of operators had to rise with the number of calls, and calls between exchanges needed operators at both ends. Multiple switchboards, common-battery power (from about 1894) and lamp signalling made each operator faster, but they could not remove the human from every call. Historians of labour also study the operator workforce closely. Companies chose women partly because customers preferred them and partly because they could be paid much less; the job offered respectable wages and independence to many young women, yet came with intense supervision, timed performance and strict rules about speech and behaviour. The 1919 New England operators' strike led by Julia O'Connor is often cited as an important moment for women in organised labour. The Hello Girls are a further case study: numbers vary slightly between sources (most accounts give about 223 women serving overseas out of roughly 450 trained), and their long fight for veteran status, finally won in 1977, has become a key example in discussions about how women's military service was recognised. Finally, a note on firsts: New Haven is widely credited with the first commercial exchange and the first printed directory, but other exchanges, including a state-run one near Berlin in November 1877 and an experimental one in Boston, appeared at almost the same time, showing once again that inventions usually have many parents.","funFact":"The world's first telephone directory, printed in New Haven on February 21, 1878, was a single sheet listing 50 names and contained no telephone numbers at all.","check":{"q":"Who is remembered as the world's first woman telephone operator, hired in Boston on September 1, 1878?","a":"Emma Nutt","wrong":["Grace Banker","Mabel Hubbard","Harriot Daley"]},"sources":[{"title":"First Commercial Telephone Exchange – Today in History: January 28","publisher":"Connecticut Humanities (ConnecticutHistory.org)","url":"https://connecticuthistory.org/the-first-commercial-telephone-exchange-today-in-history"},{"title":"First Telephone Exchange","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/First_Telephone_Exchange"},{"title":"Telephone exchange","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Telephone_exchange"},{"title":"Emma Nutt","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Emma_Nutt"},{"title":"Switchboard operator","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Switchboard_operator"},{"title":"Hello Girls","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hello_Girls"},{"title":"Party line (telephony)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Party_line_(telephony)"},{"title":"Payphone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Payphone"}],"photos":[{"src":"img/deep/telephone/11-1.jpg","alt":"A long row of telephone operators at a newly installed switchboard in Salt Lake City, Utah, in 1907.","file":"Telephone switchboard 6 Oct 1907 Salt Lake City.jpg","url":"https://commons.wikimedia.org/wiki/File:Telephone_switchboard_6_Oct_1907_Salt_Lake_City.jpg","author":"The Salt Lake Herald","license":"Public domain"},{"src":"img/deep/telephone/11-2.jpg","alt":"Cover of the New Haven, Connecticut telephone directory of November 1878, one of the world's first phone books.","file":"New haven directory 1878.jpg","url":"https://commons.wikimedia.org/wiki/File:New_haven_directory_1878.jpg","author":"Connecticut District Telephone Company","license":"Public domain"},{"src":"img/deep/telephone/11-3.jpg","alt":"The \"Hello Girls\": US Army Signal Corps telephone operators at a switchboard in Chaumont, France, during World War I.","file":"HelloGirls.jpg","url":"https://commons.wikimedia.org/wiki/File:HelloGirls.jpg","author":"Sgt. Abbott, United States Army Signal Corps","license":"Public domain"}],"words":4387},{"n":12,"title":"Spinning Dials and Automatic Switches","when":"1889 – 1960s","summary":"An undertaker in Kansas City invented a machine that could connect telephone calls with no human operator at all. Soon people were spinning dials, click-click-click, to call their friends, and later they pressed buttons that played little musical notes. Step by step, machines took over the job of connecting the world's calls.","sections":[{"heading":"The Undertaker Who Wanted No Operators","paragraphs":["Almon Brown Strowger was not the sort of person you would expect to change the telephone forever. He was born on February 11, 1839, in Penfield, a village near Rochester in New York State. As a boy he reportedly liked trying to build machines that would do his farm chores for him. When the American Civil War began, he joined the 8th New York Cavalry in October 1861 as a musician, playing the bugle calls that told soldiers when to wake, march and charge. He rose to become chief trumpeter and finished the war as a second lieutenant, after being wounded at the Third Battle of Winchester in 1864.","After the war, Strowger worked as a country schoolteacher and then, rather surprisingly, became an undertaker, the person who runs funerals. He moved west to Kansas and eventually to Kansas City, Missouri, where he ran a funeral business in the late 1880s. In those days, when someone died, a family member would often call the undertaker on the telephone. And every telephone call in Kansas City went through human operators at the exchange.","This is where one of the most famous stories in telephone history begins, and it is important to know that it is a legend, not a proven fact. According to the story, a rival undertaker in Kansas City had a wife who worked as a telephone operator. Whenever a grieving family asked the operator to connect them to \"the undertaker\", she supposedly sent the call to her husband instead of to Strowger. Strowger, the story goes, found out when a friend of his died and the funeral was handled by his rival. Furious, he decided to build a machine that would connect calls automatically, so that no operator could ever steer his customers away again.","Nobody has been able to prove the details of this tale. It may be partly true, entirely true or simply a good story that grew in the retelling, which is exactly how legends work. Other versions say he simply blamed busy or careless operators for his lost calls. What we do know for sure is that Strowger was frustrated with manual switching and wanted to replace the operator with a machine, and that he actually succeeded.","Strowger was not an electrical engineer, but he had a clear idea. According to an often-repeated account, he built his first model using a round cardboard collar box (the kind that men's detachable shirt collars were sold in) and a bunch of straight pins stuck through it to act as electrical contacts. A small arm inside could move to touch any one of the pins, connecting the caller to that line. It was the same kind of homemade ingenuity George Coy had shown with his teapot-lid switchboard, but this time the goal was to take the human out of the middle altogether.","He is usually said to have worked out the idea around 1888 or 1889, and on March 10, 1891, he was granted US Patent No. 447,918 for an \"Automatic Telephone Exchange\". Strowger was by then in his fifties, and he knew he needed help to turn his idea into a working business. He enlisted his nephew William and a group of partners who understood electricity and money, and in 1891 they founded the Strowger Automatic Telephone Exchange Company."]},{"heading":"La Porte, 1892: The First Automatic Exchange","paragraphs":["The new company needed a town willing to try something completely untested. They found it in La Porte, a small city in northern Indiana. On November 3, 1892, the first commercial automatic telephone exchange opened there. It started with about 75 subscribers and had room for 99. For the first time anywhere, ordinary customers could connect their own calls without speaking to an operator at all.","The very first La Porte telephones did not have dials. Strowger's original design used push keys instead. A customer pressed buttons a set number of times to send each digit of the number they wanted, and every press sent a pulse of electricity to the exchange. If you wanted line 34, you would tap one key three times for the tens and another key four times for the units. It worked, but it was fiddly, and if you lost count you reached the wrong person. Customers also needed extra wires from their home to the exchange to carry the signals from the separate keys.","The company's advertisements were cheerful and very proud of getting rid of the operator. They described their system as the \"girl-less, cuss-less, out-of-order-less, wait-less telephone\". The joke tells you a lot about the time: in 1892, an automatic exchange meant no operator, no rudeness and no waiting.","Engineers at the company kept improving the design. In 1896 they replaced the push keys with a much neater calling device: a finger wheel that you turned and let go, which sent the right number of pulses all by itself. This was the ancestor of the rotary dial that would sit on billions of telephones in the twentieth century. The company was later renamed the Automatic Electric Company, and it became one of the most important makers of telephone equipment in the world.","Strowger himself did not stay long. In 1896 he sold his patents to his business partners for about 1,800 dollars, and in 1898 he sold his share in the Automatic Electric Company for 10,000 dollars. He moved to St. Petersburg, Florida, and died there on May 26, 1902, at the age of 63. It turned out he had sold early: in 1916, the rights to his patents were sold to the Bell System for 2.5 million dollars. Still, his name lived on. Engineers all over the world called his kind of equipment the Strowger switch, and Strowger exchanges were still connecting calls in some places a hundred years after La Porte."]},{"heading":"How a Rotary Dial Talks to a Machine","paragraphs":["If you have ever seen an old rotary telephone, you may have wondered how spinning a wheel could possibly tell a machine miles away what number you want. The answer is wonderfully simple. The dial does exactly what Strowger's push keys did, but automatically: it switches the electric current in your line off and on a precise number of times. Engineers call these quick off-on interruptions pulses, and the whole method is called pulse dialing.","Here is what happens. You lift the receiver, and a steady electric current starts flowing from the exchange, down the wire, through your telephone and back again. You put your finger in the hole for the number 3 and turn the dial clockwise until your finger hits a curved metal piece called the finger stop. Then you let go. A spring pulls the dial back to its starting position, and as it turns back, a small switch inside opens and closes the circuit once for each number it passes. Dial 3 and the current is broken 3 times: click, click, click. Dial 7 and it is broken 7 times. Dial 0 and, in North America and many other countries, it is broken 10 times, which is why 0 sits at the far end of the dial, after 9.","Notice that nothing happens while you wind the dial up. The pulses are only sent on the way back. That is important, because people wind dials at different speeds, but the machine needs the pulses at a steady rate. Inside the dial is a tiny speed controller called a governor, a little spinning brake that stops the dial returning too fast or too slow. On a standard home telephone the dial sends about 10 pulses every second. A long gap between groups of pulses tells the exchange that one digit is finished and the next is about to start.","Pulse dialing has some funny side effects. Because a pulse is just a quick break in the current, you could actually dial a number without the dial, by tapping the hook switch (the button the receiver rests on) very fast the right number of times. Telephone engineers knew that clumsy handling of the hook, or a jiggling receiver, could accidentally send a single pulse, which looks to the exchange exactly like dialing a 1. That is one reason why, in North America, local exchange codes were not allowed to begin with 1 or 0 for many years: a number starting with 1 could be triggered by accident, and 0 was saved for calling the operator."]},{"heading":"Up and Around: The Step-by-Step Switch","paragraphs":["At the other end of the wire, in the exchange, the pulses arrive at Strowger's real invention: the stepping switch. Picture a small metal arm, called a wiper, sitting at the bottom of a curved bank of electrical contacts. The bank has 10 levels stacked one above another, like the floors of a building, and each level has 10 contacts arranged in a half-circle, like the rooms along a curved corridor. That makes 100 contacts in all, and each contact is the end of one customer's line.","When you dial the first digit, say 3, the three pulses flow into an electromagnet. Each pulse makes the magnet tug once, and each tug lifts the wiper up exactly one level. Click, click, click: the arm rises to the third floor. Then you dial the second digit, say 4. Now the pulses go to a different magnet, which turns the wiper sideways one step per pulse. Click, click, click, click: it rotates to the fourth contact on the third level. The wiper is now touching line 34, and the switch rings that telephone. No person has touched anything. Because the switch moves one step for each pulse, engineers called this system step-by-step.","One switch can only reach 100 lines, so how could a city with 10,000 or 100,000 telephones work? The trick was to chain switches together. The first digit you dial moves a switch called a selector, which picks one group of lines out of ten and hands your call on to another switch serving just that group. The next digit moves that switch, and so on, until the last two digits move the final switch, called a connector, to your friend's exact line. Each extra digit multiplies the number of lines you can reach by ten. With five digits you could reach 100,000 lines; with seven digits, ten million.","If you had walked into a step-by-step exchange, you would have heard it before you saw it. Rows of tall metal frames held thousands of switches, and every call made them rattle and chatter: wipers leaping up, swinging around, and snapping back home with a clunk when the call ended. In a busy exchange at the start of the working day, the room sounded like a giant room full of typewriters. Maintenance workers walked the aisles with tools, cleaning contacts and adjusting springs, because all those moving parts wore out."]},{"heading":"The Bell System Picks Up the Dial","paragraphs":["You might expect that the biggest telephone company in America would have rushed to use automatic switching. In fact the Bell System was cautious for years. Independent telephone companies in smaller cities installed Strowger equipment quickly in the early 1900s, but Bell's engineers worried that step-by-step switches would not cope with the enormous number of calls in huge cities such as New York and Chicago, where a single exchange might serve tens of thousands of lines.","Instead, Bell's engineers at Western Electric spent years developing their own system for big cities, called the panel switch, in which motor-driven rods moved selectors up and down tall panels of contacts. They tested it carefully. On January 16, 1915, a partly automatic panel exchange called Mulberry opened in Newark, New Jersey, serving 3,640 subscribers. Operators still answered every call there, but instead of plugging in cords they typed the wanted number on keys and let the machine finish the job.","Around 1919 the Bell System committed to switching its customers over to dial service, using step-by-step equipment in smaller cities and panel equipment in the biggest ones. Telephone traffic was growing so fast that the company would have needed an impossibly large army of operators to keep up. In December 1921 the Douglas and Tyler exchanges in Omaha, Nebraska, became the first fully machine-switched panel exchanges, and their customers received dial telephones. Rotary dials did not become common across the Bell System until the 1920s, and the changeover took decades. Some towns did not lose their last manual switchboard until the 1970s and 1980s.","Switching technology kept improving. From the late 1930s, the Bell System began installing crossbar switches, which used a grid of crossing metal bars and small relays to make connections faster and more reliably than step-by-step or panel switches, with fewer parts that wore out. From the 1960s, the first electronic switching systems arrived, which used computers rather than clanking mechanical parts to decide where each call should go. Each new generation could handle more calls with less noise, less maintenance and fewer people."]},{"heading":"PEnnsylvania 6-5000: Names, Numbers and Area Codes","paragraphs":["Once people dialed their own calls, telephone numbers became really important. In a big city, there were many exchanges, each serving a different neighbourhood, and each exchange had a name. To call someone, you dialed the first letters of the exchange name and then the number. That is why old dials have letters beside the numbers. In North America, an AT&T engineer named William G. Blauvelt worked out the standard pattern in 1917: 2 for ABC, 3 for DEF, 4 for GHI, 5 for JKL, 6 for MNO, 7 for PRS, 8 for TUV and 9 for WXY. There was no Q, and usually no Z.","So a number written as REgent 7-3456 meant dialing R and E, which are 7 and 3, followed by 7-3456. People remembered the names more easily than strings of digits, and exchange names became part of everyday life and popular culture. In 1940 the bandleader Glenn Miller had a hit song called \"PEnnsylvania 6-5000\", named after the real telephone number of the Hotel Pennsylvania in New York City. From the late 1950s and 1960s, telephone companies gradually switched to all-number calling, and the old exchange names faded away, though the letters stayed on the dial and still sit on phone keypads today.","Calling a nearby number was one thing, but how could a machine connect you to someone on the other side of the continent? In October 1947, AT&T and the other telephone companies drew up a plan that divided the United States and Canada into 86 numbered areas. Each area got a three-digit area code. This system grew into what is now called the North American Numbering Plan. The original codes followed a clever rule: the middle digit was always 0 or 1. Areas that covered a whole state or province got a 0 in the middle, while states split into several areas got a 1. Because ordinary local exchange codes never had 0 or 1 as their second digit back then, the switching machines could tell instantly whether you had dialed an area code or a local number.","New Jersey was given area code 201, the first in the list. The busiest cities received codes that were quick to dial on a rotary phone, with few pulses: New York City got 212, Los Angeles 213 and Chicago 312. Spinning 2-1-2 sends just five pulses in total, while a code such as 907 would take 26. For a person dialing many times a day, those saved seconds added up.","At first, area codes were used only by operators. Then, on November 10, 1951, the mayor of Englewood, New Jersey, M. Leslie Denning, dialed ten digits on his own telephone and reached Frank Osborne, the mayor of Alameda, California, more than 4,000 kilometres away, without speaking to a single operator. It was the first customer-dialed long-distance call in the United States, a service called direct distance dialing. At first only customers in Englewood and neighbouring Teaneck could use it, and only to reach eleven big cities. The service spread slowly in the 1950s and much faster in the 1960s. Britain began its own version, called subscriber trunk dialling, on December 5, 1958, when Queen Elizabeth II dialed a call from Bristol to Edinburgh. From March 1970, Americans could begin dialing some international calls directly too."]},{"heading":"Touch-Tone: Music in Every Button","paragraphs":["Rotary dials were reliable, but they were slow. Dialing a long number like 0 or 9 meant waiting for the dial to crawl all the way back, and a ten-digit long-distance number could take many seconds to spin. Engineers at Bell Labs started looking for something faster, and they found it in music. On November 18, 1963, the Bell System began offering Touch-Tone service to customers in two Pennsylvania towns, Carnegie and Greensburg. Instead of a dial, the new Western Electric telephone had ten push buttons.","Each button on a Touch-Tone phone plays not one musical note, but two at the same time. The buttons are laid out in a grid of rows and columns. Each row has its own low tone and each column has its own high tone. The top row plays 697 hertz, the next 770, then 852, then 941. The left column plays 1,209 hertz, the middle 1,336 and the right 1,477. So when you press 1, top row and left column, the phone plays 697 and 1,209 hertz together. Press 9, third row and right column, and you get 852 and 1,477. Engineers call this system dual-tone multi-frequency signalling, or DTMF for short.","Why two tones instead of one? Because a single tone could easily be imitated by accident by a person's voice, music on a radio in the room or noise on the line, which might fool the exchange into thinking a button had been pressed. A precise pair of notes from two separate groups almost never happens by chance in normal speech. The frequencies were also carefully chosen so they would not clash with the special tones the telephone network already used to send signals between its own exchanges. And because the tones are ordinary sounds, they travel happily through the whole network, including amplifiers and radio links, so you can use them in the middle of a call too.","Around 1968, a twelve-button version of the phone arrived with two new keys: the star (*) and the square sign (#), which people in North America often call the pound key. Engineers added them because they imagined people one day using their phones to talk to computers. They were right. Every time you hear \"Press 1 for opening hours, press 2 to speak to someone\", you are using DTMF tones invented in the early 1960s. There is even a hidden fourth column of tones, for keys labelled A, B, C and D, which the US military used for special priority calls but which never appeared on ordinary home phones.","For years many telephone companies charged extra each month for Touch-Tone service, even long after it cost them nothing more to provide. Still, push buttons gradually replaced dials in homes and offices, and the rotary phone slowly became a museum piece."]},{"heading":"What Happened to the Operators?","paragraphs":["Each step in this story, the stepping switch, the dial, area codes, direct dialing and Touch-Tone, meant fewer calls needed a human being to connect them. Operators did not vanish overnight. For decades people still dialed 0 for the operator to make collect calls, person-to-person calls, calls from pay phones and calls in emergencies, and operators still handled most long-distance calls until direct distance dialing spread in the 1960s. But the huge rooms full of switchboards slowly emptied, and one of the biggest sources of jobs for women shrank.","Historians who have studied this change found that it was hard for the operators who lost their jobs, many of whom had spent years at the board. Yet young women entering work in later years generally found jobs elsewhere, in offices and other growing kinds of work. Automation also brought something many customers wanted: privacy. With a machine connecting the call, no operator could listen in.","In some places the old ways lasted a surprisingly long time. In the small town of Bryant Pond, Maine, customers were still using hand-cranked telephones connected by an operator until October 1983, and it is believed to have been the last such exchange in the United States to switch to dialing. By then, the clatter of step-by-step switches was itself giving way to the silent hum of computers.","Automatic switching solved the problem of connecting calls without operators. But there was another, even older problem it could not solve. A voice sent down a wire becomes weaker and weaker the farther it goes. A switch can connect New York to San Francisco in a flash, but that does not help if the voice arrives too faint to hear. To make a phone call across a whole continent, engineers would need to find ways to keep a voice strong over thousands of kilometres of wire."]}],"deepDive":"The move from manual to automatic switching is a classic case study in how technology, economics and labour interact. A step-by-step exchange is a beautiful example of distributed control: each switch responds directly to the pulses of one digit and then passes the call on, with no central brain. That makes it simple and robust, but also rigid. The number you dial is literally the physical route through the machinery, so changing numbering plans or rerouting traffic around a busy part of the exchange is hard. The Bell System's panel and crossbar switches introduced common control: the dialed digits were first stored in a register, and a shared control unit then chose a free path through the switches. That separation of 'deciding' from 'connecting' was a key idea that led directly to computer-controlled electronic switching from the 1960s. Pulse dialing has a hard speed limit. At about 10 pulses per second plus gaps between digits, a ten-digit number full of 8s, 9s and 0s can take well over ten seconds to dial. DTMF removed that limit and also allowed signalling during a call, which made automated menus and later voicemail possible. Its two-of-eight tone scheme is a simple form of error resistance: real speech rarely produces exactly one frequency from the low group and one from the high group at the same time and strong enough to count. Historians still debate the Strowger origin story. The idea of a rival's wife diverting calls appears in many popular accounts, but there is little firm evidence for it, so it is best treated as a legend that captures a real frustration with manual switching. Economists have also studied the effect of automation on operators. A 2024 study found that mechanization hurt the operators already in the job but did not reduce overall employment for young women, who moved into other growing occupations. Finally, the 1947 area-code plan, with its 0-or-1 middle digit rule, is a good example of designing a numbering system around the limits of the hardware; that rule was eventually dropped in the mid-1990s, when the supply of codes ran short.","funFact":"When Touch-Tone phones arrived, engineers added the star and pound keys because they predicted people would one day use their phones to talk to computers, decades before automated phone menus became common.","check":{"q":"Where did the first commercial automatic telephone exchange, using Almon Strowger's system, open in 1892?","a":"La Porte, Indiana","wrong":["New Haven, Connecticut","Kansas City, Missouri","Englewood, New Jersey"]},"sources":[{"title":"Almon Brown Strowger","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Almon_Brown_Strowger"},{"title":"Strowger switch","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Strowger_switch"},{"title":"Rotary dial","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rotary_dial"},{"title":"Panel switch","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Panel_switch"},{"title":"Direct distance dialing","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Direct_distance_dialing"},{"title":"North American Numbering Plan","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/North_American_Numbering_Plan"},{"title":"Dual-tone multi-frequency signaling","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dual-tone_multi-frequency_signaling"},{"title":"Push-button telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Push-button_telephone"}],"photos":[{"src":"img/deep/telephone/12-1.jpg","alt":"Almon Brown Strowger, the inventor of the automatic telephone exchange.","file":"Almon Strowger.jpg","url":"https://commons.wikimedia.org/wiki/File:Almon_Strowger.jpg","author":"Unknown author","license":"Public domain"},{"src":"img/deep/telephone/12-2.jpg","alt":"Step-by-step Strowger switches (line finder, selectors, connector) and banks of contacts at the Telephone Museum in Waltham, Massachusetts.","file":"Strowger switches and contact array TMW.agr.jpg","url":"https://commons.wikimedia.org/wiki/File:Strowger_switches_and_contact_array_TMW.agr.jpg","author":"ArnoldReinhold","license":"CC BY-SA 4.0"},{"src":"img/deep/telephone/12-3.jpg","alt":"A beige Western Electric Model 500 rotary dial phone, with letters like ABC and DEF beside the numbers.","file":"WE500dialphone.jpg","url":"https://commons.wikimedia.org/wiki/File:WE500dialphone.jpg","author":"ProhibitOnions at English Wikipedia","license":"Public domain"}],"words":3812},{"n":13,"title":"Coast to Coast and Across the Sea by Radio","when":"1885 – 1940s","summary":"In 1915 Alexander Graham Bell picked up a phone in New York and talked to his old friend Thomas Watson in San Francisco, almost the whole width of America away. To make that possible, engineers had to invent clever coils and glowing glass tubes that kept voices loud. A few years later, people could even phone across the Atlantic Ocean by radio, if they had 75 dollars to spare!","sections":[{"heading":"A Company Built for Distance","paragraphs":["By the early 1880s, telephones were no longer a wonder only scientists had seen. Towns all over the United States had their own little exchanges, with operators plugging cords into switchboards. But almost every one of those networks was an island. A doctor in Boston could call a pharmacy in Boston, but calling a customer in New York, about 300 kilometres (190 miles) away, was a different matter entirely. The wires that worked fine across a town turned voices into faint, mushy whispers when they were stretched between cities.","The leaders of the American Bell Telephone Company understood that whoever solved long distance would own the future of the telephone. So on March 3, 1885, they set up a new company in New York with a long, serious name: the American Telephone and Telegraph Company, soon known everywhere by its initials, AT&T. At first AT&T was a side project, a company whose single job was to build and run long-distance lines that would knit the local Bell companies together. One of its first big lines connected New York and Philadelphia, and by 1892 a line stretched from New York to Chicago, about 1,500 kilometres (950 miles).","Something surprising happened over the next few years: the side project grew bigger than its parent. On December 30, 1899, the whole business was reorganized and AT&T became the parent company of the Bell System, the family of Bell companies, factories and laboratories that would run most of America's telephones for most of the twentieth century.","The person who shaped that system more than anyone was Theodore Vail. Vail had started his career as a telegraph operator and then ran the Railway Mail Service, which sorted letters on moving trains. He had worked for Bell's company in its early years, left, and then returned as president of AT&T in 1907. Vail had a big, simple idea, which he summed up in a slogan: “One Policy, One System, Universal Service.” He believed a telephone was only as useful as the number of people you could reach with it. A phone that connected you to your neighbours was handy; a phone that connected you to anyone in the country was something much more powerful.","Vail's vision had two sides, and it is fair to look at both. On one side, it pushed engineers to make the network reach farther and work better, and it gave customers a phone that worked the same way everywhere. On the other side, “one system” meant one company in charge. Many smaller independent phone companies had sprung up after Bell's first patents expired in the 1890s, and the Bell System bought up many of them. In 1913 the US government stepped in, and AT&T agreed to a deal called the Kingsbury Commitment, promising to sell its shares in the Western Union telegraph company, to stop swallowing up independent companies without permission, and to let independents connect to its long-distance lines. The story of the Bell System's power, and the fights it caused, comes later in this Deep Dive. For now, the important thing is that Vail had both the money and the stubbornness to attempt something no one had ever done: a phone line from one side of the continent to the other."]},{"heading":"Why Voices Fade on Long Wires","paragraphs":["To understand why long distance was so hard, imagine your voice as a pattern of electric current, rising and falling hundreds or thousands of times every second to match the vibrations of your vocal cords. That pattern has to travel down a copper wire. Two sneaky problems attack it along the way.","The first problem is resistance. Even a good copper wire pushes back a little against the current flowing through it, turning some of the electrical energy into a tiny amount of heat. Over a few kilometres you would never notice. Over hundreds of kilometres, the losses add up, and the voice signal grows weaker and weaker, like a shout fading as you walk away from someone in a field.","The second problem is harder to picture. A telephone line usually has two wires running side by side, and two wires next to each other can store a little electric charge between them, a property engineers call capacitance. On a long line, that stored charge acts like a sponge. It soaks up the quick wiggles of the signal and lets them seep out slowly. The result is that the high notes of a voice, which give words their crisp edges, get smeared and blurred more than the low notes. Sounds like s, f and t lose their sharpness, and speech turns into a muffled mumble even if it is still loud enough to hear. This is the same family of problem William Thomson had studied in the long undersea telegraph cables back in the 1850s.","The early fix was brute force: use thicker wire. Thick copper has less resistance, so the first long-distance lines used heavy wire strung on tall poles. The New York to Chicago line of 1892 used unusually thick copper wire, many tonnes of it, and copper was expensive. Even so, there was a practical limit. Without new tricks, clear speech over an ordinary line could only reach a few hundred kilometres before it became too faint and blurry to use. Experts often quote a working limit of roughly 160 kilometres (100 miles) for ordinary lines before the next invention came along. A line across the whole United States, thousands of kilometres long, seemed impossible.","Engineers needed two kinds of help: something to stop the smearing, and something to make weak voices strong again. The first answer would come from coils of wire. The second would come from a glowing glass bulb."]},{"heading":"A Coil Every Few Kilometres","paragraphs":["Back in 1887, an English scientist named Oliver Heaviside, who worked alone and wrote his ideas in difficult mathematics, figured out something that seemed backwards. He showed that adding a property called inductance to a telephone line could actually reduce the smearing. Inductance is the tendency of a coil of wire to resist sudden changes in current, a bit like a heavy flywheel that is hard to start and hard to stop. Heaviside realized that, in the right amount, inductance could balance out the sponge effect of capacitance, so that high and low notes of a voice would travel along the line together instead of falling out of step. Heaviside never patented his idea, and for years few people knew how to turn it into hardware.","Around 1899, two men in America worked out how to do it, almost at the same moment. One was George Ashley Campbell, a young mathematician and engineer working for AT&T in Boston. The other was Michael Pupin, a professor at Columbia University in New York. Pupin's own life story was remarkable: he had arrived in America as a teenager from Idvor, a Serbian village then in the Austrian Empire, with almost no money, worked on farms and in factories, and fought his way into Columbia, then went on to study physics in Europe before becoming a professor.","Campbell and Pupin both worked out the practical answer: instead of trying to spread inductance evenly along the whole wire, you could insert small coils of wire at regular spacing, a bit like putting stepping stones across a stream. If the coils were close enough together, the line behaved almost as if the inductance were smooth. These became known as loading coils, and a line fitted with them was called a loaded line. In American practice, the coils were typically placed roughly every 1.6 to 1.8 kilometres (about a mile), hidden in boxes on poles or in underground vaults.","Campbell tested a loaded cable in Boston in September 1899, and the first loaded line carrying real customer calls began working in May 1900 between Jamaica Plain and West Newton in Massachusetts. Both Campbell and Pupin applied for patents. Pupin's application had been filed first, and AT&T, worried about a long legal fight, decided to buy the rights to Pupin's patent. Accounts of the price vary, but one widely repeated version is $185,000 in cash plus $15,000 a year for as long as the patent lasted, an enormous sum at the time, and it made Pupin a wealthy man. Many historians today say Campbell deserves at least equal credit, because he did much of the careful engineering that made loading work on real lines. Once again, as with the telephone itself, an important invention had more than one parent.","The results were dramatic. Loading coils let the same voice travel roughly twice as far, or let the company use much thinner, cheaper copper wire for the same distance. Over the following decades the Bell System installed loading coils in enormous numbers. Using thinner wire is estimated to have saved AT&T around 100 million dollars in the first quarter of the twentieth century. Loaded lines pushed the Bell network westward, and by 1911 a long-distance line reached from New York all the way to Denver, Colorado, more than 2,700 kilometres (1,700 miles) away. That was about as far as loading alone could go. To cross the Rocky Mountains and reach the Pacific, the voice needed something that could do more than slow down the smearing. It needed to be made louder."]},{"heading":"A Glowing Tube That Makes Voices Louder","paragraphs":["What engineers really wanted was an amplifier, also called a repeater: a device placed partway along a line that takes in a weak, tired voice signal and sends out a strong copy of it. People had tried mechanical repeaters, in which an earpiece-like receiver was pressed against a microphone to give the voice a push. They worked a little, but they added hiss and distortion, and you could not chain many of them together without the voice becoming a scratchy mess.","The answer came from an unexpected direction: early radio. In 1906 an American inventor named Lee de Forest took a glass bulb similar to a light bulb, with a glowing filament inside, and added a small zigzag of wire between the filament and a metal plate. He called his invention the Audion. That extra piece of wire, later called the grid, turned out to be magic. A tiny changing voltage on the grid could control a much larger current flowing through the tube, the way a small turn of a tap controls a big flow of water. That is exactly what an amplifier does: a small signal steers a big one, so the big one becomes an enlarged copy of the small one.","De Forest himself did not fully understand how his tube worked, and his early Audions were unreliable. They contained some leftover gas, which made them glow blue and behave unpredictably. In 1913 Western Electric, the Bell System's manufacturing company, bought rights to use the Audion. AT&T engineers, led by a physicist named Harold Arnold, set to work improving it. Arnold realized that the gas was the problem and that the tube worked far better when almost every bit of air was pumped out to make a high vacuum. At about the same time, Irving Langmuir at General Electric came to similar conclusions. The result was the vacuum tube, a dependable amplifier that would power radios, telephone networks and the first electronic computers for the next forty years.","Now the long-distance plan finally made sense. Loading coils would keep the voice from smearing, and vacuum-tube repeaters placed at stations along the route would boost it whenever it got weak. Each repeater station was a small building with racks of equipment, glowing tubes and technicians who kept everything adjusted. In a way, it was a high-tech version of the old relay runners from the start of this story: the voice ran for a while, got tired, and was handed on, fresh and strong, to the next stretch of wire."]},{"heading":"Stringing a Wire Across a Continent","paragraphs":["Theodore Vail had made a bold public promise. In 1909, before anyone knew whether the vacuum tube would work, AT&T committed to building a telephone line from New York to San Francisco. A great world's fair, the Panama-Pacific International Exposition, was planned for San Francisco in 1915 to celebrate the opening of the Panama Canal, and AT&T wanted to open coast-to-coast calling in time for it.","Building the line was a giant outdoor adventure as well as a scientific one. Crews had to carry poles and wire across prairies, deserts, the Rocky Mountains and the Sierra Nevada. The wires were open copper wires strung on crossarms of wooden poles, and the line needed tens of thousands of poles; a commonly quoted figure is around 130,000. Workers dug holes in frozen ground, hauled equipment by wagon where there were no roads, and fought snowstorms in the mountains and blazing heat in the Nevada and Utah deserts.","On June 17, 1914, crews set the final pole at Wendover, on the border between Utah and Nevada, connecting the eastern and western halves. In July 1914 engineers made the first successful voice tests across the whole line, and Vail himself spoke across the continent that summer. But AT&T held back the grand public opening for months, waiting for the Exposition. The finished route stretched about 5,400 kilometres (3,400 miles) from New York to San Francisco, and the call travelled through a few vacuum-tube repeater stations along the way. Without those tubes, the voice would have faded to nothing long before it reached California."]},{"heading":"January 25, 1915: Watson, Come Here Again","paragraphs":["Picture the scene. It is late afternoon on January 25, 1915, and in a room at AT&T's offices at 15 Dey Street in lower Manhattan, a crowd of officials and reporters is watching an old man with a white beard. Alexander Graham Bell is now 67 years old. Nearly 39 years earlier, in a cramped workshop in Boston, he had spoken the first famous sentence ever carried by a telephone. Now, 5,400 kilometres away, at 333 Grant Avenue in San Francisco, his former assistant Thomas Watson is holding a receiver to his ear.","The call was organized like a celebration. Other people listened in from other places: President Woodrow Wilson joined from the White House in Washington, D.C., and Theodore Vail, who was unwell, listened from Jekyll Island in Georgia. Bell spoke into the transmitter and, for the cameras and reporters, repeated a version of his famous first words, reported in the newspapers as “Mr. Watson, come here, I want you.” (Remember that in his 1876 notebook, the line was written as “Mr. Watson — come here — I want to see you.”)","Watson's answer was a joke that made everyone laugh. Accounts differ on the exact wording. Some say he replied that it would take him a week to get there; others quote him as saying it would take five days. Either way, the point was clear and wonderful: Watson could hear Bell instantly, but crossing the same distance in person would take days on a fast train.","For AT&T, the call was partly a science triumph and partly a giant advertisement. The line had actually been working for some months, but the Bell-and-Watson conversation gave the public a story they would never forget. The service was not cheap. A three-minute call from New York to San Francisco in 1915 cost about $20.70, which was more than many workers earned in a week. Most people would not make a coast-to-coast call for years. Still, the message was out: distance itself had been beaten. A voice could now cross a continent in a tiny fraction of a second.","There is a lovely symmetry in this moment. The same two men who had first heard a voice travel from one room to another were now hearing each other across America. In just under four decades, the telephone had gone from a fragile experiment with acid and wires to a continent-spanning machine with coils, vacuum tubes and thousands of workers keeping it alive."]},{"heading":"Voices Over the Waves: Calling Across the Atlantic by Radio","paragraphs":["Once America was crossed, the next obvious target was the ocean. But there was a big problem. Telegraph cables had crossed the Atlantic since 1866, but those cables carried simple on-off clicks, slowly. A voice signal is far more complicated, and the old cable designs could not carry it. Over thousands of kilometres of seabed, a voice would be smeared and weakened beyond rescue, and nobody yet knew how to place amplifiers safely on the bottom of the ocean.","So engineers turned to the sky. Radio waves, invisible waves of electromagnetic energy, could travel across the ocean without any wire at all. In 1915, the same year as the transcontinental call, AT&T engineers used banks of vacuum tubes at a powerful US Navy radio station in Arlington, Virginia, to send speech by radio. Listeners heard it as far away as Hawaii in one direction and Paris, at the Eiffel Tower, in the other. It was the first known time a human voice crossed the Atlantic, even though the conversation only went one way.","Turning that experiment into a reliable public service took more than ten years. AT&T in America and the British Post Office, which ran Britain's phone system, worked together on powerful long-wave radio stations, with a huge transmitter at Rugby in England and a matching system on the American side. On March 7, 1926, a test call travelled by radio between London and New York. Then, on January 7, 1927, commercial service opened. Walter Gifford, the president of AT&T, spoke from New York with Sir Evelyn Murray of the British Post Office in London, and paying customers could book calls the same day.","Those calls were astonishingly expensive: $75 for the first three minutes, with each extra minute costing about $25 more. In today's money, a short call cost well over a thousand dollars. In the beginning, the system could handle only one conversation at a time, so callers booked their calls in advance through an operator, almost like reserving a seat on a ship. Most early customers were bankers, newspapers, businesses and the very wealthy.","Radio telephone had other weaknesses too. Radio signals bouncing around the atmosphere could fade, crackle or vanish during storms and at certain times of day. And radio was not private. Anyone with the right receiver could listen in, so over time engineers added scrambling equipment that jumbled the sound, so that a casual eavesdropper would hear only gibberish (though it was not strong enough to stop a determined spy). During the 1930s, the service improved, expanded to shorter radio waves that could carry more calls, and spread to more countries, connecting America by radio telephone to much of Europe, South America and beyond. Ships at sea gained radio telephones too. By the late 1930s, a person in New York could, with enough money and patience, talk to most of the developed world."]},{"heading":"Telephones in Every Town, and a Minute of Silence","paragraphs":["While engineers stretched lines across continents and oceans, the telephone was quietly becoming an ordinary part of life. Around 1900 there were roughly 1.4 million telephones in the United States. By 1920 there were more than 13 million. In cities, phones moved from shops and offices into apartments and houses. People began to expect that the doctor, the grocer and the fire station could be reached with a call, and a later part of this Deep Dive will look closely at how that changed everyday life.","For people who did not have a phone at home, or were out and about, there were public telephones. Early ones were often attended phones in shops, hotels, railway stations and drugstores, where an attendant collected the money. After coin-operated pay phones appeared, they spread quickly, and by the early twentieth century many cities had wooden or glass telephone booths with folding doors that gave the caller a little privacy from the noisy street. In Britain, the Post Office introduced its famous red telephone kiosks in the 1920s and 1930s, designed by the architect Giles Gilbert Scott, and many still stand today as beloved landmarks.","Alexander Graham Bell himself had long since moved on to other inventions. He spent much of his later life at Beinn Bhreagh, his estate on Cape Breton Island in Nova Scotia, Canada, experimenting with giant kites built from tetrahedrons, flying machines, and fast boats called hydrofoils. One of his hydrofoils, the HD-4, set a world water-speed record of about 114 kilometres per hour (71 miles per hour) in 1919.","Bell died at Beinn Bhreagh on August 2, 1922, aged 75, after suffering from complications of diabetes. His family buried him on top of a hill on his estate, overlooking the Bras d'Or Lake. Then something moving happened. As a tribute, telephone service across the United States and Canada was reportedly halted for one minute, at about 6:25 in the evening, Eastern time. For sixty seconds, the great network that had grown from his invention fell silent. Millions of phones, thousands of switchboards and long-distance lines from coast to coast went quiet together, a silence that showed just how big his invention had become.","Yet there was still one gap that wires could not cross. Radio calls over the ocean were expensive, crackly and few. Engineers dreamed of something better: a voice cable lying along the ocean floor, like the old telegraph cables, but with amplifiers sealed against the crushing deep sea, so that voices could cross the Atlantic as clearly as they crossed America. It would take another world war, and a tiny new invention from Bell's own laboratories, to begin to make that dream come true."]}],"deepDive":"The engineering story of long-distance telephony is really a story about two enemies: attenuation (the signal getting weaker) and distortion (different parts of the signal arriving changed or out of step). In the 1880s and 1890s, Oliver Heaviside wrote down the 'telegrapher's equations', which describe a line in terms of four quantities per unit length: resistance, inductance, capacitance and leakage. He showed that if these are balanced in a particular ratio, a line becomes 'distortionless': all frequencies are weakened by the same amount and travel at the same speed. Real copper lines had far too little inductance, so the high frequencies of speech lagged and faded faster than the low ones. Loading coils, inserted at regular intervals, raised the effective inductance. The trade-off was that a loaded line acts as a low-pass filter, cutting off frequencies above a certain point; engineers chose spacing so that the cutoff stayed above most of the frequencies that matter for understanding speech (telephone circuits came to carry roughly 300 to 3,400 hertz). Historians still debate credit for loading. Pupin won the patent contest and was paid handsomely by AT&T, but Campbell's mathematics and field tests were at least as important, and Campbell went on to invent the electric wave filter. The vacuum-tube amplifier introduced a new design problem: each repeater amplifies noise as well as signal, and a two-way telephone line can 'sing' (howl with feedback) if the gain is too high. Bell System engineers developed careful gain settings and devices called hybrids to separate the two directions of conversation. Within a few years, the same tubes made 'carrier' systems possible, in which several conversations were shifted to different frequencies and sent along one pair of wires at once, a technique that would eventually carry thousands of calls on a single cable. Radio telephony used long-wave frequencies at first, which travel along the curve of the Earth; later shortwave links bounced signals off the ionosphere, a charged layer of the upper atmosphere, giving more capacity but less reliability, since ionospheric conditions change with the time of day, the seasons and the Sun's activity.","funFact":"When Bell died in 1922, telephone service across the United States and Canada was reportedly silenced for one minute in his honour.","check":{"q":"Which glowing device, improved by Bell System engineers, made the 1915 coast-to-coast telephone call possible by making weak voices louder?","a":"The vacuum-tube amplifier (developed from Lee de Forest's Audion)","wrong":["The carbon microphone","The transistor","The rotary dial"]},"sources":[{"title":"First transcontinental telephone call","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/First_transcontinental_telephone_call"},{"title":"History of Communications timeline: 1915","publisher":"IEEE Communications Society","url":"https://www.comsoc.org/node/18886"},{"title":"History of Communications timeline: 1900 (loading coils)","publisher":"IEEE Communications Society","url":"https://www.comsoc.org/node/18806"},{"title":"AT&T Corporation","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/AT%26T_Corporation"},{"title":"Audion","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Audion"},{"title":"First Transatlantic Telephone Call","publisher":"This Day in Tech History","url":"https://thisdayintechhistory.com/03/07/first-transatlantic-telephone-call"},{"title":"Alexander Graham Bell","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alexander_Graham_Bell"},{"title":"Loading coil","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Loading_coil"}],"photos":[{"src":"img/deep/telephone/13-1.jpg","alt":"Alexander Graham Bell (centre) in New York opening the first coast-to-coast telephone line on 25 January 1915.","file":"Alexander Graham Bell, first transcontinental phone call, 25 Jan 1915.jpg","url":"https://commons.wikimedia.org/wiki/File:Alexander_Graham_Bell,_first_transcontinental_phone_call,_25_Jan_1915.jpg","author":"Irving Underhill","license":"Public domain"},{"src":"img/deep/telephone/13-2.jpg","alt":"An early De Forest Audion, the first vacuum tube that could amplify, with its filament, grid and plate inside the glass.","file":"Triode tube 1906.jpg","url":"https://commons.wikimedia.org/wiki/File:Triode_tube_1906.jpg","author":"Gregory F. Maxwell","license":"GFDL 1.2"},{"src":"img/deep/telephone/13-3.jpg","alt":"An old loading coil (Pupin coil): copper wire wound around a ring, used on long-distance phone lines. PTT Museum, Belgrade.","file":"Pupin coils in PTT Museum in Belgrade 02.jpg","url":"https://commons.wikimedia.org/wiki/File:Pupin_coils_in_PTT_Museum_in_Belgrade_02.jpg","author":"Milica Buha","license":"CC BY-SA 4.0"}],"words":3908},{"n":14,"title":"Voices Under the Ocean and Light in a Glass Thread","when":"1947 – today","summary":"In 1956 a long cable laid on the bottom of the Atlantic Ocean finally let people talk clearly between Europe and America. Soon after, a shiny ball-shaped satellite called Telstar bounced calls and TV pictures through space. Today, most calls and internet messages between continents race along as flashes of light inside glass threads thinner than a hair, lying on the sea floor.","sections":[{"heading":"A Christmas Present from Bell Labs","paragraphs":["By the 1940s the telephone network ran on two kinds of machinery: clattering electromechanical switches that connected calls, and glowing vacuum tubes that amplified voices along the way. Vacuum tubes had made the coast-to-coast call possible, but they had serious weaknesses. They were made of glass, so they could break. They needed a hot glowing filament, so they used a lot of power and gave off heat. And like light bulbs, they eventually burned out. In a network with many thousands of tubes, something was always failing somewhere.","At Bell Telephone Laboratories, the Bell System's huge research centre in Murray Hill, New Jersey, a team of scientists was hunting for a replacement. They were studying semiconductors, materials such as germanium and silicon that conduct electricity better than an insulator like rubber but not as well as a metal like copper. The group was organized by William Shockley. Two of its members, the theoretical physicist John Bardeen and the experimental physicist Walter Brattain, made the breakthrough.","On December 16, 1947, Bardeen and Brattain pressed two tiny gold contacts, extremely close together, onto a small slab of germanium. When they changed the voltage on one contact, it controlled a larger current flowing through the other. The little device amplified a signal, much as a vacuum tube did, but with no glass bulb, no glowing filament and no vacuum. On December 23 they showed it to their bosses, and Shockley later called it a magnificent Christmas present. Another Bell Labs engineer, John Pierce, came up with the name transistor. Bell Labs announced the invention to the world on June 30, 1948, and in 1956 Bardeen, Brattain and Shockley shared the Nobel Prize in Physics for it.","The first transistors were fiddly and expensive, but they improved quickly. Over the following decades they became smaller, cheaper, more reliable and far less power-hungry than tubes. Transistors would eventually replace tubes in telephone amplifiers, switching equipment, radios, satellites and computers, and billions of them now sit inside every mobile phone. But in the early 1950s, transistors were still brand new, and engineers did not yet trust them for the toughest job in telephone engineering: sitting at the bottom of the ocean for twenty years with nobody able to fix them."]},{"heading":"Why a Voice Cable Under the Sea Was So Hard","paragraphs":["In the previous part we left engineers dreaming of a telephone cable along the floor of the Atlantic, like the old telegraph cables laid by the Great Eastern back in 1866. Those telegraph cables could carry only a slow trickle of clicks. Over thousands of kilometres, a voice signal would fade to nothing long before it reached the far shore. On land, the answer was to put amplifiers, or repeaters, in little buildings along the route. Under the ocean there are no buildings.","So the repeaters had to go into the cable itself, lying on the sea floor. Think about what that meant. In the deep Atlantic, the water is around 4 kilometres (2.5 miles) deep, almost completely dark, near freezing, and the pressure is hundreds of times greater than at the surface. Each repeater had to be sealed in a strong, watertight case that could survive being dropped over the side of a ship and sinking all the way down. It had to work non-stop for many years, because hauling a cable up from that depth to replace a part is slow, difficult and very expensive. And it needed electricity, but there are no power sockets on the sea floor, so power had to be sent from the shore along the same cable that carried the voices.","Engineers solved these problems with a design called a coaxial cable: a central copper conductor surrounded by a layer of insulation, then an outer conductor, all wrapped in protective layers. The insulation was no longer the gutta-percha tree sap of Victorian cables but a new plastic, polyethylene, which insulated better and did not rot. Short undersea telephone cables with repeaters had already been laid in calmer, shallower waters, such as between Florida and Cuba in 1950. The Atlantic was the great test.","Because transistors were too new to trust, Bell Labs engineers designed the Atlantic repeaters around specially made vacuum tubes. These were not ordinary tubes. They were built and tested with extraordinary care, using carefully chosen materials, so that they would last for decades without failing. The engineers chose tubes they had years of experience with over a newer device that might be better but had not yet proved itself, a careful choice that paid off."]},{"heading":"TAT-1: The First Telephone Cable Across the Atlantic","paragraphs":["The project was called TAT-1, short for Transatlantic Telephone Cable No. 1. It was a partnership between AT&T, the British Post Office and the Canadian Overseas Telecommunication Corporation. The main cable ran from Gallanach Bay near Oban, on the west coast of Scotland, to Clarenville, in Newfoundland, Canada. From there, connections continued across the Cabot Strait to Nova Scotia and onward to the United States.","There was a clever trick in the design: TAT-1 was really two cables, laid side by side but some distance apart, one for each direction of conversation. That kept the electronics in the repeaters simpler, because each repeater only had to amplify signals flowing one way. Most of the laying was done in the summers of 1955 and 1956 by the British cable ship HMTS Monarch, which carried coils of cable in huge tanks in its hull and paid it out over the stern as it steamed slowly across the ocean.","The deep-sea section crossed more than 3,000 kilometres of ocean floor, and each cable is usually said to have contained about 51 repeaters, spaced roughly 70 kilometres apart. The repeaters were long, flexible units designed to bend around the cable-laying machinery on the ship, rather than bulky boxes. Each one quietly boosted the voices passing through, again and again, all the way across the ocean.","TAT-1 officially opened on September 25, 1956. It carried 36 telephone channels at first, meaning about 36 conversations could take place at once, compared with only a handful of crackly radio-telephone channels before. In its first 24 hours, it carried 588 calls between London and the United States and another 119 between London and Canada. People were thrilled by how clear the calls sounded; it was like talking to someone in the next town rather than through a storm.","Engineers kept squeezing more out of the cable. By narrowing the slice of sound frequencies given to each call slightly, they raised it to 48 channels. Then, in 1960, they added a clever system called TASI (time-assignment speech interpolation). It took advantage of the fact that in a normal conversation each person is silent much of the time, listening, pausing, or breathing. TASI handed those silent moments to other callers, so the same cable could carry about 72 conversations at once.","TAT-1 also played a part in world history. In 1963, after the Cuban Missile Crisis showed how dangerous slow communication between world leaders could be, a direct link was set up between Washington and Moscow, often called the hotline. Despite the movie image of a red telephone, it actually used teleprinters that typed out messages, and one of its routes ran through TAT-1. The cable served for 22 years and was retired in 1978, after newer cables with much more capacity had been laid alongside it. In 2006 it was honoured as an IEEE Milestone, an award for great achievements in engineering history."]},{"heading":"Telstar: A Telephone Exchange in Space","paragraphs":["Just six years after TAT-1, engineers tried a completely different route across the ocean: up. In 1945 the science-fiction writer Arthur C. Clarke had suggested that satellites high above the Earth could relay radio signals between continents. By the early 1960s, rockets had made that idea possible to try.","Telstar 1 was built by Bell Labs and paid for by AT&T, working with NASA, which launched it and helped run the project. It was the first privately funded satellite. Telstar looked like a faceted ball about 88 centimetres (34.5 inches) across, covered in solar cells that turned sunlight into electricity, and it weighed about 77 kilograms (171 pounds). Inside, it carried a radio receiver, an amplifier and a transmitter, built mostly with transistors, the young invention from Bell Labs we met at the start of this part. It worked like a mirror in the sky: it caught a signal sent up from one ground station, made it stronger, and beamed it back down to another.","Telstar 1 was launched from Cape Canaveral in Florida on a Thor-Delta rocket early in the morning of July 10, 1962. On the ground, AT&T had built an enormous horn-shaped antenna at Andover, Maine, about seven storeys tall and weighing around 340 tonnes, inside a giant inflated dome to protect it from the weather. In Europe, matching stations stood at Pleumeur-Bodou in France and Goonhilly Downs in Cornwall, England.","Hours after launch, Telstar relayed its first test pictures, including an image of an American flag outside the Andover station, to France. On July 23, 1962, it carried the first publicly broadcast live television across the Atlantic, watched by millions in Europe and North America. The same day it relayed a telephone call between US Vice President Lyndon Johnson and AT&T's chairman, Frederick Kappel. Telstar also carried test telephone calls, data and photographs.","The public went wild for it. The idea of voices and pictures bouncing off a machine in space felt like science fiction come true. An instrumental pop song named after the satellite, “Telstar” by the British band the Tornados, shot to number one in Britain and then in the United States, the first record by a British group to top the American charts. Newspapers printed diagrams showing signals zigzagging up to the satellite and down again, and schoolchildren learned the names of the ground stations.","Telstar had a big limitation. It flew in a low, egg-shaped orbit, circling the Earth every couple of hours, so it was only in view of both sides of the Atlantic at once for short windows, about 18 to 20 minutes at a time. Then it dipped below the horizon and the link was lost. Its electronics were also damaged by radiation in space, made worse by a high-altitude nuclear test the United States had carried out shortly before the launch, and Telstar 1 stopped working in early 1963.","The solution was to put satellites much higher, about 35,800 kilometres (22,200 miles) above the equator, in what is called a geostationary orbit. At that height a satellite takes exactly one day to go around the Earth, so it seems to hang still in the sky, always in view. In 1965 Intelsat I, nicknamed Early Bird, became the first commercial communications satellite in that orbit, able to carry about 240 telephone conversations across the Atlantic.","But satellite calls had a curious side effect. A radio signal travels at the speed of light, about 300,000 kilometres per second, which sounds unbeatable. Yet going up 35,800 kilometres and back down again takes about a quarter of a second, and the reply has to make the same journey. That added up to roughly half a second between saying something and hearing the other person begin to answer. People on satellite calls often talked over each other, paused awkwardly, or heard a faint echo of their own voice coming back. Engineers built echo cancellers to tame the echo, but the delay itself could not be removed, because no one can make light go faster. That is one reason telephone companies kept laying cables, which are much closer to the ground and therefore much quicker."]},{"heading":"Light in a Glass Thread","paragraphs":["The next revolution did not use electricity in copper at all. It used light. The idea is called fiber optics, and at its heart is a beautifully simple trick of physics called total internal reflection. If you shine a light down a thin, very clear strand of glass, and the glass in the middle (the core) is surrounded by a slightly different glass (the cladding), the light keeps bouncing off the boundary and stays trapped inside, even when the strand curves. It is a bit like water flowing through a hose: the light follows the fiber wherever it goes.","To send a phone call through a fiber, the voice is first turned into a digital signal, a stream of numbers made of ones and zeros. Then a tiny laser flashes on and off incredibly fast, with a flash for a one and darkness for a zero, billions of times every second. At the far end, a light detector turns the flashes back into electrical ones and zeros, and the equipment rebuilds the sound of the voice. A fiber can be thinner than a human hair, yet it can carry far more conversations than a thick bundle of copper wires.","In the early 1960s, there was a serious problem. The best glass of the day was nowhere near clear enough. Light fading inside it lost almost all its strength within a few metres. Most experts thought glass fibers would never be useful for long-distance communication.","Charles Kuen Kao thought otherwise. Born in Shanghai, China, in 1933, Kao studied electrical engineering in London and worked at Standard Telecommunication Laboratories in Harlow, England. With his colleague George Hockham, he investigated why the light faded. Their answer, published in July 1966, was that the glass itself was not the problem. The problem was impurities, tiny traces of metals like iron mixed into the glass. If glass could be made pure enough, they calculated, light could travel a kilometre and still keep about one percent of its strength, which was good enough for long-distance links. At the time, the best glass was so cloudy that this seemed like a fantasy, but Kao travelled around the world urging glassmakers to try.","About four years later, in 1970, scientists at the Corning Glass Works company in New York State made fibers clear enough to meet Kao's target. Within a decade, fibers had become so pure that light could travel many kilometres before fading noticeably. Imagine a window made of such glass that was several kilometres thick, and you could still see through it. Around the same time, small semiconductor lasers were developed that could switch on and off fast enough to send signals. In 2009 Kao was awarded half of the Nobel Prize in Physics for his groundbreaking work on the transmission of light in fibers for optical communication. He is often called the father of fiber optics.","How fast is a call through a fiber? Light slows down a little inside glass, travelling at roughly 200,000 kilometres per second, about two thirds of its speed in empty space. A cable crossing the Atlantic is around 6,000 kilometres long, so a flash of light takes only about three hundredths of a second to cross the whole ocean. That is far quicker than the trip up to a geostationary satellite and back. On a fiber call between London and New York, the delay is too short for most people to notice at all, and conversations feel just as natural as talking to someone across town."]},{"heading":"TAT-8 and the Hidden Web on the Sea Floor","paragraphs":["On December 14, 1988, the first transatlantic fiber-optic cable, TAT-8, went into service. It was built by AT&T, British Telecom and France Télécom, and it cost about $335 million. It linked Tuckerton, New Jersey, in the United States with Widemouth Bay in Cornwall, England, and Penmarch in Brittany, France, splitting on the sea floor using a branching unit, a kind of underwater junction. TAT-8 could carry about 40,000 telephone conversations at once. Compare that with TAT-1's 36 channels just over thirty years earlier: more than a thousand times as many calls on a single cable.","TAT-8 still needed repeaters, but now they were electronic boxes that turned the weak light back into electrical signals, cleaned them up, and sent them on as fresh laser flashes. In the 1990s, a clever invention removed even that step. Optical amplifiers, made from a short length of special fiber containing a rare element called erbium, could strengthen the light directly, without turning it into electricity first. Engineers also learned to send many different colours of laser light down the same fiber at once, each colour carrying its own stream of information. Capacity exploded. TAT-8 was retired in 2002, already completely outclassed by newer cables.","Today the ocean floors are crisscrossed by hundreds of undersea fiber-optic cables, together more than a million kilometres long. They carry almost all the voice calls, video calls, emails, videos and web pages that travel between continents, roughly 99 percent of intercontinental data. Satellites still matter for ships, planes and remote places, but they carry only a tiny fraction of the traffic. Every time someone in Europe video-chats with a cousin in America, their voices are very likely racing as flashes of light through glass on the bottom of the Atlantic.","A modern deep-sea cable is surprisingly thin, often about the thickness of a garden hose, roughly 2 to 2.5 centimetres. Most of that is protection. At the centre are the fibers themselves, surrounded by a tube, a copper layer that carries the electric power for the amplifiers, and a tough plastic jacket. Near the coast, where the danger is greater, cables get extra layers of steel armour wires and are often buried in the seabed by an underwater plough towed behind the cable ship."]},{"heading":"Anchors, Earthquakes and the Occasional Shark","paragraphs":["Undersea cables lie in one of the most remote places on Earth, but they are not safe from harm. Around the world, cables suffer well over a hundred faults every year. Most of the damage is caused by people, not nature. According to the International Cable Protection Committee, an organisation of cable owners and operators, ship anchors being dragged along the seabed and fishing gear such as heavy trawl nets cause about 65 to 75 percent of all cable faults. That is why most damage happens in fairly shallow water near coasts, where ships anchor and fishing boats work.","Nature causes some breaks too. Undersea earthquakes and landslides can trigger fast-moving underwater avalanches of mud and sand. A famous example came in 1929, when an earthquake off the Grand Banks of Newfoundland set off one of these avalanches, and telegraph cables on the sea floor snapped one after another as it rushed downhill. Scientists later used the timing of the breaks to work out how fast the avalanche had travelled, turning a disaster into a discovery about the ocean floor.","And sharks? It is true that sharks and other fish have occasionally bitten cables. In the 1980s, an early experimental fiber-optic cable was damaged several times by bites, which some experts think came from deep-sea sharks attracted by the cable's weak electric field. Cable makers responded by adding tougher protective layers. In recent years, cable experts say fish bites have caused almost no faults at all. Sharks make a great story, but they are a tiny danger compared with anchors and fishing nets.","When a cable does break, a special repair ship sets out. Engineers on shore first send test signals down the cable and time how long it takes for them to bounce back from the break, which tells them roughly where the damage is. The ship sails to the spot and lowers a grappling hook called a grapnel to snag the cable on the seabed, sometimes kilometres below. It hauls one end up to the deck, where technicians in a clean workroom carefully splice the hair-thin fibers back together by melting their ends and joining them, then do the same with the other end, adding a new piece of cable if needed. Finally the repaired cable is lowered back into the sea. A repair can take days or weeks, especially in deep water or stormy weather.","Because cables are so important, networks are designed with backups. Traffic can usually be rerouted through other cables when one breaks, so most people never notice a fault on the other side of the world. Still, places served by only one or two cables, such as some small island nations, can lose much of their connection to the outside world until a repair ship arrives.","From TAT-1's 36 conversations in 1956 to today's fibers carrying vast amounts of data, the ocean floor has become the hidden backbone of how humanity talks. Yet all this amazing engineering exists for a very human reason: so that ordinary people can reach each other. In the next part, we zoom back up from the dark sea floor to living rooms, offices, farms and fire stations, to see how all these connections changed everyday life."]}],"deepDive":"Kao and Hockham's 1966 argument turned on a number: attenuation, measured in decibels per kilometre (dB/km). A loss of 10 dB means only one tenth of the light power survives; 20 dB means one hundredth. The best optical glass in the mid-1960s lost something like 1,000 dB/km, so after a single kilometre essentially nothing was left. Kao and Hockham argued that intrinsic losses in silica glass were far lower, and that the excess came from impurities, especially transition-metal ions such as iron and copper, and from water. If loss could be brought below about 20 dB/km, a fiber link with repeaters every few kilometres would be practical. Corning's Robert Maurer, Donald Keck and Peter Schultz beat that target in 1970, and by the late 1970s fibers reached about 0.2 dB/km at a wavelength near 1,550 nanometres, close to the physical limit set by Rayleigh scattering (light bouncing off tiny density variations frozen into the glass). Today's submarine systems rely on several further ideas. Erbium-doped fiber amplifiers, introduced into transoceanic cables in the 1990s, amplify a broad band of wavelengths around 1,550 nm at once. Wavelength-division multiplexing puts many independent channels, each on its own wavelength, into one fiber. Modern 'coherent' transmission encodes data in the phase as well as the brightness of light, and spatial-division cables carry many fiber pairs. Some recent transatlantic cables are rated at hundreds of terabits per second. By contrast, TAT-1's analog coaxial system carried 36 voice channels of roughly 4 kHz each. Satellites remain essential for coverage, but geostationary physics imposes a round-trip delay of roughly half a second for a two-way exchange, which is why low-orbit satellite constellations have attracted interest. Historians also note the strategic side of cables: from the Victorian telegraph to today, governments have regarded them as critical infrastructure, and cable protection, routing diversity and repair capacity are active policy issues.","funFact":"The first transatlantic telephone cable, TAT-1, was laid as two separate cables, one for each direction of conversation.","check":{"q":"What did Charles Kao show in 1966 was the main reason light faded quickly inside glass fibers?","a":"Impurities in the glass, not the glass itself","wrong":["Sharks biting the cables","The fibers were too thin to carry light","Light cannot travel around bends"]},"sources":[{"title":"1947 - Invention of the Point-Contact Transistor","publisher":"Computer History Museum","url":"https://www.computerhistory.org/siliconengine/invention-of-the-point-contact-transistor/"},{"title":"Telstar Opened Era of Global Satellite Television","publisher":"NASA","url":"https://www.nasa.gov/history/telstar-opened-era-of-global-satellite-television"},{"title":"Optical Fiber Pioneer Shares Physics Nobel","publisher":"IEEE Spectrum","url":"https://spectrum.ieee.org/amp/optical-fiber-pioneer-shares-physics-nobel-2650252235"},{"title":"TAT-1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/TAT-1"},{"title":"TAT-8","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/TAT-8"},{"title":"Telstar 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Telstar_1"},{"title":"Don't blame sharks for Asian Internet problems, experts say","publisher":"Computerworld","url":"https://www.computerworld.com/article/1618278/dont-blame-sharks-for-asian-internet-problems.html"},{"title":"Submarine communications cable","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Submarine_communications_cable"}],"photos":[{"src":"img/deep/telephone/14-1.jpg","alt":"A Telstar satellite, its many-sided ball covered in solar cells, on display at the Science Museum in London.","file":"Telstar satellite.jpg","url":"https://commons.wikimedia.org/wiki/File:Telstar_satellite.jpg","author":"Tiia Monto","license":"CC BY-SA 3.0"},{"src":"img/deep/telephone/14-2.jpg","alt":"The huge horn antenna inside its radome at the Andover, Maine ground station, used to talk to early satellites like Telstar.","file":"Relay 1 antenna USA.jpg","url":"https://commons.wikimedia.org/wiki/File:Relay_1_antenna_USA.jpg","author":"Unknown author","license":"Public domain"},{"src":"img/deep/telephone/14-3.jpg","alt":"Diagram of a modern undersea fiber-optic cable, showing the tiny glass fibers in the middle and the protective layers around them.","file":"Submarine cable cross-section.svg","url":"https://commons.wikimedia.org/wiki/File:Submarine_cable_cross-section.svg","author":"Mysid","license":"Public domain"}],"words":3734},{"n":15,"title":"How the Phone Changed Everyday Life","when":"1880s – 1990s","summary":"Once telephones reached shops, farms and homes, life sped up. Farmers strung phone lines along their fences, people could call for help with three simple numbers, and deaf people found a clever way to 'talk' by typing over the phone.","sections":[{"heading":"The Office That Never Stopped Ringing","paragraphs":["Picture a busy shop counter in an American city around 1885. Behind the counter, bolted to the wall, is a wooden box with a crank on the side and a little horn to speak into. When it rings, the shopkeeper hurries over, lifts the earpiece and hears a customer from across town asking for two pounds of coffee and a sack of flour to be delivered before supper. Ten years earlier, that order would have needed a walk, a horse ride or a messenger boy. Now it took less than a minute.","The very first people to rent telephones were mostly not families. They were businesses: doctors, pharmacies, hotels, factories, banks, newspapers, livery stables that rented out horses, and shops of every kind. For them, the telephone was not a fun gadget. It was a tool that saved time, and in business, time is money. A factory owner could call a supplier to ask whether a shipment of iron had left the station. A doctor could be called to a sick child's bedside without someone running through the streets to find him.","Money markets changed too. Traders had already used the telegraph and the ticker tape machine, which printed share prices on long paper strips. The telephone added something new: a real conversation. A broker could talk to a client, hear the worry or excitement in their voice, ask a question and get an answer straight away. Over the following decades, trading floors filled with telephones, and shouting into a receiver became part of the noisy music of every stock exchange.","Newspapers loved the telephone. A reporter standing at the scene of a fire or a big court case no longer had to rush back to the office. He or she could find the nearest phone and read the story out loud to a 'rewrite' desk, where another journalist typed it up for the next edition. That meant news reached readers hours sooner. Big stores began taking orders by phone, and catalogue companies and grocers built whole delivery systems around the ring of a bell.","There was a quieter change, too. Before the telephone, important business was usually done face to face or by letter. Now deals could be made, cancelled or changed in a single call. Offices began to hire people whose main job was answering the phone politely and passing on messages. The 'telephone voice' — a slightly brighter, clearer way of speaking used on calls — became part of office life. By the early 1900s, a company without a telephone number printed on its letters and adverts looked old-fashioned."]},{"heading":"Farmers, Fences and the Ring for Everyone","paragraphs":["In the countryside, the story was different and, in some ways, more surprising. Big telephone companies wanted to build lines where lots of customers lived close together, because that brought the most money for each kilometre of wire. A farmhouse kilometres from its nearest neighbour was not very tempting. For years, many farm families were left out.","Then came an important date. Alexander Graham Bell's two key telephone patents expired in 1893 and 1894. Once they ran out, anyone was allowed to build and sell telephones. Thousands of small 'independent' telephone companies sprang up across the United States, especially in the Midwest. Some were run by local businesspeople. Many were owned by the farmers themselves, who formed 'mutual' or co-operative companies: each family paid a share, helped put up the poles and wire, and took turns keeping the line in repair.","Some farmers found an even cheaper trick. Around the turn of the twentieth century, in some rural areas, people used the barbed-wire fences that already stretched between their fields as telephone lines. A metal fence is a long piece of wire, after all, and electricity does not care whether the wire has sharp barbs on it. Families connected a telephone to the top strand of fence, sometimes with short bits of wire to jump across gates and roads. These fence lines were crackly, and they could stop working when wet weeds or a fallen post touched the wire, but they cost almost nothing and could link a whole valley of ranches.","Most rural phones were on party lines, which means one line shared by many homes. Every house on the line heard every ring, so each family had its own pattern, such as two long rings and one short. If it was not your ring, you were supposed to ignore it. (Many people did not, as we will see in the next part.) There was also a special 'general ring', often one very long ring, that meant everyone should pick up. The operator or a neighbour might use it to announce a fire, a storm coming, a lost child, the result of an election, or the weather forecast for farmers about to cut their hay.","For lonely farm families, especially women who might not see another adult for days, the party line became a kind of village square made of wire. People shared recipes, prices for corn and hogs, news of births and illnesses, and warnings about wolves or floods. Some historians point out that, in the early 1900s, farm families in parts of the Midwest were actually more likely to have a telephone than many families in big cities. It is a good reminder that inventions do not just flow down from big companies; ordinary people often grab them and build their own networks."]},{"heading":"Nine, Nine, Nine: London Invents the Emergency Number","paragraphs":["Travel back to London in November 1935. A fire breaks out at number 27 Wimpole Street, a building where an ear surgeon, Dr Philip Franklin, had his surgery. A neighbour sees the flames and picks up the phone to call the fire brigade. In those days you dialled 0 for the operator and waited. But the exchange was busy, and the call sat in a queue with everybody else's ordinary calls. Five women died in the fire. At the official inquiry afterwards, people learned something shocking: the fire engines had actually arrived before the operator answered the neighbour's call.","The government set up a group of experts, called the Belgrave Committee, to solve a simple but important problem: how could an operator tell, instantly, that a call was an emergency? Their answer was to create one special number, the same everywhere, that anybody could remember even when frightened.","Choosing the number was trickier than you might think. One idea was 707, because on the old dial those numbers lined up with the letters S, O and S, the famous distress signal. Another was 333. But the telephone equipment of the time could not easily handle them. The number had to be three digits to work in London's system, and it had to be dialled from coin-operated phone boxes without putting money in. The number 111 was rejected partly because of a strange technical problem: when wind made overhead wires swing and touch, the tiny clicks could look to the exchange like someone dialling 1-1-1, which would have caused false alarms. So 999 was chosen as the most practical option.","The world's first emergency telephone number went live in London on 30 June 1937, across 91 automatic exchanges. When someone dialled 999, a red light flashed and a loud alarm sounded at the exchange so the operator knew to drop everything. If every operator was busy, one would cut off an ordinary call to take the emergency. The alarm horns were so noisy that, according to one popular telephone-company story, an operator stuffed a tennis ball into one to make it bearable.","In the first week there were 1,336 calls to 999. Most, 1,073, were real emergencies. Some came from people who just wanted the operator, and 91 were listed as coming from practical jokers — a problem emergency services still face today. Within days, a call from a woman in Hampstead led police to arrest a burglar. Glasgow became the second city with 999 in 1938, but the Second World War slowed the spread, and it took years more before the whole country was covered. Today, 999 calls in the UK are counted in the tens of millions every year."]},{"heading":"A Red Phone in Haleyville","paragraphs":["Across the Atlantic, the United States took much longer to get a single emergency number. For decades, if your house was on fire you had to know the fire station's own number, or dial the operator and hope she could connect you quickly. Every town had different numbers for police, fire and ambulance. Visitors, children and panicking people often had no idea what to dial.","People had been asking for a better system for years. In 1957 the National Association of Fire Chiefs recommended a single number for reporting fires. In 1967 a commission set up by the President to study law enforcement recommended one nationwide emergency number. Late that year, the Federal Communications Commission, the government agency in charge of telephones, met with AT&T, the giant company that ran most of America's phones, to pick it.","Why not copy Britain's 999? On American switching equipment it was not practical. Instead, engineers chose 9-1-1. It was short, it was easy to remember, and it had never been given out as an area code or the start of an ordinary number, so it would not clash with anyone's existing phone number.","AT&T planned to switch on its first 911 system in Huntington, Indiana. But a small, independent company beat it. B. W. Gallagher, the president of the Alabama Telephone Company, read about the plan and decided his company should be first. He chose the little town of Haleyville, Alabama, because its exchange equipment could be changed quickly, and an engineer named Robert Fitzgerald designed and installed the system in less than a week.","On February 16, 1968, Alabama's Speaker of the House, Rankin Fite, picked up a phone and dialled 9-1-1. At the other end, in the Haleyville police station, a bright red phone rang, and US Congressman Tom Bevill answered. It was a ceremonial call — there was no real emergency — but it was the first 911 call in the United States. Huntington, Indiana, got AT&T's own 911 system on March 1, 1968.","Spreading the number across a huge country took a long time, because every local phone system and emergency service had to be changed. About 26 percent of Americans could dial 911 in 1979. By 1987 it was about half, and by 2000 about 93 percent. Later 'Enhanced 911' systems added something brilliant: the dispatcher's screen could show the caller's phone number and address automatically, so help could be sent even if the caller could not speak. Today 911 centres in the US handle roughly 240 million calls a year. Meanwhile, much of Europe adopted another number, 112, as a shared emergency number in 1991, so a traveller can dial the same three digits in many countries."]},{"heading":"Number, Please: A Giant Job for Women","paragraphs":["Back in Part 11 we met Emma Nutt, who in 1878 became the first woman telephone operator. What started with one young woman in Boston grew into one of the biggest kinds of work open to women anywhere. By the early and middle 1900s, hundreds of thousands of women in the United States alone sat in long rows at switchboards, wearing headsets and plugging cords into jacks while saying 'Number, please?' many hundreds of times a day.","Why women? Telephone companies said women were more polite and patient than the rowdy teenage boys who had first done the job. There was also a less flattering reason: companies could pay women far less. One estimate is that women operators were paid between a quarter and a half of what a man might earn in similar work. Still, for many young women, especially daughters of working families and immigrants, being an operator was a respectable, steady job in a modern industry, and a step away from factory work or cleaning in other people's houses.","The work was hard. Supervisors walked up and down behind the operators, timing how fast they answered. Operators had to use exact, polite phrases, could not chat with callers, and sometimes needed permission to leave their seats. Long shifts with the constant buzz of voices left many exhausted. In 1919 thousands of operators in New England, led by a young union leader named Julia O'Connor, went on strike. After five days, the government agreed to step in, and the operators won higher pay and the right to bargain together as a union.","Operators did far more than connect calls. In small towns, the local operator often knew everyone. People called her to ask the time, to find out where the fire was, to check on the doctor, or to wake them up in the morning. During floods, fires and storms, operators sometimes stayed at their switchboards for hours, calling families one by one to warn them, even when their own homes were in danger.","As automatic dialling spread (Part 12), the number of operator jobs slowly fell. The change was not instant. In the tiny town of Bryant Pond, Maine, people kept using a hand-crank switchboard until 1983. A study published in 2024 by economists James Feigenbaum and Daniel Gross found that older operators who lost their jobs to automation often had a hard time afterwards, but young women in general found work in other growing jobs, such as offices. It is a pattern we still see today: new machines remove some kinds of work and create others."]},{"heading":"Party Lines, Long Talks and Calling Grandma","paragraphs":["For a long time, a home telephone was something of a luxury. By around 1946, about half of American households had one, and that share kept rising through the 1950s and 1960s. In Britain and many other countries, home phones spread more slowly; plenty of families relied on the red public phone box down the street.","Where was the family phone? Usually in one fixed spot: the hallway, the kitchen wall, or a little table near the front door. Some families even bought a 'telephone seat', a small bench with a shelf for the phone and the thick phone book. The cord was short, so whoever was talking stood or sat right there, in full hearing of everyone walking past. Later, families stretched extra-long curly cords so a teenager could drag the receiver around a corner or into a cupboard for a bit of privacy.","Teenagers and the telephone became a famous pair. From the 1940s onward, newspapers, cartoons and films joked about teens tying up the family line for hours, chatting about school, music and friends. Parents complained that nobody else could get through. Some families paid for a second line just so the grown-ups could make calls.","Long-distance calls were special events. They cost much more than local calls, often charged by the minute, so people kept them short and planned them carefully. Many families waited for evenings or weekends, when the rates were cheaper, to call grandparents in another city. Hearing the voice of a relative hundreds of kilometres away could be so exciting that the whole family crowded around to take turns saying a few words. For soldiers far from home, emigrants who had moved to a new country, and students away at college, the phone call home became an important ritual.","With all this talking came rules of 'phone etiquette'. Books and telephone companies taught people to answer clearly, often with their family name or phone number, to speak at a normal volume, not to shout, and not to call too early in the morning or too late at night. On party lines, good manners meant hanging up if you picked up during someone else's call, and keeping calls short so neighbours could use the line. Children were taught how to take a message with a pencil and notepad kept by the phone. The phone book, listing almost everyone's name, address and number, became a kind of map of the community."]},{"heading":"Typing Down the Telephone: Robert Weitbrecht's Clever Coupler","paragraphs":["There is a sad twist in the telephone story. Bell spent much of his life working with deaf people, yet for nearly ninety years the telephone itself was almost useless to them. If you cannot hear the voice at the other end, a phone is just a plastic object on the wall. Deaf people had to ask hearing friends or family to make calls for them, or travel in person to deliver even small messages.","The person who changed that was Robert Weitbrecht. He was born deaf in Orange, California, on April 11, 1920. As a teenager he earned a licence for Morse code and became a keen amateur radio operator, chatting by code with people far away. He studied astronomy at the University of California, Berkeley, worked on electronics during the Second World War, and later earned another degree in astronomy from the University of Chicago. In 1957 he went to work at the Stanford Research Institute in California, designing equipment for Lick Observatory.","In 1950 Weitbrecht bought an old teletypewriter, or TTY, from a Los Angeles newspaper plant. A teletypewriter is a machine that looks like a big, heavy typewriter: what you type at one machine is sent as electrical signals and printed out at another. Newspapers and news agencies used them to receive stories. But Weitbrecht's machine could only receive, so he rebuilt it, using clever home-made fixes, so it could send too.","The big problem was connecting TTYs to the telephone network. At the time, the phone company did not want customers wiring their own machines into its lines. Then, in 1964, a deaf orthodontist in Pasadena named Dr James C. Marsters sent Weitbrecht a teletypewriter and asked him to find a way for them to communicate. Weitbrecht designed an 'acoustic coupler'. You placed the ordinary telephone handset into two rubber cups. The coupler turned the TTY's signals into beeping tones, which it played into the phone's mouthpiece, and listened to tones coming out of the earpiece, turning them back into signals for the printer. Because it only used sound, it did not need to be wired into the phone company's lines.","The first tries were messy, with garbled letters. Then, at last, Weitbrecht's words printed clearly on Marsters's machine: 'Are you printing now? Let's quit for now and gloat over the success.' Deaf people could now 'phone' each other by typing. Weitbrecht, Marsters and another deaf man, Andrew Saks, formed a company to make the couplers, and none of them got rich from it. Deaf volunteers collected old teletypewriters that businesses were throwing away, repaired them, and passed them on to deaf families.","The next step was letting deaf and hearing people talk to each other. Relay services were created, in which a trained operator in the middle reads the typed words aloud to the hearing person and types the spoken reply back. In the United States, the Americans with Disabilities Act of 1990 required telephone companies to provide relay services across the country. Weitbrecht was given an honorary doctorate by Gallaudet University, a university for deaf students, in 1974. He died in 1983, but the idea he started grew into today's text relay, captioned phones and video relay services."]},{"heading":"A World Rewired","paragraphs":["Step back and look at the century between the 1880s and the 1990s, and you can see how deeply the telephone changed daily life. Businesses moved faster. Farmers who had once been isolated for weeks shared news every day. A frightened child could dial three numbers and reach help. Millions of women earned their own wages, and some of them led strikes that improved working conditions for everyone after them. Families separated by oceans could hear each other laugh. And deaf people, after a long wait, found a way in.","But every powerful invention has a shadow side. A line that lets you talk to your friend can also let someone else listen in. A network run by one giant company can make that company very powerful. And clever people can find ways to trick the system for their own benefit. The telephone, it turned out, also created brand-new problems — and some of them are still ringing today."]}],"deepDive":"Historians of technology like to ask a deceptively simple question: who decides what an invention is for? The telephone's makers originally imagined it mostly as a business tool. Early Bell System advertising stressed efficiency, and some managers were even uneasy about 'frivolous' social chatter clogging the lines. Sociologist Claude Fischer, in his book America Calling, showed that ordinary users, especially women and rural families, pushed the telephone toward sociability: visiting, gossip, keeping families together. Companies eventually followed, and by the 1920s and 1930s their adverts encouraged people to call friends and relatives. Rural telephony is a striking case. After Bell's basic patents expired in 1893–1894, thousands of independent and farmer-owned companies spread service into the countryside, and for a time the Bell System faced real competition. Many independents later connected to, or were absorbed by, the Bell network after AT&T agreed in 1913 to let them interconnect. Emergency numbers show how engineering details shape policy. Britain picked 999 partly because of how its step-by-step switches counted dialling pulses; 111 was rejected because swinging overhead wires could create accidental pulses. In the US, 911 was chosen because it did not clash with any area code or exchange prefix. Rolling it out took decades because emergency answering is run by local governments, not one national agency: only about 26 percent of Americans could dial 911 in 1979, roughly half by 1987. The 2024 study by James Feigenbaum and Daniel Gross on operator automation is a good example of modern economic history. Using census records, it found that incumbent operators suffered lasting losses, but later generations of young women were not shut out of work, because growing clerical and service jobs absorbed them. Finally, TTY history shows how disabled people often drive their own technology. Weitbrecht's acoustic coupler sidestepped AT&T's restrictions on attached equipment by using sound, and deaf volunteers built the early network themselves from cast-off machines. National relay services followed under the Americans with Disabilities Act of 1990.","funFact":"Britain rejected 111 as its emergency number partly because overhead telephone wires swinging together in the wind could accidentally 'dial' 1-1-1.","check":{"q":"Where was the first 911 call in the United States made, in February 1968?","a":"Haleyville, Alabama","wrong":["Huntington, Indiana","New York City","Boston, Massachusetts"]},"sources":[{"title":"The 999 service is 80 years old today","publisher":"BT (press release)","url":"https://www.mynewsdesk.com/uk/bt/pressreleases/the-999-service-is-80-years-old-today-2042177"},{"title":"Emergency telephone number","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Emergency_telephone_number"},{"title":"History Blotter: First 9-1-1 call is placed on Feb. 16, 1968","publisher":"National Law Enforcement Officers Memorial Fund","url":"https://nleomf.org/history-blotter-first-9-1-1-call-is-placed-on-feb-16-1968/"},{"title":"9-1-1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/9-1-1"},{"title":"Development of the TTY – Part I","publisher":"Hearing Health Matters","url":"https://hearinghealthmatters.org/hearing-international/2016/tty/"},{"title":"Robert Weitbrecht","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Weitbrecht"},{"title":"Switchboard operator","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Switchboard_operator"},{"title":"Barbed wire","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Barbed_wire"}],"photos":[{"src":"img/deep/telephone/15-1.jpg","alt":"Women operators with headsets at a Bell System international switchboard, with jacks labelled London, Paris and more.","file":"Photograph of Women Working at a Bell System Telephone Switchboard (3660047829).jpg","url":"https://commons.wikimedia.org/wiki/File:Photograph_of_Women_Working_at_a_Bell_System_Telephone_Switchboard_(3660047829).jpg","author":"The U.S. National Archives","license":"No restrictions"},{"src":"img/deep/telephone/15-2.jpg","alt":"An AT&T TDD 2700 text telephone for deaf people; a phone handset rests in the two rubber cups on top.","file":"Jrb 20080809 att tdd 2700.jpg","url":"https://commons.wikimedia.org/wiki/File:Jrb_20080809_att_tdd_2700.jpg","author":"Jesper Rautell Balle","license":"CC BY-SA 3.0"},{"src":"img/deep/telephone/15-3.jpg","alt":"A classic red K6 telephone box on Great George Street in London, with Big Ben behind it.","file":"Red telephone box on Great George Street and Big Ben.jpg","url":"https://commons.wikimedia.org/wiki/File:Red_telephone_box_on_Great_George_Street_and_Big_Ben.jpg","author":"APK","license":"CC BY 4.0"}],"words":3655},{"n":16,"title":"Problems, Fights and Hard Questions","when":"1880s – today","summary":"For about a hundred years, one giant company ran almost every phone in America, and you could not even buy your own telephone. People listened in on other people's calls, clever tricksters fooled the network with a toy whistle, and even Alexander Graham Bell had ideas that many people today think were badly wrong.","sections":[{"heading":"Ma Bell: One Company, Almost Every Phone","paragraphs":["Imagine if one company owned every phone line, every exchange, every long-distance cable and every single telephone in your country. It decided how much calls cost, which phones you could use and what colour they came in. For most of the twentieth century, that was close to the truth in the United States. The company was the Bell System, led by the American Telephone and Telegraph Company, or AT&T. People nicknamed it 'Ma Bell', as if it were everyone's slightly bossy mother.","The Bell System had several parts that fitted together like pieces of a machine. AT&T ran the long-distance network. Local 'Bell operating companies', such as New York Telephone or Pacific Telephone, ran service in different regions. Western Electric manufactured the telephones, switches and cables. And Bell Telephone Laboratories, or Bell Labs, did research, inventing things like the transistor. Not every American phone belonged to Bell — there were still independent companies, especially in small towns — but by the middle of the century the Bell System carried the great majority of the country's calls.","A business that controls almost a whole market is called a monopoly. Normally governments try to stop monopolies, because without competition a company can charge high prices or stop improving its products. The telephone was treated differently. Many people believed one unified network worked best, so that any phone could reach any other. In 1913, after the government threatened legal action, AT&T made a deal known as the Kingsbury Commitment: it agreed to give up control of the Western Union telegraph company and to let independent phone companies connect to its long-distance lines. In return, the Bell System was allowed to keep growing as a 'regulated monopoly', with government agencies watching its prices.","One of the strangest rules, by today's standards, was that you did not own your telephone. You rented it from the phone company, month after month, often paying the rent for decades, far more than the phone was worth. Most were heavy black desk phones made by Western Electric. They were built to last for years and were so tough you could drop one on the floor without much harm. If you wanted a different colour, a longer cord or an extra phone upstairs, you asked the phone company, and it usually charged you more.","You were also not allowed to plug your own equipment into the line. AT&T said that 'foreign attachments' — any device not made or approved by the Bell System — might damage the network or cause problems for other callers. There was some truth in the worry: a badly made device really could disturb a line. But the rule also protected AT&T from competition. For years, a company had sold a simple cup called the Hush-A-Phone that fitted onto the mouthpiece so people could talk without being overheard. AT&T objected, and in the 1950s the fight went to court. In 1956 a court decided that harmless attachments like this were allowed, but most electrical devices were still banned.","Was the Bell System good or bad? The honest answer is both. Because one company planned the whole network, American phone service became famous for being reliable: you picked up the receiver and almost always heard a dial tone. Bell Labs produced world-changing science. But a company with no real rivals had little reason to hurry. New ideas could take years to reach customers, and customers had very little choice. That tension — reliability and size on one side, competition and freedom on the other — sits at the heart of the next big fights."]},{"heading":"The Carterfone Case: Opening the Door","paragraphs":["The real crack in the wall came from a Texan named Thomas Carter. Born in 1924 in Mabank, Texas, he loved radio all his life. During the Second World War he ran a radio station in Juneau, Alaska, that broadcast news and entertainment to troops in remote places. After the war, he ran a two-way radio business for customers such as oil drilling crews and ranchers, people who worked far from any telephone.","His customers had a problem. They could talk by radio to a base station, but they could not reach anyone on the ordinary phone network. So Carter invented a device he called the Carterfone. At the base station, the operator dialled a normal phone call, then set the telephone handset into a cradle on the Carterfone. The cradle connected the sound from the handset to the radio. A voice-activated switch flipped the radio between talking and listening, so the person in the oil field and the person on the telephone could take turns speaking. Nothing was wired directly into AT&T's lines.","Starting in 1959, Carter's company assembled Carterfones on wooden tables in a small brick building in Dallas and sold them. AT&T warned customers that anyone using a Carterfone might have their phone service cut off. Frightened customers started sending their devices back. In 1965 Carter sued.","On June 26, 1968, the Federal Communications Commission ruled in Carter's favour. The decision said that customers could connect devices that were not made by Bell to the telephone network, as long as they did not harm it. This became known as the Carterfone decision, and it changed everything. Over the next years, a flood of new products appeared that plugged into ordinary phone lines: answering machines, fax machines, cordless phones, and modems that let computers talk to each other over telephone lines — the same kind of connection that early home internet users would rely on.","Carter himself never made much money from his victory. He died in 1991. But in 2001 he was honoured in the Wireless Hall of Fame, and a Carterfone is on display at the Smithsonian's National Museum of American History. It is a good example of how one stubborn small-business owner can change a giant industry."]},{"heading":"Breaking Up Ma Bell","paragraphs":["Carterfone opened the door for other companies to make telephones and gadgets. Soon others wanted to compete in long-distance calls too. A company called MCI built a microwave radio network between cities and fought with AT&T for the right to connect it to local phone lines. The bigger question was whether the Bell System had become too powerful.","In 1974 the United States Department of Justice sued AT&T under antitrust laws, the laws designed to stop monopolies from crushing competition. The case dragged on for years. Finally, in January 1982, AT&T agreed to a settlement. A federal judge, Harold H. Greene, supervised the details. It was one of the biggest business break-ups in history.","The break-up took effect on January 1, 1984. AT&T kept its long-distance service, its manufacturing arm Western Electric, and much of Bell Labs. But it had to give away its 22 local telephone companies. These were grouped into seven new regional companies, nicknamed the 'Baby Bells': Ameritech, Bell Atlantic, BellSouth, NYNEX, Pacific Telesis, Southwestern Bell and US West. Each one ran local phone service in its own part of the country.","What changed for ordinary people? Long-distance calls became cheaper as companies such as MCI and Sprint competed with AT&T, running adverts to win customers. People could buy their own phones instead of renting them, and shops filled with telephones of every shape: see-through phones, phones shaped like cartoon characters, phones with big buttons and memory for favourite numbers. On the other hand, local phone bills often went up, and many people found the new system confusing, with separate companies and separate bills.","History also has a twist here. Over the following decades, many of the Baby Bells merged back together. In 2005 one of them, by then called SBC Communications (it had grown out of Southwestern Bell), bought AT&T itself and took the famous AT&T name. Another group of former Baby Bells became part of Verizon. Today's phone companies are very different from Ma Bell, but some historians joke that the family got back together."]},{"heading":"Who Else Is on the Line?","paragraphs":["In the early days, a telephone call was never truly private. Every call went through an operator, and the operator could, if she chose, stay on the line and listen. Telephone companies had strict rules forbidding this, and most operators followed them, but people knew it was possible. In a small town where the operator knew everyone, callers sometimes chose their words very carefully.","Party lines were even leakier. Remember that on a party line, every house heard every ring. Picking up the receiver quietly to listen to the neighbours was so common that people had a slang word for it: 'rubbernecking', after the way curious people stretch their necks to stare. You could sometimes hear a click as another person picked up, or the sound of a clock ticking or a baby crying in somebody else's kitchen. Gossip travelled fast. Some families invented private codes or spoke in another language when they wanted to keep something secret.","Operators and party lines were not the only leaks. In the early years, telephone wires hung on poles in the open air, and long lines ran side by side for kilometres. Sometimes the electrical signal from one wire leaked faintly into a neighbouring wire, so callers heard ghostly snatches of other people's conversations in the background. Engineers called this 'crosstalk'. Better cable designs, such as twisting each pair of wires around each other, greatly reduced it, but for decades many people simply assumed that someone, somewhere, might be overhearing them.","Then there was wiretapping, which means secretly connecting to a phone line to listen to calls. It started surprisingly early: police in the United States were already tapping telephone wires in the 1890s. In the 1920s, during Prohibition, when alcohol was illegal in the US, federal agents tapped the phones of a Seattle bootlegger named Roy Olmstead. He argued that this broke the Constitution's protection against unreasonable searches. In 1928, in the case Olmstead v. United States, the Supreme Court disagreed: it said listening to wires outside someone's home was not a 'search'.","That decision lasted almost forty years. In 1967, in Katz v. United States, the Supreme Court changed its mind. Charles Katz had been recorded making calls from a public phone booth. The court decided that the Constitution protects people, not just places, and that people using a phone have a reasonable expectation of privacy. Police would need a warrant — permission from a judge — before listening. In 1968 Congress passed a law setting out the rules for when and how wiretaps could be approved in criminal investigations.","These questions have never gone away. Today, arguments continue around the world about when governments should be allowed to collect information about phone calls, text messages and internet data, and how to balance catching criminals with protecting everyone's privacy. The technology is very different from a curious neighbour on a party line, but the basic question — who is allowed to listen? — is exactly the same."]},{"heading":"Phone Phreaks and the 2600-Hertz Whistle","paragraphs":["To understand one of the most famous tricks in telephone history, you need to know how the old long-distance network talked to itself. When long-distance lines were idle and ready for a call, the switching machines signalled this using a musical tone at exactly 2,600 hertz, which means 2,600 vibrations per second. That is a high, piercing note, like a whistle. Other combinations of tones were used to send the digits of the number being called from one exchange to the next. The important thing is that these control tones travelled down the same line as people's voices. Engineers call this 'in-band signalling'.","That design had a hidden weakness. If the network listened for tones on the same channel as voices, then anybody who could make the right tone could talk to the machines. Around 1957, a blind seven-year-old boy named Joe Engressia, who had perfect pitch, discovered that whistling a particular note into the phone could make the network react. He had found the 2,600-hertz tone with his own voice.","Later, people discovered that a small plastic toy whistle given away in boxes of Cap'n Crunch breakfast cereal happened to produce almost exactly 2,600 hertz. A man named John Draper became so famous for using it that he took the nickname 'Captain Crunch'. People who explored and tricked the phone network like this were called 'phone phreaks', a mix of 'phone' and 'freak'. Some built electronic gadgets called 'blue boxes' that could produce all the control tones, letting them route calls around the world.","Ironically, part of what made this possible was information the Bell System had published itself. Its own technical journal printed articles explaining the signalling tones, intended for engineers. In October 1971, a magazine article by Ron Rosenbaum called 'Secrets of the Little Blue Box' told the world about phreaks. Two young friends in California read it: Steve Wozniak and Steve Jobs. They built and sold blue boxes for a while before going on to start a company called Apple.","Many phreaks said they were just curious explorers who loved understanding a giant, hidden machine. But using a blue box to make free long-distance calls was a crime: it was a way of stealing service that other people paid for, called toll fraud. Several phreaks, including Draper, were arrested and convicted. The phone companies also fixed the weakness. During the 1970s and 1980s, they moved the control signals onto a separate data network, away from the voice channel. This 'out-of-band' system, known as Signalling System No. 7, meant whistles and blue boxes no longer worked. The age of the phone phreak faded, but its spirit of curiosity fed into early computer hacking culture."]},{"heading":"Today's Troubles: Scams, Screens and Old Phones","paragraphs":["Some telephone problems are very modern. If your family has a phone, you have probably heard it ring with a call nobody wanted: a recorded voice offering a prize, warning about a fake problem with a bank account, or pretending to be from the government. Automated calls like these are called robocalls. Scammers use computers to dial thousands of numbers cheaply over the internet, and they often fake the caller ID, the number shown on your screen, to look like a local or trusted number. This trick is called spoofing.","Governments have fought back. In the United States, the Telephone Consumer Protection Act of 1991 set rules for automated calls, and the National Do Not Call Registry, launched in 2003, lets people sign up to block sales calls. Because scammers simply ignore the rules, the US government later pushed phone companies to adopt a system called STIR/SHAKEN, which digitally checks whether a call really comes from the number it claims. The best protection is still simple: never give personal information, passwords or payment details to someone who calls you unexpectedly — hang up and check with a trusted adult or the real organisation.","Robocalls are not a small nuisance. In the United States, the government's communications agency has received hundreds of thousands of complaints a year about unwanted calls. Some scams target older people with frightening stories, such as a grandchild supposedly in trouble who needs money right away. Newer scams can even use computer-generated voices that sound like real people, which is why it is wise for families to agree on a simple rule: if a call asks for money or secrets in a hurry, stop and check first.","Phones have also made roads more dangerous. Talking on a phone while driving is linked to roughly four times the risk of a serious crash, and texting while driving to an even bigger risk. Studies have found that using a hands-free phone is not much safer, because the danger comes from the brain being busy with the conversation, not just from the hands holding the phone. That is why many countries ban holding a phone while driving; the UK did so in 2003, for example. In the US in 2009, distracted drivers were involved in crashes that killed more than 5,000 people.","Finally there is the question of what happens to old phones. Every phone, from an old dial telephone to a modern smartphone, contains metals and plastics, and some contain harmful substances such as lead or mercury. Broken and unwanted electronics are called e-waste. According to the World Health Organization, the world produced about 62 million tonnes of e-waste in 2022, and only about 22 percent of it was documented as properly collected and recycled. Much of the rest is dumped or taken apart by hand in unsafe conditions, sometimes by children, which can harm people's health. Recycling old phones properly, and keeping phones longer, are small ways everyone can help."]},{"heading":"A Hard Look at Bell Himself","paragraphs":["It might feel strange to end a part about problems by looking at Alexander Graham Bell. He is the hero of much of this story: a brilliant teacher, a devoted husband to Mabel, a man who cared deeply about deaf people. All of that is true. But historians try to look at whole people, not just the shiny parts. And many Deaf people today have very mixed feelings about Bell.","To understand why, you need to know about a long argument in deaf education. One side believed deaf children should be taught mainly in sign language, a full language made with the hands, face and body. The other side, called 'oralism', believed deaf children should be taught to speak out loud and to lip-read, and that sign language should be discouraged or even banned in schools. Bell was one of the most famous supporters of oralism. He hoped it would help deaf people fit into the hearing world. He gave large amounts of money to promote the teaching of speech, and the organisation he founded is known today as the Alexander Graham Bell Association for the Deaf and Hard of Hearing.","Oralism became very powerful. In 1880 an international meeting of educators of the deaf, held in Milan, Italy, and attended mostly by hearing people, voted in favour of teaching by speech instead of signs. In the following decades, many schools around the world banned sign language. Deaf children were sometimes punished for signing, and many Deaf teachers lost their jobs. Many deaf students struggled to learn spoken language well enough to follow lessons, and their education suffered. Sign language survived anyway, passed secretly between students and kept alive in Deaf clubs and communities. From the 1960s, the work of researchers such as William Stokoe showed that American Sign Language is a complete language with its own grammar, and sign language slowly returned to classrooms. Many Deaf people see oralism as one of the darkest chapters in their history, and Bell as one of its leaders.","There is a second difficult subject: eugenics. Eugenics was a set of ideas, popular in the late 1800s and early 1900s, that claimed human society could be 'improved' by controlling who had children. These ideas are now rejected as scientifically wrong and deeply unfair, and in many countries they were used to justify terrible harm, including forcing people to be sterilised so they could not have children. In 1883 Bell gave a paper called 'Memoir upon the Formation of a Deaf Variety of the Human Race', in which he worried that deaf people marrying each other would lead to more deaf children. Later he chaired a scientific board for the Eugenics Record Office, a major American eugenics organisation, and in 1921 he was made honorary president of an international eugenics conference.","Historians point out important details here too. Bell wrote that society could not dictate whom people should marry, he opposed laws banning deaf people from marrying, and he never called for sterilisation. But his fame lent respectability to a movement that did cause great harm. As many historians have argued, Bell's legacy is complicated: he did real good for many deaf people, and he also helped spread ideas that hurt others. Learning about both sides does not mean we stop admiring the telephone. It means remembering that brilliant inventors are human beings who can be wrong, and that the people most affected by an idea deserve a voice in judging it."]},{"heading":"Still Tied to the Wall","paragraphs":["By the 1970s, the telephone had survived monopolies, court battles, eavesdroppers and whistling tricksters. It had become cheaper, more open to new inventions and more available than ever. Yet for all its success, one big limit had never really been solved. Almost every telephone was still stuck to the wall by a wire. If you wanted to make a call, you had to go to where the phone was. Some engineers had been working for decades on a different dream: a phone that could leave the house and come with you."]}],"deepDive":"The Bell System monopoly is a classic case study in economics. Telephone networks have strong 'network effects': each new subscriber makes the network more valuable to everyone else. AT&T president Theodore Vail used this to argue for 'one system, one policy, universal service', and the 1913 Kingsbury Commitment created a regulated monopoly rather than open competition. Critics later argued that the arrangement slowed innovation in customer equipment. The 'foreign attachments' rule shows the tension clearly: AT&T claimed network protection, while the Hush-A-Phone ruling (1956) and the Carterfone decision (1968) pushed toward the principle that any device that did no harm could connect. The FCC later created a registration program so certified equipment could plug straight into standard jacks, which helped make modems, fax machines and answering machines common. Economists still debate the 1984 divestiture. Long-distance prices fell substantially and competition grew, but local rates rose, and the later re-merging of Baby Bells into a few giants (AT&T and Verizon) shows how strong the pull toward concentration remains. Phreaking illustrates a key principle in security engineering: never send control signals on the same channel that users can access. In-band signalling at 2,600 Hz and multifrequency digit tones let anyone who could reproduce the tones command the switches. Moving signalling out of band — first with Common Channel Interoffice Signalling and then Signalling System No. 7 — closed that hole, though researchers have since found different weaknesses in SS7 itself. On wiretapping, Olmstead (1928) treated privacy as tied to physical trespass, while Katz (1967) shifted to a 'reasonable expectation of privacy', a test still argued over in cases about phone records and mobile location data. Bell's legacy is debated in Deaf studies. Some historians stress that Bell explicitly opposed marriage restrictions and never advocated sterilisation; others, including Deaf scholars, argue that his research, prestige and campaigning against sign language did lasting harm to Deaf communities. Both points can be true at once.","funFact":"A toy whistle given away in Cap'n Crunch cereal boxes could produce a tone of almost exactly 2,600 hertz, close enough to control parts of America's long-distance telephone network.","check":{"q":"What did the 1968 Carterfone decision allow?","a":"Connecting non-Bell devices to the phone network if they caused no harm","wrong":["Breaking AT&T into seven Baby Bells","Creating the 911 emergency number","Banning phone use while driving"]},"sources":[{"title":"Thomas Carter","publisher":"Wireless History Foundation","url":"https://wirelesshistoryfoundation.org/thomas-carter/"},{"title":"Carterfone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Carterfone"},{"title":"Breakup of the Bell System","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Breakup_of_the_Bell_System"},{"title":"Telephone tapping","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Telephone_tapping"},{"title":"Phreaking","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Phreaking"},{"title":"Electronic waste (e-waste) fact sheet","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/electronic-waste-(e-waste)"},{"title":"Oralism and the Deaf Community","publisher":"Lifeprint (ASL University)","url":"https://www.lifeprint.com/asl101/topics/oralism-and-the-deaf-community.htm"},{"title":"Alexander Graham Bell","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alexander_Graham_Bell"}],"photos":[{"src":"img/deep/telephone/16-1.jpg","alt":"A phone-hacking \"blue box\" keypad with its little speaker, on display at the Powerhouse Museum in Sydney.","file":"Blue Box at the Powerhouse Museum.jpg","url":"https://commons.wikimedia.org/wiki/File:Blue_Box_at_the_Powerhouse_Museum.jpg","author":"Maksym Kozlenko","license":"CC BY-SA 4.0"},{"src":"img/deep/telephone/16-2.jpg","alt":"A black Western Electric Model 500 rotary-dial desk telephone from 1951, the classic Bell System phone.","file":"Model500Telephone1951.jpg","url":"https://commons.wikimedia.org/wiki/File:Model500Telephone1951.jpg","author":"ProhibitOnions","license":"Public domain"},{"src":"img/deep/telephone/16-3.jpg","alt":"The original 1959 Carterfone cradle, which linked a phone handset to a two-way radio, at the Computer History Museum.","file":"Carterfone cradle at CHM.agr.png","url":"https://commons.wikimedia.org/wiki/File:Carterfone_cradle_at_CHM.agr.png","author":"ArnoldReinhold","license":"CC BY-SA 3.0"}],"words":3733},{"n":17,"title":"Phones That Leave the House","when":"1946 – 1983","summary":"For 70 years every telephone was tied to a wall by a wire. Then engineers put phones in cars, came up with a clever honeycomb of 'cells', and in 1973 a man walked down a New York street talking into a phone the size of a brick. Ten years later, anyone with a few thousand dollars could buy one!","sections":[{"heading":"A Phone Call from a Car: St. Louis, 1946","paragraphs":["Picture a warm summer day in St. Louis, Missouri, on June 17, 1946. World War II has been over for less than a year. A man sits in a parked car, reaches under the dashboard and lifts out a telephone handset, curly cord and all. There is no wire running from the car to any wall. He makes a call, and on the other end an ordinary telephone rings. It sounds like nothing special to us, but at that moment it was something new: a regular telephone service you could use from a moving vehicle.","The service was called Mobile Telephone Service, or MTS. It was opened by Southwestern Bell, one of the local companies that made up the giant Bell System run by AT&T. Engineers at Bell Labs and the factory company Western Electric had spent years getting it ready. It was not the first time anyone had used a radio to talk from a car. Police departments had been using two-way car radios since the 1930s. What made MTS different was that it connected a car to the whole telephone network, so a driver could call any home or office with a phone.","The way it worked was very different from a phone in your pocket today. The car carried a two-way radio: a transmitter to send your voice out as radio waves and a receiver to pick up the other person's voice. Somewhere high above the city, on a tall building or tower, stood one powerful antenna that served the whole metropolitan area. Your car's radio talked to that antenna, the antenna was wired into a telephone exchange, and a human mobile operator connected your call to the ordinary wired network, just like the switchboard operators you met in Part 11.","The equipment was enormous. A complete car phone set weighed about 36 kilograms (80 pounds), heavier than many ten-year-olds. Most of it was a box of radio gear, full of glowing vacuum tubes, that lived in the car's trunk. Only the handset and a small control unit sat up front with the driver. The tubes used so much electricity that leaving the phone switched on for a long time with the engine off could drain the car's battery.","Talking was a little like using a walkie-talkie. Early sets had a push-to-talk button: you pressed it to speak and let go to listen, because the system could not easily send and receive at the same moment. To call out, you picked up the handset and asked the mobile operator for the number you wanted. To call a car, a person on an ordinary phone asked the operator, who sent out a radio call to that vehicle.","The very first customers are said to have included the Monsanto Chemical Company and a local building contractor, who could now reach his work crews and office while driving around the city. The price was steep: according to accounts of the time, about 15 dollars a month plus 30 to 40 cents or so for each local call, at a time when a whole family's monthly phone bill at home was usually only a few dollars. Even so, the idea spread fast. By the end of 1946, AT&T had opened similar services in about 25 American cities, and by 1948 mobile service reached around 100 towns and stretches of highway.","Who wanted a car phone? Doctors who needed to be reached in an emergency, delivery companies, utility crews fixing power lines, newspaper reporters chasing stories, and a few wealthy people who liked having the newest gadget. Notice one important thing, though. These were radio telephones, or car phones, not cell phones. That is why historians are careful about the famous 1973 call you will read about later in this part: it was not the first mobile phone call ever, but the first public call on a handheld cellular phone."]},{"heading":"Three Channels for a Whole City","paragraphs":["To understand the biggest problem with car phones, you need to know a little about radio. Radio waves are invisible waves of energy that travel at the speed of light. Each radio signal has a frequency, which is how many waves pass a point every second, measured in hertz. MTS used frequencies around 150 megahertz, which means about 150 million waves every second. Your car radio, a TV station, a police radio and an airplane's radio all use different frequencies so they do not get mixed up.","A radio channel is a narrow slice of those frequencies, set aside for one conversation. You can think of channels as lanes on a highway or as the numbered channels on a pair of walkie-talkies. If two people try to use the same channel in the same place at the same time, their voices crash into each other and nobody can understand anything. So every phone call needed its own channel for as long as the call lasted.","MTS in St. Louis started with six channels, but the signals on neighboring channels leaked into each other, causing a messy kind of interference called crosstalk. Bell's engineers ended up using only three. Think about what that means: in an entire city, only three car phone conversations could happen at once. If a fourth customer picked up the handset, he simply had to wait until a channel was free. Imagine a city of hundreds of thousands of people sharing three phone lines!","Privacy was another problem. Every call was broadcast through the air, so anyone with the right kind of radio receiver could listen in. In a way, the car phone was like the old party lines from Part 11, except the 'party' could include anyone in the city with a scanner.","Why not just add more channels? Because the radio spectrum, the whole range of usable radio frequencies, is limited, and lots of other users need it too: radio and TV stations, police and fire services, the military, ships and aircraft, taxi companies and more. In the United States, a government agency called the Federal Communications Commission (FCC) decides who gets which frequencies. For decades it gave mobile telephones only a small slice.","So mobile phones stayed rare. In the late 1940s there were only about 5,000 customers across the country, making roughly 30,000 calls a week. In the mid-1960s the Bell companies introduced Improved Mobile Telephone Service (IMTS), starting in Harrisburg, Pennsylvania, in 1964. It was a real upgrade: you could dial numbers yourself without an operator, the phone hunted automatically for a free channel, and you could talk and listen at the same time like a normal phone. But IMTS still used one big transmitter for a whole city. In big cities, large numbers of customers still had to share only a handful of channels, so the 'all channels busy' problem was common. Many people who wanted a car phone sat on waiting lists, sometimes for years.","Engineers could see the trap clearly. With one giant tower per city, more customers just meant more waiting. To give mobile phones to millions of people, they would need a completely different idea."]},{"heading":"A Honeycomb over the City","paragraphs":["That different idea had actually been written down years earlier. In December 1947, two engineers at Bell Labs, Douglas H. Ring and W. Rae Young, described a new plan in an internal company memo. Instead of one powerful transmitter shouting across a whole city, why not cover the city with many small, low-power transmitters? Each one would serve only a small area, called a cell. A phone in a car would talk to whichever cell's antenna was closest.","On maps, engineers drew cells as hexagons, the six-sided shape of a honeycomb. Real radio coverage is not a perfect hexagon, of course; it is shaped by hills, buildings and weather. But hexagons fit together with no gaps and no overlaps, and they are close to the shape of a circle, so they make a handy way to plan a network on paper.","Here is the clever part, called frequency reuse. Because each cell's transmitter is weak, its signal fades out after a few kilometres. That means two cells that are far enough apart can use exactly the same channel at the same time without bothering each other. Imagine a huge school hall. If one person shouts, nobody else can be heard. But if small groups sit in far-apart corners and speak quietly, many groups can talk at once, and two groups can even be saying the same words without any confusion.","In practice, engineers split the available channels into groups and gave each cell in a small cluster a different group, often seven cells per cluster. Then the pattern repeated across the city like tiles on a floor. If a city had 50 cells, each channel could be used about seven times at once instead of just once. And here is the best part: when a city got too busy, the company could split crowded cells into smaller ones and add more towers. Smaller cells meant even more reuse and room for even more callers.","So why did nobody build it in 1947? There were two big obstacles. The first was the problem of movement. If you are driving while talking, you will leave one cell and enter the next. The network must notice, pick a free channel in the new cell, and switch your call over in a fraction of a second, without you hearing a break. In 1947 there were no small, fast computers to do that kind of quick decision-making. In fact, the transistor, the tiny electronic switch that eventually made such computers possible, was first demonstrated at Bell Labs only a couple of weeks after the cellular memo was written.","The second obstacle was the radio spectrum. A cellular network needed a large block of frequencies, and the FCC was not ready to hand one over. Arguments about who should get which frequencies, and whether one company should control mobile phones, went on for many years.","Meanwhile Bell Labs kept working. In the late 1960s and 1970s, engineers including Richard Frenkiel and Joel Engel worked out how a full cellular system could actually function, with the towers, switching centres and computer control it would need. Another Bell Labs engineer, Amos Joel, patented a switching system (issued in 1972) for passing calls between cell sites as a vehicle moved. The FCC eventually set aside frequencies around 800 megahertz for cellular service, and Bell's design became known as AMPS, the Advanced Mobile Phone System. In 1978 a test system began running in the Chicago area. Bell Labs was thinking mostly about phones built into cars. But a company in Illinois had a different dream."]},{"heading":"Hello, Joel, It's Marty","paragraphs":["Motorola, based near Chicago, already knew a lot about portable radios. It made two-way radios for police officers, walkie-talkies, and pagers, the little beeping boxes that told doctors to call the hospital. One of its engineers was Martin Cooper, born in Chicago in 1928 to Ukrainian Jewish immigrant parents. Cooper studied engineering at the Illinois Institute of Technology, served as an officer on a submarine during the Korean War, and joined Motorola in 1954. By the early 1970s he was leading the company's work on portable communication.","Cooper and his team had a strong opinion. AT&T's plans focused on car phones, but Cooper liked to argue that people, not places or cars, should have phone numbers. A phone, he believed, should go wherever you go: into a shop, down the street, into a park. If AT&T won the right to run cellular service built only around car phones, Motorola, which made portable radios, could lose out. So Motorola decided to show the world, and the government officials in Washington, that a truly handheld cellular phone was possible.","The prototype they built was called the DynaTAC, short for Dynamic Adaptive Total Area Coverage. It was about 25 centimetres (10 inches) tall, not counting its antenna, and weighed about 1.1 kilograms (2.5 pounds), with much of that weight in the battery. People nicknamed it 'the brick' or 'the shoe'. The battery gave about 30 minutes of talk time and then needed around 10 hours to recharge. Cooper later joked that the short battery life did not matter much, because the phone was too heavy to hold up to your ear for longer than that anyway.","On April 3, 1973, Cooper stood on Sixth Avenue in midtown Manhattan, near the New York Hilton hotel, shortly before a press conference to show off the new phone. Motorola had put a base station, the radio equipment a cell phone talks to, on the roof of a nearby skyscraper called Burlington House, and connected it into the ordinary landline telephone network. Cooper took out the prototype, punched in a number, and made the first public call on a handheld cellular phone.","Whom did he call? His rival. On the other end was Joel Engel, the head of the cellular project at Bell Labs. As Cooper remembers it, he said something like, 'Joel, this is Marty. I'm calling you from a cell phone, a real handheld portable cell phone.' Cooper recalls there was silence on the line. Engel has said he does not remember the call at all, which is a funny reminder that historic moments do not always feel historic to everyone involved. People walking past on the busy New York sidewalk stared at the man talking into a big plastic block with no wire.","It is important to be precise about what this call was. It was not the first mobile phone call; car phones had been working since 1946. It was not on a commercial network that ordinary people could join; it was a demonstration. What made it historic was that it was the first public call made from a handheld phone on a cellular-style system, a phone you could carry in your hand while walking around.","Motorola hoped handheld phones would be in shops within a few years. Instead it took a whole decade. The company had to make the phone smaller and more reliable, wait for the FCC to make decisions about frequencies, and wait for someone to build actual cellular networks. Inside Motorola, prototypes kept being improved from 1973 all the way to 1983."]},{"heading":"An Actress, a Composer and a Secret Radio Idea","paragraphs":["Long before Martin Cooper's call, a very different inventor had been thinking about radio. Hedy Lamarr was born Hedwig Kiesler in Vienna, Austria, in 1914 and became a famous Hollywood film star. She was also deeply curious about how things worked and loved tinkering with ideas.","During World War II, Lamarr wanted to help the Allies. She had learned, through her first husband's work with weapons makers, that navies wanted a way to guide torpedoes by radio. The trouble was jamming: an enemy could blast noise on the same radio frequency and block the control signal, sending the torpedo off course.","Lamarr teamed up with her friend George Antheil, an American composer. Together they came up with a plan called frequency hopping. Instead of using one frequency, the transmitter and the receiver would jump from frequency to frequency many times, following the same secret pattern. An enemy who did not know the pattern could not follow the signal and would have great trouble jamming it. To keep the transmitter and receiver in step, they borrowed an idea from Antheil's music: he had once tried to synchronize several player pianos, which are pianos that play automatically from punched paper rolls. Their design described hopping among 88 frequencies, the same number as the keys on a piano.","They received US Patent 2,292,387, titled 'Secret Communication System', on August 11, 1942. It was issued under Lamarr's married name at the time, Hedy Kiesler Markey. The US Navy did not use it during the war; it reportedly considered the system too bulky to fit inside a torpedo. Years later, after the patent had expired, similar frequency-hopping techniques began appearing in military communication systems in the early 1960s.","Lamarr's work was not widely recognized until late in her life. In 1997 she and Antheil received a Pioneer Award from the Electronic Frontier Foundation, and in 2014 Lamarr was added to the National Inventors Hall of Fame.","You may hear people say that Hedy Lamarr invented Wi-Fi, Bluetooth or the cell phone. That is not true. The idea of frequency hopping had been explored by others before her, and modern wireless systems were built by thousands of engineers using many different methods. What is fair to say is that the Lamarr and Antheil patent was one early, inventive ancestor of the 'spread spectrum' radio techniques used later. Bluetooth, for example, hops between frequencies, and some later cell phone systems also spread signals across wide bands. Her story is a great reminder that good ideas can come from unexpected people."]},{"heading":"Tokyo and the Nordic Countries Go First","paragraphs":["Here is a surprise: even though the cellular idea was born at Bell Labs in New Jersey, the first commercial cellular networks opened outside the United States.","In 1979, Japan's national telephone company, Nippon Telegraph and Telephone (NTT), launched the world's first commercial cellular network in Tokyo. It was an analog system, meaning voices were sent as smoothly changing radio waves, a copy of the shape of the sound, just like in the older wired telephones. At first it served car phones. Over the next few years NTT spread the network across the country, making Japan the first nation with a full-scale cellular system.","In northern Europe, the telephone authorities of Sweden, Norway, Denmark and Finland had been planning together since the late 1960s. Their system was called NMT, short for Nordic Mobile Telephone. Interestingly, the Swedish company Ericsson opened the very first NMT network not in Scandinavia but in Saudi Arabia, on September 1, 1981, as a pilot with about 1,200 users. A month later, in October 1981, NMT opened in Sweden, then in Norway in November. Denmark and Finland followed in 1982.","NMT had some features that were remarkable for the time. Calls were handed over automatically from one cell to the next as you travelled. Because all four countries used the same system, you could take your phone across the border and keep using it, an early form of what we now call roaming. The NMT rules were also open, so many different companies could build phones for it. Ericsson and Mobira, a Finnish company that became part of Nokia, both made NMT phones, and the competition helped bring prices down.","The first version, NMT-450, used frequencies around 450 megahertz. Lower frequencies travel farther, which suited countries with long distances, forests, mountains, fjords and scattered villages. A single NMT cell could cover anything from about 2 kilometres to 30 kilometres. By 1985 about 110,000 people in the Nordic countries were using NMT, which made it the world's largest mobile network at the time.","Most early NMT phones were still car phones or heavy 'portable' units carried like a small suitcase. But the Nordic countries built a habit of using mobile phones that would later help Finnish and Swedish companies become world leaders. NMT kept running for decades in some places. Finland switched its NMT network off at the end of 2002 and Sweden at the end of 2007, and the very last NMT-450 base station in Russia was switched off in 2017."]},{"heading":"The Brick Goes on Sale","paragraphs":["In the United States, the long arguments about frequencies and licences finally ended in the early 1980s. The FCC decided that each city would have two cellular companies, so customers would have some choice. On October 13, 1983, commercial AMPS cellular service opened in Chicago, run by Ameritech Mobile Communications. News reports from the time say that at the opening ceremony at Soldier Field, an Ameritech executive placed a call to a grandson of Alexander Graham Bell, a nice link back to where the whole story began.","AMPS, the Advanced Mobile Phone System, used frequencies in the 800 megahertz range, divided into channels each 30 kilohertz wide. Each of a city's two cellular companies started with 666 channels, increased to 832 in 1989. Compare that with the three channels of 1946 St. Louis! And because of frequency reuse, every one of those channels could be used again and again in different cells across the city.","Now ordinary customers could finally buy a handheld cellular phone. The FCC approved Motorola's DynaTAC 8000X on September 21, 1983. It went on sale for 3,995 dollars, which is well over 10,000 dollars in today's money. It was about 25 centimetres tall, offered around 30 minutes of talk time, and needed about 10 hours on its charger. Its small glowing red LED display showed the numbers you dialled, and it could remember 30 phone numbers. Motorola had spent about ten years developing it.","Despite the price, people put their names on waiting lists to get one. Owning a brick phone became a status symbol for business people, stockbrokers and estate agents. Yet most early cellular customers actually chose car phones, which were cheaper, had stronger transmitters and could run from the car's battery. Calls were also expensive, often costing much more per minute than calls from home.","First-generation, or 1G, cellular networks such as AMPS, NMT and NTT's system were all analog, and that brought problems. Calls could be noisy and full of static. Anyone with a radio scanner could tune in and listen to private conversations. Criminals learned to copy the identification numbers broadcast by phones, a trick called cloning, so they could make calls charged to someone else's account. In the 1990s cloning cost American phone companies millions of dollars. Different countries also used different systems, so a phone from one country often would not work in another.","Still, a giant step had been taken. In less than 40 years, phones had gone from a 36-kilogram box in a car trunk to a 1-kilogram brick you could hold in one hand. And the brick was about to start shrinking fast. Through the rest of the 1980s, phones got smaller, lighter and cheaper. Soon engineers would turn voices into digital numbers, and phones would learn a brand-new trick: sending short typed messages, not just voices."]}],"deepDive":"Why did the cellular idea need 36 years to go from a memo to a shop counter? Engineers usually point to capacity math, while historians point to regulation. Start with the math. In an old MTS-style system, a city's capacity equals the number of channels, because each channel can carry only one call across the whole area. In a cellular system, capacity is roughly the number of channels multiplied by the number of times each channel can be reused. If channels are split among clusters of N cells, each channel is reused about once per cluster, so a city with C cells has around C divided by N times the capacity of a single-tower system. Shrink the cells and C rises, so capacity rises too, at the price of more towers and more handoffs. Martin Cooper later summed up the long-term trend as 'Cooper's law': the number of conversations that the usable radio spectrum can carry in a given area has doubled roughly every 30 months since the early days of radio, and most of that gain came from smaller cells and smarter reuse rather than from new spectrum. The engineering challenge was handoff. A network needs to measure signal strength continually, choose a new cell and channel, and retune the phone, which demanded fast switching computers that did not exist in 1947. The regulatory story was just as important. The FCC spent years debating how much spectrum to give mobile telephony, whether AT&T should be allowed to dominate it, and how licences should be divided; it eventually created two licences per market, one usually going to a local telephone company. Motorola's 1973 demonstration was partly aimed at these debates, to show that portable phones, not just car phones, were realistic. Historians also debate 'firsts'. Ring and Young described the cellular layout, Bell Labs engineers designed AMPS, Motorola built the first public handheld, NTT ran the first commercial cellular network, and NMT offered early cross-border roaming. Each is a genuine first of a different kind. Hedy Lamarr's patent belongs to a separate line of thinking about secure, jam-resistant radio, which later fed into spread-spectrum methods; it did not create cellular networks.","funFact":"Douglas Ring's memo describing a cellular phone network was written in December 1947, the same month that Bell Labs first demonstrated the transistor, the tiny part that would eventually make handheld cell phones possible.","check":{"q":"Whom did Martin Cooper call on April 3, 1973, during the first public handheld cellular phone call?","a":"Joel Engel, his rival at Bell Labs","wrong":["Alexander Graham Bell's grandson","The President of the United States","His mother in Chicago"]},"sources":[{"title":"History of mobile phones","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_mobile_phones"},{"title":"First networks","publisher":"Ericsson","url":"https://www.ericsson.com/en/about-us/history/changing-the-world/small-steps-great-advances/first-networks"},{"title":"Martin Cooper (inventor)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Martin_Cooper_(inventor)"},{"title":"Motorola DynaTAC","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Motorola_DynaTAC"},{"title":"Hedy Lamarr","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hedy_Lamarr"},{"title":"Nordic Mobile Telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nordic_Mobile_Telephone"},{"title":"Advanced Mobile Phone System","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Advanced_Mobile_Phone_System"},{"title":"Cellular network","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cellular_network"}],"photos":[{"src":"img/deep/telephone/17-1.jpg","alt":"Martin Cooper, who made the first handheld cell phone call in 1973, holding his DynaTAC prototype in 2007.","file":"2007Computex e21Forum-MartinCooper.jpg","url":"https://commons.wikimedia.org/wiki/File:2007Computex_e21Forum-MartinCooper.jpg","author":"Rico Shen","license":"CC BY-SA 3.0"},{"src":"img/deep/telephone/17-2.jpg","alt":"A big Motorola DynaTAC \"brick\" phone held next to a modern Samsung smartphone, in front of a wall of old phones.","file":"Motorola DynaTAC and Samsung Galaxy Note Edge.jpg","url":"https://commons.wikimedia.org/wiki/File:Motorola_DynaTAC_and_Samsung_Galaxy_Note_Edge.jpg","author":"Umut Çolak","license":"Public domain"},{"src":"img/deep/telephone/17-3.jpg","alt":"Diagram of hexagon-shaped phone cells: numbered cells in each colored group reuse the same radio frequencies.","file":"Frequency reuse factors.png","url":"https://commons.wikimedia.org/wiki/File:Frequency_reuse_factors.png","author":"Johannes M","license":"CC BY-SA 4.0"}],"words":4034},{"n":18,"title":"Pocket Phones for Everyone","when":"1990s – 2000s","summary":"In the 1990s phones went digital, shrank to fit in a pocket, and learned to send text messages, starting with a simple 'Merry Christmas' in 1992. Cheap, tough phones spread to villages that had never had a telephone line at all. Today there are more mobile phone subscriptions on Earth than people!","sections":[{"heading":"What Really Happens When You Press Call","paragraphs":["Imagine you are standing in a park and you call your grandmother. You tap her name, hold the phone to your ear, and a few seconds later she says hello. It feels like magic, but a lot is happening in those few seconds, and almost all of it happens by radio.","Your phone is really a small two-way radio, like the car phones of 1946 from Part 17, only far smaller and smarter. Somewhere nearby, perhaps on a tall mast, a rooftop or even disguised as a tree or a church tower, there is a base station: a set of antennas and radio equipment that serves one cell of the network. When you press call, your phone sends a short radio message to the strongest base station it can hear, saying, in effect, 'This is me, and I want to reach this number.'","The base station is connected, usually by cable or fiber-optic line and sometimes by a microwave radio link, to a mobile switching centre. That is the modern version of the telephone exchange from Part 11, except that instead of operators with plugs and cords, it is run by powerful computers. The switching centre checks that you are a real customer, works out where your grandmother is, and connects the two of you. If she is on a landline, the call goes out into the ordinary wired telephone network. If she has a mobile phone too, the network finds the cell she is in and rings her phone by radio.","How does the network know where her phone is? Even when nobody is calling, a switched-on phone is quietly busy. Every so often it listens for signals from nearby base stations and tells the network which area it is in. When a call comes in, the network sends out a 'paging' message in that area, a bit like a teacher calling a name in the right classroom instead of shouting through the whole school. Her phone hears its own identity, answers, and starts to ring.","In the digital phones that arrived in the 1990s, the key to all of this is a tiny card called a SIM, short for Subscriber Identity Module. The SIM holds the secret information that proves to the network which customer you are. Because it can slide out of one phone and into another, you can change handsets and keep your number. Today many phones use a built-in electronic SIM instead, but the idea is the same.","All of this, from your tap to her ringtone, normally takes only a few seconds. Your voice then travels by radio for only the first short stretch, from your phone to the nearest mast. After that, it usually rushes along cables and fiber, perhaps even under the ocean like the cables in Part 14, before hopping back onto radio for the last stretch to her phone."]},{"heading":"The Great Hand-Off","paragraphs":["Now imagine you are not standing in the park but riding in a car or a train while you talk. Every few minutes, maybe even every few seconds, you leave one cell and enter another. The first base station's signal grows weaker, and a new one grows stronger. If nothing happened, your call would fade into crackles and drop.","Instead, the network performs a hand-off, also called a handover. While you talk, your phone keeps measuring the strength of signals from the base stations around it and reports back. When a neighbouring cell would give a better connection, the network picks a free channel in that cell, tells your phone to switch, and moves the call over. In good conditions this happens in a fraction of a second, and you do not hear anything at all. Engineers call this a seamless handover. On a long train journey, your call might be handed from cell to cell dozens of times.","Older analog phones often had a tiny gap during the switch. Some later digital systems became even smoother: in a 'soft handoff', the phone briefly connects to two cells at once and lets go of the old one only when the new one is working well. Hand-offs can still fail, though, which is one reason calls drop in tunnels, in lifts or out in the countryside where cells are far apart.","Cells come in many sizes. In crowded city centres, where thousands of people may be making calls in a few blocks, a cell might cover only a few hundred metres, and engineers add 'small cells' in places like shopping centres, stadiums and train stations. Out in farmland, where few people live, one tall mast might cover several kilometres, and in very open country a signal can sometimes be picked up from tens of kilometres away. Lower radio frequencies travel farther, so they are useful for big rural cells, while higher frequencies carry more data but need smaller cells.","Small cells also help your battery. A phone close to its base station does not need to shout. Networks tell each phone to use only as much transmitting power as it needs, so a phone right next to a mast whispers, while a phone at the edge of a cell has to work harder. That is one reason your battery seems to run down faster when the signal is weak.","This whole system of cells, reuse and hand-offs is the idea that Douglas Ring and W. Rae Young sketched in 1947. It took faster computers, tiny chips and decades of engineering to make it work for billions of people at once."]},{"heading":"From Analog to Digital: The GSM Revolution","paragraphs":["By the late 1980s, first-generation (1G) analog phones had three big problems. They were easy to eavesdrop on, since anyone with a scanner could listen. Cloning let criminals make calls charged to other people. And in Europe, almost every country had its own incompatible system: the Nordic countries had NMT, Britain had a system called TACS, West Germany had another, France another. A business traveller crossing Europe might need several different phones.","European telephone authorities decided to build one shared system. Back in the early 1980s, their organization, called CEPT, set up a working group named Groupe Special Mobile, French for 'special mobile group', giving the system its name: GSM. In 1987, 13 European countries signed an agreement in Copenhagen to build GSM networks. Later the letters were given a new, English meaning: Global System for Mobile Communications.","The big change was going digital. Remember that an analog phone sends a smooth copy of the shape of your voice wave. A digital phone measures your voice thousands of times every second and turns each measurement into numbers, ones and zeros. Clever software then squeezes those numbers down, keeping what matters for understanding speech and throwing away the rest. Numbers are easier to protect: they can be scrambled with a secret code, called encryption, so a person with a simple scanner hears only gibberish. Numbers can also be checked and repaired if a few get damaged on the way, so calls sound clearer.","Digital also let networks squeeze more calls into the same radio waves. GSM uses a method called TDMA, time division multiple access. Each radio channel is chopped into eight tiny time slots that repeat over and over. Eight phones take turns, each sending a short burst of its compressed voice in its own slot, so fast that nobody notices the gaps. It is like eight people sharing one bicycle by riding it for a split second each, in a perfect rotation.","The first GSM call is usually dated July 1, 1991, in Finland, when former Prime Minister Harri Holkeri used the new Radiolinja network to call Kaarina Suonio, the deputy mayor of the city of Tampere. Like many 'firsts', this one comes with a footnote: engineers had already made test calls on the network before that public ceremony. Still, Finland became the home of the first commercial GSM network.","GSM spread across Europe and then the world. Because most countries used the same standard, a phone and its SIM card could roam from country to country. In the Americas and parts of Asia, other digital systems competed with GSM, including a US system called D-AMPS and another called CDMA, which spreads each call across a wide band of frequencies. But GSM became the most widely used mobile system on Earth. It passed 2 billion subscribers in 2006 and 3 billion in 2008, and it was used in more than 200 countries and territories."]},{"heading":"Merry Christmas: The First Text Message","paragraphs":["When engineers designed GSM, they added a small extra feature that hardly anyone thought would matter much: the Short Message Service, or SMS. A German engineer named Friedhelm Hillebrand, working with Bernard Ghillebaert from France, helped develop the idea in the mid-1980s. Hillebrand wanted to know how long a message really needed to be. The story goes that he sat at his typewriter writing out sample sentences and questions, and looked at postcards and telex messages. Most said what they needed in fewer than 160 characters. So 160 characters became the limit for a text message.","Why such a short limit? Text messages were designed to squeeze into the signalling channels a phone network already used for its own housekeeping, such as setting up calls. Those channels had room for only 140 bytes of data at a time, and by using a compact 7-bit code for each letter, engineers could fit 160 characters into that space.","On December 3, 1992, a young engineer named Neil Papworth, then 22 years old, was working for a company called Sema Group, which was building a messaging system for the British network Vodafone. He sat at a computer and typed a short message: 'Merry Christmas'. It travelled through the Vodafone network to an Orbitel 901 handset belonging to Richard Jarvis, a Vodafone director, who was at the company's Christmas party. It was the first SMS text message.","Jarvis could not reply, because phones of that time had no way to type and send a message. The first text was sent from a computer, not from a phone. In 1993, the Finnish network Radiolinja offered the first commercial service for sending text messages from person to person, and Nokia's GSM phones of that year were among the first that let ordinary users type and send texts.","Some phones made texting much easier than others. The Nokia 2010, released in January 1994, is often remembered as one of the first phones that made writing a message simple enough for ordinary people. Phone companies also discovered that texts were cheap for them to deliver, because each one used only a tiny amount of the network, so many began offering texting at low prices or bundled into prepaid plans. That turned out to be exactly what young people with small budgets wanted: a text cost less than a call, could be sent quietly in places where talking was not allowed, and could be read later.","Typing on a phone keypad took some skill. Each number key held three or four letters, so to write the letter C you pressed the 2 key three times. Typing 'hello' took a surprising number of presses. Teenagers, especially, became incredibly fast at it. Later, 'predictive text' software guessed which word you meant from a single press of each key, and people invented short spellings like 'gr8' and 'c u l8r' to save time and characters.","Texting started slowly. In 1995 the average GSM customer sent only about 0.4 messages a month. Then it exploded. By the end of 2000 the average was about 35 messages a month per user. On Christmas Day 2006, people in the United Kingdom alone sent more than 205 million texts, and around the world about 6.1 trillion text messages were sent in 2010. Something designed as a minor extra had become one of the most popular ways humans talk to each other."]},{"heading":"Phones Worth Remembering","paragraphs":["In the 1990s and 2000s, mobile phones stopped being bricks and became something you could slip into a jacket pocket. Some models became so famous that people still talk about them today.","The shrinking was dramatic. The brick of 1983 weighed around a kilogram. By the 2G era of the late 1990s, many popular phones weighed only about 100 to 200 grams, roughly the weight of an apple. Digital chips did more work using less power, batteries improved, and screens moved from glowing red numbers to small black-and-white displays that could show names, menus and messages. Phones also stopped needing a long pull-up antenna; designers tucked it inside the case.","In January 1996, Motorola unveiled the StarTAC. It folded in half like a seashell, a design called a clamshell or flip phone, and at about 88 grams (3.1 ounces) in its lightest version it was the smallest and lightest mobile phone of its time. It cost about 1,000 dollars when it came out. It is often called the first flip phone, although the Japanese company NEC had already sold a folding phone a few years earlier. The StarTAC could also buzz silently instead of ringing, using a vibrating alert, which helped make it the first phone many people thought of as fashionable.","The Finnish company Nokia, which had once made rubber boots, paper and cables, became the world's biggest phone maker. Its phones were known for being simple, cheap to run, long-lasting and very tough. The Nokia 3310, released in 2000, became a legend for surviving drops that would smash other phones, and for its battery that could last for days. Nokia phones also made mobile gaming popular with the game Snake, in which you steered a growing line of pixels around the screen without hitting your own tail.","The best-selling of all was the Nokia 1100, announced in August 2003. It was designed especially for people in developing countries. It had a dust-resistant keypad, grippy sides that would not slip in a sweaty hand in hot, humid weather, and a built-in flashlight you could switch on by holding down a key, very handy in places where electricity cuts were common. It was Nokia's cheapest phone at the time. More than 250 million were sold, making it one of the best-selling phones in history. Nokia's one-billionth phone, sold in 2005, is said to have been a Nokia 1100 bought in Nigeria.","Then, in 2004, Motorola brought out the Razr V3, a flip phone made of metal and only about 13 millimetres thick when closed. It started out as an expensive, stylish gadget, but after its price came down it became the most popular phone in the United States for several years. Official reports said more than 110 million were sold, and many publications give a figure of around 130 million, making it the best-selling flip phone of all time.","Just as important as the phones themselves was a new way to pay. Early mobile service usually needed a monthly contract, which often meant a credit check and a bank account. From the mid-1990s, prepaid service spread: you paid in advance, often by buying a scratch card with a secret code at a corner shop or market stall, and topped up your credit whenever you had money. There were no monthly bills and no credit checks, so prepaid phones could be used by teenagers, students, people with small or irregular incomes, and people who had never had a bank account. In many countries, most mobile customers came to use prepaid."]},{"heading":"Skipping the Landline","paragraphs":["Laying copper telephone wires to every home is slow and expensive. Workers have to put up poles or dig trenches, and in thinly populated areas, far-apart villages might each need kilometres of wire. In much of the world, including large parts of Africa and Asia, landline networks had never reached many towns and villages. Some families waited years for a line; many never got one.","Mobile networks changed that. One tower can serve thousands of people in a wide area without a single wire running to their homes. So many communities skipped the landline entirely and went straight from having no telephone to having mobile phones. People who study technology call this 'leapfrogging', like a frog jumping over a step instead of climbing it.","The effects could be huge. A farmer could call a market town to check prices before making a long trip to sell crops. A fisher could find out which harbour was paying most for the day's catch. Families separated by work in distant cities could stay in touch. In Bangladesh, a programme called Village Phone, begun in the late 1990s, helped women in rural villages buy a mobile phone and earn money by renting out calls to their neighbours.","Then phones started carrying money. In March 2007, the Kenyan mobile company Safaricom, working with Vodafone, launched a service called M-Pesa (pesa means 'money' in Swahili). It let people store money on their phone account and send it to someone else with a secure text-message-style transaction protected by a PIN number, without needing a bank. A worker in Nairobi could send money to family in a faraway village in seconds instead of sending cash with a bus driver. By the end of 2011, M-Pesa had about 17 million users in Kenya. A 2016 study in the journal Science estimated it had helped lift about 2 percent of Kenyan households out of poverty, although other researchers have questioned that estimate.","There are still gaps. According to the International Telecommunication Union (ITU), the United Nations agency for communication technology, about 78 percent of people aged 10 and over around the world owned a mobile phone in 2023. In Africa the figure was about 63 percent. Women were about 8 percent less likely than men to own one. So even though mobile phones reached further and faster than any telephone before them, not everyone is connected yet."]},{"heading":"3G, 4G, 5G, and a Handoff to Another Story","paragraphs":["Engineers count mobile phone history in generations, written with a G. The first generation, 1G, was the analog phones of the 1980s, like the brick. The second generation, 2G, brought digital calls and text messages in the 1990s, with GSM leading the way. Each new generation carried more data, faster.","The first commercial 3G network opened on October 1, 2001, when Japan's NTT DoCoMo launched service in the Tokyo area using a system called WCDMA. 3G was fast enough for things like simple web pages, email, music downloads and small video calls on a phone. By the middle of 2007, about 200 million people worldwide were using 3G networks.","4G arrived in December 2009, when the Nordic company TeliaSonera opened the first public network using a standard called LTE, in Stockholm and Oslo. 4G was quick enough to stream video smoothly. Then, in 2019, 5G networks began to switch on around the world, with South Korea and the United States among the first. 5G can carry much more data with less delay, which is useful in crowded places like stadiums and for machines that talk to each other. By 2023, the ITU estimated, about 90 percent of the world's population lived within reach of a 4G network or better, and about 40 percent were covered by 5G.","Something remarkable happened along the way: there are now more mobile phone subscriptions in the world than there are people, more than 8 billion. That does not mean every single person has a phone. Many people have two subscriptions, for example one for work and one for home, or extra SIMs for tablets, watches and other devices, while others still have none.","Along with faster networks came a huge change in the phone itself. With 3G, 4G and 5G, the mobile phone stopped being mostly a telephone and turned into a pocket computer with a touchscreen, a camera, maps, apps and the internet. That is a whole story of its own, and you can follow it in the separate Smartphone Deep Dive.","For this story, the important point is this: in just over 150 years, the telephone went from Bell's wooden box with a wire to a radio in almost every pocket on the planet. So, now that nearly everyone can call nearly anyone, what comes next? Where does calling go from here?"]}],"deepDive":"Why did digital win, and why did GSM in particular spread so widely? Technically, digital cellular offered three big gains over analog. First, capacity: speech coding compressed the voice so that, in GSM, eight users could share one 200-kilohertz carrier through time slots, and digital signals tolerate more interference, so channels could be reused more tightly. Second, security: GSM encrypted the radio link and used the SIM to authenticate the subscriber, which largely ended the cloning fraud of the analog era. Security researchers later showed that GSM's original ciphers, A5/1 and A5/2, could be broken, and that GSM checked the user but not the network, weaknesses that later standards fixed with mutual authentication. Third, flexibility: once voice is data, the same network can carry text messages and, eventually, internet traffic. Historians and economists often argue that GSM's success was as much political as technical. European governments and phone companies agreed on a single standard through the 1987 Copenhagen memorandum, which created a huge common market, so manufacturers such as Nokia, Ericsson and Siemens could make phones in enormous numbers, driving prices down. The United States instead let several digital standards compete (D-AMPS, CDMA and GSM), which encouraged innovation, especially CDMA's spread-spectrum approach that influenced 3G, but slowed roaming and economies of scale. Another debate concerns SMS: its success was not planned. Operators at first saw it as a minor extra; its popularity was driven by cheap prepaid customers and young people, which shows that users, not just designers, decide what a technology is for. Finally, development researchers continue to argue about how much mobile phones reduce poverty. Studies of fishing markets, farm prices and mobile money such as M-Pesa found real benefits, but some findings, including the widely quoted Kenyan poverty estimate, have been challenged, and gaps in ownership between rich and poor countries, and between men and women, remain.","funFact":"The very first text message, 'Merry Christmas', was sent from a computer, not a phone, because the phones of 1992 had no way to type and send a message. The person who received it could not even text back!","check":{"q":"What did the first SMS text message say when it was sent on December 3, 1992?","a":"Merry Christmas","wrong":["Happy New Year","Hello, can you hear me?","Mr. Watson, come here"]},"sources":[{"title":"GSM","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/GSM"},{"title":"SMS","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/SMS"},{"title":"Radiolinja","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Radiolinja"},{"title":"Cellular network","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cellular_network"},{"title":"Facts and Figures 2023: Mobile phone ownership","publisher":"International Telecommunication Union (ITU)","url":"https://www.itu.int/itu-d/reports/statistics/2023/10/10/ff23-mobile-phone-ownership/"},{"title":"Facts and Figures 2023: Mobile network coverage","publisher":"International Telecommunication Union (ITU)","url":"https://www.itu.int/itu-d/reports/statistics/2023/10/10/ff23-mobile-network-coverage/"},{"title":"Nokia 1100","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nokia_1100"},{"title":"M-Pesa","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/M-Pesa"}],"photos":[{"src":"img/deep/telephone/18-1.jpg","alt":"A Motorola StarTAC flip phone, opened to show its glowing red number display and keypad.","file":"Motorola StarTAC 6500 Phone.jpg","url":"https://commons.wikimedia.org/wiki/File:Motorola_StarTAC_6500_Phone.jpg","author":"rfdigitalwpg","license":"CC BY 2.0"},{"src":"img/deep/telephone/18-2.jpg","alt":"A well-used Nokia 1100, one of the best-selling phones ever, with its small screen and worn keypad.","file":"Nokia 1100 20140624.jpg","url":"https://commons.wikimedia.org/wiki/File:Nokia_1100_20140624.jpg","author":"Namlong618","license":"CC BY-SA 4.0"},{"src":"img/deep/telephone/18-3.jpg","alt":"A cell tower in Finland with white panel antennas mounted near the top of its lattice mast.","file":"Celltower antennas.jpg","url":"https://commons.wikimedia.org/wiki/File:Celltower_antennas.jpg","author":"4shadoww","license":"CC BY-SA 4.0"}],"words":3654},{"n":19,"title":"The Future of Talking at a Distance","when":"2000s – the future","summary":"Today your voice can be chopped into tiny pieces of data, zoom across the internet and be glued back together in a blink. Old phone wires and phone booths are disappearing, while phones are learning to talk straight to satellites in space. Next come faster networks, instant translation and captions that help everyone join the conversation.","sections":[{"heading":"Your Voice, Chopped into Packets","paragraphs":["For about a hundred years, a telephone call worked like a private water pipe. When you called your grandmother, the exchanges connected a continuous path of wire from your phone to hers, and that path belonged to your call alone until you hung up. Engineers call this circuit switching. It was reliable, but wasteful: even when nobody was speaking, the whole circuit sat reserved, carrying silence.","The internet works in a completely different way, and since the 2000s more and more of our calls have moved onto it. The method is called Voice over Internet Protocol, or VoIP for short (people often say it like the word 'voyp'). Instead of reserving a pipe, VoIP turns your voice into numbers and mails those numbers across the network in thousands of tiny envelopes called packets.","Here is how it works, step by step. First, a microphone turns the air vibrations of your voice into a changing electric signal, just as Bell's transmitter did in 1876. Next, a chip measures that signal thousands of times every second and writes down each measurement as a number. This is called digitizing, and it turns an analog wave (smooth, like a hill) into digital data (a staircase of ones and zeros). Then a clever program called a codec squeezes the numbers so they take up less room, throwing away details our ears would never notice. Some codecs can shrink a voice down to only about 8,000 bits per second in each direction, a tiny trickle compared with a video stream.","Finally, the squeezed numbers are cut into small chunks. Each chunk goes into a packet with a label showing where it came from, where it is going and what order it belongs in. The packets are thrown onto the internet, and each one can take its own route through cables, routers and maybe even an undersea fiber before it reaches the other phone. There, the packets are put back in order, unsqueezed and turned back into sound in a speaker. All of this usually happens in a fraction of a second.","Packets do not always behave. Some arrive late, some arrive out of order and a few get lost entirely. If a phone waited for every lost packet to be sent again, the conversation would stutter and drag, so most voice systems simply skip the missing bits and keep going. To smooth out packets that arrive at uneven times (engineers call this unevenness jitter), the receiving phone keeps a tiny waiting room called a buffer. It holds the packets for a few hundredths of a second and then plays them out at a steady pace. That is why an internet call can sometimes sound a little robotic or choppy when your connection is weak: the waiting room has run empty.","The idea is older than you might think. In 1973 a computer scientist named Danny Cohen demonstrated sending voice in packets, and in August 1974 researchers tested a Network Voice Protocol over ARPANET, the American research network that grew into the internet. Their computers were so slow that speech had to be squeezed to only about 2,400 bits per second. In 1995 an Israeli company called VocalTec released Internet Phone, one of the first programs that let ordinary people talk through their home computers, if both people had the software, microphones and a lot of patience."]},{"heading":"Skype and the Free Video Call","paragraphs":["Internet calling became famous thanks to a program with a bouncy name: Skype. It was founded in 2003 by two entrepreneurs, Niklas Zennström from Sweden and Janus Friis from Denmark, and the software itself was written by four programmers in Estonia: Ahti Heinla, Priit Kasesalu, Jaan Tallinn and Toivo Annus. The first public test version appeared on August 29, 2003.","Skype's big promise was simple: calls from one Skype user to another, anywhere in the world, were free. For families split between countries, this felt like magic. A student studying abroad in the 2000s might once have bought expensive phone cards and watched the minutes tick away. With Skype, the same student could talk to their parents for an hour and pay nothing extra beyond their internet connection. Soon Skype added video, and people could see each other's faces, wave at new babies and show off a new puppy across oceans.","Big companies noticed. The auction website eBay bought Skype in 2005 for about 2.6 billion US dollars, and in 2011 Microsoft bought it for 8.5 billion dollars. In January 2013 more than 50 million people were logged in to Skype at the same moment. But the story did not last forever. Many newer apps arrived, built into phones, social networks and work tools. Microsoft retired Skype on May 5, 2025, and pointed its users to its other calling app, Microsoft Teams.","Skype's disappearance does not mean internet calling failed. The opposite happened: it won so completely that it became invisible. In 2020, when schools and offices around the world closed during the COVID-19 pandemic, millions of people suddenly met their teachers, coworkers and grandparents through video-calling apps. Classes, birthday parties, doctor's appointments and even weddings happened on screens.","Even an ordinary call on a modern mobile phone is usually a packet call now. Recent mobile networks carry voice using systems called Voice over LTE (VoLTE) on 4G and Voice over New Radio on 5G. When you tap a contact's name and hear it ring, your voice is very likely being chopped into packets just like a Skype call. The telephone and the internet, which began as separate inventions, have quietly merged into one."]},{"heading":"Goodbye, Copper Wire","paragraphs":["For more than a century, the main network of wired phones was called the public switched telephone network, or PSTN. It was built from copper wires running to homes, giant exchange buildings full of switches, and trunk lines tying cities together. Many of those copper pairs were laid decades ago, and in some neighborhoods the wire running to a house is older than the people living inside it.","Now many countries are switching that old network off and moving landline calls onto digital, internet-style connections. The reasons are practical. The old equipment is wearing out, spare parts are hard to find, and fewer engineers still know how to repair the ancient switches. Running two networks side by side, an old one and a new one, also costs a lot of money.","The United Kingdom gives a clear example. Its plan first aimed to retire the old copper landline network by December 2025, but the deadline was pushed back to January 2027 to give people more time to prepare. Customers are moved to digital phone lines that plug into a home broadband router instead of straight into the wall. By September 2026, the company that runs most British phone lines had converted about 90 percent of old lines in ten major cities and the areas around them. Countries such as the Netherlands, Germany, Estonia, Norway, Iceland, Spain and Portugal have also retired, or are retiring, their traditional networks, and many others are planning similar changes.","At the same time, many families have simply stopped having a home phone at all. In the United States, government health surveys have tracked this for years, and today well over half of adults live in homes that have only mobile phones and no landline. Around the world, mobile subscriptions now outnumber people, while the number of fixed lines has been shrinking.","The humble phone booth has faded even faster. In the United States there were somewhere around 2.2 to 2.6 million payphones between the mid-1990s and 2000. By 2018 only about 100,000 were left, and New York City removed its last regular public payphone in 2022. In Britain, many of the famous red telephone kiosks are still standing, but their phones are often gone. Local communities have adopted hundreds of them and turned them into tiny libraries, art galleries, information points or homes for defibrillators, the life-saving machines that can restart a heart. A box built for emergency calls can still help in emergencies, just in a new way."]},{"heading":"Why Some People Still Love the Wire","paragraphs":["If the old landline is going away, why do some people want to keep it? The answer is that the old copper network had a few superpowers that are easy to forget.","The first superpower is electricity. A traditional landline phone gets its small amount of power through the phone line itself, sent out from batteries and generators at the telephone exchange. That means a simple corded phone often keeps working during a blackout, even when every light in the house is out. A digital phone line, by contrast, depends on a router plugged into the wall at home. When the power goes off, the router goes dark and so does the phone, unless there is a backup battery. That is why phone companies switching to digital lines often offer battery backup units, especially to older people, people with disabilities and people who have no mobile phone or poor mobile signal.","The second superpower is location. An old landline number is tied to a fixed address, so when someone dials an emergency number, the call taker can see where the call is coming from. An internet phone can be carried anywhere, and its network address does not reveal its street. In the United States, internet phone companies must ask customers for a registered address and pass it on to emergency services, but that only works if the address is kept up to date. Engineers are working hard to make every type of call reveal its location as reliably as the old wire did.","The third issue is the many machines that quietly use phone lines without anyone talking. Burglar alarms, lift emergency phones, some card payment machines and, most importantly, telecare alarms all used the old network. Telecare alarms are pendants or buttons that older or disabled people wear at home; if they fall, they press the button and the alarm phones a response center. Some of these older devices did not work properly on digital lines. Protecting the people who depend on them was one important reason the UK slowed down its switch-off and asked phone companies to check carefully before moving vulnerable customers.","None of this means the switch is a mistake. Digital lines can carry clearer sound, cost less to run and connect to the same networks that carry the internet. It simply shows a lesson that runs through this whole Deep Dive: when a communication system changes, the people who most need it must not be left behind."]},{"heading":"Calling from Anywhere: Phones That Talk to Space","paragraphs":["Even today, there are huge parts of Earth with no phone towers at all: open oceans, deserts, polar ice, high mountains and remote forests. Cell towers usually reach only a few kilometres, and nobody is going to build one every few kilometres across the Pacific Ocean. For a sailor, a mountain climber or a scientist in Antarctica, the answer has long been a satellite phone.","A satellite phone skips the towers and talks directly to a satellite overhead. There are two main ways to do this. Some systems use satellites in geostationary orbit, about 36,000 kilometres (22,000 miles) above the equator. Up there, a satellite circles Earth exactly once a day, so it seems to hang still in the sky, and just a few of them can cover most of the planet. The catch is distance: a radio signal must travel up and down tens of thousands of kilometres, so there is a noticeable delay, the same slight echo-like pause you learned about with Telstar. Companies such as Inmarsat and Thuraya use this kind of orbit.","Other systems use satellites in low Earth orbit, usually a few hundred to a little over a thousand kilometres up. These satellites race around Earth in about an hour and a half, so no single one stays overhead for long. To give constant coverage, a company needs dozens of them working as a team, handing your call from one satellite to the next, a bit like cell towers handing off a call as you drive. Iridium and Globalstar launched systems like this in the late 1990s. Both companies ran into money trouble and went through bankruptcy before being rescued, because building a whole constellation of satellites costs billions of dollars and early customers were few.","Satellite phones have always had limits. They need a clear view of the sky, so they struggle indoors or in deep valleys. They carry mainly voice, text and slow data, and the calls are much more expensive than ordinary mobile calls. Some countries also restrict or license them. But when an earthquake knocks down towers, or a ship is far out at sea, they can be lifesavers.","The newest step is even more surprising: ordinary smartphones connecting to satellites directly. In 2022 Apple added a feature to the iPhone 14 that let people send emergency text messages by satellite when they had no mobile signal. The phone shows the user which way to point it to find a satellite, and the messages are squeezed very small because the link is so weak. In January 2024, SpaceX reported successful text-message tests between its Starlink satellites and ordinary phones on T-Mobile's network in the United States, and a commercial service followed. Other companies, such as AST SpaceMobile, are building satellites with enormous antennas to do the same thing.","How can a small phone reach something hundreds of kilometres away? The trick is mostly on the satellite's side. Each one carries a large, very sensitive antenna and behaves like a cell tower in space, listening for the faint whisper of an ordinary phone's radio. Right now these services mostly handle texts and some data, and they work best outdoors with open sky. Engineers hope that within the next few years, the phrase 'no signal' will become rare almost anywhere on Earth."]},{"heading":"6G: The Next Generation","paragraphs":["Each new generation of mobile network has been given a number. 1G carried analog voice, 2G made calls digital and added texts, 3G brought the mobile internet, 4G made video streaming easy, and 5G, launched in 2019, added more speed and less delay. Engineers are already working on 6G, and it is widely expected to start appearing around 2030.","Who decides what counts as 6G? An important role belongs to the International Telecommunication Union (ITU), a United Nations agency whose history goes all the way back to 1865, when European countries met to agree on rules for the telegraph. The ITU calls the next generation IMT-2030. In November 2023 its members approved a framework describing what IMT-2030 should be able to do. The timeline then calls for companies and countries to submit candidate technologies between about February 2027 and February 2029, before the final standards are chosen.","The framework lists six main uses for future networks. One is immersive communication, such as calls that feel like being in the same room. Another is hyper-reliable, low-latency communication, for jobs where every thousandth of a second matters, like controlling machines in a factory or perhaps helping with remote surgery. Others include connecting enormous numbers of small sensors, giving coverage almost everywhere, combining networks with artificial intelligence, and something called integrated sensing, where the radio signals themselves help detect objects and movement around them, a little like radar.","A key word for 6G is latency, which means delay: how long it takes a signal to make the trip and come back. When you talk to someone, a delay of a quarter of a second already makes conversation awkward, because people start talking over each other. For a game, a robot or a self-driving machine, even tiny delays can matter. Each new generation of network has tried to push latency down, and 6G researchers hope to push it lower still.","Researchers are also testing higher radio frequencies than today's phones use. Higher frequencies can carry much more data, but they do not travel as far and are easily blocked by walls, leaves and even rain. That means 6G might need many more small antennas, smarter ways to aim signals, and a close partnership with satellites. All of these details are still being worked out, so any claims you read about exact 6G speeds are goals, not promises."]},{"heading":"Words Without Borders: Translation, Captions and Holograms","paragraphs":["Alexander Graham Bell spent much of his life as a teacher of deaf students, and his wife Mabel was deaf. It would surely have fascinated him that some of the most exciting changes in calling today are about helping people who cannot easily hear, or who do not speak the same language.","One of these is the live caption. Modern phones and video-calling apps can listen to speech and turn it into text on the screen almost instantly, using speech-recognition software trained on huge amounts of recorded talk. Google introduced a Live Caption feature for Android phones in 2019, and many other companies now offer similar captions during calls and video meetings. For deaf and hard-of-hearing people, this builds on a long history that includes Robert Weitbrecht's TTY coupler of the 1960s and the relay services that followed, where a human operator would type out what a hearing caller said. Video calling has also been a big gift to Deaf people who use sign language, because for the first time they can sign to each other directly across long distances.","Captions are not perfect. They can stumble on accents, names, background noise and technical words, and they work better in some languages than others. That is why human captioners and interpreters still matter, especially for important conversations like medical or legal calls.","Another big change is machine translation during calls. Some phones and apps can now listen to one language, translate it and speak or display it in another, with only a short delay. Imagine a girl in Brazil talking to her new pen pal in Japan, each in her own language, with a computer translating in between. Today's versions are impressive but can still make funny or serious mistakes, especially with jokes, slang and words that have several meanings. Many people still find it best to learn a little of each other's language too.","And then there are holograms. Science fiction has long imagined three-dimensional images of callers standing in the room with you. Researchers and companies have built experimental 3D video booths and headset-based calls that make a distant person appear life-sized and solid-looking. These are still mostly demonstrations and expensive experiments, not something you can do from your phone. They are ideas for the future, and it is not yet clear whether they will ever become ordinary. But remember: in 1876 a talking wire also sounded like science fiction."]},{"heading":"Hard Problems on the Line","paragraphs":["The future of calling is exciting, but it comes with serious problems that inventors still need to solve. Some of them may be problems that you will help fix.","The first is energy. Every call, video chat and message passes through data centers, routers, mobile towers and undersea cables, all of which need electricity, often around the clock. As more people stream more video and as networks grow faster, engineers are trying to make every part of the network do more work with less power, for example by putting quiet parts of a network to sleep when few people are using them.","The second is electronic waste, or e-waste: thrown-away phones, chargers, cables, computers and other gadgets. According to the Global E-waste Monitor, the world produced about 62 million tonnes of e-waste in 2022, and less than a quarter of it, about 22 percent, was properly collected and recycled. That number is expected to rise to about 82 million tonnes by 2030. Old phones contain useful metals such as copper, gold and cobalt, but also materials that can be harmful if dumped carelessly. Repairing phones, using them for longer and recycling them properly all help.","The third is keeping networks safe. Almost all intercontinental internet and call traffic travels through undersea cables, and most damage to them comes from accidents such as ship anchors and fishing gear. But governments also worry about deliberate harm. When several cables in the Baltic Sea were damaged in 2023 and 2024, investigators looked closely at ships that had passed overhead. Protecting cables, satellites and towers, and building backups so one break cannot cut off a whole country, has become a major job for engineers and governments.","The fourth is privacy and trust. Many apps now use end-to-end encryption, which scrambles a call so that only the two phones at the ends can unscramble it, not even the company in the middle. That protects ordinary people, though it also creates hard debates with police who want to investigate crimes. Meanwhile, scam calls keep changing, and computers can now imitate a real person's voice. Some families have agreed on a secret code word, so that if someone calls pretending to be a relative in trouble, they can check whether it is truly them.","From signal fires to satellites, every leap in communication has brought new benefits and new dangers. The telephone's next chapter will be written by people who keep both in mind.","Before we look ahead any further, though, it is worth pausing to look back. Picture it: a beacon fire flickering on a dark hilltop, and a satellite gliding silently overhead. Between those two lights lies one of the greatest stories in human invention, and in the final part we will travel the whole journey again, from start to finish."]}],"deepDive":"The move from circuit-switched telephony to packet-switched VoIP is a classic engineering trade-off. A traditional digital phone circuit reserved a constant 64 kilobits per second for each direction of a call: 8,000 samples per second, each recorded as an 8-bit number, a scheme standardized as G.711. That bandwidth was used whether anyone spoke or not. Packet networks share capacity among everyone, so idle moments cost almost nothing, and codecs can compress speech far below 64 kbit/s; G.729, for example, uses about 8 kbit/s, and modern adaptive codecs such as Opus adjust their bit rate to the connection. The price is unpredictability. The internet is a 'best-effort' network: it promises to try, not to deliver on time. Voice therefore usually travels over UDP, a protocol that does not resend lost packets, because a resent packet would arrive too late to be useful. Receivers use a jitter buffer, trading a little extra delay for smoother playback, and packet-loss concealment software guesses at missing fragments. The ITU's guidance has long suggested keeping one-way delay below roughly 150 milliseconds for comfortable conversation, which is one reason geostationary satellite links, with roughly 250 milliseconds of one-way delay from orbital distance alone, feel awkward. The switch-off of copper networks raises policy questions that are not purely technical. Copper lines delivered power from the exchange, so landline service survived local blackouts; digital lines depend on customer equipment, and regulators have had to decide how much battery backup providers must offer and to whom. Emergency-location rules differ by country, and the reliability of legacy devices such as telecare alarms has proved a real constraint on timetables. For 6G, the ITU's IMT-2030 framework (Recommendation ITU-R M.2160, approved in 2023) sets out usage scenarios and capabilities rather than a finished design. Candidate technologies are due later in the decade, which is why credible sources describe 6G as expected around 2030 and treat specific performance numbers as research targets rather than guarantees.","funFact":"When Skype was retired in May 2025, its software was older than many of the teenagers who had used it to call their grandparents: the first public test version came out on August 29, 2003.","check":{"q":"In VoIP, what happens to your voice before it travels across the internet?","a":"It is turned into digital data and split into small packets","wrong":["It is sent as a continuous current along one reserved copper wire","It is turned into Morse code and tapped out by an operator","It is beamed only by geostationary satellites"]},"sources":[{"title":"Voice over IP","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Voice_over_IP"},{"title":"Skype","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Skype"},{"title":"Public switched telephone network","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Public_switched_telephone_network"},{"title":"Payphone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Payphone"},{"title":"Satellite phone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Satellite_phone"},{"title":"IMT towards 2030 and beyond (IMT-2030)","publisher":"International Telecommunication Union (ITU)","url":"https://www.itu.int/en/ITU-R/study-groups/rsg5/rwp5d/imt-2030/Pages/default.aspx"},{"title":"The Global E-waste Monitor 2024","publisher":"UNITAR / ITU Global E-waste Monitor","url":"https://ewastemonitor.info/the-global-e-waste-monitor-2024/"},{"title":"Starlink","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Starlink"}],"photos":[{"src":"img/deep/telephone/19-1.jpg","alt":"A red British telephone box in Bosham, England, turned into a little free library full of books.","file":"Telephone box library, Bosham, West Sussex, England.jpg","url":"https://commons.wikimedia.org/wiki/File:Telephone_box_library,_Bosham,_West_Sussex,_England.jpg","author":"ITookSomePhotos","license":"CC BY 4.0"},{"src":"img/deep/telephone/19-2.jpg","alt":"An Iridium satellite phone with its thick fold-out antenna, held up by the sea while it searches for satellites.","file":"Iridium satellite phone.jpg","url":"https://commons.wikimedia.org/wiki/File:Iridium_satellite_phone.jpg","author":"Bruno Sanchez-Andrade Nuño","license":"CC BY 2.0"},{"src":"img/deep/telephone/19-3.jpg","alt":"Diagram of Voice over IP: computers, consoles and radios all send their voices as data through an IP network.","file":"VoIP Interface Architecture.JPG","url":"https://commons.wikimedia.org/wiki/File:VoIP_Interface_Architecture.JPG","author":"Cluu2009 (talk)","license":"Public domain"}],"words":3881},{"n":20,"title":"From Signal Fire to Satellite: Putting It All Together","when":"Ancient times – today","summary":"Long ago, the fastest message was a fire on a hill. Then came towers with arms, clicking telegraphs, talking wires, busy operators, spinning dials, glass threads full of light and phones in our pockets. Many clever people built this together, and the big wish behind it never changed: we want to hear the people we care about.","sections":[{"heading":"Rewinding the Whole Journey","paragraphs":["Imagine you could stand on a hilltop and watch the whole history of long-distance talking pass by like a movie on fast-forward. It would begin in darkness, with a fire crackling on a ridge and another answering far away. Ancient writers described beacon chains like this, including the famous one in Aeschylus's play Agamemnon from 458 BCE, which is a story rather than a record. Real beacon towers stood along China's Great Wall, and in 1588 beacons were prepared across England to warn that the Spanish Armada was coming. Talking drums in West Africa copied the rising and falling tones of spoken languages. Inca relay runners called chasqui carried messages along mountain roads, reportedly covering around 240 kilometres in a day, and pigeons carried notes tied to their legs.","Then the movie speeds up. In 1794 Claude Chappe and his brothers opened an optical telegraph line between Paris and Lille, about 230 kilometres long, with wooden arms on hilltop towers spelling out signals read through telescopes. At its peak, France had more than 500 such stations. Meanwhile, scientists were taming electricity: Alessandro Volta built the first battery in 1800, Hans Christian Ørsted saw a current move a compass needle in 1820, and Joseph Henry and Michael Faraday unlocked the secrets of electromagnets and induction around 1830 and 1831.","Electricity soon learned to write. In 1837 William Cooke and Charles Wheatstone patented a needle telegraph in Britain, and on May 24, 1844, Samuel Morse sent 'What hath God wrought' about 60 kilometres from Washington to Baltimore. Wires spread along railways, and in October 1861 a telegraph line crossed the United States, ending the Pony Express two days later. Under the sea, cables followed: the 1858 transatlantic cable carried Queen Victoria's 98-word greeting, which took about 16 hours to send, and failed after about three weeks. In 1866 the giant ship Great Eastern laid a cable that lasted, and news that once took about ten days by ship crossed the Atlantic in minutes.","Next came the voice. Charles Bourseul imagined electrical speech in 1854; Johann Philipp Reis built his Telephon in 1861; Antonio Meucci filed a patent caveat in 1871; and on February 14, 1876, both Alexander Graham Bell's patent application and Elisha Gray's caveat reached the US Patent Office. Bell's patent, number 174,465, was issued on March 7, 1876, and three days later he said, 'Mr. Watson — come here — I want to see you.'","After that, the telephone grew a network. The first commercial switchboard opened in New Haven, Connecticut, in January 1878 with 21 subscribers. Operators like Emma Nutt connected calls by hand. Almon Strowger's automatic switch was patented in 1891, rotary dials spread in the early 1900s, and the first coast-to-coast call rang through in 1915. TAT-1 carried about three dozen calls at once under the Atlantic in 1956, Telstar bounced calls through space in 1962, and Touch-Tone keypads arrived in 1963. Then the phone left the house: car phones from 1946, Martin Cooper's handheld call in 1973, commercial cellular networks from 1979, digital GSM in 1991, the first text message in 1992, and fiber-optic cables carrying almost all of the world's long-distance traffic as flashes of light. Today there are more mobile subscriptions than people on Earth.","Put it all together and you get a line of messengers: fire, wooden arms, electric clicks, copper wires, switchboards, dials, radio waves, glass fibers and satellites. Each one solved a problem the one before could not."]},{"heading":"The Whole Science in One Sentence","paragraphs":["If you had to explain every invention in this Deep Dive in one sentence, here it is: turn a message into a signal, send the signal, and turn it back into a message at the other end. For the telephone, that becomes: turn sound into a signal, send it, and turn it back into sound.","Look how that same idea appears again and again. A beacon fire turned a message into the simplest possible signal: fire or no fire, which is really just 'yes' or 'no'. Chappe's semaphore turned letters and words into arm positions. The electric telegraph turned letters into short and long pulses of current, the dots and dashes of Morse code. All of these could only send messages that had been agreed in advance or spelled out letter by letter.","Bell's telephone made a giant leap. It did not spell anything. Instead, a thin diaphragm in the transmitter shook with the sound of a voice, and that shaking changed an electric current so that the current became a copy of the sound wave. This is an analog signal: it rises and falls smoothly, just like the pressure of air hitting your eardrum. At the other end, the changing current pulled on an electromagnet, which shook another diaphragm, which pushed the air, which reached the listener's ear. The voice had been translated into electricity and translated back. Later, carbon microphones made that copy louder and stronger, and they stayed in phones for about a hundred years.","Modern phones still follow the same three steps, but they add new tricks in the middle. Instead of sending a smooth copy of the wave, they measure it thousands of times every second and turn it into digital numbers. Those numbers can be squeezed, protected from errors, scrambled for privacy, chopped into packets, sent as radio waves to a tower or as flashes of light through glass, and finally turned back into a smooth wave that moves a tiny speaker next to your ear.","The amazing thing is that nature has always done the first and last steps for us. Your vocal cords turn breath into vibrations, and your eardrum turns vibrations back into signals in nerves that your brain understands. In a way, the telephone is just a very, very long extension between one person's throat and another person's ear."]},{"heading":"Many Hands on the Receiver","paragraphs":["Who invented the telephone? If you have read this whole Deep Dive, you know the honest answer is longer than one name.","Alexander Graham Bell deserves enormous credit. He understood sound and speech deeply from his family's work and his teaching of deaf students. He realized that a smoothly changing current could carry a voice, he won the key patent, he and Thomas Watson made the first famous working call, and he showed the world the telephone was more than a toy. His patent, number 174,465, is often called one of the most valuable patents ever issued, because it became the foundation of a giant industry.","But Bell did not work alone, and he was not the only one with the idea. Elisha Gray filed his caveat on the very same day, describing a liquid transmitter much like the one Bell used for his first famous sentence. Whether Bell saw Gray's papers is still debated by historians, and it has never been proven. Antonio Meucci spent years developing his telettrofono in New York and filed a caveat in 1871, but was too poor to keep renewing it; in 2002 the US House of Representatives honored his work, although that did not change who held the patent. Johann Philipp Reis built a device that sent tones and some speech in 1861, and Charles Bourseul described the basic idea even earlier.","Then there were the people who made the telephone actually useful. Thomas Watson built the instruments with his skilled hands. Thomas Edison, Emile Berliner and David Edward Hughes worked on carbon microphones that made voices clear over long lines. George Coy built the first commercial switchboard. Emma Nutt and many thousands of operators after her, mostly women, connected the calls, one plug at a time. Almon Strowger automated the switch. Michael Pupin and George Campbell made long lines carry voices farther, Theodore Vail organized a nationwide system, and engineers at Bell Labs built amplifiers, transistors and cables. Later still, Charles Kao showed that glass fibers could carry light over long distances, and Martin Cooper, Joel Engel and their teams raced to make phones portable.","So a fair way to say it is this: Bell received the key patent and built the first successful telephone business, but the telephone as we know it was created by many inventors, engineers, workers and users over many years. That is true of almost every great invention. A single name makes a neat headline, but real invention is usually a crowd."]},{"heading":"The Telephone's Surprising Children","paragraphs":["Some inventions are like trees: once they grow, new branches sprout in directions nobody expected. The telephone is one of the biggest trees in the forest of invention.","In 1925 AT&T and Western Electric created Bell Telephone Laboratories, usually called Bell Labs, in the United States. Its job was to make the phone network better, and to do that its scientists studied everything from metals and magnets to mathematics and sound. Because the phone company was so huge, Bell Labs could afford to let brilliant people chase difficult questions for years. The results changed the world far beyond telephones.","The most famous result came just before Christmas. On December 16, 1947, two Bell Labs physicists, John Bardeen and Walter Brattain, got a small piece of germanium with gold contacts pressed against it to amplify an electric signal. It was the first transistor, a tiny switch and amplifier with no glowing glass tube. They showed it to lab leaders on December 23, and their group leader William Shockley called it 'a magnificent Christmas present.' A Bell Labs engineer named John Pierce came up with the name 'transistor', and the invention was announced to the public on June 30, 1948. Bardeen, Brattain and Shockley shared the 1956 Nobel Prize in Physics.","Why did a phone company want a transistor? Because the network was full of bulky vacuum tubes and clattering mechanical switches that got hot, used lots of power and wore out. Transistors were smaller, cooler and more reliable. But they did not stay in telephone exchanges. Billions upon billions of them now sit inside every computer, game console and smartphone. The chip in a modern phone contains billions of transistors, all descendants of that little lump of germanium.","In the same year the transistor was announced, another Bell Labs scientist, a mathematician named Claude Shannon, published a paper called 'A Mathematical Theory of Communication'. It appeared in two parts, in July and October 1948, in the Bell System Technical Journal. Shannon asked a deep question: what exactly is information, and how much of it can you squeeze through a noisy channel like a crackly phone line? He described every communication system as a chain of five parts: a source, a transmitter, a channel, a receiver and a destination, with noise trying to spoil the message along the way. That chain fits a signal fire, a telegraph, a telephone and a Wi-Fi network equally well.","Shannon also made popular a tiny new word: the bit, short for 'binary digit', a single choice between 0 and 1. He credited the word to his colleague John Tukey. Shannon showed that any message, whether words, music or pictures, can be measured in bits, and that clever coding can send information almost perfectly even through noise, as long as you do not try to send faster than the channel's limit. This became the foundation of information theory, and it is why your phone can still understand a call when the signal is weak. Some writers have called his paper the 'Magna Carta' of the Information Age.","Bell Labs kept going. Its scientists made the first modern solar cell in 1954, described the idea of the laser in 1958, discovered the faint leftover glow of the Big Bang in 1965, and created the Unix operating system and the C programming language around 1969 to 1972, which still shape the software inside phones and computers. Work done at Bell Labs has earned eleven Nobel Prizes. Today the lab belongs to the Finnish company Nokia.","And remember the cables. The routes first tested by telegraph cables in the 1850s and 1860s, and then by telephone cables like TAT-1, are the ancestors of today's fiber-optic cables. When you watch a video from another continent, it very likely travels along the seabed, just as Queen Victoria's slow greeting did in 1858, only billions of times faster."]},{"heading":"Numbers That Tell the Story","paragraphs":["Sometimes numbers tell a story better than words. Here are a few from this Deep Dive, side by side.","Speed of a message: an Inca chasqui relay could reportedly carry news around 240 kilometres in a day. A ship carrying news across the Atlantic took about ten days. In 1858, Queen Victoria's 98-word message took about 16 hours to tap through a weak undersea cable. After 1866, news crossed the same ocean in minutes. Today a call or message crosses the planet in well under a second.","How many calls at once: the first transatlantic telephone cable, TAT-1, could carry about 36 conversations at the same time in 1956. A single modern fiber-optic cable can carry vastly more traffic, enough for millions of calls and huge amounts of internet data together.","How many phones: in 1878, New Haven's first exchange had 21 subscribers. By 1880 there were already tens of thousands of telephones in the United States, and by the late 1940s roughly half of American households had a phone. Today there are more mobile phone subscriptions in the world than there are people, over 8 billion.","How long it took: from Morse's 'What hath God wrought' in 1844 to Martin Cooper's handheld cellular call in 1973 is about 130 years. In that time, long-distance messages went from clicks that only trained operators could read to a phone you could hold in one hand and simply talk into. Humans spent thousands of years relying on fires, runners and pigeons, and then changed everything in little more than a century.","How heavy: Cooper's 1973 prototype weighed about 1.1 kilograms, around the weight of a bag of sugar. The DynaTAC 8000X that went on sale in 1983 cost 3,995 US dollars and offered about 30 minutes of talk time. A modern phone weighs a fraction of that and can last all day.","These numbers show something important. Progress did not happen in one smooth line. It came in jumps, each one built on the steps before. Without the battery, no telegraph. Without the telegraph, no telephone. Without the telephone network, no Bell Labs and no transistor. Without transistors, no smartphone."]},{"heading":"Four Lessons Hidden in the Story","paragraphs":["Looking back over twenty parts, a few patterns keep popping up. They are useful not only for understanding the telephone, but for understanding how almost any big invention grows.","Lesson one: a network becomes more valuable as it grows. A single telephone is useless; you need someone to call. When Bell's company rented the first phones in pairs, each pair could only talk to each other. New Haven's switchboard in 1878 connected 21 subscribers, so each person suddenly had 20 others to reach. Every new customer made the network more useful for everybody already on it. The same is true of the telegraph, the internet and every messaging app on your phone. That is one reason why the company with the biggest network so often won, and why governments later had to think hard about monopolies.","Lesson two: agreements matter as much as gadgets. Signals only work if both ends understand them. Beacon watchers had to agree in advance what a fire meant. Telegraph operators had to share the same code. In 1865 European countries founded what became the International Telecommunication Union so their telegraph lines could connect across borders, and that same organization helps plan 6G today. Area codes, the 2600-hertz tones phreaks exploited, the paired musical tones of Touch-Tone keypads, and the GSM standard that let one phone work in many countries were all agreements. Without them, a call could not cross a border, or even a town.","Lesson three: a weak signal can be rescued. Again and again, the hardest problem was a message fading or smearing over distance. William Thomson found ways to read faint signals from the Atlantic cable. Loading coils and vacuum-tube amplifiers made the 1915 coast-to-coast call possible. TAT-1 used repeaters sitting on the seabed. Fiber optics needed ultra-pure glass and light amplifiers. Shannon's mathematics finally explained exactly how much information any noisy channel can carry, and how to get close to that limit.","Lesson four: people decide what an invention is for. The first telephone companies imagined business uses, but customers turned the phone into a tool for gossip, friendship, family news and emergencies. Operators shaped how calls felt. Deaf inventors like Robert Weitbrecht bent the network to fit their needs. Mobile phones spread fastest in places that had few landlines at all. An invention is never really finished when it leaves the workshop; its users keep inventing it."]},{"heading":"What Never Changed","paragraphs":["With all those changes, you might think nothing stayed the same. But one thing has not changed at all since the first fires flickered on hilltops: people want to reach each other.","Think about why people made calls in every part of this story. A beacon warned of danger. A telegram announced a birth, a death, a victory or a train arriving late. In the early days of the telephone, doctors could be called to a sick child in the night. Operators connected farmers to markets and soldiers' families to faraway news. Teenagers stretched cords around the kitchen corner for a little privacy. Families paid for expensive long-distance minutes just to hear a grandmother laugh. Emergency numbers like 999 and 911 turned the telephone into a lifeline.","The telephone also proved something special about voices. A written message can carry facts, but a voice carries feelings: the wobble when someone is nervous, the smile you can hear even without seeing a face, the comfort of a familiar 'hello'. That may be why, even with texting, emojis and video, people still pick up the phone when the news is very good or very bad.","The problems have repeated too. Every new system has had to deal with noise, cost, privacy, fair access and people who get left out. Fire signals failed in fog; telegraph cables snapped; switchboard operators could overhear; landline monopolies kept prices high; and today scam calls and e-waste trouble us. Each generation of inventors had to fix what the last generation could not, and they never ran out of work.","Perhaps the deepest thing that stayed the same is curiosity. Bell was a teacher who wanted to understand how sound works. Shannon wanted to know what information really is. Meucci, Gray, Reis, Watson, Strowger, Kao and Cooper all looked at something everyone else took for granted and asked, 'Could this be better?'"]},{"heading":"Your Turn to Invent","paragraphs":["Now it is your turn. The story of talking at a distance is not finished, and the next chapter may begin with someone reading these words.","Here is a challenge: think of a problem in communication that still bothers people, then imagine a solution. You do not need a laboratory. Bell started with a stuck reed and a good question. Strowger started with a frustrating business problem. Weitbrecht started with the wish to talk on the phone in a way that worked for deaf people like himself.","Need ideas? How could a person who cannot speak or hear easily join a fast group conversation? How could a village with no electricity stay in touch during a storm? How could a phone tell a real caller from a scam caller? How could old phones be recycled so nothing goes to waste? How could two people who speak different languages chat without the translation getting in the way? How could a network keep working when a cable on the seabed breaks? Pick one, sketch your idea, and ask what science it would need.","Every great inventor in this Deep Dive also had to test, fail and try again. The 1858 cable broke. Bell's early devices mostly hummed and squeaked. Cooper's first handheld phone was heavy and ran out of battery quickly. Failing was not the end of their stories; it was part of the method. If your first idea does not work, you are in excellent company.","So here we are at the end of a very long line, one that runs from a fire on a dark hill, through towers with waving arms, clicking keys, a shout of 'Mr. Watson — come here — I want to see you', busy switchboards, spinning dials, cables on the ocean floor, glass threads full of light and satellites gliding through space, all the way to the phone that might be sitting next to you right now.","Thank you for staying on the line for all twenty parts. It has been a wonderful conversation. Before you go, maybe pick up your phone and call someone you love, just to say hello. Then, when you are ready, hang up gently. Goodbye for now, and talk soon."]}],"deepDive":"Historians of technology often use the telephone as a case study in why simple 'lone genius' stories mislead. Sociologists describe invention as a system: a working telephone needed not only a transmitter and receiver but also batteries, wire, insulation, switches, billing, legal protection, trained operators and customers willing to rent instruments. Bell's patent 174,465 mattered so much precisely because the courts treated it broadly, covering the method of transmitting speech with an undulating current rather than one specific device; that legal breadth, upheld in the 1888 Telephone Cases by a 4–3 vote, helped the Bell companies dominate the early industry. Whether such broad patents speed up innovation or slow it down is still debated by economists. Claude Shannon's 1948 paper reframed the whole history. His model of source, transmitter, channel, receiver and destination, with noise intruding in the channel, applies equally to beacons and to 5G. His central result, the noisy-channel coding theorem, says every channel has a capacity, measured in bits per second; below that rate, suitable codes can make errors as rare as you like, while above it, reliable communication is impossible. For a channel limited by bandwidth B and signal-to-noise ratio S/N, the Shannon–Hartley formula gives capacity C = B log2(1 + S/N). That explains why engineers chase wider bandwidth (more radio spectrum, or the enormous bandwidth of optical fiber) and better signal-to-noise ratios (amplifiers, repeaters, error-correcting codes). It also explains why the move from analog to digital was so powerful: an analog signal accumulates noise at every amplifier, but a digital signal can be regenerated and checked, so a call can cross an ocean with little loss in quality. The transistor, invented at Bell Labs in December 1947 by Bardeen and Brattain in Shockley's group, made the digital approach practical by replacing power-hungry vacuum tubes. Together, Shannon's theory and the transistor turned a telephone company's research lab into one of the birthplaces of the digital age.","funFact":"The word 'bit', now used for every piece of digital data in the world, was made popular by Claude Shannon's 1948 paper for the telephone company's Bell System Technical Journal, and Shannon credited the word to his colleague John Tukey.","check":{"q":"Which world-changing invention was made at Bell Labs in December 1947?","a":"The transistor","wrong":["The carbon microphone","The optical semaphore telegraph","The rotary dial"]},"sources":[{"title":"1947: Invention of the Point-Contact Transistor","publisher":"Computer History Museum","url":"https://www.computerhistory.org/siliconengine/invention-of-the-point-contact-transistor/"},{"title":"A Mathematical Theory of Communication","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/A_Mathematical_Theory_of_Communication"},{"title":"Bell Labs","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bell_Labs"},{"title":"Telephone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Telephone"},{"title":"Transatlantic telegraph cable","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Transatlantic_telegraph_cable"},{"title":"Optical telegraph","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Optical_telegraph"},{"title":"TAT-1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/TAT-1"},{"title":"George W. Coy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/George_W._Coy"}],"photos":[{"src":"img/deep/telephone/20-1.jpg","alt":"A replica of the first transistor, invented at Bell Labs on December 23, 1947, under a glass dome.","file":"Replica of first transistor.jpg","url":"https://commons.wikimedia.org/wiki/File:Replica_of_first_transistor.jpg","author":"Revol Web","license":"CC BY-SA 2.0"},{"src":"img/deep/telephone/20-2.jpg","alt":"Claude Shannon, the father of information theory, at his desk at MIT in 1958.","file":"Claude Shannon 1958 MIT portrait original.jpg","url":"https://commons.wikimedia.org/wiki/File:Claude_Shannon_1958_MIT_portrait_original.jpg","author":"MIT Photo Service","license":"Public domain"},{"src":"img/deep/telephone/20-3.jpg","alt":"An 1868 engraving of a Chappe optical telegraph: movable arms on top of a tower spelled out signals.","file":"Télégraphe Chappe 1.jpg","url":"https://commons.wikimedia.org/wiki/File:T%C3%A9l%C3%A9graphe_Chappe_1.jpg","author":"Illustration parue dans «Les merveilles de la science», Louis Figuier, 1868.","license":"Public domain"}],"words":3785}],"words":77620};
